Object.assign(window.TEM8_DICTIONARY, {"proliferate":{"media":{"uk":"media/uk/proliferate__gb_1.mp3","us":"media/us/proliferate__us_1.mp3"},"oxford":{"phon":"prəˈlɪfəreɪt","pos":"verb","senses":[{"en":"to increase rapidly in number or amount","cn":"迅速繁殖（或增殖）；猛增","ex":{"en":"Books and articles on the subject have proliferated over the last year.","cn":"过去一年以来，论及这一专题的书和文章大量涌现。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"激增；剧增","en":"If things proliferate, they increase in number very quickly.","ex":{"en":"Computerized data bases are proliferating fast","cn":"计算机化的数据库正在激增。"}}]},"examples":[{"en":"Books and articles on the subject have proliferated over the last year.","cn":"过去一年以来，论及这一专题的书和文章大量涌现。"},{"en":"Computer courses continue to proliferate.","cn":"计算机课程层出不穷。"}]},"producers":{"lemma":"producer"},"property":{"media":{"uk":"media/uk/property__gb_1.mp3","us":"media/us/property__us_1.mp3"},"oxford":{"phon":"ˈprɒpəti","pos":"noun","senses":[{"en":"a thing or things that are owned by somebody; a possession or possessions","cn":"所有物；财产；财物","g":"[uncountable]","ex":{"en":"personal/stolen property","cn":"个人／被盗财物"}},{"en":"land and buildings","cn":"不动产；房地产","g":"[uncountable]","lab":"British English","ex":{"en":"The price of property has risen enormously.","cn":"房地产的价格大幅上升了。"}},{"en":"a building or buildings and the surrounding land","cn":"房屋及院落；庄园；房地产","g":"[countable]","lab":"formal","ex":{"en":"to own/buy/purchase/acquire/sell a property","cn":"拥有／买入／购买／购入／出售物业"}},{"en":"a quality or characteristic that something has","cn":"性质；特性","g":"[countable, usually plural]","lab":"formal","ex":{"en":"Compare the physical properties of the two substances.","cn":"比较一下这两种物质的物理性质。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"财产；资产；所有物","en":"Someone's property is all the things that belong to them or something that belongs to them.","ex":{"en":"Richard could easily destroy her personal property to punish her for walking out on him","cn":"理查德能轻易毁掉她的私人财产来惩罚她对他的背叛。"}},{"pos":"N-VAR 可变名词","cn":"房地产","en":"A property is a building and the land belonging to it.","ex":{"en":"Cecil inherited a family property near Stamford","cn":"塞西尔继承了斯坦福德附近的一处家族房产。"}},{"pos":"N-COUNT 可数名词","cn":"特性；性质；性能；属性","en":"The properties of a substance or object are the ways in which it behaves in particular conditions.","ex":{"en":"A radio signal has both electrical and magnetic properties.","cn":"无线电信号具有电、磁双重属性。"}}]},"examples":[{"en":"Compare the physical properties of the two substances.","cn":"比较一下这两种物质的物理特性。"},{"en":"There are a lot of empty properties in the area.","cn":"这个地区有大量的闲置房地产。"}]},"princess":{"media":{"uk":"media/uk/princess__gb_1.mp3","us":"media/us/princess__us_1.mp3"},"oxford":{"phon":"ˌprɪnˈses","pos":"noun","senses":[{"en":"a female member of a royal family who is not a queen, especially the daughter or granddaughter of the king or queen","cn":"（除女王或王后外的）王室女性成员；（尤指）公主","ex":{"en":"the royal princesses","cn":"王室女性成员"}},{"en":"the wife of a prince","cn":"王妃；王公贵族夫人","ex":{"en":"the Princess of Wales","cn":"威尔士王妃"}},{"en":"a young woman who has always been given everything that she wants, and who thinks that she is better than other people","cn":"（受宠溺而自以为优越的）娇小姐","lab":"disapproving"},{"en":"used by some men as a form of address to a girl or young woman","cn":"（男子对女孩或年轻女子的称呼）大小姐","lab":"British English, informal，，","ex":{"en":"Is something the matter, princess?","cn":"有什么事吗，大小姐？"}}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"公主；王妃；亲王夫人","en":"A princess is a female member of a royal family, usually the daughter of a king or queen or the wife of a prince.","ex":{"en":"Princess Anne topped the guest list.","cn":"安妮公主排在宾客名单之首。"}}]},"examples":[{"en":"Is something the matter, princess?","cn":"有什么事吗，大小姐？"},{"en":"Princess Michael of Kent","cn":"肯特郡迈克尔公爵夫人"}]},"pressing":{"media":{"uk":"media/uk/pressing__gb_1.mp3","us":"media/us/pressing__us_1.mp3"},"oxford":{"phon":"ˈpresɪŋ","pos":"adjective","senses":[{"en":"needing to be dealt with immediately","cn":"紧急的；急迫的","ex":{"en":"I'm afraid I have some pressing business to attend to.","cn":"很抱歉，我有些急事需要处理。"}},{"en":"difficult to refuse or to ignore","cn":"难以推却的；不容忽视的","ex":{"en":"a pressing invitation","cn":"难以推却的邀请"}},{"en":"an object, especially a record, made by using pressure or weight to shape a piece of metal, plastic, etc.; a number of such objects that are made at one time","cn":"模压制品，同批次的模压产品（尤指唱片）","ex":{"en":"The initial pressing of the group's album has already sold out.","cn":"这个乐队的首批专辑唱片已售罄。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧迫的；紧急的；急迫的","en":"A pressing problem, need, or issue has to be dealt with immediately.","ex":{"en":"It is one of the most pressing problems facing this country","cn":"这是该国面临的最紧迫的问题之一。"}}]},"examples":[{"en":"The initial pressing of the group's album has already sold out.","cn":"这个乐队的首批专辑唱片已售罄。"},{"en":"I'm afraid I have some pressing business to attend to.","cn":"很抱歉，我有些急事需要处理。"}],"base":"press"},"problematical":{"lemma":"problematic"},"prevention":{"media":{"uk":"media/uk/prevention__gb_1.mp3","us":"media/us/prevention__us_1.mp3"},"oxford":{"phon":"prɪˈvenʃn","pos":"noun","senses":[{"en":"the act of stopping something bad from happening","cn":"预防；防止；防范","ex":{"en":"accident/crime prevention","cn":"防止事故／犯罪"}}]},"examples":[{"en":"accident/crime prevention","cn":"防止事故/犯罪"},{"en":"the prevention of disease","cn":"疾病的预防"}]},"proportion":{"media":{"uk":"media/uk/proportion__gb_1.mp3","us":"media/us/proportion__us_1.mp3"},"oxford":{"phon":"prəˈpɔːʃn","pos":"noun","senses":[{"en":"a part or share of a whole","cn":"部分；份额","g":"[countable + singular or plural verb]","lab":"British English","sc":"part of whole","ex":{"en":"Water covers a large proportion of the earth's surface.","cn":"水覆盖了地球表面的大部分。"}},{"en":"the relationship of one thing to another in size, amount, etc.","cn":"比例；倍数关系","g":"[uncountable]","sc":"relationship","ex":{"en":"The proportion of men to women in the college has changed dramatically over the years.","cn":"近年来，这个学院的男女学生比例出现了剧变。"}},{"en":"the correct relationship in size, degree, importance, etc. between one thing and another or between the parts of a whole","cn":"正确的比例；均衡；匀称","g":"[uncountable, countable, usually plural]","lab":"figurative","sc":"relationship","ex":{"en":"You haven't drawn the figures in the foreground in proportion.","cn":"你的前景人物画得不合比例。"}},{"en":"the measurements of something; its size and shape","cn":"面积；体积；规模；程度","g":"[plural]","sc":"size/shape","ex":{"en":"This method divides the task into more manageable proportions.","cn":"这个方法把要完成的任务划分成较易操作的步骤。"}},{"en":"the equal relationship between two pairs of numbers, as in the statement ‘4 is to 8 as 6 is to 12’","cn":"等比关系；比例","g":"[uncountable]","sc":"mathematics"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分","en":"A proportion of a group or an amount is a part of it.","ex":{"en":"A large proportion of the dolphins in that area will eventually die","cn":"那片区域里的很大一部分海豚终将死去。"}},{"pos":"N-COUNT 可数名词","cn":"比例","en":"The proportion of one kind of person or thing in a group is the number of people or things of that kind compared to the total number of people or things in the group.","ex":{"en":"The proportion of women in the profession had risen to 17.3%","cn":"从事该职业的女性比例已升高到17.3%。"}},{"pos":"N-COUNT 可数名词","cn":"比例；比","en":"The proportion of one amount to another is the relationship between the two amounts in terms of how much there is of each thing.","ex":{"en":"Women's bodies tend to have a higher proportion of fat to water.","cn":"女性的身体内脂肪与水分的比例往往更高。"}},{"pos":"N-PLURAL 复数名词","cn":"（通常指极其巨大的事物的）大小，尺寸","en":"If you refer to the proportions of something, you are referring to its size, usually when this is extremely large.","ex":{"en":"In the tropics plants grow to huge proportions.","cn":"在热带，植物会长得非常高大。"}},{"pos":"N-PLURAL 复数名词","cn":"（艺术品或设计的各部分之间的）比例","en":"If you refer to the proportions in a work of art or design, you are referring to the relative sizes of its different parts.","ex":{"en":"You can vary the relative proportions of things in a picture very simply.","cn":"你能很简单地改变一幅画中事物的相对比例。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…成比例；与…相称；按照","en":"If one thing increases or decreases in proportion to another thing, it increases or decreases to the same degree as that thing.","ex":{"en":"The pressure in the cylinders would go up in proportion to the boiler pressure.","cn":"汽缸内的压力会随着汽锅压力的增加而相应增加。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…相比","en":"If something is small or large in proportion to something else, it is small or large when compared with that thing.","ex":{"en":"Children tend to have relatively larger heads than adults in proportion to the rest of their body.","cn":"与成人相比，儿童头部占整个身体的比例相对较大。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…极不成比例；与…完全不相称","en":"If you say that something is out of all proportion to something else, you think that it is far greater or more serious than it should be.","ex":{"en":"The punishment was out of all proportion to the crime.","cn":"罚不当罪。"}},{"pos":"PHRASE 短语","cn":"过于看重/正确看待","en":"If you get something out of proportion, you think it is more important or worrying than it really is. If you keep something in proportion, you have a realistic view of how important it is.","ex":{"en":"Everything just got blown out of proportion","cn":"所有一切都变得不可收拾了。"}},{"pos":"PHRASE 短语","cn":"区别轻重缓急的能力；分寸感；主次观念","en":"If someone has a sense of proportion, they know what is really important and what is not.","ex":{"en":"We must not lose our sense of proportion.","cn":"我们不能丧失主次观念。"}}]},"examples":[{"en":"This method divides the task into more manageable proportions.","cn":"这个方法把要完成的任务划分成较为易于操作的步骤。"},{"en":"The proportion of men to women in the college has changed dramatically over the years.","cn":"近年来，这个学院的男女学生比例出现了剧变。"}]},"prior":{"media":{"uk":"media/uk/prior__gb_1.mp3","us":"media/us/prior__us_1.mp3"},"oxford":{"phon":"ˈpraɪə(r)","pos":"adjective","senses":[{"en":"happening or existing before something else or before a particular time","cn":"先前的；较早的；在前的","ex":{"en":"Although not essential, some prior knowledge of statistics is desirable.","cn":"统计学的知识虽非必要，但最好是学过一点。"}},{"en":"already existing and therefore more important","cn":"优先的；占先的；较重要的","ex":{"en":"They have a prior claim to the property.","cn":"他们有权优先获得该处房产。"}},{"en":"before something","cn":"在…前面的","ex":{"en":"during the week prior to the meeting","cn":"在开会前的一周内"}},{"en":"a person who is in charge of a group of monks or nuns living in a priory","cn":"（小隐修院）院长","pos":"noun"},{"en":"(in an abbey) a person next in rank below an abbot or abbess","cn":"（隐修院）会长，副院长","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"先前的；在前的；在先的","en":"You use prior to indicate that something has already happened, or must happen, before another event takes place.","ex":{"en":"He claimed he had no prior knowledge of the protest","cn":"他声称自己事先并不知道这次抗议的事。"}},{"pos":"ADJ 形容词","cn":"（所有权、责任）更重要的，优先的","en":"A prior claim or duty is more important than other claims or duties and needs to be dealt with first.","ex":{"en":"The firm I wanted to use had prior commitments.","cn":"我想选用的这家公司已有约在先。"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"小修道院院长；大修道院副院长","en":"A prior is a monk who is in charge of a priory or a monk who is the second most important person in a monastery."},{"pos":"PREP-PHRASE 短语介词","cn":"在…之前；先于","en":"If something happens prior to a particular time or event, it happens before that time or event.","ex":{"en":"Prior to his Japan trip, he went to New York","cn":"在去日本之前，他去了纽约。"}}]},"examples":[{"en":"Although not essential, some prior knowledge of statistics is desirable.","cn":"统计学的知识虽非必要，但最好是学过一点。"},{"en":"This information must not be disclosed without prior written consent.","cn":"未事先征得书面许可，此消息不得泄露。"}]},"processed":{"lemma":"process","media":{"uk":"media/uk/process__gb_1.mp3","us":"media/us/process__us_1.mp3"}},"prompts":{"lemma":"prompt"},"prize":{"oxford":{"phon":"praɪz","pos":"noun","senses":[{"en":"an award that is given to a person who wins a competition, race, etc. or who does very good work","cn":"奖；奖赏；奖励；奖品；奖金","ex":{"en":"She was awarded the Nobel Peace Prize.","cn":"她获颁诺贝尔和平奖。"}},{"en":"something very important or valuable that is difficult to achieve or obtain","cn":"难能可贵的事物；难以争取的重要事物","ex":{"en":"World peace is the greatest prize of all.","cn":"世界和平是最可贵的。"}},{"en":"good enough to win a prize in a competition","cn":"好得足以得奖的；应获奖的","ex":{"en":"prize cattle","cn":"能获奖的牛"},"pos":"adjective"},{"en":"being a very good example of its kind","cn":"优秀的；典范性的；出类拔萃的","lab":"informal","ex":{"en":"a prize student","cn":"模范学生"},"pos":"adjective"},{"en":"to value something highly","cn":"珍视；高度重视","g":"[usually passive]","ex":{"en":"an era when honesty was prized above all other virtues","cn":"尊诚实为美德之首的时代"},"pos":"verb"},{"en":"to use force to separate something from something else","cn":"强行使分开；撬开","lab":"North American English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奖品；奖赏；奖金","en":"A prize is money or something valuable that is given to someone who has the best results in a competition or game, or as a reward for doing good work.","ex":{"en":"You must claim your prize by telephoning our claims line","cn":"您必须通过拨打我们的领奖电话来领取奖品。"}},{"pos":"ADJ 形容词","cn":"可以获奖的；获奖的","en":"You use prize to describe things that are of such good quality that they win prizes or deserve to win prizes.","ex":{"en":"...a prize bull.","cn":"获奖的公牛"}},{"pos":"N-COUNT 可数名词","cn":"非常珍贵的人（或物）；十分重要的人（或物）","en":"You can refer to someone or something as a prize when people consider them to be of great value or importance.","ex":{"en":"With no lands of his own, he was no great matrimonial prize.","cn":"他没有自己的地产，不是结婚的上佳人选。"}},{"pos":"VERB 动词","cn":"重视；珍惜","en":"Something that is prized is wanted and admired because it is considered to be very valuable or very good quality.","ex":{"en":"Military figures, made out of lead are prized by collectors","cn":"收藏家们对铅铸的军人塑像视若珍宝。"}},{"pos":"VERB 动词","cn":"撬；撬动；撬开；掰开","en":"If you prize something open or prize it away from a surface, you force it to open or force it to come away from the surface.","ex":{"en":"He tried to prize the dog's mouth open","cn":"他试图把这条狗的嘴掰开。"}},{"pos":"VERB 动词","cn":"竭力打探（消息等）；说服…透露（消息）","en":"If you prize something such as information out of someone, you persuade them to tell you although they may be very unwilling to.","ex":{"en":"Alison and I had to prize conversation out of him.","cn":"我和艾莉森只得从他口中撬出谈话内容。"}}]},"media":{"uk":"media/uk/prize__gb_1.mp3","us":"media/us/prize__us_1.mp3"},"examples":[{"en":"Oil of cedarwood is highly prized for its use in perfumery.","cn":"雪松油可用于制香水，因此十分珍贵。"},{"en":"Win a car in our grand prize draw!","cn":"参加我们的大抽奖，赢取一辆汽车！"}]},"process":{"media":{"uk":"media/uk/process__gb_1.mp3","us":"media/us/process__us_1.mp3"},"oxford":{"phon":"ˈprəʊses","pos":"noun","senses":[{"en":"a series of things that are done in order to achieve a particular result","cn":"（为达到某一目标的）过程；进程","ex":{"en":"the consultation/planning process","cn":"咨询／策划过程"}},{"en":"a series of things that happen, especially ones that result in natural changes","cn":"（事物发展，尤指自然变化的）过程，步骤，流程","ex":{"en":"It's a normal part of the learning process.","cn":"那是学习过程中的正常现象。"}},{"en":"a method of doing or making something, especially one that is used in industry","cn":"做事方法；工艺流程；工序","ex":{"en":"manufacturing processes","cn":"制造方法"}},{"en":"to treat raw material, food, etc. in order to change it, preserve it, etc.","cn":"加工；处理","g":"[often passive]","ex":{"en":"Most of the food we buy is processed in some way.","cn":"我们买的大部分食品都用某种方法加工过。"},"pos":"verb"},{"en":"to deal officially with a document, request, etc.","cn":"审阅，审核，处理（文件、请求等）","g":"[often passive]","ex":{"en":"It will take a week for your application to be processed.","cn":"审核你的申请需要一周时间。"},"pos":"verb"},{"en":"to perform a series of operations on data in a computer","cn":"数据处理","g":"[often passive]","lab":"computing","ex":{"en":"The image is processed digitally by computer software.","cn":"这一图像已经过计算机软件数字化处理。"},"pos":"verb"},{"en":"to understand the meaning of something that has happened or been said","cn":"理解；弄明白","ex":{"en":"My brain slowly processed the fact that I was free to leave.","cn":"我的大脑慢慢明白过来，我可以自由离开了。"},"pos":"verb"},{"en":"to walk or move along slowly in, or as if in, a procession","cn":"列队行进；缓缓前进","ex":{"en":"The bishop, priests and deacons processed slowly through the cathedral.","cn":"主教、神父和执事缓慢地穿过大教堂。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"过程；进程","en":"A process is a series of actions which are carried out in order to achieve a particular result.","ex":{"en":"There was total agreement to start the peace process as soon as possible","cn":"全体一致同意尽快开始和平进程。"}},{"pos":"N-COUNT 可数名词","cn":"（生物或化学的）变化过程","en":"A process is a series of things which happen naturally and result in a biological or chemical change.","ex":{"en":"It occurs in elderly men, apparently as part of the ageing process","cn":"这种情况出现在老年人当中，显然是衰老过程的一部分。"}},{"pos":"VERB 动词","cn":"加工；处理","en":"When raw materials or foods are processed, they are prepared in factories before they are used or sold.","ex":{"en":"...fish which are processed by freezing, canning or smoking","cn":"经过冷冻、罐装或熏制处理的鱼"}},{"pos":"VERB 动词","cn":"处理（信息）","en":"When people process information, they put it through a system or into a computer in order to deal with it.","ex":{"en":"...facilities to process the data, and the right to publish the results","cn":"处理数据的设备和公开其结果的权利"}},{"pos":"VERB 动词","cn":"审核；审议；检查；使接受处理","en":"When people are processed by officials, their case is dealt with in stages and they pass from one stage of the process to the next.","ex":{"en":"Patients took more than two hours to be processed through the department.","cn":"病人在这个科看病需要两个多小时的时间。"}},{"pos":"PHRASE 短语","cn":"在…的过程中；正在做","en":"If you are in the process of doing something, you have started to do it and are still doing it.","ex":{"en":"The administration is in the process of drawing up a peace plan","cn":"政府正在起草和平计划。"}},{"pos":"PHRASE 短语","cn":"在此过程中；与此同时","en":"If you are doing something and you do something else in the process, you do the second thing as part of doing the first thing.","ex":{"en":"He finished ahead of the Spaniard, and in the process picked up his first time trial win as a pro","cn":"他领先那个西班牙人到达终点，同时也首次作为职业选手获得计时赛的胜利。"}}]},"examples":[{"en":"Most of the food we buy is processed in some way.","cn":"我们买的大部分食品都用某种方法加工过。"},{"en":"I'm afraid getting things changed will be a slow process.","cn":"做任何改革恐怕都会是个缓慢的过程。"}]},"prestige":{"media":{"uk":"media/uk/prestige__gb_1.mp3","us":"media/us/prestige__us_1.mp3"},"oxford":{"phon":"preˈstiːʒ","pos":"noun","senses":[{"en":"the respect and value that somebody/something has because of their social position, or what they have done","cn":"威信；声望；威望","ex":{"en":"personal prestige","cn":"个人声望"}},{"en":"that brings respect and importance","cn":"令人敬仰的；受尊重的；重要的","ex":{"en":"a prestige job","cn":"体面的工作"},"pos":"adjective"},{"en":"admired and respected because it looks important and expensive","cn":"名贵的；贵重的；讲究派头的","ex":{"en":"a prestige car","cn":"豪华的汽车"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"声望；威望；威信","en":"If a person, a country, or an organization has prestige, they are admired and respected because of the position they hold or the things they have achieved.","ex":{"en":"...efforts to build up the prestige of the United Nations","cn":"为树立联合国的威望所作的努力"}},{"pos":"ADJ 形容词","cn":"气派的；贵重的；令人敬仰的","en":"Prestige is used to describe products, places, or activities which people admire because they are associated with being rich or having a high social position.","ex":{"en":"...such prestige cars as Cadillac, Mercedes, Porsche and Jaguar.","cn":"像凯迪拉克、奔驰、保时捷和捷豹这样气派的汽车"}}]},"examples":[{"en":"There is a lot of prestige attached to owning a car like this.","cn":"拥有这样一部汽车会显得很气派。"},{"en":"jobs with low prestige","cn":"地位低微的工作"}]},"printing":{"media":{"uk":"media/uk/printing__gb_1.mp3","us":"media/us/printing__us_1.mp3"},"oxford":{"phon":"ˈprɪntɪŋ","pos":"noun","senses":[{"en":"the act of producing letters, pictures, patterns, etc. on something by pressing a surface covered with ink (= coloured liquid for printing, drawing, etc.) against it","cn":"印刷；印刷术","g":"[uncountable]","ex":{"en":"the invention of printing","cn":"印刷术的发明"}},{"en":"the act of printing a number of copies of a book at one time","cn":"（书籍的）一次印刷","g":"[countable]","ex":{"en":"The book is in its sixth printing.","cn":"这本书是第六次印刷了。"}},{"en":"a type of writing when you write all the letters separately and do not join them together","cn":"印刷字体","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书籍的）一次印刷","en":"If copies of a book are printed and published on a number of different occasions, you can refer to each of these occasions as a printing.","ex":{"en":"The American edition of 'Cloud Street' is already in its third printing.","cn":"美国版的《云街》已经是第三次印刷了。"}}]},"examples":[{"en":"The book is in its sixth printing.","cn":"这本书是第六次印刷了。"},{"en":"the invention of printing","cn":"印刷术的发明"}],"base":"print"},"primarily":{"media":{"uk":"media/uk/primarily__gb_1.mp3","us":"media/us/primarily__us_1.mp3"},"oxford":{"phon":"praɪˈmerəli","pos":"adverb","senses":[{"en":"mainly","cn":"主要地","ex":{"en":"a course designed primarily for specialists","cn":"主要为专业人员开设的课程"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"主要地；根本地","en":"You use primarily to say what is mainly true in a particular situation.","ex":{"en":"...a book aimed primarily at high-energy physicists","cn":"一本主要针对高能物理学家的书"}}]},"examples":[{"en":"The problem is not primarily a financial one.","cn":"这个问题基本上不是财政问题。"},{"en":"a course designed primarily for specialists","cn":"主要为专业人员开设的课程"}]},"project":{"media":{"uk":"media/uk/project__gb_1.mp3","us":"media/us/project__us_1.mp3"},"oxford":{"phon":"ˈprɒdʒekt","pos":"noun","senses":[{"en":"a piece of work involving careful study of a subject over a period of time, done by school or college students","cn":"（大、中学学生的）专题研究","sc":"school/college work","ex":{"en":"a history project","cn":"历史科的专题研究"}},{"en":"a planned piece of work that is designed to find information about something, to produce something new, or to improve something","cn":"生产（或研究等）项目；方案；工程","sc":"planned work","ex":{"en":"We worked on various projects together.","cn":"我们一起参与了多个项目。"}},{"en":"a set of aims, ideas or activities that somebody is interested in or wants to bring to people’s attention","cn":"方案；计划","sc":"set of aims/activities","ex":{"en":"The party attempted to assemble its aims into a focused political project.","cn":"这个党试图把订立的目标整合为一个政治方案。"}},{"en":"a group of houses or apartments built for poor families, usually with government money","cn":"公房项目；公房区（常由政府为贫困家庭建造）","lab":"North American English","sc":"housing","ex":{"en":"Going into the projects alone can be dangerous.","cn":"独自进入公共住房区会有危险。"}},{"en":"to estimate what the size, cost or amount of something will be in the future based on what is happening now","cn":"预测；预计；推想","g":"[transitive, usually passive]","sc":"estimate","ex":{"en":"A growth rate of 4 per cent is projected for next year.","cn":"预计明年的增长率为 4%。"},"pos":"verb"},{"en":"to plan an activity, a project etc. for a time in the future","cn":"规划；计划；拟订方案","g":"[transitive, usually passive]","sc":"plan","ex":{"en":"The next edition of the book is projected for publication in March.","cn":"本书的下一版计划于三月发行。"},"pos":"verb"},{"en":"to make light, an image, etc. fall onto a flat surface or screen","cn":"放映；投射；投影","g":"[transitive]","sc":"light/image","ex":{"en":"They projected the digital image onto the model's surface.","cn":"他们将数字图像投影到模型表面。"},"pos":"verb"},{"en":"to stick out beyond an edge or a surface","cn":"突出；外伸；伸出","g":"[intransitive]","sc":"stick out","ex":{"en":"a building with balconies projecting out over the street","cn":"有临街凸阳台的楼房"},"pos":"verb"},{"en":"to present somebody/something/yourself to other people in a particular way, especially one that gives a good impression","cn":"展现；表现；确立（好印象）","g":"[transitive]","sc":"present yourself","ex":{"en":"They sought advice on how to project a more positive image of their company.","cn":"他们就如何树立公司更正面的形象征询意见。"},"pos":"verb"},{"en":"to send or throw something up or away from yourself","cn":"投掷；抛射；发送","g":"[transitive]","lab":"figurative","sc":"send/throw up or away","ex":{"en":"Actors must learn to project their voices.","cn":"演员必须学会放开声音。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"项目；工程；计划；规划","en":"A project is a task that requires a lot of time and effort.","ex":{"en":"Money will also go into local development projects in Vietnam","cn":"钱也会用于越南的地方发展项目当中。"}},{"pos":"N-COUNT 可数名词","cn":"（学生的）课题，研究项目","en":"A project is a detailed study of a subject by a pupil or student.","ex":{"en":"Students complete projects for a personal tutor, working at home at their own pace.","cn":"学生完成了做私人家教的课题，在家里按自己的步调工作。"}},{"pos":"VERB 动词","cn":"规划；计划；预计","en":"If something is projected, it is planned or expected.","ex":{"en":"Africa's mid-1993 population is projected to more than double by 2025","cn":"预计到2025年，非洲的人口会是1993年年中人口的两倍多。"}},{"pos":"VERB 动词","cn":"（使）呈现；（使）表现；（使）展现","en":"If you project someone or something in a particular way, you try to make people see them in that way. If you project a particular feeling or quality, you show it in your behaviour.","ex":{"en":"Bradley projects a natural warmth and sincerity","cn":"布拉德利表现出一种自然的热情和真诚。"}},{"pos":"VERB 动词","cn":"把（情感、想法）投射转移（到他人身上）","en":"If you project feelings or ideas on to other people, you imagine that they have the same ideas or feelings as you.","ex":{"en":"He projects his own thoughts and ideas onto her.","cn":"他以为她有着和自己相同的想法和观点。"}},{"pos":"VERB 动词","cn":"投射；放映","en":"If you project a film or picture onto a screen or wall, you make it appear there.","ex":{"en":"The team tried projecting the maps with two different projectors onto the same screen.","cn":"这个小组想用两台不同的投影仪把这些地图投射到同一个屏幕上。"}},{"pos":"VERB 动词","cn":"伸出；凸出","en":"If something projects, it sticks out above or beyond a surface or edge.","ex":{"en":"...the remains of a war-time defence which projected out from the shore.","cn":"海滨凸立着的战时防御工事的遗迹"}}]},"examples":[{"en":"The party attempted to assemble its aims into a focussed political project.","cn":"这个党试图把订立的目标综合为一个政治方案。"},{"en":"They sought advice on how to project a more positive image of their company.","cn":"他们就如何加强树立公司的形象征询意见。"}]},"pretense":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of pretence pretence","cn":"的美式拼法"}]},"media":{"uk":"media/uk/pretense__gb_1.mp3","us":"media/us/pretense__us_1.mp3"},"oxford":{"phon":"prɪˈtens","pos":"noun","senses":[{"en":"the act of behaving in a particular way, in order to make other people believe something that is not true","cn":"假象；伪装；虚伪的表现","g":"[uncountable, singular]","ex":{"en":"Their friendliness was only pretense.","cn":"他们的友善只是假装的。"}},{"en":"a claim that you have a particular quality or skill","cn":"妄称；自称；标榜","g":"[uncountable, countable, usually singular]","lab":"formal or literary","ex":{"en":"A judge should have at least some pretense to objectivity.","cn":"法官至少应该有一定程度的客观性。"}}]}},"protests":{"lemma":"protest","media":{"uk":"media/uk/protest__gb_1.mp3","us":"media/us/protest__us_1.mp3"}},"privacy":{"oxford":{"phon":"ˈprɪvəsi","pos":"noun","senses":[{"en":"the state of being alone and not watched or interrupted by other people","cn":"独处；私密；不受打扰","ex":{"en":"She was longing for some peace and privacy.","cn":"她渴望过清静的私人生活。"}},{"en":"the state of being free from the attention of the public","cn":"隐私","ex":{"en":"freedom of speech and the right to privacy","cn":"言论自由与隐私权"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"隐私；独处；清静","en":"If you have privacy, you are in a place or situation which allows you to do things without other people seeing you or disturbing you.","ex":{"en":"He saw the publication of this book as an embarrassing invasion of his privacy","cn":"他觉得这本书的出版侵犯了他的私生活，让他十分难堪。"}},{"pos":"PHRASE 短语","cn":"干扰…的生活；侵犯…的隐私","en":"If someone or something invades your privacy, they interfere in your life without your permission.","ex":{"en":"The press invade people's privacy unjustifiably every day.","cn":"每天媒体都会毫无道理地干扰人们的生活。"}}]},"media":{"uk":"media/uk/privacy__gb_1.mp3","us":"media/us/privacy__us_1.mp3"},"examples":[{"en":"He read the letter later in the privacy of his own room.","cn":"稍后，他在自己房间里私下读了那封信。"},{"en":"She was longing for some peace and privacy.","cn":"她渴望过清静的私人生活。"}]},"procedure":{"media":{"uk":"media/uk/procedure__gb_1.mp3","us":"media/us/procedure__us_1.mp3"},"oxford":{"phon":"prəˈsiːdʒə(r)","pos":"noun","senses":[{"en":"a way of doing something, especially the usual or correct way","cn":"（正常）程序，手续，步骤","g":"[countable, uncountable]","ex":{"en":"emergency/safety/disciplinary procedures","cn":"紧急状况／安全事务／纪律问题的处理程序"}},{"en":"the official or formal order or way of doing something, especially in business, law or politics","cn":"（商业、法律或政治上的）程序","g":"[uncountable]","ex":{"en":"court/legal/parliamentary procedure","cn":"法庭／司法／议会程序"}},{"en":"a medical operation","cn":"手术","g":"[countable]","lab":"medical","ex":{"en":"a routine surgical procedure","cn":"普通的外科手术"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"程序；步骤；手续","en":"A procedure is a way of doing something, especially the usual or correct way.","ex":{"en":"A biopsy is usually a minor surgical procedure","cn":"活组织检查通常是一个很小的外科手术。"}}]},"examples":[{"en":"Making a complaint is quite a simple procedure.","cn":"申诉的手续相当简单。"},{"en":"to perform a routine surgical procedure","cn":"做常规的外科手术"}]},"processing":{"oxford":{"phon":"ˈprəʊsesɪŋ","pos":"noun","senses":[{"en":"the treatment of raw material, food, etc. in order to change it, preserve it, etc.","cn":"加工；处理","ex":{"en":"the food processing industry","cn":"食品加工业"}},{"en":"the process of dealing officially with a document, request, etc.","cn":"（对文件、请求等的）审阅，审核，处理","ex":{"en":"errors in the processing of financial transactions","cn":"金融交易处理中的错误"}}]},"media":{"uk":"media/uk/processing__gb_1.mp3","us":"media/us/processing__us_1.mp3"},"examples":[{"en":"the food processing industry","cn":"食品加工业"}],"base":"process"},"practice":{"media":{"uk":"media/uk/practice__gb_1.mp3","us":"media/us/practice__us_1.mp3"},"oxford":{"phon":"ˈpræktɪs","pos":"noun","senses":[{"en":"doing an activity or training regularly so that you can improve your skill; the time you spend doing this","cn":"训练；练习（时间）","g":"[uncountable, countable]","sc":"for improving skill","ex":{"en":"conversation practice","cn":"会话练习"}},{"en":"action rather than ideas","cn":"实践；实际行动","g":"[uncountable]","sc":"action not ideas","ex":{"en":"the theory and practice of teaching","cn":"教学的理论与实践"}},{"en":"a way of doing something that is the usual or expected way in a particular organization or situation","cn":"通常的做法；惯例；常规","g":"[uncountable, countable]","sc":"way of doing something","ex":{"en":"Wearing gloves should be standard practice when handling pesticides.","cn":"处理农药时戴手套应该是标准做法。"}},{"en":"a thing that is done regularly; a habit or a custom","cn":"惯常做的事；习惯；习俗","g":"[countable]","sc":"habit/custom","ex":{"en":"the German practice of giving workers a say in how their company is run","cn":"德国人在公司经营上给予工人发言权的做法"}},{"en":"the work or the business of some professional people such as doctors, dentists and lawyers; the place where they work","cn":"（医生、律师的）工作，业务活动，工作地点","g":"[uncountable, countable]","sc":"of doctor/lawyer","ex":{"en":"the practice of medicine","cn":"行医"}},{"en":"to do an activity or train regularly so that you can improve your skill","cn":"练习；实习；训练","g":"[intransitive, transitive]","ex":{"en":"to practice the piano every day","cn":"每天练习弹钢琴"},"pos":"verb"},{"en":"to work as a doctor, lawyer, etc.","cn":"从事（医务、法律工作等）；执业","g":"[intransitive, transitive]","ex":{"en":"She's practicing medicine in Philadelphia.","cn":"她在费城行医。"},"pos":"verb"},{"en":"to do something regularly as part of your normal behaviour","cn":"经常做；养成…的习惯","g":"[transitive]","lab":"formal","ex":{"en":"to practice self-restraint/safe sex","cn":"实行自我克制/安全性行为"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"通常做法；常规；惯例","en":"You can refer to something that people do regularly as a practice .","ex":{"en":"Some firms have cut workers' pay below the level set in their contract, a practice that is illegal in Germany","cn":"一些公司把工人薪水减至低于合同规定的水平，这种做法在德国是非法的。"}},{"pos":"N-VAR 可变名词","cn":"练习；训练","en":"Practice means doing something regularly in order to be able to do it better. A practice is one of these periods of doing something.","ex":{"en":"She was taking all three of her daughters to basketball practice every day","cn":"她每天都带3个女儿进行篮球训练。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（医生或律师的）业务活动，工作；宗教活动","en":"The work done by doctors and lawyers is referred to as the practice of medicine and law. People's religious activities are referred to as the practice of a religion.","ex":{"en":"...the practice of internal medicine","cn":"内科业务"}},{"pos":"N-COUNT 可数名词","cn":"诊所；律师事务所","en":"A doctor's or lawyer's practice is his or her business, often shared with other doctors or lawyers.","ex":{"en":"The new doctor's practice was miles away from where I lived","cn":"新开的诊所离我住的地方有几英里远。"}},{"pos":"PHRASE 短语","cn":"事实上；实际上","en":"What happens in practice is what actually happens, in contrast to what is supposed to happen.","ex":{"en":"...the difference between foreign policy as presented to the public and foreign policy in actual practice","cn":"公布于众的外交政策和实际外交政策的区别"}},{"pos":"PHRASE 短语","cn":"惯例；常规；一般做法","en":"If something such as a procedure is normal practice or standard practice, it is the usual thing that is done in a particular situation.","ex":{"en":"It is normal practice not to reveal details of a patient's condition","cn":"不透露患者病情的细节是惯常的做法。"}},{"pos":"PHRASE 短语","cn":"疏于练习；荒疏；荒废","en":"If you are out of practice at doing something, you have not had much experience of it recently, although you used to do it a lot or be quite good at it.","ex":{"en":"'How's your German?' — 'Not bad, but I'm out of practice.'","cn":"“你的德语如何？”——“还行，只是长时间没练习了。”"}},{"pos":"PHRASE 短语","cn":"熟能生巧","en":"If you say 'practice makes perfect ', you mean that it is possible to learn something or develop a skill if you practise enough. People often say this to encourage someone to keep practising."},{"pos":"PHRASE 短语","cn":"实施；实行；实践","en":"If you put a belief or method into practice, you behave or act in accordance with it.","ex":{"en":"Now that he is back, the prime minister has another chance to put his new ideas into practice","cn":"既然首相又掌权了，他就重新有机会实施他的新想法。"}}]},"examples":[{"en":"Prisoners have legal rights, but in practice these rights are not always respected.","cn":"囚犯虽有合法的权利，但实际上这些权利常未受到尊重。"},{"en":"the German practice of giving workers a say in how their company is run","cn":"德国人在公司经营上给予工人发言权的做法"}]},"preoccupy":{"oxford":{"phon":"priˈɒkjupaɪ","pos":"verb","senses":[{"en":"if something is preoccupying you, you think or worry about it very often or all the time","cn":"使日夜思考；使忧心忡忡","ex":{"en":"Thoughts of failure preoccupied him.","cn":"他全神贯注于失败的念头。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使全神贯注；使入神；占据…的思想","en":"If something is preoccupying you, you are thinking about it a lot.","ex":{"en":"Crime and the fear of crime preoccupy the community.","cn":"犯罪和对犯罪的恐惧一直困扰着这个社区。"}}]},"media":{"uk":"media/uk/preoccupy__gb_1.mp3","us":"media/us/preoccupy__us_1.mp3"}},"profitable":{"media":{"uk":"media/uk/profitable__gb_1.mp3","us":"media/us/profitable__us_1.mp3"},"oxford":{"phon":"ˈprɒfɪtəbl","pos":"adjective","senses":[{"en":"that makes or is likely to make money","cn":"有利润的；赢利的","ex":{"en":"a highly profitable business","cn":"一家赢利很高的企业"}},{"en":"that gives somebody an advantage or a useful result","cn":"有益的；有好处的","ex":{"en":"a profitable experience","cn":"一次有利可图的经历"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"盈利的；有利润的；赚钱的","en":"A profitable organization or practice makes a profit.","ex":{"en":"Drug manufacturing is the most profitable business in America","cn":"制药业是美国利润最丰厚的业务。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利可图的；有益的；有用的","en":"Something that is profitable results in some benefit for you.","ex":{"en":"...collaboration which leads to a profitable exchange of personnel and ideas.","cn":"有利于人员和观念交流的合作"}}]},"examples":[{"en":"She spent a profitable afternoon in the library.","cn":"她在图书馆待了一个下午，颇有收获。"},{"en":"It is usually more profitable to sell direct to the public.","cn":"向社会大众直销往往获利较高。"}]},"pressure":{"media":{"uk":"media/uk/pressure__gb_1.mp3","us":"media/us/pressure__us_1.mp3"},"oxford":{"phon":"ˈpreʃə(r)","pos":"noun","senses":[{"en":"the act of trying to persuade or to force somebody to do something","cn":"催促；要求；呼吁；强迫","g":"[uncountable]","sc":"persuasion/force","ex":{"en":"The pressure for change continued to mount.","cn":"改革的呼声越来越高。"}},{"en":"difficulties and worries that are caused by the need to achieve or to behave in a particular way","cn":"心理压力；紧张","g":"[uncountable]","sc":"stress","ex":{"en":"You need to be able to handle pressure in this job.","cn":"做这工作要能承受压力。"}},{"en":"the force or weight with which something presses against something else","cn":"压力；挤压","g":"[uncountable]","sc":"when something presses","ex":{"en":"The nurse applied pressure to his arm to stop the bleeding.","cn":"护士压住他的胳膊止血。"}},{"en":"the force produced by a particular amount of gas or liquid in a container or a limited space; the amount of this","cn":"气压；水压；压力；压强","g":"[uncountable, countable]","sc":"of gas/liquid","ex":{"en":"air/water pressure","cn":"空气／水的压力"}},{"en":"the effect that something has on the way a situation develops, especially when this causes problems","cn":"（坏）影响","g":"[uncountable]","sc":"effect on something","ex":{"en":"This puts upward pressure on prices.","cn":"这会使价格上涨。"}},{"en":"the force of the atmosphere on the earth’s surface","cn":"大气压","g":"[uncountable]","sc":"of atmosphere","ex":{"en":"A band of high/low pressure is moving across the country.","cn":"一股高／低气压正经过这个国家。"}},{"en":"to persuade somebody to do something, especially by making them feel that they have to or should do it","cn":"逼迫；使迫不得已","ex":{"en":"No one has the right to pressure you. You can always say no.","cn":"没人有权逼你，你什么时候都可以说“不”。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"压力","en":"Pressure is force that you produce when you press hard on something.","ex":{"en":"She kicked at the door with her foot, and the pressure was enough to open it","cn":"她用脚踢门，力气之大足以把门踹开。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"压力；气压；压强","en":"The pressure in a place or container is the force produced by the quantity of gas or liquid in that place or container.","ex":{"en":"The window in the cockpit had blown in and the pressure dropped dramatically","cn":"驾驶舱的窗户突然向内破裂，气压急剧降低。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（向某人施加的）压力","en":"If there is pressure on a person, someone is trying to persuade or force them to do something.","ex":{"en":"He may have put pressure on her to agree","cn":"他可能向她施加了压力，迫使她同意。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（工作等的）压力","en":"If you are experiencing pressure, you feel that you must do a lot of tasks or make a lot of decisions in very little time, or that people expect a lot from you.","ex":{"en":"Can you work under pressure?","cn":"你能在压力下工作吗？"}},{"pos":"VERB 动词","cn":"强迫；迫使；竭力劝说","en":"If you pressure someone to do something, you try forcefully to persuade them to do it.","ex":{"en":"He will never pressure you to get married","cn":"他永远不会强迫你结婚。"}}]},"examples":[{"en":"Teenagers may find it difficult to resist peer pressure.","cn":"青少年可能觉得很难抗拒同侪的压力。"},{"en":"How can anyone enjoy the pressures of city life?","cn":"怎么会有人喜欢都市生活的压力呢？"}]},"present":{"media":{"uk":"media/uk/present__gb_1.mp3","us":"media/us/present__us_1.mp3","img":["media/ldoce/img/christmas_present.jpg"]},"oxford":{"phon":"ˈpreznt","pos":"adjective","senses":[{"en":"existing or happening now","cn":"现存的；当前的","g":"[only before noun]","ex":{"en":"I am not satisfied with the present situation.","cn":"我对现状不满意。"}},{"en":"being in a particular place","cn":"在场；出席","g":"[not before noun]","ex":{"en":"I wasn’t present when the doctor examined him.","cn":"医生给他做检查时我不在场。"}},{"en":"existing in a particular place or thing","cn":"存在","g":"[not before noun]","ex":{"en":"The threat of force was always present.","cn":"武力威胁一直存在。"}},{"en":"a thing that you give to somebody as a gift","cn":"礼物；礼品","ex":{"en":"What can I get him for a birthday present?","cn":"我给他送点什么生日礼物呢？"},"pos":"noun"},{"en":"the time now","cn":"目前；现在","g":"[singular]","ex":{"en":"You've got to forget the past and start living in the present.","cn":"你必须忘掉过去，开始把握现在。"},"pos":"noun"},{"en":"the form of a verb that expresses an action that is happening now or at the time of speaking","cn":"现在时；现在式","g":"[singular]","lab":"grammar","pos":"noun"},{"en":"to show or offer something for other people to look at or consider","cn":"提出；提交","sc":"something to be considered","ex":{"en":"Are you presenting a paper at the conference?","cn":"你会在研讨会上发表论文吗？"},"pos":"verb"},{"en":"to give something to somebody, especially formally at a ceremony","cn":"把…交给；颁发；授予","sc":"give","ex":{"en":"The local MP will start the race and present the prizes.","cn":"当地议员将鸣枪开赛，并颁发奖品。"},"pos":"verb"},{"en":"to show or describe something/somebody in a particular way","cn":"（以某种方式）展现，显示，表现","sc":"something in particular way","ex":{"en":"The company has decided it must present a more modern image.","cn":"公司已决定，必须展现出更加现代的形象。"},"pos":"verb"},{"en":"to cause something to happen or be experienced","cn":"使发生；使经历","sc":"problem/opportunity","ex":{"en":"The course presents an excellent learning opportunity.","cn":"该课程提供了一个极好的学习机会。"},"pos":"verb"},{"en":"to suddenly happen or become available","cn":"突然出现；显露；产生","sc":"itself","ex":{"en":"One major problem did present itself, though.","cn":"不过，确实出现了一个重大问题。"},"pos":"verb"},{"en":"to appear in a radio or television programme and introduce the different items in it","cn":"主持播放；主持（节目）","lab":"British English","sc":"radio/TV programme","ex":{"en":"She used to present a gardening programme on TV.","cn":"她曾在电视上主持一个园艺节目。"},"pos":"verb"},{"en":"to produce a show, play, broadcast, etc. for the public","cn":"上演；公演；推出","sc":"play/broadcast","ex":{"en":"Compass Theatre Company presents a new production of ‘King Lear’.","cn":"罗经剧团推出了全新制作的《李尔王》。"},"pos":"verb"},{"en":"to introduce somebody formally, especially to somebody of higher rank or status","cn":"正式介绍；引见","lab":"formal","sc":"introduce somebody","ex":{"en":"May I present my fiancé to you?","cn":"请允许我向您介绍我的未婚夫。"},"pos":"verb"},{"en":"to officially appear somewhere","cn":"正式出席；莅临；出现","lab":"formal","sc":"yourself","ex":{"en":"You will be asked to present yourself for interview.","cn":"将请你到场面试。"},"pos":"verb"},{"en":"to offer or express something in speech or writing","cn":"（口头或书面）表达，表示","lab":"formal","sc":"express something","ex":{"en":"Please allow me to present my apologies.","cn":"请允许我致歉。"},"pos":"verb"},{"en":"to give somebody a cheque or bill that they should pay","cn":"交付；提交","sc":"cheque/bill","ex":{"en":"A cheque presented by Mr Jackson was returned by the bank.","cn":"银行退回了杰克逊先生提交的支票。"},"pos":"verb"},{"en":"to have or show particular symptoms","cn":"出现病症,呈现症状","g":"[intransitive, transitive]","lab":"medical","sc":"medical","ex":{"en":"The patient presented with a chest complaint.","cn":"患者出现胸部不适。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"现在的；目前的","en":"You use present to describe things and people that exist now, rather than those that existed in the past or those that may exist in the future.","ex":{"en":"He has brought much of the present crisis on himself","cn":"目前的大部分危机都是他自己引起的。"}},{"pos":"N-SING 单数名词","cn":"现在；目前；现状","en":"The present is the period of time that we are in now and the things that are happening now.","ex":{"en":"...his struggle to reconcile the past with the present.","cn":"他为协调过去和现在所付出的努力。"}},{"pos":"ADJ 形容词","cn":"现在时的；现在式的","en":"In grammar, the present tenses of a verb are the ones that are used to talk about things that happen regularly or situations that exist at this time. The simple present tense uses the base form or the 's' form of a verb, as in 'I play tennis twice a week' and 'He works in a bank'."},{"pos":"PHRASE 短语","cn":"目前；现在；眼下","en":"A situation that exists at present exists now, although it may change.","ex":{"en":"There is no way at present of predicting which individuals will develop the disease","cn":"目前还没有办法预测谁会得这种病。"}},{"pos":"PHRASE 短语","cn":"当代；现代","en":"The present day is the period of history that we are in now.","ex":{"en":"...Western European art from the period of Giotto to the present day.","cn":"从乔托时期直至现代的西欧艺术"}},{"pos":"PHRASE 短语","cn":"暂时；暂且","en":"Something that exists or will be done for the present exists now or will continue for a while, although the situation may change later.","ex":{"en":"The ministers had expressed the unanimous view that sanctions should remain in place for the present.","cn":"大臣们一致认为暂时还不能取消制裁。"}},{"pos":"PHRASE 短语","cn":"机不可失，失不再来；就在当下","en":"If you say 'There's no time like the present', you are suggesting to someone that they should do something now, not later.","ex":{"en":"Don't wait until New Year to resolve to organise your life. There's no time like the present.","cn":"不要等到新年才下决心规划生活。要把握当下。"}},{"pos":"ADJ 形容词","cn":"出席的；在场的","en":"If someone is present at an event, they are there.","ex":{"en":"The president was not present at the meeting","cn":"总裁没有出席这次会议。"}},{"pos":"ADJ 形容词","cn":"（尤指物质、疾病）存在于…的，包含于…的","en":"If something, especially a substance or disease, is present in something else, it exists within that thing.","ex":{"en":"This special form of vitamin D is naturally present in breast milk","cn":"这种特殊形态的维生素D天然存在于母乳中。"}},{"pos":"N-COUNT 可数名词","cn":"礼物；礼品","en":"A present is something that you give to someone, for example at Christmas or when you visit them.","ex":{"en":"The carpet was a wedding present from the Prime Minister","cn":"这张地毯是首相送的结婚礼物。"}},{"pos":"VERB 动词","cn":"颁发；授予；呈献；呈递","en":"If you present someone with something such as a prize or document, or if you present it to them, you formally give it to them.","ex":{"en":"The mayor presented him with a gold medal at an official city reception","cn":"市长在一次正式的市政招待会上给他颁发了一枚金质奖章。"}},{"pos":"VERB 动词","cn":"引起；导致；带来；提供","en":"If something presents a difficulty, challenge, or opportunity, it causes it or provides it.","ex":{"en":"This presents a problem for many financial consumers","cn":"这给很多金融消费者带来了一个问题。"}},{"pos":"VERB 动词","cn":"（机会或问题）产生，意外出现","en":"If an opportunity or problem presents itself, it occurs, often when you do not expect it.","ex":{"en":"Their colleagues insulted them whenever the opportunity presented itself","cn":"一有机会，同事们就会侮辱他们。"}},{"pos":"VERB 动词","cn":"呈现；展示；陈述","en":"When you present information, you give it to people in a formal way.","ex":{"en":"We spend the time collating and presenting the information in a variety of chart forms","cn":"我们花费时间用各种各样的图表来比照和展示这些信息。"}},{"pos":"VERB 动词","cn":"描述；形容","en":"If you present someone or something in a particular way, you describe them in that way.","ex":{"en":"The government has presented these changes as major reforms","cn":"政府将这些变化描述为重大的改革。"}},{"pos":"VERB 动词","cn":"（通过言行举止）表现（自己）","en":"The way you present yourself is the way you speak and act when meeting new people.","ex":{"en":"...all those tricks which would help him to present himself in a more confident way in public.","cn":"能使他在公众面前表现得更为自信的那些窍门"}},{"pos":"VERB 动词","cn":"表现；展现","en":"If someone or something presents a particular appearance or image, that is how they appear or try to appear.","ex":{"en":"The small group of onlookers presented a pathetic sight","cn":"这一小群旁观者看上去让人觉得悲哀。"}},{"pos":"VERB 动词","cn":"出席；到场","en":"If you present yourself somewhere, you officially arrive there, for example for an appointment.","ex":{"en":"She was told to present herself at the Town Hall at 11.30 for the induction ceremony","cn":"她被告知于11点30分在市政厅参加就职仪式。"}},{"pos":"VERB 动词","cn":"主持（电视或广播节目）","en":"If someone presents a programme on television or radio, they introduce each item in it.","ex":{"en":"She presents a monthly magazine programme on the BBC.","cn":"她在英国广播公司主持一个月刊节目。"}},{"pos":"VERB 动词","cn":"上演；组织（演出或展览）","en":"When someone presents something such as a production of a play or an exhibition, they organize it.","ex":{"en":"The Lyric Theatre is presenting a new production of 'Over the Bridge'.","cn":"利里克剧院正在上演新排的《桥对面》。"}},{"pos":"VERB 动词","cn":"引见；介绍","en":"If you present someone to someone else, often an important person, you formally introduce them.","ex":{"en":"Fox stepped forward, welcomed him in Malay, and presented him to Jack","cn":"福克斯走向前，用马来语向他表示欢迎，并把他介绍给了杰克。"}}]},"examples":[{"en":"On his retirement, colleagues presented him with a set of golf clubs.","cn":"在他退休之际，同事们赠给他一套高尔夫球杆。"},{"en":"The company has decided it must present a more modern image.","cn":"公司已决定，必须展现出更加现代的形象。"}]},"precise":{"media":{"uk":"media/uk/precise__gb_1.mp3","us":"media/us/precise__us_1.mp3"},"oxford":{"phon":"prɪˈsaɪs","pos":"adjective","senses":[{"en":"clear and accurate","cn":"准确的；确切的；精确的；明确的","ex":{"en":"precise details/instructions/measurements","cn":"确切的细节；明确的指令；精确的尺寸"}},{"en":"used to emphasize that something happens at a particular time or in a particular way","cn":"（强调时间或方式等）就，恰好","g":"[only before noun]","ex":{"en":"We were just talking about her when, at that precise moment, she walked in.","cn":"我们正谈论着她，恰好在这个时候，她走进来了。"}},{"en":"taking care to be exact and accurate, especially about small details","cn":"细致的；精细的；认真的；一丝不苟的","lab":"disapproving","ex":{"en":"a skilled and precise worker","cn":"熟练而认真的工人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明确的；确切的","en":"You use precise to emphasize that you are referring to an exact thing, rather than something vague.","ex":{"en":"I can remember the precise moment when my daughter came to see me and her new baby brother in hospital","cn":"我能清楚地回想起我女儿来医院看我和她刚出生的弟弟的那一刻。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精确的；准确的","en":"Something that is precise is exact and accurate in all its details.","ex":{"en":"They speak very precise English","cn":"他们讲一口非常地道的英语。"}},{"pos":"PHRASE 短语","cn":"确切地说；准确地说","en":"You say 'to be precise' to indicate that you are giving more detailed or accurate information than you have just given.","ex":{"en":"More than a week ago, Thursday evening to be precise, Susanne was at her evening class","cn":"一个多星期以前，确切地说是周四晚上，苏珊在夜校上课。"}}]},"examples":[{"en":"We were just talking about her when, at that precise moment, she walked in.","cn":"我们正谈论着她，恰好在这个时候，她走进来了。"},{"en":"The shelf is about a metre long — well, 98cm, to be precise.","cn":"架子长约一米。嗯，精确地说，是 98 厘米。"}]},"proficient":{"media":{"uk":"media/uk/proficient__gb_1.mp3","us":"media/us/proficient__us_1.mp3"},"oxford":{"phon":"prəˈfɪʃnt","pos":"adjective","senses":[{"en":"able to do something well because of training and practice","cn":"熟练的；娴熟的；精通的；训练有素的","ex":{"en":"I'm a reasonably proficient driver.","cn":"我开车的技术还算不错。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精通的；熟练的","en":"If you are proficient in something, you can do it well.","ex":{"en":"A great number of Egyptians are proficient in foreign languages.","cn":"很多埃及人都精通外语。"}}]},"examples":[{"en":"I'm a reasonably proficient driver.","cn":"我开车的技术还算不错。"},{"en":"She's proficient in several languages.","cn":"她精通好几种语言。"}]},"prone":{"media":{"uk":"media/uk/prone__gb_1.mp3","us":"media/us/prone__us_1.mp3"},"oxford":{"phon":"prəʊn","pos":"adjective","senses":[{"en":"likely to suffer from something or to do something bad","cn":"易于遭受；有做（坏事）的倾向","ex":{"en":"prone to injury","cn":"容易受伤"}},{"en":"likely to suffer or do the thing mentioned","cn":"有做…倾向的；易于遭受…的","ex":{"en":"injury-prone","cn":"容易受伤的"}},{"en":"lying flat with the front of your body touching the ground","cn":"俯卧的","lab":"formal","ex":{"en":"The victim lay prone without moving.","cn":"受害人趴在地上一动不动。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有（不好的）倾向的；易于…的；很可能…的","en":"To be prone to something, usually something bad, means to have a tendency to be affected by it or to do it.","ex":{"en":"For all her experience, she was still prone to nerves","cn":"尽管有经验，她还是容易紧张。"}},{"pos":"ADJ 形容词","cn":"俯卧的；面部（或腹部）朝下的","en":"If you are lying prone, you are lying on your front.","ex":{"en":"Bob slid from his chair and lay prone on the floor","cn":"鲍勃从椅子上滑下来，趴在了地板上。"}}]},"examples":[{"en":"Tired drivers were found to be particularly prone to ignore warning signs.","cn":"据调查，疲劳驾车时特别容易忽视警示标志。"},{"en":"Working without a break makes you more prone to error.","cn":"连续工作不停歇使人更容易出错。"}]},"produce":{"media":{"uk":"media/uk/produce__gb_1.mp3","us":"media/us/produce__us_1.mp3"},"oxford":{"phon":"prəˈdjuːs","pos":"verb","senses":[{"en":"to make things to be sold, especially in large quantities","cn":"生产；制造","sc":"goods","ex":{"en":"Our company mainly produces goods for export.","cn":"我们公司主要生产供出口的商品。"}},{"en":"to grow or make something as part of a natural process; to have a baby or young animal","cn":"生长；出产；繁育","sc":"make naturally","ex":{"en":"The region produces over 50 per cent of the country's wheat.","cn":"这个地区生产全国 50% 以上的小麦。"}},{"en":"to create something, especially when skill is needed","cn":"（运用技巧）制作，造出","sc":"create with skill","ex":{"en":"She produced a delicious meal out of a few leftovers.","cn":"她用几样剩菜烹制出美味的一餐。"}},{"en":"to cause a particular result or effect","cn":"引起；导致；使产生","sc":"result/effect","ex":{"en":"A phone call to the manager produced the result she wanted.","cn":"她给经理打了个电话便如愿以偿。"}},{"en":"to show something or make something appear from somewhere","cn":"出示；展现；使出现","sc":"show/bring out","ex":{"en":"He produced a letter from his pocket.","cn":"他从口袋里掏出一封信来。"}},{"en":"if a town, country, etc. produces somebody with a particular skill or quality, the person comes from that town, country, etc.","cn":"栽培；培养","sc":"person","ex":{"en":"He is the greatest athlete this country has ever produced.","cn":"他是这个国家培养的最了不起的运动员。"}},{"en":"to be in charge of preparing a film, play, etc. for the public to see","cn":"制作，拍摄（电影、戏剧等）；监督","sc":"movie/play","ex":{"en":"She produced a TV series about adopted children.","cn":"她拍了一部描写收养儿童的电视系列片。"}},{"en":"things that have been made or grown, especially things connected with farming","cn":"产品；（尤指）农产品","ex":{"en":"The market is full of farm produce.","cn":"市场上摆满了农产品。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"产生；引起；造成","en":"To produce something means to cause it to happen.","ex":{"en":"The drug is known to produce side-effects in women","cn":"据悉，这种药会对女性产生副作用。"}},{"pos":"VERB 动词","cn":"生产；出产","en":"If you produce something, you make or create it.","ex":{"en":"The company produced circuitry for communications systems","cn":"该公司为通信系统生产电路。"}},{"pos":"VERB 动词","cn":"生长；长出；产生","en":"When things or people produce something, it comes from them or slowly forms from them, especially as the result of a biological or chemical process.","ex":{"en":"These plants are then pollinated and allowed to mature and produce seed.","cn":"然后，这些植物就被授粉，从而成熟结籽。"}},{"pos":"VERB 动词","cn":"提出；提供","en":"If you produce evidence or an argument, you show it or explain it to people in order to make them agree with you.","ex":{"en":"They challenged him to produce evidence to support his allegations","cn":"他们要他拿出证据证明自己的主张。"}},{"pos":"VERB 动词","cn":"出示；拿出；亮出","en":"If you produce an object from somewhere, you show it or bring it out so that it can be seen.","ex":{"en":"To hire a car you must produce a passport and a current driving licence","cn":"租车必须出示护照和有效驾驶执照。"}},{"pos":"VERB 动词","cn":"上演（戏剧）；制作（电影、电视节目）；灌制（唱片）","en":"If someone produces something such as a film, a magazine, or a CD, they organize it and decide how it should be done.","ex":{"en":"He has produced his own sports magazine called Yes Sport","cn":"他推出了自己的体育杂志，叫做《是的，体育》。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"农产品","en":"Produce is food or other things that are grown in large quantities to be sold.","ex":{"en":"We manage to get most of our produce in Britain","cn":"我们设法在英国搞到我们所需的大部分农产品。"}}]},"examples":[{"en":"He is the greatest athlete this country has ever produced.","cn":"他是这个国家曾经栽培出来的运动员中最了不起的一个。"},{"en":"The region produces over 50% of the country's wheat.","cn":"这个地区出产全国 50% 以上的小麦。"}]},"promising":{"media":{"uk":"media/uk/promising__gb_1.mp3","us":"media/us/promising__us_1.mp3"},"oxford":{"phon":"ˈprɒmɪsɪŋ","pos":"adjective","senses":[{"en":"showing signs of being good or successful","cn":"有希望的；有前途的；有出息的","ex":{"en":"He was voted the most promising new actor for his part in the movie.","cn":"他因在该电影中扮演的角色而获评为最有前途的新演员。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大有希望的；很有前途的；前景很好的","en":"Someone or something that is promising seems likely to be very good or successful.","ex":{"en":"A school has honoured one of its brightest and most promising former pupils.","cn":"一所学校给曾在这里就读的最聪明、最有前途的一位学生授予了荣誉头衔。"}}]},"examples":[{"en":"He was voted the most promising new actor for his part in the movie.","cn":"他因在该电影中扮演的角色而获评为最有前途的新演员。"},{"en":"The day began promisingly with bright sunshine.","cn":"晨曦灿烂，预示了一个大好的晴天。"}],"base":"promise"},"protest":{"media":{"uk":"media/uk/protest__gb_1.mp3","us":"media/us/protest__us_1.mp3"},"oxford":{"phon":"ˈprəʊtest","pos":"noun","senses":[{"en":"the expression of strong dislike of or opposition to something; a statement or an action that shows this","cn":"抗议；抗议书（或行动）；反对","ex":{"en":"to hold/organize/join a protest","cn":"举行／组织／参加抗议"}},{"en":"to say or do something to show that you disagree with something or think it is bad, especially publicly","cn":"（公开）反对；抗议","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"There's no use protesting, I won't change my mind.","cn":"抗议没有用，我决不改变主意。"},"pos":"verb"},{"en":"to state clearly that something is true, especially when you have been accused of something or when other people do not believe you","cn":"坚决地表示；申辩","g":"[transitive]","ex":{"en":"She has always protested her innocence.","cn":"她一直坚持说自己是无辜的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抗议；提出异议；反对","en":"If you protest against something or about something, you say or show publicly that you object to it. In American English, you usually say that you protest it.","ex":{"en":"Groups of women took to the streets to protest against the arrests","cn":"成群结队的妇女上街抗议逮捕行动。"}},{"pos":"N-VAR 可变名词","cn":"抗议；反对","en":"A protest is the act of saying or showing publicly that you object to something.","ex":{"en":"The opposition now seems too weak to stage any serious protests against the government","cn":"反对党现在似乎势力非常弱小，无法针对政府发起真正的抗议。"}},{"pos":"VERB 动词","cn":"申辩；申明","en":"If you protest that something is the case, you insist that it is the case, when other people think that it may not be.","ex":{"en":"When we tried to protest that Mo was beaten up they didn't believe us","cn":"我们试图申明莫遭到了毒打，他们却不相信我们。"}},{"pos":"N-COUNT 可数名词","cn":"申明；声明；断言","en":"A protest that something is true is a strong declaration that it is true.","ex":{"en":"That was how she usually dealt with their protests that she was spoiling her grandchildren.","cn":"当他们坚持说她是在溺爱孙儿，她通常会作出那样的回应。"}}]},"examples":[{"en":"The workers staged a protest against the proposed changes in their contracts.","cn":"工人们发起抗议，反对拟议中的对他们合同的修改。"},{"en":"The building work will go ahead, despite protests from local residents.","cn":"尽管当地居民反对，建筑工程将照样进行。"}]},"problem":{"media":{"uk":"media/uk/problem__gb_1.mp3","us":"media/us/problem__us_1.mp3"},"oxford":{"phon":"ˈprɒbləm","pos":"noun","senses":[{"en":"a thing that is difficult to deal with or to understand","cn":"棘手的问题；难题；困难","lab":"especially North American English","ex":{"en":"big/serious/major problems","cn":"重大／严重／主要的问题"}},{"en":"a question that can be answered by using logical thought or mathematics","cn":"逻辑题；数学题","ex":{"en":"mathematical problems","cn":"数学题"}},{"en":"causing problems for other people or yourself","cn":"引起麻烦的；成问题的；惹乱子的","ex":{"en":"She was a problem child, always in trouble with the police.","cn":"她曾是个问题儿童，常常犯事落入警察手中。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"问题；难题；困难","en":"A problem is a situation that is unsatisfactory and causes difficulties for people.","ex":{"en":"...the economic problems of the inner city","cn":"内城区的经济问题"}},{"pos":"N-COUNT 可数名词","cn":"（通过逻辑思考或数学运算解决的）问题，习题，题","en":"A problem is a puzzle that requires logical thought or mathematics to solve it.","ex":{"en":"With mathematical problems, you can save time by approximating.","cn":"对于数学题，可以用取近似值的办法节约时间。"}},{"pos":"ADJ 形容词","cn":"（儿童或家庭）有严重问题的，引起严重问题的","en":"Problem children or problem families have serious problems or cause serious problems for other people.","ex":{"en":"In some cases a problem child is placed in a special school","cn":"有时，问题儿童被放在特殊的学校。"}},{"pos":"CONVENTION 惯用语","cn":"没问题","en":"You say 'no problem' to show that you are willing to do what you have been asked.","ex":{"en":"'Can you repair it?' — 'No problem'","cn":"“你能修好它吗？”——“没问题。”"}},{"pos":"CONVENTION 惯用语","cn":"没关系","en":"You say 'no problem' to let someone know that you do not mind them doing something they have said they are going to do.","ex":{"en":"'I ought to think about going actually. If that's all right with you.' — 'Yeah. No problem.'","cn":"“事实上，我应该考虑去，如果你不介意的话。”——“嗯，没关系。”"}}]},"examples":[{"en":"It's a nice table! The only problem is (that) it's too big for our room.","cn":"这张桌子的确不错！唯一的问题是放在我们的屋子里太大了。"},{"en":"What's your problem? — I only asked if you could help me for ten minutes.","cn":"你有毛病啊？我只是问问你能不能抽十分钟帮个忙而已。"}]},"primary":{"media":{"uk":"media/uk/primary__gb_1.mp3","us":"media/us/primary__us_1.mp3"},"oxford":{"phon":"ˈpraɪməri","pos":"adjective","senses":[{"en":"connected with the education of children between the ages of about five and eleven","cn":"初等教育的；小学教育的","g":"[only before noun]","lab":"especially British English","ex":{"en":"primary teachers","cn":"小学教师"}},{"en":"main; most important; basic","cn":"主要的；首要的；基本的","g":"[usually before noun]","ex":{"en":"our primary objective/goal/purpose","cn":"我们的首要目标"}},{"en":"developing or happening first; earliest","cn":"最初的；最早的","g":"[usually before noun]","lab":"formal or specialist","ex":{"en":"Researchers are conducting studies to determine the primary causes of this phenomenon.","cn":"研究人员正在进行研究以确定这种现象的主要原因。"}},{"en":"(in the US) an election in which people in a particular area vote to choose a candidate for a future important election","cn":"（美国）初选","ex":{"en":"the Illinois primary","cn":"伊利诺伊州的初选"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"首要的；主要的","en":"You use primary to describe something that is very important.","ex":{"en":"That's the primary reason the company's share price has held up so well","cn":"这是公司股票价格一直居高不下的主要原因。"}},{"pos":"ADJ 形容词","cn":"（教育）初级的，初等的，小学的","en":"Primary education is given to pupils between the ages of 5 and 11.","ex":{"en":"Britain did not introduce compulsory primary education until 1880","cn":"直到1880年，英国才开始实行初等义务教育。"}},{"pos":"ADJ 形容词","cn":"首先的；最早的；最初的","en":"Primary is used to describe something that occurs first.","ex":{"en":"It is not the primary tumour that kills, but secondary growths elsewhere in the body","cn":"原发性肿瘤并不会置人于死地，致命的是身体其他部位的继发肿瘤。"}},{"pos":"N-COUNT 可数名词","cn":"（美国）初选，预选","en":"A primary or a primary election is an election in an American state in which people vote for someone to become a candidate for a political office.","ex":{"en":"...the 1968 New Hampshire primary","cn":"1968年新罕布什尔州的初选"}}]},"examples":[{"en":"The primary aim of this course is to improve your spoken English.","cn":"这门课的主要目的是提高英语会话能力。"},{"en":"Our primary concern must be the children.","cn":"我们首先要关心的必须是儿童。"}]},"proper":{"media":{"uk":"media/uk/proper__gb_1.mp3","us":"media/us/proper__us_1.mp3"},"oxford":{"phon":"ˈprɒpə(r)","pos":"adjective","senses":[{"en":"right, appropriate or correct; according to the rules","cn":"正确的；恰当的；符合规则的","g":"[only before noun]","lab":"especially British English","ex":{"en":"We should have had a proper discussion before voting.","cn":"我们本应在表决之前好好讨论一下才是。"}},{"en":"that you consider to be real and of a good enough standard","cn":"真正的；像样的；名副其实的","g":"[only before noun]","lab":"British English, informal，，","ex":{"en":"I haven't had a proper meal in days.","cn":"我已经好几天没好好吃饭了。"}},{"en":"socially and morally acceptable","cn":"符合习俗（或体统）的；正当的；规矩的","ex":{"en":"It is right and proper that parents take responsibility for their children's attendance at school.","cn":"父母负责督促子女上学上课，这是天经地义的事。"}},{"en":"according to the most exact meaning of the word","cn":"严格意义上的；狭义的","g":"[after noun]","ex":{"en":"The celebrations proper always begin on the last stroke of midnight.","cn":"正式庆典总是在午夜钟声的最后一响开始。"}},{"en":"complete","cn":"完全的；彻底的","g":"[only before noun]","lab":"British English, informal，，","ex":{"en":"We're in a proper mess now.","cn":"我们现在真是一团糟。"}},{"en":"belonging to a particular type of thing; natural in a particular situation or place","cn":"独具的；天然享有的；特有的","lab":"formal","ex":{"en":"They should be treated with the dignity proper to all individuals created by God.","cn":"他们应当享有上帝赋予每一个受造物的尊严。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"适宜的；合适的；适当的；恰当的","en":"You use proper to describe things that you consider to be real and satisfactory rather than inadequate in some way.","ex":{"en":"Two out of five people lack a proper job","cn":"每五人中有两人没有正当的工作。"}},{"pos":"ADJ 形容词","cn":"正确的；准确的；最合适的","en":"The proper thing is the one that is correct or most suitable.","ex":{"en":"The Supreme Court will ensure that the proper procedures have been followed","cn":"最高法院将确保程序的履行合乎规范"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"得体的；合乎体统的；正派的","en":"If you say that a way of behaving is proper, you mean that it is considered socially acceptable and right.","ex":{"en":"In those days it was not thought entirely proper for a woman to be on the stage","cn":"那个时候，女性登台表演被认为不太得体。"}},{"pos":"ADJ 形容词","cn":"严格意义上的；真正的；本身的","en":"You can add proper after a word to indicate that you are referring to the central and most important part of a place, event, or object and want to distinguish it from other things which are not regarded as being important or central to it.","ex":{"en":"A distinction must be made between archaeology proper and science-based archaeology.","cn":"必须区分考古学本身和以科学为基础的考古学。"}}]},"examples":[{"en":"It is right and proper that parents take responsibility for their children's attendance at school.","cn":"父母负责督促子女上学上课，这是天经地义的事。"},{"en":"The development was planned without proper regard to the interests of local people.","cn":"新开发区的规划没有正当考虑当地居民的利益。"}]},"preoccupied":{"media":{"uk":"media/uk/preoccupied__gb_1.mp3","us":"media/us/preoccupied__us_1.mp3"},"oxford":{"phon":"priˈɒkjupaɪd","pos":"adjective","senses":[{"en":"thinking and/or worrying continuously about something so that you do not pay attention to other things","cn":"专注；心事重重；一门心思","ex":{"en":"He was too preoccupied with his own thoughts to notice anything wrong.","cn":"他只顾着想心事，没注意到有什么不对。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全神贯注的；入神的","en":"If you are preoccupied, you are thinking a lot about something or someone, and so you hardly notice other things.","ex":{"en":"Tom Banbury was preoccupied with the missing Shepherd child and did not want to devote time to the new murder","cn":"汤姆·班伯里一心寻找谢泼德家失踪的孩子，不想花时间处理这起新的谋杀案。"}}]},"examples":[{"en":"He was too preoccupied with his own thoughts to notice anything wrong.","cn":"他只顾想着心事，没注意到有什么不对。"},{"en":"What’s wrong with Cindy? She seems a little preoccupied.","cn":"辛迪怎么了？她好像有点心事重重。"}],"base":"preoccupy"},"pray":{"media":{"uk":"media/uk/pray__gb_1.mp3","us":"media/us/pray__us_1.mp3"},"oxford":{"phon":"preɪ","pos":"verb","senses":[{"en":"to speak to God, especially to give thanks or ask for help","cn":"祈祷；祷告","g":"[intransitive, transitive]","ex":{"en":"They knelt down and prayed.","cn":"他们跪下来祷告。"}},{"en":"to hope very much that something will happen","cn":"企盼；祈望","g":"[intransitive, transitive]","ex":{"en":"We're praying for good weather on Saturday.","cn":"我们十分企盼星期六是个晴天。"}},{"en":"used to mean ‘please’ when you are asking a question or telling somebody to do something","cn":"（用于询问或指示）请问，请","ex":{"en":"What, pray, is the meaning of this?","cn":"请问，这是什么意思？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"祈祷；祷告","en":"When people pray, they speak to God in order to give thanks or to ask for his help.","ex":{"en":"He spent his time in prison praying and studying","cn":"他把狱中的时间都用于祈祷和学习。"}},{"pos":"VERB 动词","cn":"祈望；祈求","en":"When someone is hoping very much that something will happen, you can say that they are praying that it will happen.","ex":{"en":"I'm just praying that somebody in Congress will do something before it's too late","cn":"我只是在祈求国会中会有人在还来得及的时候做点什么。"}},{"pos":"ADV 副词","cn":"（用于不太友善或气愤但镇定地提问时）请问","en":"Pray is used when asking a question in a rather unfriendly way or in an angry but calm way.","ex":{"en":"And what, pray, do you buy and sell, Major?","cn":"梅杰，请问，你都买卖些什么？"}},{"pos":"ADV 副词","cn":"（用于礼貌地提出要求）请","en":"Pray was used to add politeness to a command.","ex":{"en":"I beg your pardon, pray continue.","cn":"抱歉，请继续。"}}]},"examples":[{"en":"‘Please God don't let it happen,’ she prayed. “","cn":"请求上帝不要让这事发生。”她祈祷说。"},{"en":"We're praying for good weather on Saturday.","cn":"我们十分企盼星期六是个晴天。"}]},"properly":{"media":{"uk":"media/uk/properly__gb_1.mp3","us":"media/us/properly__us_1.mp3"},"oxford":{"phon":"ˈprɒpəli","pos":"adverb","senses":[{"en":"in a way that is correct and/or appropriate","cn":"正确地；适当地","lab":"especially British English","ex":{"en":"How much money do we need to do the job properly?","cn":"我们需要多少钱才能做好这件事？"}},{"en":"in a way that is socially or morally acceptable","cn":"得体地；恰当地；符合习俗地","ex":{"en":"You acted perfectly properly in approaching me first.","cn":"你先来找我是完全对的。"}},{"en":"really; in fact","cn":"真正地；实际上","ex":{"en":"He had usurped powers that properly belonged to parliament.","cn":"他僭夺了实际上属于议会的权力。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"正确地；准确地；令人满意地","en":"If something is done properly, it is done in a correct and satisfactory way.","ex":{"en":"You're too thin. You're not eating properly","cn":"你太瘦了。你的饮食不合理。"}},{"pos":"ADV 副词","cn":"适宜地；合适地；得体地；恰当地","en":"If someone behaves properly, they behave in a way that is considered acceptable and not rude.","ex":{"en":"He's a spoilt brat and it's about time he learnt to behave properly","cn":"他是个被宠坏的孩子，是该学些规矩了。"}}]},"examples":[{"en":"How much money do we need to do the job properly?","cn":"我们需要多少钱才能做好这件事？"},{"en":"He had usurped powers that properly belonged to parliament.","cn":"他僭越了实际上属于议会的权力。"}]},"protector":{"media":{"uk":"media/uk/protector__gb_1.mp3","us":"media/us/protector__us_1.mp3"},"oxford":{"phon":"prəˈtektə(r)","pos":"noun","senses":[{"en":"a person, an organization or a thing that protects somebody/something","cn":"保护人（或组织、装置等）","ex":{"en":"I regarded him as my friend and protector.","cn":"我视他为我的朋友和保护者。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保护人","en":"If you refer to someone as your protector, you mean that they protect you from being harmed.","ex":{"en":"Many mothers see their son as a potential protector and provider.","cn":"许多母亲将儿子看成是未来的保护人和赡养人。"}},{"pos":"N-COUNT 可数名词","cn":"保护装置","en":"A protector is a device that protects someone or something from physical harm.","ex":{"en":"He was the only National League umpire to wear an outside chest protector.","cn":"他是唯一在衣服外面穿护胸的全国联赛裁判。"}}]},"examples":[{"en":"the company's image as a protector of the environment","cn":"这个公司作为环境保护者的形象"},{"en":"I regarded him as my friend and protector.","cn":"我视他为我的朋友和保护者。"}]},"proofs":{"lemma":"proof"},"production":{"media":{"uk":"media/uk/production__gb_1.mp3","us":"media/us/production__us_1.mp3"},"oxford":{"phon":"prəˈdʌkʃn","pos":"noun","senses":[{"en":"the process of growing or making food, goods or materials, especially large quantities","cn":"生产；制造；制作","g":"[uncountable]","ex":{"en":"food/oil production","cn":"食品／石油生产"}},{"en":"the quantity of goods that is produced","cn":"产量","g":"[uncountable]","ex":{"en":"a decline/an increase in production","cn":"产量的下降／上升"}},{"en":"the act or process of making something naturally","cn":"（自然的）产生，分泌","g":"[uncountable]","ex":{"en":"Eating cheese stimulates the production of saliva.","cn":"吃奶酪会刺激唾液的产生。"}},{"en":"a film, play or broadcast that is prepared for the public; the act of preparing a film, play, etc.","cn":"（电影、戏剧或广播节目的）出品，制作","g":"[countable, uncountable]","ex":{"en":"a new production of ‘King Lear’","cn":"新制作的《李尔王》"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（大量）生产，制造，制作","en":"Production is the process of manufacturing or growing something in large quantities.","ex":{"en":"That model won't go into production before late 1990.","cn":"那种型号在20世纪90年代末以前不会批量生产。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"产量","en":"Production is the amount of goods manufactured or grown by a company or country.","ex":{"en":"We needed to increase the volume of production","cn":"我们需要提高产量。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"产生；形成；生成","en":"The production of something is its creation as the result of a natural process.","ex":{"en":"These proteins stimulate the production of blood cells.","cn":"这些蛋白质会刺激血细胞的产生。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（戏剧的）排演；（电影、电视节目的）制作；（唱片的）灌制","en":"Production is the process of organizing and preparing a play, film, programme, or CD, in order to present it to the public.","ex":{"en":"During the film's production, the director wanted to shoot a riot scene but the filming was blocked","cn":"在影片摄制期间，导演想拍摄一个暴乱场面，但是被禁止了。"}},{"pos":"N-COUNT 可数名词","cn":"演出","en":"A production is a play, opera, or other show that is performed in a theatre.","ex":{"en":"For this production she has learnt the role in Spanish.","cn":"为了这次演出，她已经学会了用西班牙语演这个角色。"}},{"pos":"PHRASE 短语","cn":"通过出示；通过展示；通过亮出","en":"When you can do something on production of or on the production of documents, you need to show someone those documents in order to be able to do that thing.","ex":{"en":"Entry to the show is free to members on production of their membership cards.","cn":"会员只要出示会员卡就可以免费观看演出。"}}]},"examples":[{"en":"The car went out of production in 2007.","cn":"这款汽车已于 2007 年停产。"},{"en":"Production of the new aircraft will start next year.","cn":"新飞机的生产将于明年开始。"}]},"principle":{"media":{"uk":"media/uk/principle__gb_1.mp3","us":"media/us/principle__us_1.mp3"},"oxford":{"phon":"ˈprɪnsəpl","pos":"noun","senses":[{"en":"a moral rule or a strong belief that influences your actions","cn":"道德原则；行为准则；规范","g":"[countable, usually plural, uncountable]","ex":{"en":"He has high moral principles.","cn":"他道德高尚。"}},{"en":"a law, a rule or a theory that something is based on","cn":"法则；原则；原理","g":"[countable]","ex":{"en":"The same principles apply to both humans and animals.","cn":"同样的原则适用于人和动物。"}},{"en":"a belief that is accepted as a reason for acting or thinking in a particular way","cn":"观念；（行动、思想的）理由，信条","g":"[countable]","ex":{"en":"The welfare of the child is the guiding principle of the family courts.","cn":"家事法院以孩子的福祉为决策的依归。"}},{"en":"a general or scientific law that explains how something works or why something happens","cn":"定律；运作原理","g":"[countable, uncountable]","ex":{"en":"O'Sullivan was among the first chemists to apply scientific principles to brewing beer.","cn":"奥沙利文是最早将科学原理应用于啤酒酿造的化学家之一。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"道德原则；行为准则；操守","en":"A principle is a general belief that you have about the way you should behave, which influences your behaviour.","ex":{"en":"Buck never allowed himself to be bullied into doing anything that went against his principles","cn":"巴克从来不会因为受到威胁而做违背自己原则的事情。"}},{"pos":"N-COUNT 可数名词","cn":"法则；原则；原理","en":"The principles of a particular theory or philosophy are its basic rules or laws.","ex":{"en":"...a violation of the basic principles of Marxism","cn":"违背马克思主义的基本原则"}},{"pos":"N-COUNT 可数名词","cn":"（科学）原理，定律","en":"Scientific principles are general scientific laws which explain how something happens or works.","ex":{"en":"These people lack all understanding of scientific principles.","cn":"这些人对科学原理一窍不通。"}},{"pos":"PHRASE 短语","cn":"大体上；基本上","en":"If you agree with something in principle, you agree in general terms to the idea of it, although you do not yet know the details or know if it will be possible.","ex":{"en":"I agree with it in principle but I doubt if it will happen in practice.","cn":"我大体上同意这一点，但是怀疑它是否能够付诸实践。"}},{"pos":"PHRASE 短语","cn":"从理论上说；按道理","en":"If something is possible in principle, there is no known reason why it should not happen, even though it has not happened before.","ex":{"en":"Even assuming this to be in principle possible, it will not be achieved soon.","cn":"即使假定这在理论上行得通，它也不可能于短期内实现。"}},{"pos":"PHRASE 短语","cn":"按照原则；根据信念","en":"If you refuse to do something on principle, you refuse to do it because of a particular belief that you have.","ex":{"en":"He would vote against it on principle","cn":"他会根据原则投反对票。"}}]},"examples":[{"en":"Discussing all these details will get us nowhere; we must get back to first principles (= the most basic rules).","cn":"一直谈这些细节不会有结果的；我们必须回到根本原则上来。"},{"en":"They have agreed to the proposal in principle but we still have to negotiate the terms.","cn":"他们已基本同意了这项提议，但我们还得磋商各项条款。"}]},"principally":{"media":{"uk":"media/uk/principally__gb_1.mp3","us":"media/us/principally__us_1.mp3"},"oxford":{"phon":"ˈprɪnsəpli","pos":"adverb","senses":[{"en":"mainly","cn":"主要地","ex":{"en":"The book is aimed principally at beginners.","cn":"这本书主要是为初学者编写的。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"主要地；首要地；最重要地","en":"Principally means more than anything else.","ex":{"en":"This is principally because the major export markets are slowing","cn":"这主要是因为主要出口市场发展缓慢。"}}]},"examples":[{"en":"No new power stations have been built, principally because of the cost.","cn":"没有新建的发电站，主要是因为经费问题。"},{"en":"The book is aimed principally at beginners.","cn":"这本书主要是为初学者编写的。"}]},"precedent":{"media":{"uk":"media/uk/precedent__gb_1.mp3","us":"media/us/precedent__us_1.mp3"},"oxford":{"phon":"ˈpresɪdənt","pos":"noun","senses":[{"en":"an official action or decision that has happened in the past and that is seen as an example or a rule to be followed in a similar situation later","cn":"可援用参考的具体例子；实例；范例","g":"[countable, uncountable]","ex":{"en":"The ruling set a precedent for future libel cases.","cn":"这项裁决为今后的诽谤案提供了判例。"}},{"en":"a similar action or event that happened earlier","cn":"先前出现的事例；前例；先例","g":"[countable, uncountable]","ex":{"en":"historical precedents","cn":"历史前例"}},{"en":"the way that things have always been done","cn":"传统；常例；常规","g":"[uncountable]","ex":{"en":"to break with precedent (= to do something in a different way)","cn":"打破常规"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"前例；先例","en":"If there is a precedent for an action or event, it has happened before, and this can be regarded as an argument for doing it again.","ex":{"en":"The trial could set an important precedent for dealing with large numbers of similar cases","cn":"这次审判能为处理大量类似案例开创重要的先例。"}}]},"examples":[{"en":"The ruling set a precedent for future libel cases.","cn":"这项裁决为今后的诽谤案提供了判例。"},{"en":"Such protests are without precedent in recent history.","cn":"这类抗议事件在近代史上没有发生过。"}]},"prosperous":{"media":{"uk":"media/uk/prosperous__gb_1.mp3","us":"media/us/prosperous__us_1.mp3"},"oxford":{"phon":"ˈprɒspərəs","pos":"adjective","senses":[{"en":"rich and successful","cn":"繁荣的；成功的；兴旺的","ex":{"en":"prosperous countries","cn":"繁荣的国家"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富足的；成功的；兴旺的；繁荣的","en":"Prosperous people, places, and economies are rich and successful.","ex":{"en":"...the youngest son of a relatively prosperous British family","cn":"一个相对富裕的英国家族中最小的儿子"}}]},"examples":[{"en":"prosperous countries","cn":"繁荣的国家"},{"en":"a prosperous landowner","cn":"富裕的土地拥有者"}]},"premature":{"oxford":{"phon":"ˈpremətʃə(r)","pos":"adjective","senses":[{"en":"happening before the normal or expected time","cn":"未成熟的；过早的；提前的","ex":{"en":"his premature death at the age of 37","cn":"他 37 岁时早逝"}},{"en":"happening or being born before the normal length of pregnancy has been completed","cn":"早产的","ex":{"en":"The baby was four weeks premature.","cn":"这个婴儿早产了四周。"}},{"en":"happening or made too soon","cn":"草率的；仓促的","ex":{"en":"a premature conclusion/decision/judgement","cn":"草率的结论／决定／判断"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过早的；太早的；提前的","en":"Something that is premature happens earlier than usual or earlier than people expect.","ex":{"en":"Accidents are still the number one cause of premature death for Americans","cn":"交通事故仍然是造成美国人过早死亡的头号因素。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不成熟的；过早的；草率的","en":"You can say that something is premature when it happens too early and is therefore inappropriate.","ex":{"en":"It now seems their optimism was premature","cn":"现在看来他们高兴得太早了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"早产的","en":"A premature baby is one that was born before the date when it was expected to be born.","ex":{"en":"Even very young premature babies respond to their mother's presence","cn":"即使是很小的早产儿也会对母亲的出现做出反应。"}}]},"media":{"uk":"media/uk/premature__gb_1.mp3","us":"media/us/premature__us_1.mp3"},"examples":[{"en":"It is premature to talk about success at this stage.","cn":"现阶段就谈成功尚为时过早。"},{"en":"Her hair became prematurely white.","cn":"她的头发过早地苍白了。"}]},"prevalence":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the fact that something is prevalent","cn":"盛行；普遍"}]},"examples":[{"en":"the prevalence of deafness in older age groups","cn":"老年人普遍耳聋的现象","src":"ld"}],"media":{"uk":"media/uk/prevalence__gb_1.mp3","us":"media/us/prevalence__us_1.mp3"},"oxford":{"phon":"ˈprevələns","pos":"noun","senses":[{"en":"the fact of existing or being very common at a particular time or in a particular place","cn":"流行；普遍存在；盛行","ex":{"en":"an increase in the prevalence of smoking among young people","cn":"年轻人中吸烟流行率上升了"}}]}},"pretty":{"media":{"uk":"media/uk/pretty__gb_1.mp3","us":"media/us/pretty__us_1.mp3"},"oxford":{"phon":"ˈprɪti","pos":"adverb","senses":[{"en":"to some extent; fairly","cn":"颇；相当","lab":"North American English","ex":{"en":"The game was pretty good.","cn":"这个游戏相当不错。"}},{"en":"very","cn":"非常；很","ex":{"en":"That performance was pretty impressive.","cn":"那场表演很出色。"}},{"en":"attractive without being very beautiful","cn":"漂亮的；标致的；妩媚的；动人的","ex":{"en":"a pretty face","cn":"俏丽的脸"},"pos":"adjective"},{"en":"attractive and pleasant to look at or to listen to without being large, beautiful or impressive","cn":"赏心悦目的；动听的；美观的；精致的","lab":"figurative","ex":{"en":"pretty clothes","cn":"漂亮的衣服"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指女孩）漂亮的，好看的，标致的","en":"If you describe someone, especially a girl, as pretty, you mean that they look nice and are attractive in a delicate way.","ex":{"en":"She's a very charming and very pretty girl.","cn":"她是一个非常迷人的漂亮女孩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方或事物）漂亮的，美丽的（但无特殊之处）","en":"A place or a thing that is pretty is attractive and pleasant, in a charming but not particularly unusual way.","ex":{"en":"Whitstable is still a very pretty little town.","cn":"惠特斯特布尔仍然是一个非常漂亮的小镇。"}},{"pos":"ADV 副词","cn":"很；颇；相当","en":"You can use pretty before an adjective or adverb to mean 'quite' or 'rather'. →see usage note at:","ex":{"en":"I had a pretty good idea what she was going to do","cn":"我很清楚她会怎么做。"}},{"pos":"PHRASE 短语","cn":"几乎；近乎；差不多","en":"Pretty much or pretty well means 'almost'.","ex":{"en":"His new government looks pretty much like the old one","cn":"他的新政府看起来和旧政府没什么两样。"}},{"pos":"PHRASE 短语","cn":"处于有利的位置；处境优越","en":"If you say that someone is sitting pretty, you mean that they are in a good, safe, or comfortable position.","ex":{"en":"When the war started, they thought they were sitting pretty, because they had all that extra grain.","cn":"战争开始的时候，他们认为自己境况不错，因为他们粮食准备充足。"}},{"pos":"","cn":"","en":"not a pretty sight→see: ;"}]},"examples":[{"en":"‘I didn't know you could play the piano.’ ‘I'm not just a pretty face, you know!’ “","cn":"我不知道你还会弹钢琴呢。” “我可不只是脸蛋儿漂亮，对吧！”"},{"en":"You should have seen him in his swimming trunks — not a pretty sight!","cn":"你应该见识见识他穿游泳裤的样子，真是一景呢！"}]},"program":{"media":{"uk":"media/uk/program__gb_1.mp3","us":"media/us/program__us_1.mp3"},"oxford":{"phon":"ˈprəʊɡræm","pos":"noun","senses":[{"en":"a set of instructions in code that control the operations or functions of a computer","cn":"程序；编码指令","sc":"for a computer","ex":{"en":"You'll need to download and install the program on your computer.","cn":"需要在计算机上下载并安装该程序。"}},{"en":"something that people watch on television or listen to on the radio","cn":"节目","sc":"on TV/radio","ex":{"en":"a TV/television/radio program","cn":"电视/电视/广播节目"}},{"en":"a plan of things that will be done or included in the development of something","cn":"计划；方案；活动安排","sc":"plan","ex":{"en":"the country's nuclear weapons/space program","cn":"该国的核武器/太空计划"}},{"en":"a course of study","cn":"课程","lab":"especially North American English","sc":"education","ex":{"en":"a school/an educational program","cn":"学校/教育计划"}},{"en":"an organized order of performances or events","cn":"（演出或活动的）流程","sc":"order of events","ex":{"en":"The concert is the highlight of the festival's musical program.","cn":"这场音乐会是音乐节音乐节目的重头戏。"}},{"en":"a thin book or piece of paper that gives you information about a play, a concert, etc.","cn":"节目单；演出介绍","sc":"for play/concert","ex":{"en":"a theater program","cn":"剧目单"}},{"en":"a series of actions done by a machine, such as a washing machine","cn":"（机器工作的）程序","sc":"of machine","ex":{"en":"Select a cool program for woolen clothes.","cn":"为羊毛衣服选择一个很酷的程序。"}},{"en":"to give a computer, etc. a set of instructions to make it perform a particular task","cn":"编程","g":"[intransitive, transitive]","sc":"computer","ex":{"en":"In this class, students will learn how to program.","cn":"这节课学生将学习编程。"},"pos":"verb"},{"en":"to plan for something to happen, especially as part of a series of planned events","cn":"计划；规划；安排","g":"[transitive, usually passive]","sc":"plan","ex":{"en":"Several evening events have been programmed.","cn":"已安排了几场晚间活动。"},"pos":"verb"},{"en":"to make a person, an animal, etc. behave in a particular way, so that they do it without thinking about it","cn":"使（人或动物）自动做某事","g":"[transitive, usually passive]","sc":"person/animal","ex":{"en":"Human beings are genetically programmed to learn certain kinds of language.","cn":"人类生来有学习某几种语言的遗传因素。"},"pos":"verb"},{"en":"to give a machine instructions to do a particular task","cn":"预调；预设","g":"[transitive]","sc":"machine","ex":{"en":"She programmed the heat to come on at eight.","cn":"她将暖气设定为八点开始。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"程序","en":"A program is a set of instructions that a computer follows in order to perform a particular task.","ex":{"en":"The chances of an error occurring in a computer program increase with the size of the program.","cn":"计算机程序越长，出错的概率也越大。"}},{"pos":"VERB 动词","cn":"为（计算机）编制程序","en":"When you program a computer, you give it a set of instructions to make it able to perform a particular task.","ex":{"en":"He programmed his computer to compare all the possible combinations.","cn":"他给他的计算机编制了一套程序，以比较所有可能的组合。"}}]},"examples":[{"en":"The computer is programmed to warn users before information is deleted.","cn":"这台计算机编程时已设计在信息删除前提醒用户。"},{"en":"In this class, students will learn how to program.","cn":"这节课学生将学习编程。"}]},"predisposition":{"media":{"uk":"media/uk/predisposition__gb_1.mp3","us":"media/us/predisposition__us_1.mp3"},"oxford":{"phon":"ˌpriːdɪspəˈzɪʃn","pos":"noun","senses":[{"en":"a condition that makes somebody/something likely to behave in a particular way or to have a particular illness","cn":"倾向；癖性；（易患某种病的）体质","ex":{"en":"a genetic predisposition to liver disease","cn":"易患肝病的遗传体质"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"倾向；禀性","en":"If you have a predisposition to behave in a particular way, you tend to behave like that because of the kind of person that you are or the attitudes that you have.","ex":{"en":"...a woman's predisposition to use the right side of her brain","cn":"女性使用右脑的倾向"}},{"pos":"N-COUNT 可数名词","cn":"（易患某种疾病的）倾向，体质","en":"If you have a predisposition to a disease or illness, it is likely that you will suffer from that disease or illness.","ex":{"en":"...a genetic predisposition to lung cancer.","cn":"易患肺癌的遗传倾向"}}]},"examples":[{"en":"a genetic predisposition to liver disease","cn":"易患肝病的遗传体质"},{"en":"a predisposition towards alcoholism","cn":"酗酒倾向"}]},"propensity":{"media":{"uk":"media/uk/propensity__gb_1.mp3","us":"media/us/propensity__us_1.mp3"},"oxford":{"phon":"prəˈpensəti","pos":"noun","senses":[{"en":"a natural desire or need that makes you tend to behave in a particular way","cn":"习性；行为倾向","ex":{"en":"He showed a propensity for violence.","cn":"他表现出暴力倾向。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（性格上的）倾向；习性","en":"A propensity to do something or a propensity for something is a natural tendency that you have to behave in a particular way.","ex":{"en":"Mr Bint has a propensity to put off decisions to the last minute","cn":"宾特先生习惯拖到最后时刻才作决定。"}}]},"examples":[{"en":"He showed a propensity for violence.","cn":"他表现出暴力倾向。"},{"en":"She has a propensity to exaggerate.","cn":"她爱言过其实。"}]},"pronoun":{"oxford":{"phon":"ˈprəʊnaʊn","pos":"noun","senses":[{"en":"a word that is used instead of a noun or noun phrase, for example he, it, hers, me, them, etc.","cn":"代词（代替名词或名词词组的单词）","lab":"British English","ex":{"en":"demonstrative/interrogative/possessive/relative pronouns","cn":"指示／疑问／物主／关系代词"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"代词；代名词","en":"A pronoun is a word that you use to refer to someone or something when you do not need to use a noun, often because the person or thing has been mentioned earlier. Examples are 'it', 'she', 'something', and 'myself'."}]},"media":{"uk":"media/uk/pronoun__gb_1.mp3","us":"media/us/pronoun__us_1.mp3"},"examples":[{"en":"demonstrative/interrogative/possessive/relative pronouns","cn":"指示/疑问/物主/关系代词"}]},"presume":{"media":{"uk":"media/uk/presume__gb_1.mp3","us":"media/us/presume__us_1.mp3"},"oxford":{"phon":"prɪˈzjuːm","pos":"verb","senses":[{"en":"to suppose that something is true, although you do not have actual proof","cn":"假设；假定","g":"[intransitive, transitive]","ex":{"en":"They are very expensive, I presume?","cn":"我想这些东西很贵吧？"}},{"en":"to accept that something is true until it is shown not to be true, especially in court","cn":"（尤指法庭上）推定，假定","g":"[transitive]","ex":{"en":"Twelve passengers are missing, presumed dead.","cn":"有十二名旅客失踪，并已推定罹难。"}},{"en":"to accept something as true or existing and to act on that basis","cn":"设定；设想；假设","g":"[transitive]","lab":"formal","ex":{"en":"The course seems to presume some previous knowledge of the subject.","cn":"这门课程似乎是以具备某些基础知识为前提的。"}},{"en":"to behave in a way that shows a lack of respect by doing something that you have no right to do","cn":"妄行；越权行事","g":"[intransitive]","lab":"formal","ex":{"en":"I wouldn't presume to tell you how to run your own business.","cn":"我不会僭越去指点你该如何经营你自己的事业。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（不肯定地）认为，相信，推测","en":"If you presume that something is the case, you think that it is the case, although you are not certain.","ex":{"en":"I presume you're here on business","cn":"我想你是来这里出差的。"}},{"pos":"VERB 动词","cn":"冒昧；擅自主张；妄行","en":"If you say that someone presumes to do something, you mean that they do it even though they have no right to do it.","ex":{"en":"They're resentful that outsiders presume to meddle in their affairs","cn":"他们对外人擅自干预他们的事务非常愤慨。"}},{"pos":"VERB 动词","cn":"假设；假定","en":"If an idea, theory, or plan presumes certain facts, it regards them as true so that they can be used as a basis for further ideas and theories.","ex":{"en":"The legal definition of 'know' often presumes mental control","cn":"“知晓”的法律定义通常假定存在思维控制能力。"}}]},"examples":[{"en":"Little is known of the youngest son; it is presumed that he died young.","cn":"对于最小的儿子一般所知甚少，据推测他已经夭亡。"},{"en":"In English law, a person is presumed innocent until proved guilty.","cn":"英国法律规定，一个人被证明有罪前假定为无罪。"}]},"primitiveness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a simple machine, tool etc has only a few parts and is not made in a complicated way","cn":""},{"en":"basic machines, equipment, or tools only have the most necessary features and you cannot use them to do unusual, difficult, or complicated things","cn":""}]},"examples":[{"en":"the tools used by primitive man","cn":"","src":"ld"},{"en":"The first station buildings were quite primitive.","cn":"","src":"ld"}],"media":{"uk":"media/uk/primitiveness__gb_1.mp3","us":"media/us/primitiveness__us_1.mp3"},"oxford":{"phon":"ˈprɪmətɪvnəs","pos":"noun","senses":[{"en":"the fact of having a very simple society with no industry, etc.","cn":"原始的；远古的","ex":{"en":"the primitiveness of village life","cn":"乡村生活的原始性"}},{"en":"the fact of being very simple and old-fashioned, especially when something is not convenient or comfortable","cn":"简陋的；落后的；发展水平低的","ex":{"en":"I was shocked by the primitiveness of their methods.","cn":"我对他们方法的原始性感到震惊。"}}]}},"preferential":{"media":{"uk":"media/uk/preferential__gb_1.mp3","us":"media/us/preferential__us_1.mp3"},"oxford":{"phon":"ˌprefəˈrenʃl","pos":"adjective","senses":[{"en":"giving an advantage to a particular person or group","cn":"优先的；优惠的；优待的","ex":{"en":"Don't expect to get preferential treatment.","cn":"不要指望受到优待。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优先的；优惠的；优待的","en":"If you get preferential treatment, you are treated better than other people and therefore have an advantage over them.","ex":{"en":"Despite her status, the Duchess will not be given preferential treatment.","cn":"虽然地位显赫，但是公爵夫人并不会得到优待。"}}]},"examples":[{"en":"Don't expect to get preferential treatment.","cn":"不要指望受到优待。"},{"en":"preferential credit terms for reliable borrowers","cn":"向可靠借款人提供的优惠信贷条件"}]},"private":{"media":{"uk":"media/uk/private__gb_1.mp3","us":"media/us/private__us_1.mp3"},"oxford":{"phon":"ˈpraɪvət","pos":"adjective","senses":[{"en":"belonging to or for the use of a particular person or group; not for public use","cn":"私有的；私用的；自用的","g":"[usually before noun]","sc":"not public","ex":{"en":"The sign said, ‘Private property. Keep out.’","cn":"标牌上写着：“私人领地，禁止进入。”"}},{"en":"intended for or involving a particular person or group of people, not for people in general or for others to know about","cn":"为一部分人的；私人的；秘密的","sc":"conversation/meeting","ex":{"en":"You shouldn't listen to other people's private conversations.","cn":"你不应该偷听别人的私人谈话。"}},{"en":"that you do not want other people to know about","cn":"内心的；隐秘的；私下的","sc":"feelings/information","ex":{"en":"She was scared of revealing her private thoughts and feelings.","cn":"她害怕流露个人的想法和情感。"}},{"en":"owned or managed by an individual person or an independent company rather than by the state","cn":"私立的；私营的；民营的","g":"[usually before noun]","sc":"not owned/run by state","ex":{"en":"a private firm/business/hospital","cn":"私人公司／企业／医院"}},{"en":"provided for a fee by an individual person or an independent organization rather than by the state","cn":"私立的；私营的；民营的","lab":"British English","sc":"not owned/run by state","ex":{"en":"She gives private English lessons at weekends.","cn":"她周末做私人英语家教。"}},{"en":"working or acting for yourself rather than for the state or for a group or company","cn":"个体的；独立的；私人的","g":"[only before noun]","sc":"not owned/run by state","ex":{"en":"a private contractor/investigator","cn":"私人承包商／调查员"}},{"en":"not connected with your work or official position","cn":"与工作（或官职）无关的；个人的；私人的","g":"[usually before noun]","sc":"not work","ex":{"en":"a politician’s private life","cn":"政界人物的私生活"}},{"en":"where you are not likely to be interrupted; quiet","cn":"僻静的；不受打扰的","sc":"quiet","ex":{"en":"Let's go somewhere a bit more private.","cn":"咱们另找个僻静些的地方吧。"}},{"en":"not wanting to share thoughts and feelings with other people","cn":"不愿吐露心思的；内向的；不爱交流思想感情的","g":"[usually before noun]","sc":"person","ex":{"en":"He's a very private person.","cn":"他是个闷葫芦。"}},{"en":"that you receive from property or other sources but do not have to earn","cn":"由财产增溢的；间接收入的；非劳动所得的","sc":"money","ex":{"en":"He has a private income.","cn":"他有一笔私人收入。"}},{"en":"a soldier of the lowest rank in the army","cn":"二等兵，列兵（级别最低的士兵）","g":"[countable]","ex":{"en":"Private (John) Smith","cn":"列兵（约翰·）史密斯"},"pos":"noun"},{"en":"private parts (= a polite way of referring to the sexual organs without saying their names)","cn":"私处","g":"[plural]","lab":"informal","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（产业、服务）私立的，私有的，私营的，民营的","en":"Private industries and services are owned or controlled by an individual person or a commercial company, rather than by the state or an official organization.","ex":{"en":"...a joint venture with private industry","cn":"与私营企业建立的合资企业"}},{"pos":"ADJ 形容词","cn":"个人的；私人的","en":"Private individuals are acting only for themselves, and are not representing any group, company, or organization.","ex":{"en":"...the law's insistence that private citizens are not permitted to have weapons","cn":"法律坚持要求公民个人不得持有武器"}},{"pos":"ADJ 形容词","cn":"（财物等）个人所有的，私有的，私人的","en":"Your private things belong only to you, or may only be used by you.","ex":{"en":"The landowners have had to sell their private aircraft","cn":"这些土地所有者不得不卖掉自己的私人飞机。"}},{"pos":"ADJ 形容词","cn":"（地方、聚会等）非公开的，私人的","en":"Private places or gatherings may be attended only by a particular group of people, rather than by the general public.","ex":{"en":"673 private golf clubs took part in a recent study","cn":"673家私人高尔夫俱乐部参与了最近的研究。"}},{"pos":"ADJ 形容词","cn":"（会议、讨论、活动等）秘密的，私下的","en":"Private meetings, discussions, and other activities involve only a small number of people, and very little information about them is given to other people.","ex":{"en":"Don't bug private conversations, and don't buy papers that reprint them.","cn":"不要窃听私人谈话，不要购买重印这些谈话的报纸。"}},{"pos":"ADJ 形容词","cn":"（生活）私人的，个人的，与工作无关的","en":"Your private life is that part of your life that is concerned with your personal relationships and activities, rather than with your work or business.","ex":{"en":"I've always kept my private and professional life separate","cn":"我总是将私生活和工作分开。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（想法、感觉）私密的，隐私的，内心的","en":"Your private thoughts or feelings are ones that you do not talk about to other people.","ex":{"en":"We all felt as if we were intruding on his private grief.","cn":"我们都觉得似乎触及到了他内心的伤痛。"}},{"pos":"ADJ 形容词","cn":"只有自己人明白的","en":"You can use private to describe situations or activities that are understood only by the people involved in them, and not by anyone else.","ex":{"en":"Chinese waiters stood in a cluster, sharing a private joke","cn":"华人服务生们站在一起，讲着只有他们自己才懂的笑话。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方等）僻静的，幽静的，无人打扰的","en":"If you describe a place as private, or as somewhere where you can be private, you mean that it is a quiet place and you can be alone there without being disturbed.","ex":{"en":"It was the only reasonably private place they could find.","cn":"这是他们能找到的唯一一个还算僻静之处。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）内敛的，文静内向的，孤僻的","en":"If you describe someone as a private person, you mean that they are very quiet by nature and do not reveal their thoughts and feelings to other people.","ex":{"en":"She has always been a rather private person","cn":"她一直是一个相当内向的人。"}},{"pos":"ADJ 形容词","cn":"私人教授的；私下辅导的","en":"You can use private to describe lessons that are not part of ordinary school activity, and which are given by a teacher to an individual pupil or a small group, usually in return for payment.","ex":{"en":"Martial arts: Private lessons: £8 per hour.","cn":"武术：私人教授：每小时8英镑"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"列兵，二等兵（级别最低的士兵）","en":"A private is a soldier of the lowest rank in an army or the marines.","ex":{"en":"One gunner in each battery was an NCO and the rest were privates.","cn":"每个炮兵连都有一个炮手是军士，其余都是二等兵。"}},{"pos":"N-PLURAL 复数名词","cn":"私处；阴部","en":"Your privates are your genitals.","ex":{"en":"You should wash your feet and your privates every day.","cn":"应该每天洗脚，并清洗阴部。"}},{"pos":"PHRASE 短语","cn":"私下地；秘密地","en":"If you do something in private, you do it without other people being present, often because it is something that you want to keep secret.","ex":{"en":"Some of what we're talking about might better be discussed in private.","cn":"我们要谈论的一些事情最好是在私下里讨论。"}}]},"examples":[{"en":"In public he supported the official policy, but privately he was sure it would fail.","cn":"他明里支持这项官方政策，但暗中却确信它会失败。"},{"en":"The hotel has 110 bedrooms, all with private bathrooms.","cn":"这家旅馆有 110 间客房，各有独立卫生间。"}]},"precision":{"media":{"uk":"media/uk/precision__gb_1.mp3","us":"media/us/precision__us_1.mp3"},"oxford":{"phon":"prɪˈsɪʒn","pos":"noun","senses":[{"en":"the quality of being exact, accurate and careful","cn":"精确；准确；细致","ex":{"en":"Her writing is imaginative but lacks precision.","cn":"她的文章想象力丰富，但是不够细致。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精确；精密","en":"If you do something with precision, you do it exactly as it should be done.","ex":{"en":"The choir sang with precision","cn":"唱诗班的演唱准确无误。"}}]},"examples":[{"en":"Historians can't estimate the date with any (degree of) precision.","cn":"历史学家无法准确估算这个日期。"},{"en":"He chose his words with precision.","cn":"他用词确切。"}]},"proceeds":{"media":{"uk":"media/uk/proceeds__gb_1.mp3","us":"media/us/proceeds__us_1.mp3"},"oxford":{"phon":"ˈprəʊsiːdz","pos":"noun","senses":[{"en":"the money that you receive when you sell something or organize a performance, etc.; profits","cn":"（售物或演出等的）收入，收益，进款","ex":{"en":"She sold her car and bought a piano with the proceeds.","cn":"她卖掉了汽车，然后用这笔收入买了一架钢琴。"}}]},"examples":[{"en":"She sold her car and bought a piano with the proceeds.","cn":"她卖掉了汽车，然后用这笔收入买了一架钢琴。"},{"en":"The proceeds of the concert will go to charity.","cn":"这次音乐会的收入将捐给慈善机构。"}],"base":"proceed"},"probationary":{"media":{"uk":"media/uk/probationary__gb_1.mp3","us":"media/us/probationary__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"试用的；见习的","en":"A probationary period is a period after someone starts a job, during which their employer can decide whether the person is suitable and should be allowed to continue.","ex":{"en":"Teachers should have a probationary period of two years.","cn":"教师应该有2年的见习期。"}}]},"examples":[{"en":"young probationary teachers","cn":"年轻的见习教师"},{"en":"a probationary period","cn":"试用期"}],"oxford":{"phon":"prəˈbeɪʃnri","pos":"adjective","senses":[{"en":"connected with a time of training and testing when you start a new job to see if you are suitable for the work","cn":"试用期；见习期；考察期","ex":{"en":"a probationary period","cn":"试用期"}},{"en":"connected with the period of time when a person who has committed a crime is on probation","cn":"缓刑期的","lab":"law"}]}},"pride":{"media":{"uk":"media/uk/pride__gb_1.mp3","us":"media/us/pride__us_1.mp3"},"oxford":{"phon":"praɪd","pos":"noun","senses":[{"en":"a feeling of being pleased or satisfied that you get when you or people who are connected with you have done something well or own something that other people admire","cn":"自豪；骄傲；得意感","g":"[uncountable, singular]","sc":"pleasure","ex":{"en":"The sight of her son graduating filled her with pride.","cn":"看到儿子毕业她充满了自豪。"}},{"en":"a person or thing that makes people feel pleased or satisfied","cn":"令人自豪的人（或事物）","g":"[singular]","sc":"pleasure","ex":{"en":"The new sports stadium is the pride of the town.","cn":"新体育场是这个城市的骄傲。"}},{"en":"the feeling of respect that you have for yourself","cn":"自尊心；自尊；尊严","g":"[uncountable]","sc":"respect for yourself","ex":{"en":"Pride would not allow him to accept the money.","cn":"自尊心不容他接受这笔钱。"}},{"en":"the feeling that you are better or more important than other people","cn":"自负；傲慢","g":"[uncountable]","lab":"disapproving","sc":"respect for yourself","ex":{"en":"She was full of pride and arrogance and despised ordinary people.","cn":"她傲慢自大，鄙视普通人。"}},{"en":"a group of lions","cn":"狮群","g":"[countable + singular or plural verb]","sc":"lions"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自豪；得意","en":"Pride is a feeling of satisfaction which you have because you or people close to you have done something good or possess something good.","ex":{"en":"...the sense of pride in a job well done","cn":"做好一项工作的自豪感"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊严；自尊；自尊心","en":"Pride is a sense of the respect that other people have for you, and that you have for yourself.","ex":{"en":"Davis had to salvage his pride","cn":"戴维斯必须得挽回他的自尊。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"骄傲；傲慢","en":"Someone's pride is the feeling that they have that they are better or more important than other people.","ex":{"en":"His pride may still be his downfall.","cn":"他的傲慢可能还会毁了他。"}},{"pos":"VERB 动词","cn":"为…感到自豪；对…感到得意","en":"If you pride yourself on a quality or skill that you have, you are very proud of it.","ex":{"en":"Smith prides himself on being able to organise his own life","cn":"史密斯对能够把自己的生活安排得井井有条感到很得意。"}},{"pos":"N-COUNT 可数名词","cn":"（狮）群","en":"A pride of lions is a group of lions that live together."},{"pos":"PHRASE 短语","cn":"引以为豪的人（或事物）","en":"Someone or something that is your pride and joy is very important to you and makes you feel very happy.","ex":{"en":"The bike soon became his pride and joy.","cn":"这辆自行车很快就成了他的骄傲。"}},{"pos":"PHRASE 短语","cn":"首要地位；最重要的地位","en":"If something takes pride of place, it is treated as the most important thing in a group of things.","ex":{"en":"A three-foot-high silver World Championship cup takes pride of place near a carved wooden chair","cn":"一个3英尺高的世界锦标赛银质奖杯放在一把木雕椅附近，位置非常显眼。"}},{"pos":"PHRASE 短语","cn":"放下自尊；忍气吞声；放下架子","en":"If you swallow your pride, you decide to do something even though you think it will cause you to lose some respect.","ex":{"en":"No doubt his old mother would now swallow her pride and go and live with Gladys.","cn":"无疑，他的老母亲如今只能放下身价，去和格拉迪斯住在一起。"}}]},"examples":[{"en":"We take great pride in offering the best service in town.","cn":"我们以能够提供全城最好的服务而自豪。"},{"en":"It's time to swallow your pride (= hide your feelings of pride) and ask for your job back.","cn":"这时候你应该收起自尊，讨回那份工作。"}]},"profusion":{"media":{"uk":"media/uk/profusion__gb_1.mp3","us":"media/us/profusion__us_1.mp3"},"oxford":{"phon":"prəˈfjuːʒn","pos":"noun","senses":[{"en":"a very large quantity of something","cn":"大量；众多","ex":{"en":"a profusion of colours","cn":"色彩斑斓"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"大量；丰富","en":"If there is a profusion of something or if it occurs in profusion, there is a very large quantity or variety of it.","ex":{"en":"The Dart is a delightful river with a profusion of wild flowers along its banks","cn":"达特河是一条令人心旷神怡的河，岸边到处开着野花。"}}]},"examples":[{"en":"Roses grew in profusion against the old wall.","cn":"老旧墙边遍生玫瑰。"},{"en":"a profusion of colours","cn":"色彩斑斓"}]},"prime":{"media":{"uk":"media/uk/prime__gb_1.mp3","us":"media/us/prime__us_1.mp3"},"oxford":{"phon":"praɪm","pos":"adjective","senses":[{"en":"main; most important; basic","cn":"主要的；首要的；基本的","ex":{"en":"My prime concern is to protect my property.","cn":"我最关心的是保护自己的财产。"}},{"en":"of the best quality; excellent","cn":"优质的；上乘的；优异的","ex":{"en":"prime (cuts of) beef","cn":"上等的牛肉（块）"}},{"en":"a prime example of something is one that is typical of it","cn":"典型的；有代表性的","ex":{"en":"The building is a prime example of 1960s architecture.","cn":"这座大楼是 20 世纪 60 年代的典型建筑。"}},{"en":"most likely to be chosen for something; most suitable","cn":"最可能的；首选的；最适宜的","ex":{"en":"The house is isolated and a prime target for burglars.","cn":"这座孤零零的房子是盗贼的首选目标。"}},{"en":"the time in your life when you are strongest or most successful","cn":"盛年；年富力强的时期；鼎盛时期","g":"[singular]","ex":{"en":"a young woman in her prime","cn":"正当妙龄的女郎"},"pos":"noun"},{"en":"a number that can be divided exactly only by itself and 1, for example 7, 17 and 41","cn":"素数，质数（只能被 1 和其自身整除）","g":"[countable]","pos":"noun"},{"en":"to prepare somebody for a situation so that they know what to do, especially by giving them special information","cn":"事先指点；使（某人）做好准备","ex":{"en":"They had been primed with good advice.","cn":"他们事先得到了高人指点。"},"pos":"verb"},{"en":"to make something ready for use or action","cn":"把（事物）准备好","ex":{"en":"The bomb was primed, ready to explode.","cn":"炸弹已准备好，可随时引爆。"},"pos":"verb"},{"en":"to prepare wood, metal, etc. for painting by covering it with a special paint that helps the next layer of paint to stay on","cn":"在（金属、木材等上）打底漆","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"主要的；首要的；最为重要的","en":"You use prime to describe something that is most important in a situation.","ex":{"en":"Political stability, meanwhile, will be a prime concern","cn":"同时，政治稳定性将放在首位。"}},{"pos":"ADJ 形容词","cn":"优质的；一流的；上等的；最好的","en":"You use prime to describe something that is of the best possible quality.","ex":{"en":"It was one of the City's prime sites, near the Stock Exchange.","cn":"这是伦敦最好的地段之一，离证券交易所很近。"}},{"pos":"ADJ 形容词","cn":"最典型的；最有代表性的","en":"You use prime to describe an example of a particular kind of thing that is absolutely typical.","ex":{"en":"The prime example is Macy's, once the undisputed king of California retailers.","cn":"最典型的例子是梅西百货，它曾经是加利福尼亚无可争辩的零售巨头。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"全盛时期；最活跃时期；最成功时期","en":"If someone or something is in their prime, they are at the stage in their existence when they are at their strongest, most active, or most successful.","ex":{"en":"Maybe I'm just coming into my prime now","cn":"也许我现在正要步入事业辉煌期。"}},{"pos":"VERB 动词","cn":"事先指点；使做好准备","en":"If you prime someone to do something, you prepare them to do it, for example by giving them information about it beforehand.","ex":{"en":"Claire wished she'd primed Sarah beforehand","cn":"克莱尔真希望她事先指点过萨拉。"}},{"pos":"VERB 动词","cn":"把（炸弹、枪支）装好","en":"If someone primes a bomb or a gun, they prepare it so that it is ready to explode or fire.","ex":{"en":"He was priming the bomb to go off in an hour's time","cn":"他正在装炸弹，设定为在一个小时之内爆炸。"}},{"pos":"","cn":"","en":"to prime the pump→see: ;"}]},"examples":[{"en":"The building is a prime example of 1960s architecture.","cn":"这座大楼是 20 世纪 60 年代的典型建筑。"},{"en":"He had primed his friends to give the journalists as little information as possible.","cn":"他已经知会他的朋友，尽量少向记者透露消息。"}]},"price":{"media":{"uk":"media/uk/price__gb_1.mp3","us":"media/us/price__us_1.mp3"},"oxford":{"phon":"praɪs","pos":"noun","senses":[{"en":"the amount of money that you have to pay for something","cn":"价格；价钱；物价","g":"[countable, uncountable]","ex":{"en":"Boat for sale, price £8 000","cn":"出售小船，价格 8 000 英镑"}},{"en":"the unpleasant things that you must do or experience in order to achieve something or as a result of achieving something","cn":"代价","g":"[singular]","ex":{"en":"Criticism is part of the price of leadership.","cn":"挨批评是当领袖要付出的代价之一。"}},{"en":"the numbers that tell you how much money you will receive if the horse that you bet on wins the race","cn":"投注赔率","g":"[countable]","ex":{"en":"Six to one is a good price for that horse.","cn":"那匹马有六比一的赔率很不错。"}},{"en":"to fix the price of something at a particular level","cn":"给…定价；为…作价","g":"[transitive, usually passive, intransitive]","ex":{"en":"The main courses are all reasonably priced.","cn":"几道主菜都价格合理。"},"pos":"verb"},{"en":"to write or stick tickets on goods to show how much they cost","cn":"（在商品上）标价，贴价格标签","pos":"verb"},{"en":"to compare the prices of different types of the same thing","cn":"比较…的价格","ex":{"en":"We priced various models before buying this one.","cn":"我们比较了多种型号的价格以后才买了这一款。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"价格；价钱","en":"The price of something is the amount of money that you have to pay in order to buy it.","ex":{"en":"...a sharp increase in the price of petrol","cn":"汽油价格猛涨"}},{"pos":"N-SING 单数名词","cn":"代价","en":"The price that you pay for something that you want is an unpleasant thing that you have to do or suffer in order to get it.","ex":{"en":"Slovenia will have to pay a high price for independence","cn":"斯洛文尼亚将为独立付出巨大的代价。"}},{"pos":"VERB 动词","cn":"把…定价为","en":"If something is priced at a particular amount, the price is set at that amount.","ex":{"en":"The shares are expected to be priced at about 330p","cn":"这些股票的价格可能会定在330便士左右。"}},{"pos":"PHRASE 短语","cn":"不惜任何代价；不计后果","en":"If you want something at any price, you are determined to get it, even if unpleasant things happen as a result.","ex":{"en":"If they wanted a deal at any price, they would have to face the consequences","cn":"如果他们无论如何都想达成交易，他们就得承担其后果。"}},{"pos":"PHRASE 短语","cn":"以极高价格","en":"If you can buy something that you want at a price, it is for sale, but it is extremely expensive.","ex":{"en":"Most goods are available, but at a price.","cn":"大多数商品都有售，但是价格极高。"}},{"pos":"PHRASE 短语","cn":"以一定代价","en":"If you get something that you want at a price, you get it but something unpleasant happens as a result.","ex":{"en":"Fame comes at a price","cn":"出名是有代价的。"}},{"pos":"PHRASE 短语","cn":"悬赏缉拿；悬赏刺杀","en":"If there is a price on someone's head, an amount of money has been offered for the capture or killing of that person.","ex":{"en":"He remains at large despite the high price put on his head by the authorities.","cn":"尽管当局悬赏重金缉拿他，他仍旧逍遥法外。"}},{"pos":"PHRASE 短语","cn":"给…定价","en":"If you say that you cannot put a price on something, you mean that it is very valuable.","ex":{"en":"You can't put a price on friendship","cn":"友谊无价。"}},{"pos":"PHRASE短语","cn":"（表示强调）…可能吗","en":"You use what price in front of a word or expression that refers to something happening when you want to ask how likely it is to happen. You usually do this to emphasize either that it is very likely or very unlikely.","ex":{"en":"What price a glorious repeat of last week's triumph?","cn":"还有可能再次上演上周的辉煌胜利吗？"}},{"pos":"PHRASE 短语","cn":"…又有什么用呢","en":"You use 'at what price ?' to comment on the fact that the consequences of doing something are unpleasant.","ex":{"en":"Yes, they are free of him, but at what price to themselves, their families, those left behind?","cn":"是的，他们离开了他，但是对他们自己、他们的家人以及那些留下来的人又有什么用呢？"}},{"pos":"","cn":"","en":"to price yourself out of the market→see: ;"}]},"examples":[{"en":"It's amazing how much computers have come down in price over the past few years.","cn":"过去这几年，电脑的价格大大降低，简直令人惊讶。"},{"en":"The winner will receive a prize to the value of £1 000.","cn":"获胜者将得到价值为 1 000 英镑的奖品。"}]},"premier":{"media":{"uk":"media/uk/premier__gb_1.mp3","us":"media/us/premier__us_1.mp3"},"oxford":{"phon":"ˈpremiə(r)","pos":"adjective","senses":[{"en":"most important, famous or successful","cn":"首要的；最著名的；最成功的；第一的","lab":"British English, sport，，","ex":{"en":"one of the country’s premier chefs","cn":"国家名厨之一"}},{"en":"used especially in newspapers, etc. to mean ‘prime minister’","cn":"（尤用于报章等）首相，总理","ex":{"en":"She was sworn in as premier last week.","cn":"她上周宣誓就任首相。"},"pos":"noun"},{"en":"(in Canada) the first minister of a province or territory","cn":"（加拿大的）省总理，地区总理","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总理；首相","en":"The leader of the government of a country is sometimes referred to as the country's premier .","ex":{"en":"...Australian premier Paul Keating.","cn":"澳大利亚总理保罗·基廷"}},{"pos":"ADJ 形容词","cn":"最好的；最佳的；最重要的","en":"Premier is used to describe something that is considered to be the best or most important thing of a particular type.","ex":{"en":"...the country's premier opera company.","cn":"这个国家的顶尖歌剧团"}}]},"examples":[{"en":"one of the country's premier chefs","cn":"国家名厨之一"},{"en":"( BrE ) ( sport","cn":"体 ) the Premier League/Division 超级联赛"}]},"previous":{"media":{"uk":"media/uk/previous__gb_1.mp3","us":"media/us/previous__us_1.mp3"},"oxford":{"phon":"ˈpriːviəs","pos":"adjective","senses":[{"en":"happening or existing before the event or object that you are talking about","cn":"先前的；以往的","ex":{"en":"No previous experience is necessary for this job.","cn":"这一工作无需相关的经验。"}},{"en":"immediately before the time you are talking about","cn":"（时间上）稍前的","ex":{"en":"the previous year/month/week/night","cn":"前一年；前一个月；前一周；前一夜"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"先前的；以前的；早先的","en":"A previous event or thing is one that happened or existed before the one that you are talking about.","ex":{"en":"She has a teenage daughter from a previous marriage","cn":"她前一段婚姻有一个十几岁的女儿。"}},{"pos":"ADJ 形容词","cn":"上一次的；上一个的","en":"You refer to the period of time or the thing immediately before the one that you are talking about as the previous one.","ex":{"en":"It was a surprisingly dry day after the rain of the previous week","cn":"上星期刚下过雨，天气却出奇地干燥。"}}]},"examples":[{"en":"I couldn't believe it when I heard the news. I'd only seen him the previous day.","cn":"听到这消息时，我不敢相信；我就在前一天还见到过他。"},{"en":"The judge will take into consideration any previous convictions.","cn":"任何前科法官都将予以考虑。"}]},"prolonged":{"media":{"uk":"media/uk/prolonged__gb_1.mp3","us":"media/us/prolonged__us_1.mp3"},"oxford":{"phon":"prəˈlɒŋd","pos":"adjective","senses":[{"en":"continuing for a long time","cn":"持久的；长期的","ex":{"en":"a prolonged illness","cn":"长期的病"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"长期的；持续很久的；时间长的","en":"A prolonged event or situation continues for a long time, or for longer than expected.","ex":{"en":"...a prolonged period of low interest rates.","cn":"长期的低利率"}}]},"examples":[{"en":"a prolonged period of dry weather","cn":"长期的干旱天气"},{"en":"a prolonged illness","cn":"长期的病"}],"base":"prolong"},"preexisting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"先前存在的；先于…而存在的","en":"A pre-existing situation or thing exists already or existed before something else.","ex":{"en":"...the pre-existing tensions between the two countries.","cn":"两国之间已经存在的紧张局势"}}]}},"privileged":{"media":{"uk":"media/uk/privileged__gb_1.mp3","us":"media/us/privileged__us_1.mp3"},"oxford":{"phon":"ˈprɪvəlɪdʒd","pos":"adjective","senses":[{"en":"having special rights or advantages that most people do not have","cn":"有特权的；受特别优待的","lab":"sometimes disapproving","ex":{"en":"Those in authority were in a privileged position.","cn":"过去，当权者自有特权。"}},{"en":"having an opportunity to do something that makes you feel proud","cn":"荣幸；幸运","g":"[not before noun]","ex":{"en":"We are privileged to welcome you as our speaker this evening.","cn":"我们荣幸地欢迎您今晚来讲演。"}},{"en":"known only to a few people and legally protected so that it does not have to be made public","cn":"特许保密的","lab":"law","ex":{"en":"I’m sorry, that’s privileged information.","cn":"抱歉，那是机密信息。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有特权的；享受特殊待遇的","en":"Someone who is privileged has an advantage or opportunity that most other people do not have, often because of their wealth or high social class.","ex":{"en":"They were, by and large, a very wealthy, privileged elite.","cn":"他们基本上是一些非常有钱有势的精英。"}},{"pos":"ADJ 形容词","cn":"（信息）保密的，只有少数人知道的","en":"Privileged information is known by only a small group of people, who are not legally required to give it to anyone else.","ex":{"en":"The data is privileged information, not to be shared with the general public","cn":"这些数据是保密的，并不向大众公开。"}}]},"examples":[{"en":"In those days, only a privileged few had the vote.","cn":"在那个时代，只有少数特殊的人才享有选举权。"},{"en":"We are privileged to welcome you as our speaker this evening.","cn":"我们荣幸地欢迎您今晚来讲演。"}],"base":"privilege"},"prosperity":{"media":{"uk":"media/uk/prosperity__gb_1.mp3","us":"media/us/prosperity__us_1.mp3"},"oxford":{"phon":"prɒˈsperəti","pos":"noun","senses":[{"en":"the state of being successful, especially in making money","cn":"兴旺；繁荣；成功；昌盛","ex":{"en":"Our future prosperity depends on economic growth.","cn":"我们未来的繁荣昌盛依赖经济的发展。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"繁荣；兴旺；富足","en":"Prosperity is a condition in which a person or community is doing well financially.","ex":{"en":"...a new era of peace and prosperity.","cn":"和平繁荣的新时代"}}]},"examples":[{"en":"Our future prosperity depends on economic growth.","cn":"我们未来的繁荣昌盛依赖经济的发展。"},{"en":"The country is enjoying a period of peace and prosperity.","cn":"国家正值太平盛世。"}]},"pronounce":{"oxford":{"phon":"prəˈnaʊns","pos":"verb","senses":[{"en":"to make the sound of a word or letter in a particular way","cn":"发音；读（音）","g":"[transitive]","ex":{"en":"to pronounce a word/syllable/vowel/consonant","cn":"发音一个单词/音节/元音/辅音"}},{"en":"to give a judgement, opinion or statement formally, officially or publicly","cn":"正式宣布（或公布、授予等）","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"to pronounce an opinion","cn":"发表意见"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发…的音；读","en":"To pronounce a word means to say it using particular sounds.","ex":{"en":"Have I pronounced your name correctly?","cn":"你的名字我念得对吗？"}},{"pos":"VERB 动词","cn":"宣称；宣告；宣布；断言","en":"If you pronounce something to be true, you state that it is the case.","ex":{"en":"A specialist has now pronounced him fully fit","cn":"一位专家已宣布他的身体完全恢复了。"}},{"pos":"VERB 动词","cn":"宣称；宣布","en":"If someone pronounces a verdict or opinion on something, they give their verdict or opinion.","ex":{"en":"The authorities took time to pronounce their verdicts","cn":"当局斟酌权衡再三才宣布他们的决定。"}}]},"media":{"uk":"media/uk/pronounce__gb_1.mp3","us":"media/us/pronounce__us_1.mp3"},"examples":[{"en":"The minister will pronounce on further security measures later today.","cn":"今天稍后，部长将发表进一步的安全措施。"},{"en":"She was pronounced dead on arrival at the hospital.","cn":"到达医院时她被宣告已经死亡。"}]},"proximity":{"media":{"uk":"media/uk/proximity__gb_1.mp3","us":"media/us/proximity__us_1.mp3"},"oxford":{"phon":"prɒkˈsɪməti","pos":"noun","senses":[{"en":"the state of being near somebody/something in distance or time","cn":"（时间或空间）接近，邻近，靠近","ex":{"en":"The proximity of the college to London makes it very popular.","cn":"这所学院因靠近伦敦而备受欢迎。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"接近；临近；邻近","en":"Proximity to a place or person is nearness to that place or person.","ex":{"en":"Part of the attraction is Darwin's proximity to Asia","cn":"达尔文市的魅力一部分在于它靠近亚洲。"}}]},"examples":[{"en":"the death of two members of her family in close proximity","cn":"她的两个亲人在短时间内的相继去世"},{"en":"The proximity of the college to London makes it very popular.","cn":"这所学院因靠近伦敦而备受欢迎。"}]},"provided":{"media":{"uk":"media/uk/provided__gb_1.mp3","us":"media/us/provided__us_1.mp3"},"oxford":{"phon":"prəˈvaɪdɪd","pos":"conjunction","senses":[{"en":"used to say what must happen or be done to make it possible for something else to happen","cn":"如果；假如；在…条件下","ex":{"en":"We'll buy everything you produce, provided of course the price is right.","cn":"我们将采购你们的全部产品，当然价格得合适。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"如果；假如；只要","en":"If you say that something will happen provided or provided that something else happens, you mean that the first thing will happen only if the second thing also happens.","ex":{"en":"The other banks are going to be very eager to help, provided that they see that he has a specific plan","cn":"如果看到他有具体的计划，其他银行会很愿意提供帮助。"}}]},"examples":[{"en":"Provided that you have the money in your account, you can withdraw up to £100 a day.","cn":"只要账户存款足够，每天可提取不超过 100 英镑。"},{"en":"We'll buy everything you produce, provided of course the price is right.","cn":"当然了，倘若价格合适，我们将采购你们的全部产品。"}],"base":"provide"},"printed":{"lemma":"print"},"promptly":{"oxford":{"phon":"ˈprɒmptli","pos":"adverb","senses":[{"en":"without delay","cn":"迅速地；立即","ex":{"en":"She deals with all the correspondence promptly and efficiently.","cn":"她迅速有效地处理全部来往信件。"}},{"en":"exactly at the correct time or at the time mentioned","cn":"及时地；准时地","ex":{"en":"They arrived promptly at two o'clock.","cn":"他们于两点钟准时到达。"}},{"en":"immediately","cn":"立即；立刻；马上","ex":{"en":"She read the letter and promptly burst into tears.","cn":"她一看信眼泪就夺眶而出。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"立即；马上；及时","en":"If you do something promptly, you do it immediately.","ex":{"en":"Sister Francesca entered the chapel, took her seat, and promptly fell asleep.","cn":"弗朗西丝卡修女走进小教堂，坐下来，很快就睡着了。"}},{"pos":"ADV 副词","cn":"准时地","en":"If you do something promptly at a particular time, you do it at exactly that time.","ex":{"en":"Promptly at a quarter past seven, we left the hotel.","cn":"我们于7点一刻准时离开了宾馆。"}}]},"media":{"uk":"media/uk/promptly__gb_1.mp3","us":"media/us/promptly__us_1.mp3"},"examples":[{"en":"She deals with all the correspondence promptly and efficiently.","cn":"她迅速有效地处理全部来往信件。"},{"en":"She read the letter and promptly burst into tears.","cn":"她一看信眼泪就夺眶而出。"}]},"precisely":{"oxford":{"phon":"prɪˈsaɪsli","pos":"adverb","senses":[{"en":"exactly","cn":"准确地；恰好地","ex":{"en":"They look precisely the same to me.","cn":"依我看，他们的长相一模一样。"}},{"en":"accurately; carefully","cn":"精确地；细心地；仔细地","ex":{"en":"to describe something precisely","cn":"精确地描述某事物"}},{"en":"used to emphasize that something is very true or obvious","cn":"（强调真实或明显）正是，确实","ex":{"en":"It's precisely because I care about you that I don't like you staying out late.","cn":"正因为我关心你，我才不要你太晚回家。"}},{"en":"used to emphasize that you agree with a statement, especially because you think it is obvious or is similar to what you have just said","cn":"（加强同意的语气）对，的确如此，一点也不错","ex":{"en":"‘It's not that easy, is it?’ ‘No, precisely.’","cn":"“事情并不那么容易吧？”“对，的确不容易。”"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"精确地；准确地","en":"Precisely means accurately and exactly.","ex":{"en":"Nobody knows precisely how many people are still living in the camp","cn":"没有人确切知道还有多少人仍住在露营地。"}},{"pos":"ADV-GRADED 副词","cn":"正好，恰恰，确实地（表示强调）","en":"You can use precisely to emphasize that a reason or fact is the only important one there is, or that it is obvious.","ex":{"en":"Children come to zoos precisely to see captive animals","cn":"孩子们到动物园就是为了看圈养的动物。"}},{"pos":"ADV 副词","cn":"确实如此；一点没错","en":"You can say 'precisely' to confirm in an emphatic way that what someone has just said is true.","ex":{"en":"'Did you find yourself wondering what went wrong?' — 'Precisely.'","cn":"“你是不是自己也在想哪儿出了问题？”——“确实如此。”"}}]},"media":{"uk":"media/uk/precisely__gb_1.mp3","us":"media/us/precisely__us_1.mp3"},"examples":[{"en":"The problem is due to discipline, or, more precisely, the lack of discipline, in schools.","cn":"问题出在纪律上，或者更确切地说，是学校缺乏纪律。"},{"en":"‘It's not that easy, is it?’ ‘No, precisely.’ “","cn":"事情并不那么容易吧？” “对，的确不容易。”"}]},"prepositions":{"lemma":"preposition"},"predominant":{"oxford":{"phon":"prɪˈdɒmɪnənt","pos":"adjective","senses":[{"en":"most obvious or easy to notice","cn":"显著的；明显的","ex":{"en":"a predominant feature","cn":"显著特征"}},{"en":"having more power or influence than others","cn":"占优势的；主导的","ex":{"en":"a predominant culture","cn":"主流文化"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"占主导地位的；占支配地位的","en":"If something is predominant, it is more important or noticeable than anything else in a set of people or things.","ex":{"en":"Amanda's predominant emotion was that of confusion.","cn":"阿曼达主要还是感到困惑。"}}]},"media":{"uk":"media/uk/predominant__gb_1.mp3","us":"media/us/predominant__us_1.mp3"},"examples":[{"en":"Yellow is the predominant colour this spring in the fashion world.","cn":"黄色是今春时装界的流行颜色。"},{"en":"a predominant feature","cn":"显著特征"}]},"protectiveness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that protects you against harm or damage","cn":""},{"en":"protective clothes, covers, substances etc protect someone or something from being hurt or damaged","cn":""}]},"examples":[{"en":"Sunscreen provides a protective layer against the sun’s harmful rays.","cn":"","src":"ld"},{"en":"I can’t help feeling protective towards my kids.","cn":"","src":"ld"}],"media":{"uk":"media/uk/protectiveness__gb_1.mp3","us":"media/us/protectiveness__us_1.mp3"},"oxford":{"phon":"prəˈtektɪvnəs","pos":"noun","senses":[{"en":"the quality of wishing to provide protection for somebody/something","cn":"保护欲","ex":{"en":"the tender protectiveness her parents felt for her","cn":"她的父母对她温柔的保护"}}]}},"preservation":{"oxford":{"phon":"ˌprezəˈveɪʃn","pos":"noun","senses":[{"en":"the act of keeping something in its original state or in good condition","cn":"保护；维护；保存","ex":{"en":"building/environmental/food preservation","cn":"建筑物的维护；环境保护；食物的保存"}},{"en":"the act of making sure that something is kept","cn":"保留；维持；保持","ex":{"en":"The central issue in the strike was the preservation of jobs.","cn":"罢工的核心问题是工作职位的保留。"}},{"en":"the degree to which something has not been changed or damaged by age, weather, etc.","cn":"保存的状况；保养的程度","ex":{"en":"The paintings were in an excellent state of preservation.","cn":"这些绘画保存得非常好。"}}]},"media":{"uk":"media/uk/preservation__gb_1.mp3","us":"media/us/preservation__us_1.mp3"},"examples":[{"en":"The central issue in the strike was the preservation of jobs.","cn":"罢工的核心问题是工作职位的保留。"},{"en":"The paintings were in an excellent state of preservation.","cn":"这些绘画保存得非常好。"}]},"proposals":{"lemma":"proposal"},"previously":{"media":{"uk":"media/uk/previously__gb_1.mp3","us":"media/us/previously__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"先前；以前","en":"Previously means at some time before the period that you are talking about.","ex":{"en":"Guyana's railways were previously owned by private companies","cn":"圭亚那的铁路以前是归私有企业所有的。"}},{"pos":"ADV 副词","cn":"（一段时间）以前","en":"You can use previously to say how much earlier one event was than another event.","ex":{"en":"He had first entered the House 12 years previously","cn":"12年前，他首次成为议员。"}}]},"examples":[{"en":"The building had previously been used as a hotel.","cn":"这座楼房早先曾用作旅馆。"},{"en":"I had visited them three days previously.","cn":"我三天之前曾探访过他们。"}],"oxford":{"phon":"ˈpriːviəsli","pos":"adverb","senses":[{"en":"at a time before the time that you are talking about","cn":"先前；以往","ex":{"en":"The building had previously been used as a hotel.","cn":"这座楼房早先曾用作旅馆。"}}]}},"priest":{"oxford":{"phon":"priːst","pos":"noun","senses":[{"en":"a person who is qualified to perform religious duties and ceremonies in the Roman Catholic, Anglican and Orthodox Churches","cn":"（天主教、圣公会、东正教的）司祭，神父，司铎","ex":{"en":"a parish priest","cn":"堂区司铎"}},{"en":"a person who performs religious ceremonies in some religions that are not Christian","cn":"（非基督教会的）教士，祭司，僧侣","ex":{"en":"a Hindu/Buddhist priest","cn":"印度教／佛教僧侣"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"基督教教士；（天主教）神父；（英国圣公会）牧师；（东正教）司铎","en":"A priest is a member of the Christian clergy in the Catholic, Anglican, or Orthodox church.","ex":{"en":"He had trained to be a Catholic priest.","cn":"他受训成为了一名天主教神父。"}},{"pos":"N-COUNT 可数名词","cn":"（非基督教会的）教士，和尚，僧侣，祭司","en":"In many non-Christian religions a priest is a man who has particular duties and responsibilities in a place where people worship."}]},"media":{"uk":"media/uk/priest__gb_1.mp3","us":"media/us/priest__us_1.mp3"},"examples":[{"en":"the ordination of women priests","cn":"女司祭的授职礼"},{"en":"a parish priest","cn":"堂区司铎"}]},"prepared":{"media":{"uk":"media/uk/prepared__gb_1.mp3","us":"media/us/prepared__us_1.mp3"},"oxford":{"phon":"prɪˈpeəd","pos":"adjective","senses":[{"en":"ready and able to deal with something","cn":"准备好；有所准备","g":"[not before noun]","ex":{"en":"We'll be better prepared next time.","cn":"下次我们会准备得更充分。"}},{"en":"willing to do something","cn":"愿意","ex":{"en":"We are not prepared to accept these conditions.","cn":"我们无意接受这些条件。"}},{"en":"done, made, written, etc. in advance","cn":"事先做好（或写好等）的","ex":{"en":"The police officer read out a prepared statement.","cn":"那个警察宣读了一份事先写好的声明。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"愿意（做…）的","en":"If you are prepared to do something, you are willing to do it if necessary.","ex":{"en":"Are you prepared to take industrial action?","cn":"你们愿意采取劳工行动吗？"}},{"pos":"ADJ 形容词","cn":"准备好的；有准备的","en":"If you are prepared for something that you think is going to happen, you are ready for it.","ex":{"en":"Police are prepared for large numbers of demonstrators","cn":"警方已经为应对大量示威者做好了准备。"}},{"pos":"ADJ 形容词","cn":"预先准备好的；事先做好的","en":"You can describe something as prepared when it has been done or made beforehand, so that it is ready when it is needed.","ex":{"en":"He ended his prepared statement by thanking the police.","cn":"在这份事先准备好的声明的最后，他对警方表示了感谢。"}}]},"examples":[{"en":"The police officer read out a prepared statement.","cn":"那个警察宣读了一份事先写好的声明。"},{"en":"I was not prepared for all the problems it caused.","cn":"我对这事引起的诸多麻烦毫无防备。"}],"base":"prepare"},"programmers":{"lemma":"programmer"},"preference":{"media":{"uk":"media/uk/preference__gb_1.mp3","us":"media/us/preference__us_1.mp3"},"oxford":{"phon":"ˈprefrəns","pos":"noun","senses":[{"en":"a greater interest in or desire for somebody/something than somebody/something else","cn":"偏爱；爱好；喜爱","g":"[uncountable, singular]","ex":{"en":"It's a matter of personal preference.","cn":"那是个人的爱好问题。"}},{"en":"a thing that is liked better or best","cn":"偏爱的事物；最喜爱的东西","g":"[countable]","ex":{"en":"a study of consumer preferences","cn":"消费者偏好调查"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"喜好；偏好；偏爱","en":"If you have a preference for something, you would like to have or do that thing rather than something else.","ex":{"en":"Parents can express a preference for the school their child attends","cn":"父母可以表达对自己孩子所上学校的偏好。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优惠；优待；优先权","en":"If you give preference to someone with a particular qualification or feature, you choose them rather than someone else.","ex":{"en":"The Pentagon will give preference to companies which do business electronically.","cn":"美国国防部将会优先考虑那些能够进行电子商务的公司。"}}]},"examples":[{"en":"Let's make a list of possible speakers, in order of preference.","cn":"咱们按优先顺序列出一份可能请到的发言者名单。"},{"en":"Preference will be given to graduates of this university.","cn":"这所大学的毕业生会获得优先考虑。"}]},"producer":{"oxford":{"phon":"prəˈdjuːsə(r)","pos":"noun","senses":[{"en":"a person, a company or a country that grows or makes food, goods or materials","cn":"生产商；制造商；产地","ex":{"en":"French wine producers","cn":"法国葡萄酒酿造商"}},{"en":"a person who is in charge of the practical and financial aspects of making a film or play","cn":"（电影的）制片人，监制人；舞台监督","ex":{"en":"Hollywood screenwriters, actors and producers","cn":"好莱坞的剧作家、演员和制片人"}},{"en":"a person or company that arranges for somebody to make a programme for radio or television, or a record, CD, etc.","cn":"（广播、电视、唱片等的）制作人，制作公司，监制","ex":{"en":"an independent television producer","cn":"独立电视节目制作人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"制片人；制作人","en":"A producer is a person whose job is to produce plays, films, programmes, or CDs.","ex":{"en":"Vanya Kewley is a freelance film producer.","cn":"万尼亚·丘利是自由电影制片人。"}},{"pos":"N-COUNT 可数名词","cn":"生产商；制造商；生产国","en":"A producer of a food or material is a company or country that grows or manufactures a large amount of it.","ex":{"en":"The estate is generally a producer of high quality wines.","cn":"这片土地盛产优质葡萄酒。"}}]},"media":{"uk":"media/uk/producer__gb_1.mp3","us":"media/us/producer__us_1.mp3"},"examples":[{"en":"Libya is a major oil producer.","cn":"利比亚是主要石油生产国之一。"},{"en":"Hollywood screenwriters, actors and producers","cn":"好莱坞的剧作家、演员和制片人"}]},"provincial":{"oxford":{"phon":"prəˈvɪnʃl","pos":"adjective","senses":[{"en":"connected with one of the large areas that some countries are divided into, with its own local government","cn":"省的；一级行政区的","g":"[only before noun]","ex":{"en":"provincial assemblies/elections","cn":"省议会；省选举"}},{"en":"connected with the parts of a country that do not include the capital city, especially when these are regarded as lacking culture or modern ideas","cn":"首都以外的，都市以外的（尤指落后守旧地区的）","g":"[only before noun]","lab":"sometimes disapproving","ex":{"en":"a provincial town","cn":"首都以外的城镇"}},{"en":"unwilling to consider new or different ideas or things","cn":"心胸狭隘的；守旧的；迂腐的","lab":"disapproving","ex":{"en":"In spite of his education and travels, he has remained very provincial.","cn":"尽管受过教育和旅行，他仍然非常守旧。"}},{"en":"a person who lives in or comes from a part of the country that is not near the capital city, especially when regarded as lacking culture or modern ideas","cn":"都市以外的人；外地人；乡下人","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"省份的；外省的；地方的","en":"Provincial means connected with the parts of a country away from the capital city.","ex":{"en":"Jeremy Styles, 34, was the house manager for a provincial theatre for ten years.","cn":"杰里米·斯泰尔斯，34岁，在一家地方剧院担任了10年经理。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的；守旧的；迂腐的","en":"If you describe someone or something as provincial, you disapprove of them because you think that they are old-fashioned and boring.","ex":{"en":"He decided to revamp the company's provincial image","cn":"他决心一改公司保守落后的形象。"}},{"pos":"N-COUNT 可数名词","cn":"外省人；地方居民","en":"A provincial is someone who comes from a part of a country away from the capital city.","ex":{"en":"Owen died an unknown provincial.","cn":"欧文死的时候是一个不为人知的外乡人。"}}]},"media":{"uk":"media/uk/provincial__gb_1.mp3","us":"media/us/provincial__us_1.mp3"},"examples":[{"en":"provincial assemblies/elections","cn":"省议会；省选举"},{"en":"a provincial town","cn":"首都以外的城镇"}]},"productive":{"media":{"uk":"media/uk/productive__gb_1.mp3","us":"media/us/productive__us_1.mp3"},"oxford":{"phon":"prəˈdʌktɪv","pos":"adjective","senses":[{"en":"making goods or growing crops, especially in large quantities","cn":"生产的；（尤指）多产的","ex":{"en":"highly productive farming land","cn":"高产农田"}},{"en":"doing or achieving a lot","cn":"有效益的；富有成效的","ex":{"en":"a productive meeting","cn":"有成效的会议"}},{"en":"resulting in something or causing something","cn":"引起；导致；唤起","lab":"formal","ex":{"en":"a play productive of the strongest emotions","cn":"唤起强烈感情的一出戏"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多产的；高产的","en":"Someone or something that is productive produces or does a lot for the amount of resources used.","ex":{"en":"Training makes workers highly productive","cn":"培训提高了工人们的生产力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有成效的；有益的","en":"If you say that a relationship between people is productive, you mean that a lot of good or useful things happen as a result of it.","ex":{"en":"He was hopeful that the next round of talks would also be productive","cn":"他对下一轮会谈同样富有成效满怀希望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"创造…的；生产…的；产生…的","en":"Something that is productive of a situation or feeling creates it.","ex":{"en":"Land, labor and capital are all productive of wealth.","cn":"土地、劳动和资本都能创造财富。"}}]},"examples":[{"en":"My time spent in the library was very productive.","cn":"我花在图书馆的时间很有收获。"},{"en":"It's important to spend your time productively.","cn":"重要的是要有效地利用时间。"}]},"preventable":{"media":{"uk":"media/uk/preventable__gb_1.mp3","us":"media/us/preventable__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可以预防的；可以防止的；可以阻止的","en":"Preventable diseases, illnesses, or deaths could be stopped from occurring.","ex":{"en":"Forty-thousand children a day die from preventable diseases","cn":"每天有4万个孩子死于本可以预防的疾病。"}}]},"examples":[{"en":"preventable diseases/accidents","cn":"可以防止的疾病/事故"},{"en":"The rules are intended to prevent accidents.","cn":""}],"oxford":{"phon":"prɪˈventəbl","pos":"adjective","senses":[{"en":"that can be stopped from happening","cn":"可防止的，可预防的，可阻止的","ex":{"en":"preventable diseases/accidents","cn":"可预防的疾病／事故"}}]}},"preparation":{"media":{"uk":"media/uk/preparation__gb_1.mp3","us":"media/us/preparation__us_1.mp3"},"oxford":{"phon":"ˌprepəˈreɪʃn","pos":"noun","senses":[{"en":"the act or process of getting ready for something or making something ready","cn":"准备；预备","g":"[uncountable]","ex":{"en":"food preparation","cn":"食物制作"}},{"en":"things that you do to get ready for something or make something ready","cn":"准备工作","g":"[countable, usually plural]","ex":{"en":"The country is making preparations for war.","cn":"这个国家正在备战。"}},{"en":"a substance that has been specially prepared for use as a medicine, cosmetic, etc.","cn":"（医药、化妆品等）配制品，制剂","g":"[countable]","ex":{"en":"a pharmaceutical preparation","cn":"药剂"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"准备；预备；筹备","en":"Preparation is the process of getting something ready for use or for a particular purpose or making arrangements for something.","ex":{"en":"Rub the surface of the wood in preparation for the varnish","cn":"打磨木头的表面，为刷清漆做准备。"}},{"pos":"N-PLURAL 复数名词","cn":"准备工作；预备工作；筹备工作","en":"Preparations are all the arrangements that are made for a future event.","ex":{"en":"The United States is making preparations for a large-scale airlift of 1,200 American citizens","cn":"美国正在为运送1,200名美国公民的大规模空运做准备。"}},{"pos":"N-COUNT 可数名词","cn":"（食物、医药、化妆品的）制剂，配制品","en":"A preparation is a mixture that has been prepared for use as food, medicine, or a cosmetic.","ex":{"en":"...anti-ageing creams and sensitive-skin preparations.","cn":"抗衰老面霜和敏感性皮肤适用的护肤制剂"}}]},"examples":[{"en":"The team has been training hard in preparation for the big game.","cn":"为备战这场重要比赛，队伍一直在严格训练。"},{"en":"Was going to college a good preparation for your career?","cn":"上大学是否为你的事业打下了良好基础？"}]},"presentation":{"media":{"uk":"media/uk/presentation__gb_1.mp3","us":"media/us/presentation__us_1.mp3"},"oxford":{"phon":"ˌpreznˈteɪʃn","pos":"noun","senses":[{"en":"a meeting at which something, especially a new product or idea, or piece of work, is shown to a group of people","cn":"展示会；介绍会；发布会","g":"[countable]","ex":{"en":"The sales manager will give a presentation on the new products.","cn":"营销经理将举行一次新产品推介会。"}},{"en":"the act of showing something or of giving something to somebody","cn":"提交；授予；颁发；出示","g":"[uncountable]","ex":{"en":"The trial was adjourned following the presentation of new evidence to the court.","cn":"新证据呈到庭上后，审讯就宣告暂停。"}},{"en":"the way in which something is offered, shown, explained, etc. to others","cn":"提出（或展示、解释等）的方式","g":"[uncountable]","ex":{"en":"Improving the product's presentation (= the way it is wrapped, advertised, etc.) should increase sales.","cn":"改进产品的包装形式会提高销售量。"}},{"en":"the series of computer slides (= images) that are shown with the talk when somebody gives a presentation at a meeting","cn":"幻灯片演示","g":"[countable]","ex":{"en":"I've put my presentation on a memory stick.","cn":"我已经把我的幻灯片演示文件存在 U 盘里了。"}},{"en":"a ceremony or formal occasion during which a gift or prize is given","cn":"颁奖仪式；赠送仪式","g":"[countable]","ex":{"en":"the school's annual presentation evening","cn":"学校一年一度的颁奖晚会"}},{"en":"a performance of a play, etc. in a theatre","cn":"（戏剧等的）上演，演出","g":"[countable]"},{"en":"the position in which a baby is lying in the mother’s body just before birth","cn":"先露（胎儿的临产胎位）","g":"[countable, uncountable]","lab":"medical"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"外观；外貌；表象","en":"Presentation is the appearance of something, which someone has worked to create.","ex":{"en":"We serve traditional French food cooked in a lighter way, keeping the presentation simple","cn":"我们供应制作清淡、样式简洁的传统法国菜肴。"}},{"pos":"N-COUNT 可数名词","cn":"颁奖仪式；颁奖典礼","en":"A presentation is a formal event at which someone is given a prize or award.","ex":{"en":"He received his award at a presentation in London yesterday.","cn":"昨天，他在伦敦的颁奖典礼上领了奖。"}},{"pos":"N-COUNT 可数名词","cn":"介绍；陈述；报告；说明","en":"When someone gives a presentation, they give a formal talk, often in order to sell something or get support for a proposal.","ex":{"en":"James Watson, Philip Mayo and I gave a slide and video presentation","cn":"詹姆斯·沃森、菲利普·梅奥和我利用幻灯片和视频进行了介绍。"}},{"pos":"N-COUNT 可数名词","cn":"表演；演出","en":"A presentation is something that is performed in front of an audience, for example a play or a ballet.","ex":{"en":"...Blackpool Opera House's presentation of Buddy, the musical.","cn":"布莱克浦歌剧院上演的音乐剧《朋友》"}}]},"examples":[{"en":"I've put my presentation on a memory stick.","cn":"我已经把我的幻灯片演示存在 U 盘里了。"},{"en":"I admire the clear, logical presentation of her arguments.","cn":"我很欣赏她的论证，言辞清晰且有条理。"}]},"promise":{"media":{"uk":"media/uk/promise__gb_1.mp3","us":"media/us/promise__us_1.mp3"},"oxford":{"phon":"ˈprɒmɪs","pos":"verb","senses":[{"en":"to tell somebody that you will definitely do or not do something, or that something will definitely happen","cn":"许诺；承诺；保证","g":"[intransitive, transitive]","ex":{"en":"‘We haven't got time to go to the park.’ ‘But you promised!’","cn":"“我们没有时间去公园。”“但你答应过的！”"}},{"en":"to make something seem likely to happen; to show signs of something","cn":"使很可能；预示","g":"[transitive]","ex":{"en":"It promises to be an exciting few days.","cn":"那可望是兴奋刺激的几天。"}},{"en":"a statement that tells somebody that you will definitely do or not do something","cn":"诺言；许诺；承诺","g":"[countable]","ex":{"en":"to make/keep/fulfil/break a promise","cn":"许下／信守／兑现／违背诺言"},"pos":"noun"},{"en":"a sign that somebody/something will be successful","cn":"获得成功的迹象","g":"[uncountable]","ex":{"en":"Her work shows great promise.","cn":"她的作品显示她大有前途。"},"pos":"noun"},{"en":"a sign, or a reason for hope that something may happen, especially something good","cn":"吉兆；迹象","g":"[uncountable, singular]","ex":{"en":"The day dawned bright and clear, with the promise of warm, sunny weather.","cn":"拂晓时晴空万里，预示着温暖晴朗的天气。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"承诺；保证；答应","en":"If you promise that you will do something, you say to someone that you will definitely do it.","ex":{"en":"The post office has promised to resume first class mail delivery to the area on Friday","cn":"邮局承诺于星期五恢复对这个地区第一类邮件的递送。"}},{"pos":"VERB 动词","cn":"答应给予；承诺给予；保证让…得到","en":"If you promise someone something, you tell them that you will definitely give it to them or make sure that they have it.","ex":{"en":"In 1920 the great powers promised them an independent state","cn":"1920年，列强承诺让他们成为一个独立的国家。"}},{"pos":"N-COUNT 可数名词","cn":"诺言；承诺；保证","en":"A promise is a statement which you make to a person in which you say that you will definitely do something or give them something.","ex":{"en":"If you make a promise, you should keep it","cn":"如果做出了承诺，就应该遵守。"}},{"pos":"VERB 动词","cn":"有可能；有希望","en":"If a situation or event promises to have a particular quality or to be a particular thing, it shows signs that it will have that quality or be that thing.","ex":{"en":"While it will be fun, the seminar also promises to be most instructive.","cn":"这次的研讨会不仅会有趣，而且有可能会颇具启发意义。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（非常好的或成功的）希望，迹象，指望","en":"If someone or something shows promise, they seem likely to be very good or successful.","ex":{"en":"The boy first showed promise as an athlete in grade school.","cn":"这个男孩在上小学的时候就初次显示出成为运动员的潜力。"}}]},"examples":[{"en":"I'll see what I can do but I can't promise anything.","cn":"我会看看我能做什么，但不能给予任何承诺。"},{"en":"The day dawned bright and clear, with the promise of warm, sunny weather.","cn":"拂晓时晴空万里，预示着温暖晴朗的天气。"}]},"product":{"media":{"uk":"media/uk/product__gb_1.mp3","us":"media/us/product__us_1.mp3"},"oxford":{"phon":"ˈprɒdʌkt","pos":"noun","senses":[{"en":"a thing that is grown, produced or created, usually for sale","cn":"产品；制品；商品","g":"[countable, uncountable]","lab":"business","ex":{"en":"food/agricultural/software products","cn":"食品；农产品；软件产品"}},{"en":"a thing produced during a natural, chemical or industrial process","cn":"（自然、化学或工业过程的）产物，生成物，产品","g":"[countable]","ex":{"en":"One product of any combustion reaction is carbon monoxide.","cn":"燃烧反应的产物之一是一氧化碳。"}},{"en":"a person or thing that is the result of something","cn":"产儿；产物；结果","g":"[countable]","ex":{"en":"The child is the product of a broken home.","cn":"这孩子是一个破裂家庭的产儿。"}},{"en":"a cream or liquid that you put on your hair or skin to make it look better","cn":"美容（或美发）用品（指发乳、润肤霜、润肤水等）","g":"[countable, uncountable]","ex":{"en":"This product can be used on wet or dry hair.","cn":"这种美发用品可用在湿发或干发上。"}},{"en":"a quantity obtained by multiplying one number by another","cn":"积；乘积","g":"[countable]","lab":"mathematics","ex":{"en":"The product of 21 and 16 is 336.","cn":"21 和 16 的乘积是 336。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"产品；制品","en":"A product is something that is produced and sold in large quantities, often as a result of a manufacturing process.","ex":{"en":"Try to get the best product at the lowest price","cn":"尽量以最低的价格买到最好的产品。"}},{"pos":"N-COUNT 可数名词","cn":"产物","en":"If you say that someone or something is a product of a situation or process, you mean that the situation or process has had a significant effect in making them what they are.","ex":{"en":"We are all products of our time","cn":"我们都是这个时代的产物。"}}]},"examples":[{"en":"This product can be used on wet or dry hair.","cn":"这种美发用品可用于湿发或干发上。"},{"en":"The child is the product of a broken home.","cn":"这孩子是一个破裂家庭的产儿。"}]},"precaution":{"media":{"uk":"media/uk/precaution__gb_1.mp3","us":"media/us/precaution__us_1.mp3"},"oxford":{"phon":"prɪˈkɔːʃn","pos":"noun","senses":[{"en":"something that is done in advance in order to prevent problems or to avoid danger","cn":"预防措施；预防；防备","ex":{"en":"safety precautions","cn":"安全防范措施"}},{"en":"a way of referring to contraception","cn":"避孕措施","g":"[plural]","ex":{"en":"We didn't take any precautions and I got pregnant.","cn":"我们没有采取任何避孕措施，所以我怀孕了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预防措施；防备","en":"A precaution is an action that is intended to prevent something dangerous or unpleasant from happening.","ex":{"en":"Could he not, just as a precaution, move to a place of safety?","cn":"就算仅仅是为了以防万一，难道他就不能挪到安全的地方吗？"}}]},"examples":[{"en":"You must take all reasonable precautions to protect yourself and your family.","cn":"你必须采取一切合理的预防措施，保护自己和家人。"},{"en":"We didn't take any precautions and I got pregnant.","cn":"我们没有采取任何避孕措施，所以我怀孕了。"}]},"products":{"lemma":"product","media":{"uk":"media/uk/product__gb_1.mp3","us":"media/us/product__us_1.mp3"}},"pretend":{"oxford":{"phon":"prɪˈtend","pos":"verb","senses":[{"en":"to behave in a particular way, in order to make other people believe something that is not true","cn":"假装；佯装","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"I'm tired of having to pretend all the time.","cn":"我厌倦了常常要装假。"}},{"en":"to imagine that something is true as part of a game","cn":"（在游戏中）装扮，扮作，模拟","g":"[intransitive, transitive]","ex":{"en":"They didn't have any real money so they had to pretend.","cn":"他们没有真钱，就用假的代替。"}},{"en":"to claim to be, do or have something, especially when this is not true","cn":"自诩；自称；自认为","g":"[intransitive, transitive]","ex":{"en":"I can't pretend to any great musical talent.","cn":"我不能妄称自己多有音乐天赋。"}},{"en":"not real, imaginary","cn":"假装的；想象的","ex":{"en":"pretend cakes","cn":"假糕点"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"假装；伪装；装作","en":"If you pretend that something is the case, you act in a way that is intended to make people believe that it is the case, although in fact it is not.","ex":{"en":"I pretend that things are really okay when they're not","cn":"当情况不好的时候我假装一切顺利。"}},{"pos":"VERB 动词","cn":"（做游戏等时）假装，假扮，装扮","en":"If children or adults pretend that they are doing something, they imagine that they are doing it, for example as part of a game.","ex":{"en":"She can sunbathe and pretend she's in Spain","cn":"她可以晒晒太阳，假装自己是在西班牙。"}},{"pos":"VERB 动词","cn":"自诩；自称；自以为","en":"If you do not pretend that something is the case, you do not claim that it is the case.","ex":{"en":"We do not pretend that the past six years have been without problems for us","cn":"我们并不自夸在过去的6年中没有遇到任何问题。"}}]},"media":{"uk":"media/uk/pretend__gb_1.mp3","us":"media/us/pretend__us_1.mp3"},"examples":[{"en":"I don't pretend (that) I know much about the subject, but …","cn":"我不敢说自己对这个主题有多了解，但是 …"},{"en":"Of course I was wrong; it would be hypocritical to pretend otherwise.","cn":"当然是我错了，混充正确就是虚伪了。"}]},"presence":{"oxford":{"phon":"ˈprezns","pos":"noun","senses":[{"en":"the fact of being in a particular place","cn":"在场；出席","g":"[uncountable]","lab":"formal","ex":{"en":"He hardly seemed to notice my presence.","cn":"他似乎没有注意到我在场。"}},{"en":"the fact of being in a particular place or thing","cn":"存在；出现","g":"[uncountable]","lab":"figurative","ex":{"en":"The test can identify the presence of abnormalities in the unborn child.","cn":"这项检查能鉴定胎儿是否有不正常现象。"}},{"en":"a group of people, especially soldiers, who have been sent to a place to deal with a particular situation","cn":"（派遣的）一个队；（尤指执行任务的）部队","g":"[singular]","ex":{"en":"The government is maintaining a heavy police presence in the area.","cn":"政府在这一地区派驻了大批警察。"}},{"en":"a person or spirit that you cannot see but that you feel is near","cn":"感觉在附近的人（或鬼魂）","g":"[countable, usually singular]","lab":"literary","ex":{"en":"She felt a presence behind her.","cn":"她觉得有什么东西跟在背后。"}},{"en":"the quality of making a strong impression on other people by the way you talk or behave; a person who has this quality","cn":"气度；气度不凡的人","g":"[uncountable, singular]","lab":"approving","ex":{"en":"a man of great presence","cn":"气度不凡的男子"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"出席；到场","en":"Someone's presence in a place is the fact that they are there.","ex":{"en":"They argued that his presence in the village could only stir up trouble","cn":"他们认为他在村里出现只会招惹麻烦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"风度；风采；仪态","en":"If you say that someone has presence, you mean that they impress people by their appearance and manner.","ex":{"en":"They do not seem to have the vast, authoritative presence of those great men","cn":"他们看起来并没有那些伟人的翩翩风度和威严。"}},{"pos":"N-COUNT 可数名词","cn":"鬼怪；幽灵","en":"A presence is a person or creature that you cannot see, but that you are aware of.","ex":{"en":"The forest was dark and silent, haunted by shadows and unseen presences","cn":"这个森林黑暗寂静，经常有幽灵和看不见的鬼怪出没。"}},{"pos":"N-SING 单数名词","cn":"（军队的）驻扎，进驻，存在","en":"If a country has a military presence in another country, it has some of its armed forces there.","ex":{"en":"The Philippine government wants the US to maintain a military presence in Southeast Asia.","cn":"菲律宾政府希望美国继续在东南亚驻军。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"存在；被包含","en":"If you refer to the presence of a substance in another thing, you mean that it is in that thing.","ex":{"en":"The somewhat acid flavour is caused by the presence of lactic acid.","cn":"这种微酸的味道是因为含有乳酸造成的。"}},{"pos":"PHRASE 短语","cn":"引起注意；使得到关注","en":"If you make your presence felt, you do something which makes people notice you or pay attention to you.","ex":{"en":"Rather than politely lobbying politicians, Gay Dignity will be making its presence felt through demonstrations.","cn":"“同性恋尊严”游行活动不会彬彬有礼地向政客们游说，而会通过示威引起关注。"}},{"pos":"PHRASE 短语","cn":"当着…的面；在…面前","en":"If you are in someone's presence, you are in the same place as that person, and are close enough to them to be seen or heard.","ex":{"en":"The talks took place in the presence of a diplomatic observer.","cn":"会谈是在一位外交观察员在场的情况下进行的。"}},{"pos":"PHRASE 短语","cn":"镇定自若；沉着冷静","en":"If you say that someone had the presence of mind to do something, you approve of them because they were able to think and act calmly in a difficult situation.","ex":{"en":"He had the presence of mind to put his emergency oxygen tube in his mouth.","cn":"他镇定自若地把应急输氧管放进了自己的嘴里。"}}]},"media":{"uk":"media/uk/presence__gb_1.mp3","us":"media/us/presence__us_1.mp3"},"examples":[{"en":"She asked them not to discuss the matter in her presence.","cn":"她要求他们不要当着她的面讨论这个问题。"},{"en":"The test can identify the presence of abnormalities in the unborn child.","cn":"这项化验能鉴定胎儿是否有不正常现象。"}]},"prison":{"oxford":{"phon":"ˈprɪzn","pos":"noun","senses":[{"en":"a building where people are kept as a punishment for a crime they have committed, or while they are waiting for trial","cn":"监狱；牢狱；看守所","g":"[countable, uncountable]","lab":"US English","ex":{"en":"She went to prison for tax evasion.","cn":"她因逃税入狱。"}},{"en":"the system of keeping people in prisons","cn":"监禁；关押；关押制度","g":"[uncountable]","ex":{"en":"the prison service/system","cn":"监狱管理机构／制度"}},{"en":"a place or situation from which somebody cannot escape","cn":"难以脱身的地方（或处境）；牢笼；樊笼","g":"[countable]","ex":{"en":"His hospital room had become a prison.","cn":"他的病房变成了牢笼。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"监狱；监牢；看守所","en":"A prison is a building where criminals are kept as punishment or where people accused of a crime are kept before their trial.","ex":{"en":"The prison's inmates are being kept in their cells","cn":"这个监狱的犯人被关在他们的囚室里。"}}]},"media":{"uk":"media/uk/prison__gb_1.mp3","us":"media/us/prison__us_1.mp3"},"examples":[{"en":"The government insists that ‘prison works’ and plans to introduce a tougher sentencing policy for people convicted of violent crime.","cn":"政府坚持认为“关押有效”，并计划对暴力犯罪者实行更严厉的判刑政策。"},{"en":"Ten prison officers and three inmates needed hospital treatment following the riot.","cn":"骚乱之后，有十名狱警和三名囚犯需入院治疗。"}]},"prohibiting":{"lemma":"prohibit"},"precious":{"oxford":{"phon":"ˈpreʃəs","pos":"adjective","senses":[{"en":"rare and worth a lot of money","cn":"珍奇的；珍稀的","ex":{"en":"a precious vase","cn":"稀世花瓶"}},{"en":"valuable or important and not to be wasted","cn":"宝贵的；珍贵的","ex":{"en":"Clean water is a precious commodity in that part of the world.","cn":"在世界的那个地方，洁净的水是宝贵的东西。"}},{"en":"loved or valued very much","cn":"受珍爱的；被珍惜的","ex":{"en":"precious memories/possessions","cn":"珍贵的回忆／财物"}},{"en":"used to show you are angry that another person thinks something is very important","cn":"（表示气愤）宝贝似的","g":"[only before noun]","lab":"informal","ex":{"en":"I didn't touch your precious car!","cn":"我没碰你那辆宝贝车！"}},{"en":"very formal, exaggerated and not natural in what you say and do","cn":"道貌岸然的；矫揉造作的","lab":"disapproving"},{"en":"used to emphasize the fact that there is very little of something or that there are very few of something","cn":"（强调极少或太少）","ex":{"en":"There's precious little to do in this town.","cn":"这个镇上没有多少可做的事。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宝贵的；珍贵的；贵重的","en":"If you say that something such as a resource is precious, you mean that it is valuable and should not be wasted or used badly.","ex":{"en":"After four months in foreign parts, every hour at home was precious","cn":"在国外呆了4个月后，在家的每一刻都是宝贵的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"珍奇的；珍稀的","en":"Precious objects and materials are worth a lot of money because they are rare.","ex":{"en":"...jewellery and precious objects belonging to her mother.","cn":"她妈妈的珠宝和珍奇物品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得珍视的；可贵的；重要的","en":"If something is precious to you, you regard it as important and do not want to lose it.","ex":{"en":"Her family's support is particularly precious to Josie","cn":"家庭的支持对乔茜来说尤为可贵。"}},{"pos":"ADJ 形容词","cn":"宝贝似的（强调对别人珍视的东西表示厌恶）","en":"People sometimes use precious to emphasize their dislike for things which other people think are important.","ex":{"en":"You don't care about anything but yourself and your precious face.","cn":"你什么都不关心，除了你自己和你那张娇贵的脸。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矫揉造作的；一本正经的","en":"If you describe someone as precious, you mean that they behave in a formal and unnatural way.","ex":{"en":"Actors, he decided, were too precious and neurotic.","cn":"他认定演员们太做作，并且都神经兮兮的。"}},{"pos":"PHRASE 短语","cn":"一点点；极少","en":"If you say that there is precious little of something, you are emphasizing that there is very little of it, and that it would be better if there were more. Precious few has a similar meaning.","ex":{"en":"The banks have had precious little to celebrate recently","cn":"银行最近没几件值得庆贺的事。"}}]},"media":{"uk":"media/uk/precious__gb_1.mp3","us":"media/us/precious__us_1.mp3"},"examples":[{"en":"The crown was set with precious jewels — diamonds, rubies and emeralds.","cn":"王冠上镶嵌着稀世宝石，有钻石、红宝石和绿宝石。"},{"en":"Clean water is a precious commodity in that part of the world.","cn":"在世界的那个地方，洁净的水是宝贵的东西。"}]},"predictably":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something happens as expected , it happens exactly in the way that people expected it to happen","cn":""},{"en":"if something that happens is no surprise or comes as no surprise , it is exactly as you expected, so you are not surprised by it","cn":""}]},"examples":[{"en":"The snow had a predictable effect on traffic.","cn":"","src":"ld"},{"en":"Logan’s reaction was predictable.","cn":"","src":"ld"}],"media":{"uk":"media/uk/predictably__gb_1.mp3","us":"media/us/predictably__us_1.mp3"},"oxford":{"phon":"prɪˈdɪktəbli","pos":"adverb","senses":[{"en":"in such a way that you know in advance that something will happen or what it will be like","cn":"可预见的；可预料的","ex":{"en":"Prices were predictably high.","cn":"价格高昂是意料中的事。"}},{"en":"in a way that you would expect and which is therefore boring","cn":"意料之中的；老套乏味的","lab":"often disapproving","ex":{"en":"Everyone was predictably outraged by her comments.","cn":"不出所料，每个人都对她的言论感到愤怒。"}}]}},"proven":{"media":{"uk":"media/uk/proven__gb_2.mp3","us":"media/us/proven__us_2.mp3"},"oxford":{"phon":"ˈpruːvn","pos":"adjective","senses":[{"en":"tested and shown to be true","cn":"被证明的；已证实的","ex":{"en":"a student of proven ability","cn":"确有才华的学生"}}]},"collins":{"senses":[{"pos":"","cn":"（prove的过去分词之一，通常作形容词）","en":"Proven is a past participle of prove .Proven is the usual form of the past participle when you are using it as an adjective."}]},"examples":[{"en":"It is a proven fact that fluoride strengthens growing teeth.","cn":"氟化物可以强化生长中的牙齿，这是已证明的事实。"},{"en":"a student of proven ability","cn":"确有才华的学生"}]},"preposition":{"oxford":{"phon":"ˌprepəˈzɪʃn","pos":"noun","senses":[{"en":"a word or group of words, such as in, from, to, out of and on behalf of, used before a noun or pronoun to show place, position, time or method","cn":"介词"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"介词；前置词","en":"A preposition is a word such as 'by', 'for', 'into', or 'with' which usually has a noun group as its object.","ex":{"en":"There is nothing in the rules of grammar to suggest that ending a sentence with a preposition is wrong.","cn":"语法规则中并没有规定句子以介词结尾是错误的。"}}]},"media":{"uk":"media/uk/preposition__gb_1.mp3","us":"media/us/preposition__us_1.mp3"},"examples":[{"en":"a prepositional phrase (= a preposition and the noun following it, for example at night or after breakfast )","cn":"介词短语"}]},"proudly":{"media":{"uk":"media/uk/proudly__gb_1.mp3","us":"media/us/proudly__us_1.mp3"},"oxford":{"phon":"ˈpraʊdli","pos":"adverb","senses":[{"en":"in a way that shows that somebody is proud of something","cn":"得意地；自豪地；骄傲地","ex":{"en":"She proudly displayed her prize.","cn":"她得意地展示所获的奖品。"}},{"en":"in a way that is large and impressive","cn":"雄伟地；壮观地；高大地","lab":"literary","ex":{"en":"The Matterhorn rose proudly in the background.","cn":"马特峰巍然屹立在背景中。"}}]},"examples":[{"en":"She proudly displayed her prize.","cn":"她得意地展示所获的奖品。"},{"en":"The Matterhorn rose proudly in the background.","cn":"马特峰巍然屹立在背景中。"}]},"provide":{"media":{"uk":"media/uk/provide__gb_1.mp3","us":"media/us/provide__us_1.mp3"},"oxford":{"phon":"prəˈvaɪd","pos":"verb","senses":[{"en":"to give something to somebody or make it available for them to use","cn":"提供；供应；给予","ex":{"en":"Please provide the following information.","cn":"请提供以下信息。"}},{"en":"to state that something will or must happen","cn":"规定","lab":"formal","ex":{"en":"The final section provides that any work produced for the company is thereafter owned by the company.","cn":"最后一节规定，此后为公司创作的一切作品均为该公司所有。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"供给；提供；给予","en":"If you provide something that someone needs or wants, or if you provide them with it, you give it to them or make it available to them.","ex":{"en":"I'll be glad to provide a copy of this","cn":"我很愿意提供它的一个副本。"}},{"pos":"VERB 动词","cn":"（法律或协议）规定","en":"If a law or agreement provides that something will happen, it states that it will happen.","ex":{"en":"The treaty provides that, by the end of the century, the United States must have removed its bases","cn":"条约规定，到本世纪末，美国必须撤除其基地。"}},{"pos":"","cn":"","en":"相关词组：provide for"}]},"examples":[{"en":"The final section provides that any work produced for the company is thereafter owned by the company.","cn":"最后一节规定，此后为公司创作的一切作品均为本公司所有。"},{"en":"The legislation provides for the detention of suspected terrorists for up to seven days.","cn":"法律规定，对嫌疑恐怖分子最多可拘留七天。"}]},"probably":{"media":{"uk":"media/uk/probably__gb_1.mp3","us":"media/us/probably__us_1.mp3"},"oxford":{"phon":"ˈprɒbəbli","pos":"adverb","senses":[{"en":"used to say that something is likely to happen or to be true","cn":"几乎肯定；很可能；大概","ex":{"en":"You're probably right.","cn":"你很可能是对的。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"大概；或许；可能","en":"If you say that something is probably the case, you think that it is likely to be the case, although you are not sure.","ex":{"en":"The White House probably won't make this plan public until July","cn":"白宫可能要等到7月份才会公开这个计划。"}},{"pos":"ADV-GRADED 副词","cn":"（用于缓和语气）大概，或许，可能","en":"You can use probably when you want to make your opinion sound less forceful or definite, so that you do not offend people.","ex":{"en":"He probably thinks you're both crazy!","cn":"他可能认为你们两个人都疯了！"}}]},"examples":[{"en":"It was the best known and probably the most popular of her songs.","cn":"这是她最著名的、大概也是她最受欢迎的歌曲。"},{"en":"‘Do we need the car?’ ‘Probably not.’ “","cn":"我们需要开车吗？” “大概不需要吧。”"}]},"programming":{"oxford":{"phon":"ˈprəʊɡræmɪŋ","pos":"noun","senses":[{"en":"the process of writing and testing computer programs","cn":"（计算机）程序设计，编程","ex":{"en":"programming languages","cn":"程序设计语言"}},{"en":"the planning of which television or radio programmes to broadcast","cn":"（广播、电视节目的）编排，选编","ex":{"en":"politically balanced programming","cn":"政治上均衡报道的节目编选"}}]},"media":{"uk":"media/uk/programming__gb_1.mp3","us":"media/us/programming__us_1.mp3"},"examples":[{"en":"politically balanced programming","cn":"政治上均衡报道的节目编选"},{"en":"a high-level programming language","cn":"高级编程语言"}],"base":"programme"},"prisoner":{"oxford":{"phon":"ˈprɪznə(r)","pos":"noun","senses":[{"en":"a person who is kept in prison as a punishment, or while they are waiting for trial","cn":"囚犯；犯人；羁押候审者","ex":{"en":"The number of prisoners serving life sentences has fallen.","cn":"被判无期徒刑的囚犯数目下降了。"}},{"en":"a person who has been captured, for example by an enemy, and is being kept somewhere","cn":"被（敌人等）关起来的人；俘虏；战俘","lab":"figurative","ex":{"en":"He was taken prisoner by rebel soldiers.","cn":"他被叛军俘虏了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"囚犯；犯人","en":"A prisoner is a person who is kept in a prison as a punishment for a crime that they have committed.","ex":{"en":"The committee is concerned about the large number of prisoners sharing cells.","cn":"这个委员会对牢房拥挤问题表示担忧。"}},{"pos":"N-COUNT 可数名词","cn":"俘虏；战俘","en":"A prisoner is a person who has been captured by an enemy, for example in war.","ex":{"en":"...wartime hostages and concentration-camp prisoners","cn":"战时的人质和集中营的战俘"}},{"pos":"N-COUNT 可数名词","cn":"为…所困的人；陷于…不能摆脱的人","en":"If you say that you are a prisoner of a situation, you mean that your are trapped by it.","ex":{"en":"We are all prisoners of our childhood and feel an obligation to it","cn":"我们都无法忘记自己的童年时代，觉得仍然为它所缚。"}}]},"media":{"uk":"media/uk/prisoner__gb_1.mp3","us":"media/us/prisoner__us_1.mp3","img":["media/ldoce/img/prisioner.jpg"]},"examples":[{"en":"( figurative ) She is afraid to go out and has become a virtual prisoner in her own home.","cn":"她不敢出门，实际上已成了关在家中的囚犯。"},{"en":"They are holding her prisoner and demanding a large ransom.","cn":"他们把她劫持了，并索要巨额赎金。"}]},"prevail":{"oxford":{"phon":"prɪˈveɪl","pos":"verb","senses":[{"en":"to exist or be very common at a particular time or in a particular place","cn":"普遍存在；盛行；流行","g":"[intransitive]","ex":{"en":"We were horrified at the conditions prevailing in local prisons.","cn":"地方监狱的普遍状况让我们震惊。"}},{"en":"to be accepted, especially after a struggle or an argument","cn":"被接受；战胜；压倒","g":"[intransitive]","ex":{"en":"Justice will prevail over tyranny.","cn":"正义必将战胜暴虐。"}},{"en":"to defeat an opponent, especially after a long struggle","cn":"（尤指长时间斗争后）战胜，挫败","g":"[intransitive]","ex":{"en":"In a one-sided final, Spain prevailed against title-holder Croatia 40–34.","cn":"在一场实力悬殊的决赛中，西班牙队以40:34挫败了卫冕的克罗地亚队。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（提议、原则、观点）占上风，占优势，获胜，被接受","en":"If a proposal, principle, or opinion prevails, it gains influence or is accepted, often after a struggle or argument.","ex":{"en":"We hope that common sense would prevail","cn":"我们希望情理会占上风。"}},{"pos":"VERB 动词","cn":"（情形、态度、风俗）盛行，流行，普遍","en":"If a situation, attitude, or custom prevails in a particular place at a particular time, it is normal or most common in that place at that time.","ex":{"en":"A similar situation prevails in America","cn":"相似的情况在美国随处可见。"}},{"pos":"VERB 动词","cn":"（在战斗、竞赛、争论中）获胜，取胜","en":"If one side in a battle, contest, or dispute prevails, it wins.","ex":{"en":"He appears to have the votes he needs to prevail","cn":"他似乎已经获得了取胜所需的选票。"}},{"pos":"VERB 动词","cn":"劝服；说服","en":"If you prevail upon someone to do something, you succeed in persuading them to do it.","ex":{"en":"We must, each of us, prevail upon our congressman to act","cn":"我们每一个人都必须说服我们各自的国会议员采取行动。"}}]},"media":{"uk":"media/uk/prevail__gb_1.mp3","us":"media/us/prevail__us_1.mp3"},"examples":[{"en":"Those beliefs still prevail among certain social groups.","cn":"那些观念在某些社会群体中仍很盛行。"},{"en":"We were horrified at the conditions prevailing in local prisons.","cn":"地方监狱的普遍状况让我们震惊。"}]},"prohibit":{"oxford":{"phon":"prəˈhɪbɪt","pos":"verb","senses":[{"en":"to stop something from being done or used especially by law","cn":"（尤指以法令）禁止","g":"[often passive]","ex":{"en":"a law prohibiting the sale of alcohol","cn":"禁止售酒的法令"}},{"en":"to make something impossible to do","cn":"阻止；使不可能","ex":{"en":"The high cost of equipment prohibits many people from taking up this sport.","cn":"昂贵的装备令许多人对这项运动望而却步。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（法律或掌权者）禁止，不允许","en":"If a law or someone in authority prohibits something, they forbid it or make it illegal.","ex":{"en":"...a law that prohibits tobacco advertising in newspapers and magazines","cn":"禁止在报刊杂志上刊登香烟广告的法律"}}]},"media":{"uk":"media/uk/prohibit__gb_1.mp3","us":"media/us/prohibit__us_1.mp3"},"examples":[{"en":"The high cost of equipment prohibits many people from taking up this sport.","cn":"昂贵的装备令许多人对这项运动望而却步。"},{"en":"Soviet citizens were prohibited from travelling abroad.","cn":"苏联时代国民被禁止出国旅游。"}]},"principal":{"media":{"uk":"media/uk/principal__gb_1.mp3","us":"media/us/principal__us_1.mp3"},"oxford":{"phon":"ˈprɪnsəpl","pos":"adjective","senses":[{"en":"most important; main","cn":"最重要的；主要的","ex":{"en":"The principal reason for this omission is lack of time.","cn":"跳过它的主要原因是时间不足。"}},{"en":"the person who is in charge of a college or (in Scotland and Canada) a university","cn":"学院院长；（苏格兰和加拿大）大学校长","lab":"British English, Canadian English，，","ex":{"en":"Peter Brown, principal of St John’s College","cn":"彼得·布朗，圣约翰学院院长"},"pos":"noun"},{"en":"a teacher who is in charge of a school","cn":"（中小学）校长","lab":"North American English","ex":{"en":"Principal Ray Smith","cn":"雷·史密斯校长"},"pos":"noun"},{"en":"an amount of money that you lend to somebody or invest to earn interest","cn":"本金；资本","g":"[usually singular]","lab":"finance","ex":{"en":"The principal must be repaid in full within ten years.","cn":"本金必须在十年内还清。"},"pos":"noun"},{"en":"the person who has the most important part in a play, an opera, etc.","cn":"主要演员；主角","ex":{"en":"The performance of the two principals is disappointing.","cn":"两位校长的表现令人失望。"},"pos":"noun"},{"en":"a person that you are representing, especially in business or law","cn":"（尤指商务或法律事务的）当事人，委托人","lab":"specialist","ex":{"en":"The shareholders are principals and the managers are agents.","cn":"股东是委托人，经理是代理人。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"首要的；最主要的；最重要的","en":"Principal means first in order of importance.","ex":{"en":"The principal reason for my change of mind is this.","cn":"这是我改变主意的最主要原因。"}},{"pos":"N-COUNT 可数名词","cn":"（中小学）校长；（英国）大学校长，学院院长","en":"The principal of a school, or in Britain the principal of a college, is the person in charge of the school or college.","ex":{"en":"Donald King is the principal of Dartmouth High School.","cn":"唐纳德·金是达特茅斯中学的校长。"}}]},"examples":[{"en":"New roads will link the principal cities of the area.","cn":"新建道路将连通这个地区的主要城市。"},{"en":"Peter Brown, principal of St John's College","cn":"彼得 · 布朗，圣约翰学院院长"}]},"practising":{"oxford":{"phon":"ˈpræktɪsɪŋ","pos":"adjective","senses":[{"en":"taking an active part in a particular religion, profession, etc.","cn":"积极参加宗教活动的","ex":{"en":"a practising Christian/teacher","cn":"虔诚的基督徒；热心的教师"}}]},"media":{"uk":"media/uk/practising__gb_1.mp3","us":"media/us/practising__us_1.mp3"},"examples":[{"en":"a practising Christian/teacher","cn":"虔诚的基督徒；热忱的教师"},{"en":"Few practicing teachers have time for such research.","cn":"从事教学工作的老师很少有时间做这样的研究。"}],"base":"practise"},"pr":{"oxford":{"phon":"ˌpiː ˈɑː(r)","pos":"noun","senses":[{"en":"the business of giving the public information about a particular organization or person in order to create a good impression (the abbreviation for ‘public relations’)","cn":"公关，公共关系（全写为 public relations）","ex":{"en":"a PR department/agency/campaign","cn":"公关部门／机构／活动"}},{"en":"a system that gives each party in an election a number of seats in relation to the number of votes its candidates receive (the abbreviation for ‘proportional representation’)","cn":"比例代表制（按参选各党派的得票比例分配席位，全写为 proportional representation）"}]},"media":{"uk":"media/uk/pr__gb_1.mp3","us":"media/us/pr__us_1.mp3"},"examples":[{"en":"The article is very good PR for the theatre.","cn":"这篇文章有助于加强该剧院的公共关系。"},{"en":"a PR department/agency/campaign","cn":"公关部/机构/运动"}],"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"","en":"PR is an abbreviation for (缩略=) public relations.","ex":{"en":"It will be good PR.","cn":"这将是很好的公关宣传。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"","en":"PR is an abbreviation for (缩略=) proportional representation."}]}},"propaganda":{"oxford":{"phon":"ˌprɒpəˈɡændə","pos":"noun","senses":[{"en":"ideas or statements that may be false or present only one side of an argument that are used in order to gain support for a political leader, party, etc.","cn":"（带有政治导向的）宣传","ex":{"en":"enemy propaganda","cn":"敌方的宣传"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（政治组织的）宣传","en":"Propaganda is information, often inaccurate information, which a political organization publishes or broadcasts in order to influence people.","ex":{"en":"The Front adopted an aggressive propaganda campaign against its rivals.","cn":"该阵线采用激进的宣传手段对付它的对手。"}}]},"media":{"uk":"media/uk/propaganda__gb_1.mp3","us":"media/us/propaganda__us_1.mp3"},"examples":[{"en":"enemy propaganda","cn":"敌方的宣传"},{"en":"a propaganda campaign","cn":"宣传运动"}]},"prepares":{"lemma":"prepare","media":{"uk":"media/uk/prepare__gb_1.mp3","us":"media/us/prepare__us_1.mp3"}},"profession":{"media":{"uk":"media/uk/profession__gb_1.mp3","us":"media/us/profession__us_1.mp3"},"oxford":{"phon":"prəˈfeʃn","pos":"noun","senses":[{"en":"a type of job that needs special training or skill, especially one that needs a high level of education","cn":"（需要专门技能，尤指需要较高教育水平的某一）行业，职业","g":"[countable]","lab":"British English","ex":{"en":"the medical/legal/teaching profession","cn":"医疗／法律／教师行业"}},{"en":"all the people who work in a particular type of profession","cn":"（某）职业界；业内人士；同业；同行","g":"[singular + singular or plural verb]","ex":{"en":"The legal profession has/have always resisted change.","cn":"法律界向来抗拒变革。"}},{"en":"the traditional jobs that need a high level of education and training, such as being a doctor or a lawyer","cn":"（统称，指需要较高教育水平的）职业","g":"[plural]","ex":{"en":"employment in industry and the professions","cn":"实业界与专业界的工作"}},{"en":"a statement about what you believe, feel or think about something, that is sometimes made publicly","cn":"声明；宣称；表白","g":"[countable]","ex":{"en":"a profession of faith","cn":"信仰的表白"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（需要高等教育或训练的）职业","en":"A profession is a type of job that requires advanced education or training.","ex":{"en":"Harper was a teacher by profession","cn":"哈珀的职业是教师。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（某一专业工作的）全体人员，业界人士，专业界","en":"You can use profession to refer to all the people who have the same profession.","ex":{"en":"The attitude of the medical profession is very much more liberal now.","cn":"现在，医务人员的态度开明多了。"}}]},"examples":[{"en":"She was at the very top of her profession.","cn":"她是她那个行业中的佼佼者。"},{"en":"The legal profession has/have always resisted change.","cn":"法律界向来抗拒变革。"}]},"prelude":{"media":{"uk":"media/uk/prelude__gb_1.mp3","us":"media/us/prelude__us_1.mp3"},"oxford":{"phon":"ˈpreljuːd","pos":"noun","senses":[{"en":"a short piece of music, especially an introduction to a longer piece","cn":"前奏曲","ex":{"en":"the prelude to Act II","cn":"第二幕前奏"}},{"en":"an action or event that happens before another more important one and forms an introduction to it","cn":"序幕；前奏；先声","ex":{"en":"This is just a prelude to a larger attack.","cn":"这仅仅是更大规模攻击的前奏。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"前奏；序幕；开端","en":"You can describe an event as a prelude to a more important event when it happens before it and acts as an introduction to it.","ex":{"en":"Most unions see privatisation as an inevitable prelude to job losses","cn":"大多数工会认为私有化会不可避免地导致失业。"}},{"pos":"N-COUNT 可数名词","cn":"序曲；前奏曲","en":"A prelude is a short piece of music for the piano or organ.","ex":{"en":"...the famous E minor prelude of Chopin.","cn":"肖邦著名的E小调前奏曲"}}]},"examples":[{"en":"Living together as a prelude to marriage is now considered acceptable in many countries.","cn":"婚前同居如今在许多国家都已被接受。"},{"en":"Chopin’s Preludes","cn":"肖邦的前奏曲"}]},"preserved":{"lemma":"preserve"},"proposal":{"oxford":{"phon":"prəˈpəʊzl","pos":"noun","senses":[{"en":"a formal suggestion or plan; the act of making a suggestion","cn":"提议；建议；动议","g":"[countable, uncountable]","ex":{"en":"to submit/present/put forward a proposal","cn":"提交建议"}},{"en":"an act of formally asking somebody to marry you","cn":"求婚","g":"[countable]","ex":{"en":"She accepted his proposal of marriage.","cn":"她接受了他的求婚。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"提议；建议；提案","en":"A proposal is a plan or an idea, often a formal or written one, which is suggested for people to think about and decide upon.","ex":{"en":"The President is to put forward new proposals for resolving the country's constitutional crisis","cn":"总统将提出解决国家宪法危机的新议案。"}},{"pos":"N-COUNT 可数名词","cn":"求婚","en":"A proposal is the act of asking someone to marry you.","ex":{"en":"After a three-weekend courtship, Pamela accepted Randolph's proposal of marriage.","cn":"经过3个周末的追求之后，帕梅拉接受了伦道夫的求婚。"}}]},"media":{"uk":"media/uk/proposal__gb_1.mp3","us":"media/us/proposal__us_1.mp3"},"examples":[{"en":"They judged that the time was right for the proposal of new terms for the trade agreement.","cn":"他们判断，提出贸易协定新条款的时机成熟了。"},{"en":"His proposal that the system should be changed was rejected.","cn":"他提的关于修改制度的建议被拒绝了。"}]},"pre-":{"oxford":{"phon":"priː","pos":"prefix","senses":[{"en":"( in verbs, nouns and adjectives","cn":"构成动词、名词和形容词 ) before 先于；在 … 前"}]},"collins":{"senses":[{"pos":"PREFIX 前缀","cn":"（用于构词）表示“在…之前”，“先于…”","en":"Pre- is used to form words that indicate that something takes place before a particular date, period, or event.","ex":{"en":"...his pre-war job.","cn":"他战前的工作"}}]},"media":{"uk":"media/uk/pre__1_gb_1.mp3","us":"media/us/pre__1_us_1.mp3"},"examples":[{"en":"preseason training (= before a sports season starts)","cn":"赛季前的训练"},{"en":"pre-war","cn":"战前的"}]},"prefer":{"media":{"uk":"media/uk/prefer__gb_1.mp3","us":"media/us/prefer__us_1.mp3"},"oxford":{"phon":"prɪˈfɜː(r)","pos":"verb","senses":[{"en":"to like one thing or person better than another; to choose one thing rather than something else because you like it better","cn":"较喜欢；喜欢…多于…","lab":"formal","ex":{"en":"‘Coffee or tea?’ ‘I'd prefer tea, thanks.’","cn":"“要咖啡还是茶？”“我要茶，谢谢。”"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"更喜欢；偏好","en":"If you prefer someone or something, you like that person or thing better than another, and so you are more likely to choose them if there is a choice.","ex":{"en":"Does he prefer a particular sort of music?","cn":"他有特别喜欢的音乐吗？"}}]},"examples":[{"en":"‘Coffee or tea?’ ‘I'd prefer tea, thanks.’ “","cn":"要咖啡还是茶？” “我要茶，谢谢。”"},{"en":"The donor prefers to remain anonymous.","cn":"捐赠者希望自己的姓名不被公开。"}]},"priests":{"lemma":"priest"},"progressive":{"oxford":{"phon":"prəˈɡresɪv","pos":"adjective","senses":[{"en":"in favour of new ideas, modern methods and change","cn":"进步的；先进的；开明的","ex":{"en":"progressive schools","cn":"开明的学校"}},{"en":"happening or developing steadily","cn":"稳步的；逐步的；稳定发展的","ex":{"en":"a progressive reduction in the size of the workforce","cn":"劳力数量的逐步减少"}},{"en":"connected with the form of a verb (for example I am waiting or It is raining) that is made from a part of be and the present participle. Progressive forms are used to express an action that continues for a period of time.","cn":"（动词）进行时的，进行式的","lab":"grammar"},{"en":"at a higher percentage as the total amount of money being taxed increases","cn":"随着被征税资金总额的增加，税率会更高","ex":{"en":"Supporters of a progressive income tax argue that it is fairer.","cn":"累进所得税的支持者认为它更公平。"}},{"en":"a person who is in favour of new ideas, modern methods and change","cn":"进步人士；开明人士；改革派","ex":{"en":"political battles between progressives and conservatives","cn":"改革派与保守派之间的政治斗争"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"进步的；先进的；革新的","en":"Someone who is progressive or has progressive ideas has modern ideas about how things should be done, rather than traditional ones.","ex":{"en":"...a progressive businessman who had voted for Roosevelt in 1932 and 1936","cn":"在1932年和1936年投票支持罗斯福的开明商人"}},{"pos":"ADJ 形容词","cn":"（变化等）逐渐的，逐步发生的，逐步发展的","en":"A progressive change happens gradually over a period of time.","ex":{"en":"One prominent symptom of the disease is progressive loss of memory.","cn":"这种疾病的一个显著症状就是记忆逐渐丧失。"}},{"pos":"ADJ 形容词","cn":"（语法中）同continuous","en":"In grammar, progressive means the same as continuous."}]},"media":{"uk":"media/uk/progressive__gb_1.mp3","us":"media/us/progressive__us_1.mp3"},"examples":[{"en":"political battles between progressives and conservatives","cn":"改革派与保守派之间的政治斗争"},{"en":"a progressive reduction in the size of the workforce","cn":"劳力数量的逐步减少"}]},"promote":{"media":{"uk":"media/uk/promote__gb_1.mp3","us":"media/us/promote__us_1.mp3"},"oxford":{"phon":"prəˈməʊt","pos":"verb","senses":[{"en":"to help sell a product, service, etc. or make it more popular by advertising it or offering it at a special price","cn":"促销；推销","ex":{"en":"The band has gone on tour to promote their new album.","cn":"这个乐队已开始巡回宣传他们的新唱片。"}},{"en":"to help something to happen or develop","cn":"促进；推动","ex":{"en":"to promote democracy/peace/understanding/health","cn":"促进民主／和平／理解／健康"}},{"en":"to move somebody to a higher rank or more senior job","cn":"提升；晋升","g":"[often passive]","ex":{"en":"She worked hard and was soon promoted.","cn":"她工作勤奋，不久就得到了提拔。"}},{"en":"to move a sports team from playing with one group of teams to playing in a better group","cn":"将（体育运动队）晋级","ex":{"en":"They were promoted to the First Division last season.","cn":"上个赛季他们晋升为甲级队。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"促进；增进；提倡","en":"If people promote something, they help or encourage it to happen, increase, or spread.","ex":{"en":"You don't have to sacrifice environmental protection to promote economic growth","cn":"不必为了促进经济增长而牺牲环境保护。"}},{"pos":"VERB 动词","cn":"促销；推广；推销","en":"If a firm promotes a product, it tries to increase the sales or popularity of that product.","ex":{"en":"Paul Weller has announced a full British tour to promote his second solo album.","cn":"保罗·韦勒已经宣布到英国巡演，以推广他的第二张专辑。"}},{"pos":"VERB 动词","cn":"晋升；提升；擢升","en":"If someone is promoted, they are given a more important job or rank in the organization that they work for.","ex":{"en":"I was promoted to editor and then editorial director","cn":"我先是被提升为编辑，然后又晋升为编务总监。"}},{"pos":"VERB 动词","cn":"使（联赛队伍）升级","en":"If a team that competes in a league is promoted, it starts competing in a higher division in the next season because it was one of the most successful teams in the lower division.","ex":{"en":"Woodford Green won the Second Division title and are promoted to the First Division.","cn":"伍德福德格林队赢得了乙级联赛的冠军，成功升甲。"}}]},"examples":[{"en":"The band has gone on tour to promote their new album.","cn":"这个乐队已开始巡回宣传他们的新唱片。"},{"en":"She worked hard and was soon promoted.","cn":"她工作勤奋，不久就得到提升了。"}]},"privately":{"collins":{"senses":[{"pos":"ADV 副词","cn":"（买卖）通过私人地","en":"If you buy or sell something privately, you buy it from or sell it to another person directly, rather than in a shop or through a business.","ex":{"en":"The whole process makes buying a car privately as painless as buying from a garage","cn":"整个过程使得从私人手中购买汽车与从汽车库购买一样方便。"}}]},"media":{"uk":"media/uk/privately__gb_1.mp3","us":"media/us/privately__us_1.mp3"},"examples":[{"en":"In public he supported the official policy, but privately he was sure it would fail.","cn":"他明里支持这项官方政策，但暗中却确信它会失败。"},{"en":"She smiled, but privately she was furious.","cn":"她面露微笑，但心里却十分气愤。"}],"oxford":{"phon":"ˈpraɪvətli","pos":"adverb","senses":[{"en":"independently; in a way that is not under control of the state","cn":"私立地；私营地；民营地","ex":{"en":"a privately owned company","cn":"私营公司"}},{"en":"in a secret way that involves a particular person or group of people, and not people in general","cn":"私下：以涉及特定个人或人群的秘密方式，而不是一般人群","ex":{"en":"Can we speak privately?","cn":"我们能单独谈谈吗？"}},{"en":"in somebody's personal thoughts; in a way that is not known about in public","cn":"私下：以某人的个人想法；以不为大众所知的方式","ex":{"en":"She smiled, but privately she was furious.","cn":"她面露微笑，心里却很生气。"}},{"en":"to one person or a small group of people for payment","cn":"私人教授的；个别传授的","ex":{"en":"She gave piano lessons privately.","cn":"她私下上钢琴课。"}},{"en":"directly between the person who sells something and the person who buys it; not involving a shop","cn":"私下：直接在卖东西的人和买东西的人之间；不涉及商店","ex":{"en":"The painting was sold privately for £4m.","cn":"这幅画以 400 万英镑的价格私下出售。"}}]}},"prestigious":{"media":{"uk":"media/uk/prestigious__gb_1.mp3","us":"media/us/prestigious__us_1.mp3"},"oxford":{"phon":"preˈstɪdʒəs","pos":"adjective","senses":[{"en":"respected and admired as very important or of very high quality","cn":"有威望的；声誉高的","ex":{"en":"a prestigious award","cn":"赫赫有名的奖项"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有威望的；有声望的；有威信的；受尊敬的","en":"A prestigious institution, job, or activity is respected and admired by people.","ex":{"en":"It's one of the best equipped and most prestigious schools in the country.","cn":"这是国内设备最先进、最有威望的学校之一。"}}]},"examples":[{"en":"a prestigious award","cn":"赫赫有名的奖项"},{"en":"a prestigious university","cn":"名牌大学"}]},"profits":{"lemma":"profit"},"prepare":{"media":{"uk":"media/uk/prepare__gb_1.mp3","us":"media/us/prepare__us_1.mp3"},"oxford":{"phon":"prɪˈpeə(r)","pos":"verb","senses":[{"en":"to make something or somebody ready to be used or to do something","cn":"使做好准备；把…预备好","g":"[transitive, intransitive]","ex":{"en":"to prepare a report","cn":"撰写报告"}},{"en":"to make yourself ready to do something or for something that you expect to happen","cn":"使（自己）有准备；防范","g":"[intransitive, transitive]","ex":{"en":"I had no time to prepare.","cn":"我当时没时间准备。"}},{"en":"to make food ready to be eaten","cn":"预备（饭菜）；做（饭）","g":"[transitive]","ex":{"en":"He was in the kitchen preparing lunch.","cn":"他在厨房做午饭。"}},{"en":"to make a medicine or chemical substance, for example by mixing other substances together","cn":"调制，配制（药品等）","g":"[transitive]","ex":{"en":"remedies prepared from herbal extracts","cn":"用草药提取成分配制的药物"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…准备好；使预备好","en":"If you prepare something, you make it ready for something that is going to happen.","ex":{"en":"Two technicians were preparing a videotape recording of last week's programme","cn":"两个技术人员正在准备上周节目的录像带。"}},{"pos":"VERB 动词","cn":"为…做准备；筹备","en":"If you prepare for an event or action that will happen soon, you get yourself ready for it or make the necessary arrangements.","ex":{"en":"The Party leadership is using management consultants to help prepare for the next election","cn":"该党的领导层正在管理顾问的帮助下筹备下一届的选举。"}},{"pos":"VERB 动词","cn":"准备（食物）；做（饭菜）","en":"When you prepare food, you get it ready to be eaten, for example by cooking it.","ex":{"en":"She made her way to the kitchen, hoping to find someone preparing dinner","cn":"她走到厨房，希望看到有人在准备晚饭。"}}]},"examples":[{"en":"The police are preparing themselves for trouble at the demonstration.","cn":"警察正在准备防范示威时可能出现的骚乱。"},{"en":"The committee will prepare the ground for next month's meeting.","cn":"这个委员会将为下个月的会议做好准备。"}]},"prizes":{"lemma":"prize"},"preload":{"oxford":{"phon":"ˈpriːləʊd","pos":"noun","senses":[{"en":"a piece of software that is already installed on a computer when you buy it","cn":"预装软件"},{"en":"to load something in advance","cn":"预载；预装","ex":{"en":"The PC comes with office software preloaded.","cn":"这台电脑随机预装了办公软件。"},"pos":"verb"}]},"media":{"uk":"media/uk/preload__gb_1.mp3","us":"media/us/preload__us_1.mp3"},"examples":[{"en":"The PC comes with office software preloaded.","cn":"这台电脑随机预装了办公软件。"}]},"proof":{"oxford":{"phon":"pruːf","pos":"noun","senses":[{"en":"information, documents, etc. that show that something is true","cn":"证据；证明","g":"[uncountable, countable]","ex":{"en":"conclusive/definitive/scientific proof","cn":"确凿的／决定性的／科学的证据"}},{"en":"the process of testing whether something is true or a fact","cn":"检验；证实","g":"[uncountable]","ex":{"en":"Is the claim capable of proof?","cn":"这个说法能证明是正确的吗？"}},{"en":"a way of proving that a statement is true or that what you have calculated is correct","cn":"证明；求证；验算","g":"[countable]","lab":"mathematics"},{"en":"a copy of printed material which is produced so that mistakes can be corrected","cn":"校样","g":"[countable, usually plural]","ex":{"en":"She was checking the proofs of her latest novel.","cn":"她正在审阅她的新小说的校样。"}},{"en":"a standard used to measure the strength of alcoholic drinks","cn":"（酒的）标准酒精度","g":"[uncountable]"},{"en":"that can resist the damaging or harmful effects of something","cn":"能抵御；能防范；可防护","lab":"formal","ex":{"en":"The sea wall was not proof against the strength of the waves.","cn":"海堤挡不住海浪的力量。"},"pos":"adjective"},{"en":"that can resist or protect against the thing mentioned","cn":"防…的；抗…的","ex":{"en":"rainproof/windproof clothing","cn":"防雨／防风服装"},"pos":"adjective"},{"en":"to put a special substance on something, especially cloth, to protect it against water, fire, etc.","cn":"给（织物等）做防护处理；使防水（或防火等）","ex":{"en":"proofed canvas","cn":"做过防水处理的帆布"},"pos":"verb"},{"en":"to produce a test copy of a piece of printed work so that mistakes can be corrected","cn":"印…的校样","ex":{"en":"colour proofing","cn":"出彩色校样"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"证据；证物；证言","en":"Proof is a fact, argument, or piece of evidence which shows that something is definitely true or definitely exists.","ex":{"en":"You have to have proof of residence in the state of Texas, such as a Texas ID card","cn":"你必须有在得克萨斯州的居住证明，比如得克萨斯身份证。"}},{"pos":"N-COUNT 可数名词","cn":"校样；样张；初印稿","en":"In publishing, the proofs of a book, magazine, or article are a first copy of it that is printed so that mistakes can be corrected before more copies are printed and published.","ex":{"en":"I'm correcting the proofs of the Spanish edition right now.","cn":"我正在校正西班牙语版本的校样。"}},{"pos":"ADJ 形容词","cn":"标准酒精度","en":"Proof is used after a number of degrees or a percentage, when indicating the strength of a strong alcoholic drink such as whisky.","ex":{"en":"...a glass of Wild Turkey bourbon: 101 degrees proof.","cn":"一杯威特基波旁威士忌：酒精度为101°"}},{"pos":"ADJ 形容词","cn":"不能穿透的；耐…的；能防…的","en":"If something or someone is proof against a particular thing, they cannot be damaged, harmed, or affected by it.","ex":{"en":"The fortress was proof against the techniques of attack then in use","cn":"该防御工事能抵御当时所使用的各种进攻手段。"}},{"pos":"PHRASE 短语","cn":"典型的例证；活生生的例子","en":"If you say that someone is living proof of something, you mean that their actions or personal qualities show that a particular fact is true or that a particular quality exists.","ex":{"en":"He is living proof that some players just get better with age.","cn":"有些运动员年纪越大状态越好，他就是个活生生的例子。"}},{"pos":"PHRASE 短语","cn":"正面例子","en":"To be proof positive of a particular fact or quality means to be evidence that it is true or that it exists.","ex":{"en":"The Windermere Golf Club is proof positive that golf and ecology can co-exist in perfect harmony.","cn":"温德米尔高尔夫俱乐部证明了高尔夫和生态能完全和谐共存。"}},{"pos":"","cn":"","en":"burden of proof→see: ; the proof of the pudding is in the eating→see: ;"}]},"media":{"uk":"media/uk/proof__gb_1.mp3","us":"media/us/proof__us_1.mp3"},"examples":[{"en":"These results are a further proof of his outstanding ability.","cn":"这些成果进一步证明了他的杰出才干。"},{"en":"There is no proof that the knife belonged to her.","cn":"没有证据证明那把刀子是属于她的。"}]},"prevailing":{"media":{"uk":"media/uk/prevailing__gb_1.mp3","us":"media/us/prevailing__us_1.mp3"},"oxford":{"phon":"prɪˈveɪlɪŋ","pos":"adjective","senses":[{"en":"existing or most common at a particular time","cn":"普遍的；盛行的；流行的","ex":{"en":"the prevailing economic conditions","cn":"普遍的经济状况"}},{"en":"the prevailing wind in an area is the one that blows over it most frequently","cn":"（指风）某地区常刮的，盛行的","ex":{"en":"The prevailing wind here is from the east.","cn":"这里盛行东风。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（风）盛行的，常年刮的","en":"The prevailing wind in an area is the type of wind that blows over that area most of the time.","ex":{"en":"The direction of the prevailing winds should be taken into account.","cn":"应该将盛行风的方向考虑在内。"}}]},"examples":[{"en":"The prevailing view seems to be that they will find her guilty.","cn":"一般人的看法似乎认为她会被判有罪。"},{"en":"the attitude towards science prevailing at the time","cn":"当时对科学的流行看法"}],"base":"prevail"},"practiced":{"lemma":"practice"},"protection":{"media":{"uk":"media/uk/protection__gb_1.mp3","us":"media/us/protection__us_1.mp3"},"oxford":{"phon":"prəˈtekʃn","pos":"noun","senses":[{"en":"the act of protecting somebody/something; the state of being protected","cn":"保护；防卫","g":"[uncountable]","ex":{"en":"Wear clothes that provide adequate protection against the wind and rain.","cn":"穿上足以防风雨的衣服。"}},{"en":"a thing that protects somebody/something against something","cn":"保护物；护身符","g":"[countable, uncountable]","ex":{"en":"The plastic sheeting is not a complete protection against the rain.","cn":"塑料薄膜不能完全防雨。"}},{"en":"insurance against fire, injury, damage, etc.","cn":"保险","g":"[uncountable]","ex":{"en":"Our policy offers complete protection against fire and theft.","cn":"我们的保单全面承保火灾及盗窃风险。"}},{"en":"the system of helping an industry in your own country by taxing foreign goods","cn":"贸易保护；关税保护制","g":"[uncountable]","ex":{"en":"The government is ready to introduce protection for the car industry.","cn":"政府准备对汽车工业实行贸易保护。"}},{"en":"the system of paying criminals so that they will not attack your business or property","cn":"保护费（付给歹徒金钱以免受骚扰或破坏）","g":"[uncountable]","ex":{"en":"to pay protection money","cn":"交保护费"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"保护；防护","en":"To give or be protection against something unpleasant means to prevent people or things from being harmed or damaged by it.","ex":{"en":"Such a diet is widely believed to offer protection against a number of cancers","cn":"这种饮食结构被广泛认为可以预防多种癌症。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（保险单提供的）保险","en":"If an insurance policy gives you protection against an event such as death, injury, fire, or theft, the insurance company will give you or your family money if that event happens.","ex":{"en":"The new policy is believed to be the first scheme to offer protection against an illness.","cn":"这份新的保险单被认为是首个承保疾病风险的保险方案。"}},{"pos":"N-COUNT 可数名词","cn":"保护法；保护条例；保护措施","en":"Protections are laws and other official measures intended to protect people's rights and freedoms.","ex":{"en":"...civil rights bills providing a myriad of protections for gays, women and the disabled.","cn":"为同性恋者、妇女和残疾人提供了诸多保护的民权法案"}},{"pos":"N-UNCOUNT 不可数名词","cn":"贸易保护；关税保护","en":"If a government has a policy of protection, it helps its own industries by putting a tax on imported goods or by restricting imports in some other way.","ex":{"en":"Over the same period trade protection has increased in the rich countries.","cn":"在同一时期，富国的贸易保护有所抬头。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（歹徒索取保护费后提供的）保护","en":"If criminals offer people protection, they demand money from them and in return promise not to hurt them or damage their property.","ex":{"en":"A businessman who refused to pay protection money was shot nine times.","cn":"一位拒交保护费的商人被打了9枪。"}}]},"examples":[{"en":"Our policy offers complete protection against fire and theft.","cn":"我们的保单全面承保火灾及盗窃风险。"},{"en":"The government is ready to introduce protection for the car industry.","cn":"政府准备对汽车工业实行贸易保护。"}]},"pretending":{"lemma":"pretend"},"protestant":{"oxford":{"phon":"ˈprɒtɪstənt","pos":"adjective","senses":[{"en":"belonging to or connected with the part of the Western Christian Church that separated from the Roman Catholic Church in the 16th century","cn":"新教教徒（16 世纪脱离天主教）","ex":{"en":"The majority of the population is Protestant.","cn":"人口中大多数是新教徒。"}},{"en":"a member of a part of the Western Christian Church that separated from the Roman Catholic Church in the 16th century","cn":"新教教徒（16 世纪脱离天主教）","ex":{"en":"He's a Protestant.","cn":"他是新教教徒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新教教徒","en":"A Protestant is a Christian who belongs to the branch of the Christian church which separated from the Catholic church in the sixteenth century."},{"pos":"ADJ 形容词","cn":"新教教徒的；新教的","en":"Protestant means relating to Protestants or their churches.","ex":{"en":"Most Protestant churches now have women ministers.","cn":"如今大多数新教教会都有女牧师。"}}]},"media":{"uk":"media/uk/protestant__gb_1.mp3","us":"media/us/protestant__us_1.mp3"},"examples":[{"en":"The majority of the population is Protestant.","cn":"这里的人大多数都信奉新教。"},{"en":"He's a Protestant.","cn":"他是新教教徒。"}]},"propose":{"media":{"uk":"media/uk/propose__gb_1.mp3","us":"media/us/propose__us_1.mp3"},"oxford":{"phon":"prəˈpəʊz","pos":"verb","senses":[{"en":"to suggest a plan, an idea, etc. for people to think about and decide on","cn":"提议；建议","g":"[transitive]","lab":"formal","sc":"suggest plan","ex":{"en":"The government proposed changes to the voting system.","cn":"政府建议修改表决制度。"}},{"en":"to intend to do something","cn":"打算；计划","g":"[transitive]","lab":"formal","sc":"intend","ex":{"en":"What do you propose to do now?","cn":"现在你打算做什么？"}},{"en":"to ask somebody to marry you","cn":"求婚","g":"[intransitive, transitive]","sc":"marriage","ex":{"en":"He was afraid that if he proposed she might refuse.","cn":"他担心他若求婚，她会拒绝。"}},{"en":"to suggest something at a formal meeting and ask people to vote on it","cn":"提名；提出…供表决","g":"[transitive]","sc":"at formal meeting","ex":{"en":"I propose Tom Ellis for chairman.","cn":"我提名汤姆·埃利斯做主席。"}},{"en":"to suggest an explanation of something for people to consider","cn":"提供（解释）","g":"[transitive]","lab":"formal","sc":"suggest explanation","ex":{"en":"She proposed a possible solution to the mystery.","cn":"她提出了对这个奥秘的一种可能的解答。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提出；建议；提议","en":"If you propose something such as a plan or an idea, you suggest it for people to think about and decide upon.","ex":{"en":"Britain is about to propose changes to some institutions","cn":"英国将提议对一些机构进行改革。"}},{"pos":"VERB 动词","cn":"打算；计划","en":"If you propose to do something, you intend to do it.","ex":{"en":"It's still far from clear what action the government proposes to take over the affair","cn":"政府打算采取何种行动处理该事件仍然十分不明朗。"}},{"pos":"VERB 动词","cn":"提出（理论或解释）","en":"If you propose a theory or an explanation, you state that it is possibly or probably true, because it fits in with the evidence that you have considered.","ex":{"en":"This highlights a problem faced by people proposing theories of ball lightning","cn":"这使得球状闪电理论的提出者所面临的一个问题凸显出来。"}},{"pos":"VERB 动词","cn":"提出；提名；推荐","en":"If you propose a motion for debate, or a candidate for election, you begin the debate or the election procedure by formally stating your support for that motion or candidate.","ex":{"en":"A delegate from Siberia proposed a resolution that he stand down as party chairman","cn":"一名来自西伯利亚的代表提议他辞去党主席的职务。"}},{"pos":"VERB 动词","cn":"提议祝（酒）；提议为…干杯","en":"If you propose a toast to someone or something, you ask people to drink a toast to them.","ex":{"en":"Usually the bride's father proposes a toast to the health of the bride and groom.","cn":"通常新娘的父亲会提议为新郎新娘的健康干杯。"}},{"pos":"VERB 动词","cn":"向…求婚","en":"If you propose to someone, or propose marriage to them, you ask them to marry you.","ex":{"en":"He had proposed to Isabel the day after taking his seat in Parliament.","cn":"当选议员的第二天，他向伊莎贝尔求婚了。"}}]},"examples":[{"en":"She proposed a possible solution to the mystery.","cn":"她提出了对这个奥秘的一种可能的解答。"},{"en":"It was proposed that the president be elected for a period of two years.","cn":"有人提议选出的主席任期为两年。"}]},"prominence":{"media":{"uk":"media/uk/prominence__gb_1.mp3","us":"media/us/prominence__us_1.mp3"},"oxford":{"phon":"ˈprɒmɪnəns","pos":"noun","senses":[{"en":"the state of being important, well known or easy to notice","cn":"重要；突出；卓越；出名","ex":{"en":"a young actor who has recently risen to prominence","cn":"最近崭露头角的一名年轻演员"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重要；杰出；著名","en":"If someone or something is in a position of prominence, they are well-known and important.","ex":{"en":"He came to prominence during the World Cup in Italy","cn":"他在意大利的世界杯赛中声名鹊起。"}}]},"examples":[{"en":"She has achieved a prominence she hardly deserves.","cn":"她实在不配享有这么大的名声。"},{"en":"a young actor who has recently risen to prominence","cn":"最近崭露头角的一名年轻演员"}]},"prince":{"oxford":{"phon":"prɪns","pos":"noun","senses":[{"en":"a male member of a royal family who is not king, especially the son or grandson of the king or queen","cn":"王子；王孙；亲王","ex":{"en":"the royal princes","cn":"亲王"}},{"en":"the male ruler of a small country or state that has a royal family; a male member of this family, especially the son or grandson of the ruler","cn":"（小国的）国王，王室男性成员，王子，王孙","ex":{"en":"the prince of Orange","cn":"奥兰治亲王"}},{"en":"(in some European countries) a nobleman","cn":"（某些欧洲国家的）贵族"},{"en":"a man who is thought to be one of the best in a particular field","cn":"（某一领域的）杰出人物，巨子，大王","lab":"literary","ex":{"en":"the prince of comedy","cn":"喜剧大师"}},{"en":"(1958-2016) a US pop singer and actor. He was born Prince Rogers Nelson in Minneapolis. In 1993 he changed his name into a symbol that nobody could pronounce, so he was called 'the Artist Formerly Known as Prince'. He changed his name back to Prince in 2000. He shocked some people with his sexual songs and performances on stage. He was the star of the film Purple Rain (1984) and won an Oscar for its music. He also wrote the music for Batman (1989).","cn":"王子：（1958-2016）美国流行歌手兼演员。他出生于明尼阿波利斯的罗杰斯·纳尔逊亲王。1993年，他将自己的名字改成了一个没人能发音的符号，因此他被称为“艺术家，以前被称为王子”。他在2000年将自己的名字改回了Prince。他在舞台上的性爱歌曲和表演震惊了一些人。他是电影《紫雨》（1984）的主角，并因其音乐获得奥斯卡奖。他还为蝙蝠侠（1989）创作了音乐。","pos":""}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"王子；亲王；王孙","en":"A prince is a male member of a royal family, especially the son of the king or queen of a country.","ex":{"en":"...Prince Edward and other royal guests","cn":"爱德华王子和其他皇室宾客"}},{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"（小国的）君王，国君","en":"A prince is the male royal ruler of a small country or state.","ex":{"en":"He was speaking without the prince's authority.","cn":"他说话的时候没有君王的威严。"}},{"pos":"N-COUNT 可数名词","cn":"大师；名家；巨匠","en":"If someone describes a man as the prince of a particular type of work, they mean that he is the best man doing that type of work.","ex":{"en":"To his 19th-century peers, Robert Brown was the prince of botany.","cn":"对于19世纪的同行来说，罗伯特·布朗是植物学巨匠。"}}]},"media":{"uk":"media/uk/prince__gb_1.mp3","us":"media/us/prince__us_1.mp3"},"examples":[{"en":"Prince Albert of Monaco","cn":"摩纳哥亲王阿尔伯特"},{"en":"the Prince of Wales","cn":"威尔士亲王"}]},"pre-emptive":{"oxford":{"phon":"ˌpriː ˈemptɪv","pos":"adjective","senses":[{"en":"done to stop somebody taking action, especially action that will be harmful to yourself","cn":"先发制人的","ex":{"en":"a pre-emptive attack/strike on the military base","cn":"对军事基地先发制人的进攻"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"先发制人的；抢先的","en":"A pre-emptive attack or strike is intended to weaken or damage an enemy or opponent, for example by destroying their weapons before they can do any harm.","ex":{"en":"...plans for a pre-emptive strike against countries that may have biological weapons","cn":"先发制人打击可能拥有生物武器的国家的计划"}}]},"media":{"uk":"media/uk/pre_emptive_1_gb_1.mp3","us":"media/us/pre_emptive_1_us_1.mp3"},"examples":[{"en":"a pre-emptive attack/strike on the military base","cn":"对军事基地的抢先进攻/打击"}]},"pristine":{"media":{"uk":"media/uk/pristine__gb_1.mp3","us":"media/us/pristine__us_1.mp3"},"oxford":{"phon":"ˈprɪstiːn","pos":"adjective","senses":[{"en":"fresh and clean, as if new","cn":"崭新的；清新的","ex":{"en":"The car is in pristine condition.","cn":"这辆汽车是全新的。"}},{"en":"not developed or changed in any way; left in its original condition","cn":"未开发的；处于原始状态的","ex":{"en":"pristine, pollution-free beaches","cn":"没有污染的原始海滩"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一尘不染的；崭新的","en":"Pristine things are extremely clean or new.","ex":{"en":"Now the house is in pristine condition.","cn":"现在，这所房子一尘不染。"}}]},"examples":[{"en":"The car is in pristine condition.","cn":"这辆汽车是全新的。"},{"en":"pristine, pollution-free beaches","cn":"没有污染的原始海滩"}]},"prisoners":{"lemma":"prisoner"},"prohibited":{"oxford":{"phon":"prəˈhɪbɪtɪd","pos":"adjective","senses":[{"en":"not allowed; banned","cn":"不允许的；禁止的","ex":{"en":"There was no evidence that the athlete was trying to improve his performance when he took the prohibited substance.","cn":"没有证据表明该运动员服用违禁药物是为了提高自己的表现。"}}]},"base":"prohibit"},"prevent":{"media":{"uk":"media/uk/prevent__gb_1.mp3","us":"media/us/prevent__us_1.mp3"},"oxford":{"phon":"prɪˈvent","pos":"verb","senses":[{"en":"to stop somebody from doing something; to stop something from happening","cn":"阻止；阻碍；阻挠","lab":"British English","ex":{"en":"The accident could have been prevented.","cn":"这次事故本来是可以预防的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"防止；预防；阻止","en":"To prevent something means to ensure that it does not happen.","ex":{"en":"These methods prevent pregnancy","cn":"这些方法能防止怀孕。"}},{"pos":"VERB 动词","cn":"阻止；制止；阻碍","en":"To prevent someone from doing something means to make it impossible for them to do it. →see usage note at:","ex":{"en":"He said this would prevent companies from creating new jobs","cn":"他说这将使公司无法创造新的工作机会。"}}]},"examples":[{"en":"( BrE ) Nothing would prevent him/his speaking out against injustice.","cn":"什么也阻挡不了他为不平之事鸣冤叫屈。"},{"en":"The accident could have been prevented.","cn":"这次事故本来是可以防止的。"}]},"programmer":{"oxford":{"phon":"ˈprəʊɡræmə(r)","pos":"noun","senses":[{"en":"a person whose job is writing computer programs","cn":"（计算机）程序员，编程员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"程序员；程序设计员；程序编制员","en":"A computer programmer is a person whose job involves writing programs for computers."}]},"media":{"uk":"media/uk/programmer__gb_1.mp3","us":"media/us/programmer__us_1.mp3"}},"proud":{"media":{"uk":"media/uk/proud__gb_1.mp3","us":"media/us/proud__us_1.mp3"},"oxford":{"phon":"praʊd","pos":"adjective","senses":[{"en":"feeling pleased and satisfied about something that you own or have done, or are connected with","cn":"骄傲的；自豪的；得意的；满足的","sc":"pleased","ex":{"en":"proud parents","cn":"自豪的父母"}},{"en":"causing somebody to feel proud","cn":"引以为荣的；令人自豪的","g":"[only before noun]","sc":"pleased","ex":{"en":"This is the proudest moment of my life.","cn":"这是我生命中最荣耀的时刻。"}},{"en":"feeling that you are better and more important than other people","cn":"傲慢的；骄傲自大的","lab":"disapproving","sc":"feeling too important","ex":{"en":"She comes across as proud and arrogant.","cn":"她给人的印象是骄傲自大。"}},{"en":"having respect for yourself and not wanting to lose the respect of others","cn":"自尊的；自重的","sc":"having self-respect","ex":{"en":"They were a proud and independent people.","cn":"他们是一个独立而自尊的民族。"}},{"en":"beautiful, tall and impressive","cn":"秀丽的；挺拔的；壮观的","lab":"literary","sc":"beautiful/tall","ex":{"en":"The sunflowers stretched tall and proud to the sun.","cn":"向日葵在阳光中亭亭玉立。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"骄傲的；自豪的；得意的","en":"If you feel proud, you feel pleased about something good that you possess or have done, or about something good that a person close to you has done.","ex":{"en":"I felt proud of his efforts","cn":"我为他的努力感到骄傲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最值得夸耀的；最引以为荣的","en":"Your proudest moments or achievements are the ones that you are most proud of.","ex":{"en":"This must have been one of the proudest moments of his busy and hard working life.","cn":"这一定是他劳碌工作的一生中最引以为荣的时刻之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自尊的；自重的","en":"Someone who is proud has respect for themselves and does not want to lose the respect that other people have for them.","ex":{"en":"He was too proud to ask his family for help and support","cn":"他自尊心太强，不愿向家人寻求帮助和支持。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"骄傲的；傲慢的；妄自尊大的","en":"Someone who is proud feels that they are better or more important than other people.","ex":{"en":"She was said to be proud and arrogant.","cn":"据说她傲慢自大。"}},{"pos":"ADJ 形容词","cn":"超出…之外的","en":"If one object stands proud of another object that it is attached to or next to, it extends beyond it.","ex":{"en":"The handles stand proud of the doors of the car.","cn":"把手位于车门之外。"}},{"pos":"PHRASE 短语","cn":"盛情款待；给…以隆重待遇","en":"If someone does you proud, they treat you very well, for example by welcoming you and giving you good food and entertainment.","ex":{"en":"The hotel has indeed done them proud.","cn":"这家宾馆的确对他们盛情款待。"}}]},"examples":[{"en":"She was too proud to admit she could be wrong.","cn":"她自视甚高，不愿承认自己也会有错。"},{"en":"I feel very proud to be a part of the team.","cn":"能成为队中的一员我感到十分荣幸。"}]},"precinct":{"media":{"uk":"media/uk/precinct__gb_1.mp3","us":"media/us/precinct__us_1.mp3"},"oxford":{"phon":"ˈpriːsɪŋkt","pos":"noun","senses":[{"en":"a commercial area in a town where cars cannot go","cn":"步行商业区","lab":"British English","ex":{"en":"a pedestrian/shopping precinct","cn":"步行区；购物区"}},{"en":"one of the parts into which a town or city is divided in order to organize elections","cn":"选区","lab":"North American English","ex":{"en":"voters in key precincts","cn":"关键选区的选民"}},{"en":"a part of a city that has its own police station; the police station in this area","cn":"警区；分区警察局；派出所","lab":"North American English","ex":{"en":"Detective Hennessy of the 44th precinct","cn":"第 44 警区的亨尼西警探"}},{"en":"the area around a place or a building, sometimes surrounded by a wall","cn":"（建筑物等的）外围，围墙内区域","g":"[usually plural]","lab":"formal","ex":{"en":"the cathedral/college precincts","cn":"大教堂／学院周围"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（市中心的）步行商业区","en":"A shopping precinct is an area in the centre of a town in which cars are not allowed.","ex":{"en":"The Centre was a pedestrian precinct with a bandstand in the middle.","cn":"该中心是步行商业区，正中央有一个室外音乐演奏台。"}},{"pos":"N-COUNT 可数名词","cn":"（城市内的）管辖区，分区，警区","en":"A precinct is a part of a city which has its own police force and fire service.","ex":{"en":"The shooting occurred in the 34th Precinct.","cn":"枪击事件发生在第34警区。"}},{"pos":"N-PLURAL 复数名词","cn":"（机构的）境域，界域","en":"The precincts of an institution are its buildings and land.","ex":{"en":"No one carrying arms is allowed within the precincts of a temple.","cn":"携带武器者不得进入神殿的界域。"}}]},"examples":[{"en":"The murder occurred just a block from the precinct.","cn":"谋杀案就发生在和警察分局相隔一条街的地方。"},{"en":"Detective Hennessy of the 44th precinct","cn":"第 44 警区的亨尼西警探"}]},"problematic":{"oxford":{"phon":"ˌprɒbləˈmætɪk","pos":"adjective","senses":[{"en":"difficult to deal with or to understand; full of problems; not certain to be successful","cn":"造成困难的；存在问题的","ex":{"en":"The situation is more problematic than we first thought.","cn":"情况比我们一开始认为的要困难。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有问题的；有困难的；疑难的","en":"Something that is problematic involves problems and difficulties.","ex":{"en":"Some places are more problematic than others for women traveling alone.","cn":"对那些独自旅行的女性来说，在有些地方遇到的问题会比其他地方更多。"}}]},"media":{"uk":"media/uk/problematic__gb_1.mp3","us":"media/us/problematic__us_1.mp3"},"examples":[{"en":"The reforms could turn out to be highly problematic .","cn":"改革最终可能会困难重重。"}]},"pressed":{"media":{"uk":"media/uk/pressed__gb_1.mp3","us":"media/us/pressed__us_1.mp3"},"oxford":{"phon":"prest","pos":"adjective","senses":[{"en":"not having enough of something, especially time or money","cn":"（时间、资金等）紧缺，短绌","g":"[not before noun]","ex":{"en":"I'm really pressed for cash at the moment.","cn":"眼下我真的缺钱。"}},{"en":"made flat using force, a heavy object or a hot iron","cn":"压平的；压扁的；熨平的","ex":{"en":"pictures made with pressed flowers","cn":"用压花制作的画"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时间、金钱）紧张的，匮乏的，不足的","en":"If you say that you are pressed for time or pressed for money, you mean that you do not have enough time or money at the moment.","ex":{"en":"Are you pressed for time, Mr Bayliss? If not, I suggest we have lunch.","cn":"你时间紧吗，贝利斯先生？如果不紧，不如我们一起吃午饭吧。"}}]},"examples":[{"en":"I'm really pressed for cash at the moment.","cn":"眼下我十分缺钱。"},{"en":"neatly pressed trousers","cn":"熨得平平整整的西裤"}],"base":"press"},"prompt":{"oxford":{"phon":"prɒmpt","pos":"verb","senses":[{"en":"to make somebody decide to do something; to cause something to happen","cn":"促使；导致；激起","g":"[transitive]","ex":{"en":"The discovery of the bomb prompted an increase in security.","cn":"此次发现炸弹促使当局加强了安全工作。"}},{"en":"to encourage somebody to speak by asking them questions or suggesting words that they could say","cn":"鼓励，提示，提醒（某人说话）","g":"[transitive]","lab":"computing","ex":{"en":"She was too nervous to speak and had to be prompted.","cn":"她紧张得说不出话来，只好听人提示。"}},{"en":"to follow the text of a play and remind the actors what the words are if they forget their lines","cn":"给（演员）提词","g":"[transitive, intransitive]"},{"en":"done without delay","cn":"立即的；迅速的；及时的","ex":{"en":"Prompt action was required as the fire spread.","cn":"火势蔓延，须立即采取行动。"},"pos":"adjective"},{"en":"acting without delay; arriving at the right time","cn":"敏捷；迅速；准时","g":"[not before noun]","ex":{"en":"Please be prompt when attending these meetings.","cn":"参加上述会议请准时出席。"},"pos":"adjective"},{"en":"a word or words said to an actor, to remind them what to say next when they have forgotten","cn":"（给演员的）提词，提示","pos":"noun"},{"en":"a sign on a computer screen that shows that the computer has finished doing something and is ready for more instructions","cn":"提示符","lab":"computing","pos":"noun"},{"en":"exactly at the time mentioned","cn":"准时地","ex":{"en":"The meeting will begin at ten o'clock prompt.","cn":"会议将于十点钟准时开始。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"促使；推动；引起","en":"To prompt someone to do something means to make them decide to do it.","ex":{"en":"Japan's recession has prompted consumers to cut back on buying cars","cn":"日本经济的不景气使得消费者在购买车辆上减少了开支。"}},{"pos":"VERB 动词","cn":"鼓励，提示（说话者）；给（演员）提词","en":"If you prompt someone when they stop speaking, you encourage or help them to continue. If you prompt an actor, you tell them what their next line is when they have forgotten what comes next.","ex":{"en":"'Go on,' the therapist prompted him","cn":"“接着说，”医生鼓励他道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迅速的；即刻的；立即的；及时的","en":"A prompt action is done without any delay.","ex":{"en":"It is not too late, but prompt action is needed.","cn":"现在还不算晚，但是需要立即采取行动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"敏捷的；迅速的；及时的","en":"If you are prompt to do something, you do it without delay or you are not late.","ex":{"en":"You have been so prompt in carrying out all these commissions","cn":"你执行所有这些命令可真够迅速的。"}}]},"media":{"uk":"media/uk/prompt__gb_1.mp3","us":"media/us/prompt__us_1.mp3"},"examples":[{"en":"The discovery of the bomb prompted an increase in security.","cn":"此次发现炸弹促使当局加强了安全工作。"},{"en":"‘And then what happened?’ he prompted. “","cn":"后来怎样了？”他鼓励对方继续说下去。"}]},"professor":{"media":{"uk":"media/uk/professor__gb_1.mp3","us":"media/us/professor__us_1.mp3"},"oxford":{"phon":"prəˈfesə(r)","pos":"noun","senses":[{"en":"a university teacher of the highest rank","cn":"教授","lab":"especially British English","ex":{"en":"Professor (Ann) Williams","cn":"（安·）威廉斯教授"}},{"en":"a teacher at a university or college","cn":"（大学的）讲师，教员","lab":"North American English","ex":{"en":"a university/college professor","cn":"大学教师"}}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT; N-VOC头衔名词；可数名词；称呼名词","cn":"（英国大学的）教授","en":"A professor in a British university is the most senior teacher in a department.","ex":{"en":"...Professor Cameron","cn":"卡梅伦教授"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"（美国或加拿大的）大学教师，学院教师","en":"A professor in an American or Canadian university or college is a teacher of the highest rank.","ex":{"en":"Robert Dunn is a professor of economics at George Washington University.","cn":"罗伯特·达恩是乔治·华盛顿大学经济学的教师。"}}]},"examples":[{"en":"to be appointed Professor of French at Cambridge","cn":"被任命为剑桥大学的法文教授"},{"en":"He was made (a) professor at the age of 40.","cn":"他 40 岁时就成为教授。"}]},"promotion":{"media":{"uk":"media/uk/promotion__gb_1.mp3","us":"media/us/promotion__us_1.mp3"},"oxford":{"phon":"prəˈməʊʃn","pos":"noun","senses":[{"en":"a move to a more important job or rank in a company or an organization","cn":"提升；提拔；晋升","g":"[uncountable, countable]","lab":"British English","ex":{"en":"The new job is a promotion for him.","cn":"这一新职务对他是擢升。"}},{"en":"a move by a sports team from playing in one group of teams to playing in a better group","cn":"（体育运动队的）晋级，升级","g":"[uncountable]","ex":{"en":"the team’s promotion to the First Division","cn":"这个球队晋升为甲级队"}},{"en":"activities done in order to increase the sales of a product or service; a set of advertisements for a particular product or service","cn":"促销活动；广告宣传","g":"[uncountable, countable]","lab":"especially British English","ex":{"en":"Her job is mainly concerned with sales and promotion.","cn":"她的工作主要是销售和广告宣传方面的。"}},{"en":"activity that encourages people to believe in the value or importance of something, or that helps something to succeed","cn":"推广；促进","g":"[uncountable]","lab":"formal","ex":{"en":"a society for the promotion of religious tolerance","cn":"一个促进宗教包容的团体"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"晋升；升职；提升；擢升","en":"If you are given promotion or a promotion in your job, you are given a more important job or rank in the organization that you work for.","ex":{"en":"Consider changing jobs or trying for promotion.","cn":"考虑换个工作或者争取升职。"}},{"pos":"N-VAR 可变名词","cn":"（尤指通过广告进行的）促销，推广，推销","en":"A promotion is an attempt to make a product or event popular or successful, especially by advertising.","ex":{"en":"During 1984, Remington spent a lot of money on advertising and promotion","cn":"1984年，雷明顿公司在广告和促销方面花费了大量的资金。"}}]},"examples":[{"en":"Her promotion to Sales Manager took everyone by surprise.","cn":"竟然提拔她当销售经理，叫每个人都感到意外。"},{"en":"Her job is mainly concerned with sales and promotion.","cn":"她的工作主要是销售和广告宣传方面的。"}]},"prediction":{"media":{"uk":"media/uk/prediction__gb_1.mp3","us":"media/us/prediction__us_1.mp3"},"oxford":{"phon":"prɪˈdɪkʃn","pos":"noun","senses":[{"en":"a statement that says what you think will happen; the act of making such a statement","cn":"预言；预测；预告","ex":{"en":"The results of the experiment confirmed our predictions.","cn":"实验结果一如我们所料。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"预言；预告；预测","en":"If you make a prediction about something, you say what you think will happen.","ex":{"en":"He was unwilling to make a prediction about which books would sell in the coming year","cn":"他不愿意预测来年哪些书会有销路。"}}]},"examples":[{"en":"Not many people agree with the government's prediction that the economy will improve.","cn":"没有多少人赞同政府认为经济将会有所改善的预测。"},{"en":"Skilled readers make use of context and prediction.","cn":"阅读能力强的人会利用上下文及推测来理解文意。"}]},"prerequisite":{"oxford":{"phon":"ˌpriːˈrekwəzɪt","pos":"adjective","senses":[{"en":"that must exist or happen before something else can happen or be done","cn":"必要的，先决条件的，必须预先具备的","ex":{"en":"prerequisite knowledge","cn":"必备知识"}},{"en":"something that must exist or happen before something else can happen or be done","cn":"先决条件；前提；必备条件","ex":{"en":"A degree is an essential prerequisite for employment at this level.","cn":"学位是做这级工作必备的先决条件。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"先决条件；前提；必要条件","en":"If one thing is a prerequisite for another, it must happen or exist before the other thing is possible.","ex":{"en":"Good self-esteem is a prerequisite for a happy life","cn":"良好的自尊是幸福生活的前提。"}}]},"media":{"uk":"media/uk/prerequisite__gb_1.mp3","us":"media/us/prerequisite__us_1.mp3"},"examples":[{"en":"A degree is an essential prerequisite for employment at this level.","cn":"学位是做这级工作必备的先决条件。"},{"en":"prerequisite knowledge","cn":"必备的知识"}]},"proceed":{"media":{"uk":"media/uk/proceed__gb_1.mp3","us":"media/us/proceed__us_1.mp3"},"oxford":{"phon":"prəˈsiːd","pos":"verb","senses":[{"en":"to continue doing something that has already been started; to continue being done","cn":"继续做（或从事、进行）","g":"[intransitive]","ex":{"en":"We're not sure whether we still want to proceed with the sale.","cn":"我们不确定是否还要继续减价促销。"}},{"en":"to do something next, after having done something else first","cn":"接着做；继而做","g":"[intransitive]","lab":"humorous","ex":{"en":"He outlined his plans and then proceeded to explain them in more detail.","cn":"他简单介绍了他的计划，接着又作了更详细的解释。"}},{"en":"to move or travel in a particular direction","cn":"行进；前往","g":"[intransitive]","lab":"formal","ex":{"en":"The marchers proceeded slowly along the street.","cn":"游行者沿着街道缓缓行进。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"接下来做；接着做","en":"If you proceed to do something, you do it, often after doing something else first.","ex":{"en":"He proceeded to tell me of my birth","cn":"他接着给我讲我出生的事。"}},{"pos":"VERB 动词","cn":"继续进行；继续做","en":"If you proceed with a course of action, you continue with it.","ex":{"en":"The group proceeded with a march they knew would lead to bloodshed","cn":"这个团体继续示威游行，他们知道这将导致流血事件的发生。"}},{"pos":"VERB 动词","cn":"（活动、过程或事件）继续，持续，连续不断","en":"If an activity, process, or event proceeds, it goes on and does not stop.","ex":{"en":"The ideas were not new. Their development had proceeded steadily since the war","cn":"这些并不是什么新思想，自从战争开始就一直稳定地发展演变。"}},{"pos":"VERB 动词","cn":"（朝某个方向）前进，行进","en":"If you proceed in a particular direction, you go in that direction.","ex":{"en":"She climbed the steps and proceeded along the upstairs hallway","cn":"她爬上楼梯，顺着楼上的走廊走去。"}},{"pos":"N-PLURAL 复数名词","cn":"（某个事件或活动的）收入，收益","en":"The proceeds of an event or activity are the money that has been obtained from it.","ex":{"en":"The proceeds of the arms sales were then funneled to Contra fighters in Central America","cn":"出售武器所得的收入随后用来支持了中美洲的反政府武装组织。"}}]},"examples":[{"en":"He outlined his plans and then proceeded to explain them in more detail.","cn":"他简单介绍了他的计划，接着又作了更详细的解释。"},{"en":"Passengers for Rome should proceed to Gate 32 for boarding.","cn":"前往罗马的旅客，请到 32 号登机口登机。"}]},"preserver":{"media":{"uk":"media/uk/preserver__gb_1.mp3","us":"media/us/preserver__us_1.mp3"},"oxford":{"phon":"prɪˈzɜːvə(r)","pos":"noun","senses":[{"en":"a person who makes sure that a particular situation does not change","cn":"保护人；维护者；保存者","g":"[countable]","ex":{"en":"The police are the preservers of law and order.","cn":"警察负责维持治安。"}},{"en":"a substance used to prevent wood from decaying (= being destroyed by natural processes)","cn":"木材防腐剂","g":"[countable, uncountable]"}]},"examples":[{"en":"The police are the preservers of law and order.","cn":"警察负责维持治安。"},{"en":"We must encourage the planting of new trees and preserve our existing woodlands.","cn":""}]},"pronouncing":{"lemma":"pronounce"},"programmes":{"lemma":"programme","media":{"uk":"media/uk/programme__gb_1.mp3","us":"media/us/programme__us_1.mp3"}},"prodigy":{"media":{"uk":"media/uk/prodigy__gb_1.mp3","us":"media/us/prodigy__us_1.mp3"},"oxford":{"phon":"ˈprɒdədʒi","pos":"noun","senses":[{"en":"a young person whose intelligence or skill is unusually good for their age","cn":"（年轻的）天才，奇才，精英；神童","ex":{"en":"a child/an infant prodigy","cn":"天才儿童；神童"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（有音乐、数学或体育等天赋的）天才，奇才，神童","en":"A prodigy is someone young who has a great natural ability for something such as music, mathematics, or sport.","ex":{"en":"...a Russian tennis prodigy.","cn":"俄罗斯的网球奇才"}}]},"examples":[{"en":"a child/an infant prodigy","cn":"天才儿童；神童"},{"en":"a musical prodigy","cn":"音乐奇才"}]},"professional":{"media":{"uk":"media/uk/professional__gb_1.mp3","us":"media/us/professional__us_1.mp3"},"oxford":{"phon":"prəˈfeʃənl","pos":"adjective","senses":[{"en":"doing something as a paid job rather than as a hobby","cn":"职业性的；专业的；非业余的","ex":{"en":"professional athletes/players","cn":"职业运动员／选手"}},{"en":"done as a paid job rather than as a hobby","cn":"职业性的；专业的；非业余的","ex":{"en":"In professional sport winning is everything.","cn":"在职业运动中，胜者为王。"}},{"en":"connected with a job that needs special training or skill, especially one that needs a high level of education","cn":"职业的；专业的","g":"[only before noun]","ex":{"en":"professional qualifications/skills","cn":"专业资格／技能"}},{"en":"having a job which needs special training and a high level of education","cn":"有职业的；专业的","ex":{"en":"Most of the people on the course were professional women.","cn":"参加本课程的大多数人是职业女性。"}},{"en":"showing that somebody is well trained and has a lot of skill","cn":"娴熟的；训练有素的；精通业务的","ex":{"en":"He dealt with the problem in a highly professional way.","cn":"他处理这个问题非常专业。"}},{"en":"connected with the standards that are expected in a particular profession","cn":"职业操守的；职业规范的","ex":{"en":"professional conduct/misconduct","cn":"职业操守；失职"}},{"en":"a person who does a job that needs special training and a high level of education","cn":"专门人员；专业人士；专家","ex":{"en":"You need a professional to sort out your finances.","cn":"你需要专业人员替你理财。"},"pos":"noun"},{"en":"a person who does a sport or other activity as a paid job rather than as a hobby","cn":"职业运动员；（从事某活动的）专业人员","lab":"informal","ex":{"en":"a top golf professional","cn":"顶尖高尔夫球职业选手"},"pos":"noun"},{"en":"a person who has a lot of skill and experience","cn":"内行；专门人才；技术精湛者；老练的人","lab":"informal","ex":{"en":"This was clearly a job for a real professional.","cn":"这显然是真正的专家才能干的工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"职业的；专业的","en":"Professional means relating to a person's work, especially work that requires special training.","ex":{"en":"His professional career started at Liverpool University.","cn":"他的职业生涯是从利物浦大学开始的。"}},{"pos":"ADJ 形容词","cn":"（人）职业的，专业的","en":"Professional people have jobs that require advanced education or training.","ex":{"en":"...highly qualified professional people like doctors and engineers.","cn":"像医生和工程师这样需要高技能的专业人员"}},{"pos":"ADJ 形容词","cn":"专门从事的；非业余的","en":"You use professional to describe people who do a particular thing to earn money rather than as a hobby.","ex":{"en":"This has been my worst time for injuries since I started as a professional footballer","cn":"这是我当职业足球运动员以来受伤来得最不是时候的一次。"}},{"pos":"ADJ 形容词","cn":"（运动）职业性质的","en":"Professional sports are played for money rather than as a hobby.","ex":{"en":"...an art student who had played professional football for a short time.","cn":"踢过短时间职业足球的艺术系学生"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"专业的；内行的；高水平的","en":"If you say that something that someone does or produces is professional, you approve of it because you think that it is of a very high standard.","ex":{"en":"They run it with a truly professional but personal touch.","cn":"他们的经营既有真正的专业水准又不乏个人特色。"}}]},"examples":[{"en":"If it's a legal matter you need to seek professional advice.","cn":"如果这属于法律问题，你就需要寻求专业意见了。"},{"en":"After he won the amateur championship he turned professional.","cn":"他获得业余赛冠军后就转为职业运动员了。"}]},"pronunciation":{"oxford":{"phon":"prəˌnʌnsiˈeɪʃn","pos":"noun","senses":[{"en":"the way in which a language or a particular word or sound is pronounced","cn":"发音；读音","g":"[uncountable, countable]","ex":{"en":"a guide to English pronunciation","cn":"英语发音指南"}},{"en":"the way in which a particular person pronounces the words of a language","cn":"（某人的）发音","g":"[singular]","ex":{"en":"Your pronunciation is excellent.","cn":"你的发音好极了。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"发音；读法","en":"The pronunciation of a word or language is the way in which it is pronounced.","ex":{"en":"She gave the word its French pronunciation","cn":"她读出了该词的法语发音。"}}]},"media":{"uk":"media/uk/pronunciation__gb_1.mp3","us":"media/us/pronunciation__us_1.mp3"},"examples":[{"en":"There is more than one pronunciation of ‘garage’. * garage","cn":"的读音不止一种。"},{"en":"Your pronunciation is excellent.","cn":"你的发音好极了。"}]},"protections":{"lemma":"protection","media":{"uk":"media/uk/protection__gb_1.mp3","us":"media/us/protection__us_1.mp3"}},"priceless":{"media":{"uk":"media/uk/priceless__gb_1.mp3","us":"media/us/priceless__us_1.mp3"},"oxford":{"phon":"ˈpraɪsləs","pos":"adjective","senses":[{"en":"extremely valuable or important","cn":"无价的；极珍贵的；极重要的","ex":{"en":"a priceless collection of antiques","cn":"价值连城的古文物收藏"}},{"en":"extremely funny","cn":"滑稽的；极可笑的；令人捧腹的","lab":"informal","ex":{"en":"You should have seen his face—it was priceless!","cn":"你真该见识见识他那副尊容，可笑极了！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无价的；极贵重的；极为昂贵的","en":"If you say that something is priceless, you are emphasizing that it is worth a very large amount of money.","ex":{"en":"They are priceless, unique and irreplaceable.","cn":"它们是独一无二、不可替代的无价之宝。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宝贵的；极其有用的","en":"If you say that something is priceless, you approve of it because it is extremely useful.","ex":{"en":"They are a priceless record of a brief period in British history","cn":"它们是对英国历史上一个短暂时期的极为珍贵的记录。"}}]},"examples":[{"en":"You should have seen his face — it was priceless!","cn":"你真该见识见识他那副尊容，可笑极了！"},{"en":"a priceless collection of antiques","cn":"价值连城的古文物收藏"}]},"probable":{"oxford":{"phon":"ˈprɒbəbl","pos":"adjective","senses":[{"en":"likely to happen, to exist or to be true","cn":"很可能发生（或存在等）的","ex":{"en":"the probable cause/explanation/outcome","cn":"可能的原因／解释／结果"}},{"en":"a person or an animal that is likely to win a race or to be chosen for a team","cn":"可能获胜的人（或动物）；可能入选者","ex":{"en":"All four players are probables for the national team.","cn":"这四名球员都有可能入选国家队。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可能的；也许的；大概的","en":"If you say that something is probable, you mean that it is likely to be true or likely to happen.","ex":{"en":"It is probable that the medication will suppress the symptom without treating the condition","cn":"这种药物有可能治标不治本。"}},{"pos":"ADJ 形容词","cn":"很有希望的；有可能的","en":"You can use probable to describe a role or function that someone or something is likely to have.","ex":{"en":"The Socialists united behind their probable presidential candidate, Michel Rocard.","cn":"社会党人团结在他们很有希望当选的总统候选人米歇尔·罗卡尔周围。"}}]},"media":{"uk":"media/uk/probable__gb_1.mp3","us":"media/us/probable__us_1.mp3"},"examples":[{"en":"It is probable that the disease has a genetic element.","cn":"这种疾病很可能有遗传因素。"},{"en":"the probable cause/explanation/outcome","cn":"可能的原因/解释/结果"}]},"provision":{"media":{"uk":"media/uk/provision__gb_1.mp3","us":"media/us/provision__us_1.mp3"},"oxford":{"phon":"prəˈvɪʒn","pos":"noun","senses":[{"en":"the act of supplying somebody with something that they need or want; something that is supplied","cn":"提供；供给；给养；供应品","g":"[uncountable, countable, usually singular]","ex":{"en":"housing provision","cn":"住房供应"}},{"en":"preparations that you make for something that might or will happen in the future","cn":"（为将来做的）准备","g":"[uncountable, countable]","ex":{"en":"He had already made provisions for (= planned for the financial future of) his wife and children before the accident.","cn":"意外事故发生之前，他已为妻子、儿女做好了经济安排。"}},{"en":"supplies of food and drink, especially for a long journey","cn":"饮食供应；（尤指旅途中的）粮食","g":"[plural]","ex":{"en":"We have enough provisions to last us two weeks.","cn":"我们的食物足够用两周的。"}},{"en":"a condition or an arrangement in a legal document","cn":"（法律文件的）规定，条款","g":"[countable]","ex":{"en":"The same provisions apply to foreign-owned companies.","cn":"同样的规定适用于外资公司。"}},{"en":"to supply somebody/something with enough of something, especially food, to last for a particular period of time","cn":"为…提供所需物品（尤指食物）","ex":{"en":"The main business of the port is to provision passing ocean liners.","cn":"港口的主要业务是为过往海轮供应食品。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"供应；提供","en":"The provision of something is the act of giving it or making it available to people who need or want it.","ex":{"en":"The department is responsible for the provision of residential care services.","cn":"该部门负责提供家庭护理服务。"}},{"pos":"N-VAR 可变名词","cn":"预备；准备；预先采取的措施","en":"If you make provision for something that might happen or that might need to be done, you make arrangements to deal with it.","ex":{"en":"Mr King asked if it had ever occurred to her to make provision for her own pension","cn":"金先生问她是否曾想过要为自己的养老金预先作安排。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赡养；供养","en":"If you make provision for someone, you support them financially and make sure that they have the things that they need.","ex":{"en":"Special provision should be made for children","cn":"应给孩子在经济上专门作好安排。"}},{"pos":"N-COUNT 可数名词","cn":"（法律或协议的）条文，条款，规定","en":"A provision in a law or an agreement is an arrangement which is included in it.","ex":{"en":"He backed a provision that would allow judges to delay granting a divorce decree in some cases","cn":"他赞成一项允许法官在一些情况下延迟作出离婚判决的法律条款。"}},{"pos":"N-PLURAL 复数名词","cn":"食品供应","en":"Provisions are supplies of food.","ex":{"en":"On board were enough provisions for two weeks.","cn":"船上有足够两周吃的食物。"}}]},"examples":[{"en":"He had already made provisions for (= planned for the financial future of) his wife and children before the accident.","cn":"意外事故发生之前，他已为妻子、儿女做好了经济安排。"},{"en":"Under the provisions of the lease, the tenant is responsible for repairs.","cn":"按契约规定，房客负责房屋维修。"}]},"print":{"oxford":{"phon":"prɪnt","pos":"verb","senses":[{"en":"to produce letters, pictures, etc. on paper using a machine that puts ink (= coloured liquid) on the surface","cn":"打印","g":"[transitive, intransitive]","lab":"computing","sc":"letters/pictures","ex":{"en":"I'm printing a copy of the document for you.","cn":"我正在给你印一份这个文件。"}},{"en":"to produce books, newspapers, etc. by printing them in large quantities","cn":"印刷","g":"[transitive]","sc":"books/newspapers","ex":{"en":"They printed 30 000 copies of the book.","cn":"这本书他们印了 3 万册。"}},{"en":"to publish something in printed form","cn":"登载；刊登；发表","g":"[transitive]","sc":"publish","ex":{"en":"The photo was printed in all the national newspapers.","cn":"这张照片被刊登在所有全国性报纸上。"}},{"en":"to produce a photograph on paper from a digital file or from film","cn":"洗印；冲洗","g":"[transitive]","sc":"photograph","ex":{"en":"Photographs can be printed from a digital file or from a negative.","cn":"数字文档或底片均可打印出照片。"}},{"en":"to write without joining the letters together","cn":"用印刷体写（字母之间笔画不相连接）","g":"[transitive, intransitive]","sc":"write","ex":{"en":"Print your name and address clearly in the space provided.","cn":"请用印刷体在空白处清晰填写你的姓名和住址。"}},{"en":"to make a mark on a soft surface by pressing","cn":"（在松软的表面）压印，印出","g":"[transitive]","lab":"figurative","sc":"make mark","ex":{"en":"The tracks of the large animal were clearly printed in the sand.","cn":"这只大动物的足迹清晰地印在沙滩上。"}},{"en":"to make a design on a surface or cloth by pressing a surface against it which has been coloured with ink or dye","cn":"印（图案）；印染","g":"[transitive]","sc":"make design","ex":{"en":"They had printed their own design on the T-shirt.","cn":"他们在 T 恤衫上印了自己设计的图案。"}},{"en":"letters, words, numbers, etc. that have been printed onto paper","cn":"印刷的文字","g":"[uncountable]","sc":"letters/numbers","ex":{"en":"The tiny print was hard to read without my glasses.","cn":"字体太小，我不戴眼镜很难看清。"},"pos":"noun"},{"en":"used to refer to the business of producing newspapers, magazines and books","cn":"印刷行业；出版界","g":"[uncountable]","sc":"newspapers/books","ex":{"en":"the print media","cn":"印刷媒体"},"pos":"noun"},{"en":"a mark left by your finger, foot, etc. on the surface of something","cn":"指纹；手印；脚印；足迹","g":"[countable, usually plural]","sc":"mark","ex":{"en":"His prints were found on the gun.","cn":"在枪上发现了他的指纹。"},"pos":"noun"},{"en":"a picture that is cut into wood or metal then covered with ink (= coloured liquid for printing, drawing, etc.) and printed onto paper; a picture that is copied from a painting using photography","cn":"版画；影印画","g":"[countable]","lab":"US English","sc":"picture","ex":{"en":"a framed set of prints","cn":"一组镶框的版画"},"pos":"noun"},{"en":"a photograph produced from film","cn":"（用底片洗印的）相片","g":"[countable]","sc":"photograph","ex":{"en":"How many sets of prints would you like?","cn":"你想洗几套照片？"},"pos":"noun"},{"en":"cotton cloth that has a pattern printed on it; this pattern","cn":"印花棉布（或图案）；花样","g":"[uncountable, countable]","sc":"cloth","ex":{"en":"a cotton print dress","cn":"花布连衣裙"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打印；印刷","en":"If someone prints something such as a book or newspaper, they produce it in large quantities using a machine.","ex":{"en":"He started to print his own posters to distribute abroad","cn":"他开始印刷自己的海报并发往国外。"}},{"pos":"VERB 动词","cn":"（在报纸、杂志上）刊印，刊登，发表","en":"If a newspaper or magazine prints a piece of writing, it includes it or publishes it.","ex":{"en":"We can only print letters which are accompanied by the writer's name and address.","cn":"我们只能刊登附有作者姓名和地址的信件。"}},{"pos":"VERB 动词","cn":"印（数字、字母或图案）；印染","en":"If numbers, letters, or designs are printed on a surface, they are put on it in ink or dye using a machine. You can also say that a surface is printed with numbers, letters, or designs.","ex":{"en":"...the number printed on the receipt","cn":"印在发票上的数字"}},{"pos":"N-COUNT 可数名词","cn":"印花织物；印刷品；印花；印制图案","en":"A print is a piece of clothing or material with a pattern printed on it. You can also refer to the pattern itself as a print .","ex":{"en":"Her mother wore one of her dark summer prints","cn":"她妈妈穿着一件深色印花夏装。"}},{"pos":"VERB 动词","cn":"冲洗，冲印（照片）","en":"When you print a photograph, you produce it from a negative.","ex":{"en":"Printing a black-and-white negative on to colour paper produces a similar monochrome effect","cn":"将一张黑白底片冲印到彩色相纸上会产生相似的单色效果。"}},{"pos":"N-COUNT 可数名词","cn":"（冲印出来的）照片","en":"A print is a photograph from a film that has been developed.","ex":{"en":"...black and white prints of Margaret and Jean as children.","cn":"玛格丽特和吉恩小时候的黑白照片"}},{"pos":"N-COUNT 可数名词","cn":"电影拷贝","en":"A print of a cinema film is a particular copy or set of copies of it.","ex":{"en":"First released in 1957, the movie now appears in a new print.","cn":"1957年首次上映后，这部影片现在有了新的拷贝。"}},{"pos":"N-COUNT 可数名词","cn":"绘画复制品；版画","en":"A print is one of a number of copies of a particular picture. It can be either a photograph, something such as a painting, or a picture made by an artist who puts ink on a prepared surface and presses it against paper.","ex":{"en":"...William Hogarth's famous series of prints.","cn":"威廉·霍加斯著名的版画系列"}},{"pos":"N-UNCOUNT 不可数名词","cn":"印出的字； 印刷字体","en":"Print is used to refer to letters and numbers as they appear on the pages of a book, newspaper, or printed document.","ex":{"en":"...columns of tiny print","cn":"一栏栏极小的印刷字"}},{"pos":"ADJ 形容词","cn":"印刷（媒体）的；纸媒的","en":"The print media consists of newspapers and magazines, but not television or radio.","ex":{"en":"I have been convinced that the print media are more accurate and more reliable than television.","cn":"我已经确信印刷媒体比电视更准确、更可靠。"}},{"pos":"VERB 动词","cn":"用印刷体书写","en":"If you print words, you write in letters that are not joined together and that look like the letters in a book or newspaper.","ex":{"en":"Print your name and address on a postcard and send it to us.","cn":"在明信片上用印刷体写上你的名字和地址，然后邮寄给我们。"}},{"pos":"N-COUNT 可数名词","cn":"脚印；足迹","en":"You can refer to a mark left by someone's foot as a print .","ex":{"en":"He crawled from print to print, sniffing at the earth, following the scent left in the tracks.","cn":"它沿着脚印向前爬，在地面上嗅着，追踪着路上留下的气味。"}},{"pos":"N-COUNT 可数名词","cn":"指纹","en":"You can refer to invisible marks left by someone's fingers as their prints .","ex":{"en":"Fresh prints of both girls were found in the flat.","cn":"在公寓里发现了两个女孩不久前留下的指纹。"}},{"pos":"PHRASE 短语","cn":"（在书刊或报纸上）发表，刊登","en":"If you appear in print, or get into print, what you say or write is published in a book, newspaper, or magazine.","ex":{"en":"Many of these poets appeared in print only long after their deaths","cn":"这些诗人中有很多都是在去世很久以后作品才得以发表的。"}},{"pos":"PHRASE 短语","cn":"（书）仍在印行，仍在出版","en":"If a book is in print, copies of it are still being produced.","ex":{"en":"Many of their books have been in print for nearly 40 years.","cn":"他们的很多书都印行将近40年了。"}},{"pos":"PHRASE 短语","cn":"（书）已经停印，已经绝版","en":"If a book is out of print, copies of it are no longer being produced.","ex":{"en":"I believe the book is now out of print, but it can easily be borrowed from libraries.","cn":"我想这本书现在已经停印了，但从图书馆很容易借到。"}},{"pos":"PHRASE 短语","cn":"（广告、合同等的）细节，附属细则，小号字体印刷条款","en":"The small print or the fine print of something such as an advertisement or a contract consists of the technical details and legal conditions, which are often printed in much smaller letters than the rest of the text.","ex":{"en":"I'm looking at the small print; I don't want to sign anything that I shouldn't sign","cn":"我正在看附属细则，我可不想签署任何不应该签署的东西。"}},{"pos":"","cn":"","en":"a licence to print money→see: ;"},{"pos":"","cn":"","en":"相关词组：print out print up"}]},"media":{"uk":"media/uk/print__gb_1.mp3","us":"media/us/print__us_1.mp3"},"examples":[{"en":"By the time this gets into print, they'll already have left the country.","cn":"这篇东西发表的时候，他们将已经离开这个国家了。"},{"en":"In some countries children learn to print when they first go to school.","cn":"在有些国家，儿童刚上学时学习用印刷体书写。"}]},"practically":{"media":{"uk":"media/uk/practically__gb_1.mp3","us":"media/us/practically__us_1.mp3"},"oxford":{"phon":"ˈpræktɪkli","pos":"adverb","senses":[{"en":"almost; very nearly","cn":"几乎；差不多；很接近","lab":"British English","ex":{"en":"The theatre was practically empty.","cn":"剧院几乎是空的。"}},{"en":"in a realistic or sensible way; in real situations","cn":"实事求是地；实际地","ex":{"en":"Practically speaking, we can't afford it.","cn":"实际说来，我们买不起这东西。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"简直；几乎","en":"Practically means almost, but not completely or exactly.","ex":{"en":"He'd known the old man practically all his life","cn":"他几乎打记事起就认识这个老人。"}},{"pos":"ADV 副词","cn":"实际上；实践上","en":"You use practically to describe something which involves real actions or events rather than ideas or theories.","ex":{"en":"The course is more practically based than the Masters degree","cn":"该课程比硕士学位课程更注重实践。"}}]},"examples":[{"en":"It sounds like a good idea, but I don't think it will work practically.","cn":"这个主意听起来不错，但我认为它实际上行不通。"},{"en":"Practically speaking, we can't afford it.","cn":"实际说来，我们买不起这东西。"}]},"predictable":{"media":{"uk":"media/uk/predictable__gb_1.mp3","us":"media/us/predictable__us_1.mp3"},"oxford":{"phon":"prɪˈdɪktəbl","pos":"adjective","senses":[{"en":"if something is predictable, you know in advance that it will happen or what it will be like","cn":"可预见的；可预料的","ex":{"en":"a predictable result","cn":"可预见的结果"}},{"en":"behaving or happening in a way that you would expect and therefore boring","cn":"意料之中的；老套乏味的","lab":"often disapproving","ex":{"en":"He's very nice, but I find him rather dull and predictable.","cn":"他为人很不错，但我觉得他相当呆板乏味。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可预言的；可预测的；可预料的","en":"If you say that an event is predictable, you mean that it is obvious in advance that it will happen.","ex":{"en":"This was a predictable reaction, given the bitter hostility between the two countries","cn":"考虑到这两个国家之间激烈的敌对情绪，这种反应是可以预见的。"}}]},"examples":[{"en":"He's very nice, but I find him rather dull and predictable.","cn":"他为人很不错，但我觉得他相当呆板乏味。"},{"en":"Predictably, the new regulations proved unpopular.","cn":"正如所预料，新规定果然不得人心。"}]},"programme":{"media":{"uk":"media/uk/programme__gb_1.mp3","us":"media/us/programme__us_1.mp3"},"oxford":{"phon":"ˈprəʊɡræm","pos":"noun","senses":[{"en":"something that people watch on television or listen to on the radio","cn":"节目","lab":"British English","sc":"on TV/radio","ex":{"en":"a news programme","cn":"新闻节目"}},{"en":"a plan of things that will be done or included in the development of something","cn":"计划；方案；活动安排","sc":"plan","ex":{"en":"the country's nuclear weapons/space programme","cn":"该国的核武器／太空计划"}},{"en":"a course of study","cn":"课程","lab":"especially North American English","sc":"course of study","ex":{"en":"a school/an educational programme","cn":"学校／教育课程"}},{"en":"an organized order of performances or events","cn":"（演出或活动的）流程","sc":"order of events","ex":{"en":"The concert is the highlight of the festival's musical programme.","cn":"这场音乐会是艺术节音乐节目的亮点。"}},{"en":"a thin book or a piece of paper that gives you information about a play, a concert, etc.","cn":"节目单；演出介绍","sc":"for play/concert","ex":{"en":"a theatre programme","cn":"剧场节目单"}},{"en":"a series of actions done by a machine, such as a washing machine","cn":"（机器工作的）程序","sc":"of machine","ex":{"en":"Select a cool programme for woollen clothes.","cn":"洗毛衣要选择凉水程序。"}},{"en":"to plan for something to happen, especially as part of a series of planned events","cn":"计划；规划；安排","g":"[usually passive]","sc":"plan","ex":{"en":"Several evening events have been programmed.","cn":"已安排了几场晚间活动。"},"pos":"verb"},{"en":"to make a person, an animal, etc. behave in a particular way, so that they do it without thinking about it","cn":"使（人或动物）自动做某事","g":"[usually passive]","sc":"person/animal","ex":{"en":"Human beings are genetically programmed to learn certain kinds of language.","cn":"人类生来有学习某几种语言的遗传因素。"},"pos":"verb"},{"en":"to give a machine instructions to do a particular task","cn":"预调；预设","sc":"machine","ex":{"en":"She programmed the central heating to come on at eight.","cn":"她把中央供暖系统设定为八点启动。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方案；计划；安排","en":"A programme of actions or events is a series of actions or events that are planned to be done.","ex":{"en":"The general argued that the nuclear programme should still continue","cn":"将军认为核计划应该继续进行。"}},{"pos":"N-COUNT 可数名词","cn":"（电视或广播）节目","en":"A television or radio programme is something that is broadcast on television or radio.","ex":{"en":"...a series of TV programmes on global environment.","cn":"有关全球环境的一系列电视节目"}},{"pos":"N-COUNT 可数名词","cn":"（剧院或音乐会的）节目单","en":"A theatre or concert programme is a small book or sheet of paper which gives information about the play or concert you are attending."},{"pos":"VERB 动词","cn":"为（机器或系统）设定程序","en":"When you programme a machine or system, you set its controls so that it will work in a particular way.","ex":{"en":"Parents can programme the machine not to turn on at certain times.","cn":"父母可以设定这台机器的程序，使它在特定时间段无法开启。"}},{"pos":"VERB 动词","cn":"按特定的方式行事","en":"If a living creature is programmed to behave in a particular way, they are likely to behave in that way because of social or biological factors that they cannot control.","ex":{"en":"We are all genetically programmed to develop certain illnesses.","cn":"基因决定了我们都会患上某些疾病。"}}]},"examples":[{"en":"Human beings are genetically programmed to learn certain kinds of language.","cn":"人类生来有学习某几种语言的遗传因素。"},{"en":"Did you see that programme on India last night?","cn":"昨晚关于印度的那个节目你看了没有？"}]},"predictions":{"lemma":"prediction","media":{"uk":"media/uk/prediction__gb_1.mp3","us":"media/us/prediction__us_1.mp3"}},"pres":{"oxford":{"phon":"ˌpiː ˈɑː(r)","pos":"noun","senses":[{"en":"the abbreviation for public relations","cn":"公关，公共关系（全写为 public relations）"},{"en":"the abbreviation for proportional representation","cn":"比例代表制（全写为 proportional representation）"}]},"media":{"uk":"media/uk/pr__gb_1.mp3","us":"media/us/pr__us_1.mp3"}},"primacy":{"media":{"uk":"media/uk/primacy__gb_1.mp3","us":"media/us/primacy__us_1.mp3"},"oxford":{"phon":"ˈpraɪməsi","pos":"noun","senses":[{"en":"the fact of being the most important person or thing","cn":"首要；至高无上","g":"[uncountable]","ex":{"en":"a belief in the primacy of the family","cn":"家庭至上论"}},{"en":"the position of an archbishop","cn":"总主教职","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"首要；首位","en":"The primacy of something is the fact that it is the most important or most powerful thing in a particular situation.","ex":{"en":"The political idea at the heart of this is the primacy of the individual.","cn":"其核心的政治观点就是把个人放在首位。"}}]},"examples":[{"en":"a belief in the primacy of the family","cn":"家庭至上论"},{"en":"We must give primacy to education.","cn":"我们必须以教育为本。"}]},"praise":{"media":{"uk":"media/uk/praise__gb_1.mp3","us":"media/us/praise__us_1.mp3"},"oxford":{"phon":"preɪz","pos":"noun","senses":[{"en":"words that show that you approve of and admire somebody/something","cn":"赞扬；称赞；赞美","g":"[plural]","lab":"less frequent","ex":{"en":"The team coach singled out two players for special praise.","cn":"教练特别点名称赞两名队员。"}},{"en":"the expression of thanks to or respect for God","cn":"（对上帝的）赞美，颂扬","ex":{"en":"hymns/songs of praise","cn":"赞美诗；颂歌"}},{"en":"to say that you approve of and admire somebody/something","cn":"赞扬；称赞；赞美","ex":{"en":"She praised his cooking.","cn":"她称赞他的厨艺。"},"pos":"verb"},{"en":"to express your thanks to or your respect for God","cn":"赞美，颂扬（上帝）","ex":{"en":"Praise the Lord.","cn":"赞美上帝！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"称赞；赞扬；表扬","en":"If you praise someone or something, you express approval for their achievements or qualities.","ex":{"en":"The American president praised Turkey for its courage","cn":"美国总统赞扬了土耳其的勇气。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"称赞；赞美；赞扬","en":"Praise is what you say or write about someone when you are praising them.","ex":{"en":"All the ladies are full of praise for the staff and service they received","cn":"所有女士都高度赞扬了工作人员和他们所提供的服务。"}},{"pos":"VERB 动词","cn":"称颂，赞美，感谢（上帝）","en":"If you praise God, you express your respect, honour, and thanks to God.","ex":{"en":"She asked the church to praise God.","cn":"她请求教会赞美上帝。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对上帝的）赞美，敬拜，感谢","en":"Praise is the expression of respect, honour, and thanks to God.","ex":{"en":"Hindus were singing hymns in praise of the god Rama.","cn":"印度教教徒在唱圣歌赞美罗摩神。"}},{"pos":"PHRASE 短语","cn":"用冷漠的赞许贬低；明褒实贬","en":"If someone damns something with faint praise, they say something about it which sounds quite nice but is not enthusiastic, and shows that they do not have a high opinion of it.","ex":{"en":"...the belief that the US had signalled a policy shift by damning with faint praise the mediation efforts.","cn":"认为美国对调停努力明褒实贬是表明其政策已发生转变的观点"}},{"pos":"PHRASE 短语","cn":"高度赞扬；热情表扬","en":"If you sing someone's praises, you praise them in an enthusiastic way.","ex":{"en":"Ottershaw's been singing your praises for years","cn":"奥特肖多年来对你一直高度赞赏。"}}]},"examples":[{"en":"His latest movie has won high praise from the critics.","cn":"他的最新电影得到了评论家的高度赞扬。"},{"en":"We have nothing but praise for the way they handled the investigation.","cn":"对于他们处理调查的方式我们唯有赞赏。"}]},"pronounced":{"oxford":{"phon":"prəˈnaʊnst","pos":"adjective","senses":[{"en":"very obvious, easy to notice or strongly expressed","cn":"显著的；显而易见的；表达明确的","ex":{"en":"He walked with a pronounced limp.","cn":"他走路明显跛足。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的； 显著的","en":"Something that is pronounced is very noticeable.","ex":{"en":"Most of the art exhibitions have a pronounced Scottish theme.","cn":"大多数的艺术展品带有明显的苏格兰风格。"}}]},"media":{"uk":"media/uk/pronounced__gb_1.mp3","us":"media/us/pronounced__us_1.mp3"},"examples":[{"en":"She has very pronounced views on art.","cn":"她有非常明确的艺术观。"},{"en":"He walked with a pronounced limp.","cn":"他走路明显跛足。"}],"base":"pronounce"},"proportional":{"oxford":{"phon":"prəˈpɔːʃənl","pos":"adjective","senses":[{"en":"increasing or decreasing in size, amount or degree according to changes in something else","cn":"成比例的；相应的；相称的","ex":{"en":"Salary is proportional to years of experience.","cn":"薪金视资历而定。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"与…成比例的","en":"If one amount is proportional to another, the two amounts increase and decrease at the same rate so there is always the same relationship between them.","ex":{"en":"Loss of weight is directly proportional to the rate at which the disease is progressing.","cn":"体重的下降与病情发展的速度成正比。"}}]},"media":{"uk":"media/uk/proportional__gb_1.mp3","us":"media/us/proportional__us_1.mp3"},"examples":[{"en":"Families with children spend proportionally less per person than families without children.","cn":"有子女家庭比无子女家庭的人均开销相对地少。"},{"en":"to be directly/inversely proportional to sth","cn":"与某事物成正比/反比"}]},"promotes":{"lemma":"promote","media":{"uk":"media/uk/promote__gb_1.mp3","us":"media/us/promote__us_1.mp3"}},"progeny":{"media":{"uk":"media/uk/progeny__gb_1.mp3","us":"media/us/progeny__us_1.mp3"},"oxford":{"phon":"ˈprɒdʒəni","pos":"noun","senses":[{"en":"a person’s children; the young of animals and plants","cn":"子孙；幼崽；幼兽；幼苗","ex":{"en":"He was surrounded by his numerous progeny.","cn":"众多的子孙簇拥着他。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（人的）后裔，子女；（动物的）幼崽","en":"You can refer to a person's children or to an animal's young as their progeny.","ex":{"en":"Davis was never loquacious on the subject of his progeny.","cn":"戴维斯说到他的子女时总是寡言少语。"}},{"pos":"N-PLURAL 复数名词","cn":"（某物的）新一代，下一代","en":"The progeny of a particular thing are the things that develop from it.","ex":{"en":"Among its many progeny, the 1944 Education Act gave birth to the modern youth service.","cn":"在1944年通过的《教育法案》的诸多衍生条款中，就包括了现代青年教育服务。"}}]},"examples":[{"en":"He was surrounded by his numerous progeny.","cn":"众多的子孙簇拥着他。"},{"en":"Connolly’s book is the progeny of an earlier TV series.","cn":"康诺利的书是早先一部电视连续剧的衍生品。"}]},"prep":{"oxford":{"phon":"prep","pos":"noun","senses":[{"en":"(in some private schools) school work that is done at the end of the day after lessons","cn":"（某些私立学校的）课外作业"},{"en":"to prepare (something)","cn":"把…准备好；预备","g":"[transitive, intransitive]","lab":"especially North American English, informal，，","ex":{"en":"Prep the vegetables in advance.","cn":"提前把蔬菜准备好。"},"pos":"verb"},{"en":"to prepare somebody for a medical operation","cn":"为（患者）做手术前准备","g":"[transitive]","lab":"specialist","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"准备；预备","en":"If you prep something, you prepare it.","ex":{"en":"After prepping the boat, they sailed it down to Carloforte.","cn":"备好船后，他们就驶向了南边的卡洛福泰。"}},{"pos":"VERB 动词","cn":"为（患者）做手术准备","en":"If a doctor or nurse preps a patient, they get them ready for surgery or another procedure.","ex":{"en":"I was already prepped for surgery so I went straight into theatre.","cn":"我已经做好了接受外科手术的准备，于是就直接进入了手术室。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（英国一些私立学校的）家庭作业","en":"In some British private schools, prep is the name given to school work that children do in the evening after school has finished.","ex":{"en":"Anne struggled to help Peter and Zara with their prep.","cn":"安妮努力帮助彼得和扎拉完成他们的家庭作业。"}}]},"media":{"uk":"media/uk/prep__gb_1.mp3","us":"media/us/prep__us_1.mp3"},"examples":[{"en":"They're prepping for college.","cn":"他们正为上大学做准备。"},{"en":"Prep the vegetables in advance.","cn":"提前把蔬菜准备好。"}]},"premiere":{"media":{"uk":"media/uk/premiere__gb_1.mp3","us":"media/us/premiere__us_1.mp3"},"oxford":{"phon":"ˈpremieə(r)","pos":"noun","senses":[{"en":"the first public performance of a film or play","cn":"（电影或戏剧的）首次公演，首映","ex":{"en":"the world premiere of his new play","cn":"他的新戏在全世界的首次公演"}},{"en":"to perform a play or piece of music or show a film to an audience for the first time; to be performed or shown to an audience for the first time","cn":"首次公演（戏剧、音乐、电影）","ex":{"en":"The play was premiered at the Birmingham Rep in 2014.","cn":"这出戏于 2014 年在伯明翰轮演剧场首次公演。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"首映；首演；初次公演","en":"The premiere of a new play or film is the first public performance of it.","ex":{"en":"A new Czechoslovak film has had its premiere at the Karlovy Vary film festival.","cn":"一部捷克斯洛伐克新电影在卡罗维发利电影节上首映。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）首映；（使）首演；（使）初次公演","en":"When a film or show premieres or is premiered, it is shown to an audience for the first time.","ex":{"en":"The documentary premiered at the Jerusalem Film Festival","cn":"这部纪录片在耶路撒冷电影节首映。"}}]},"examples":[{"en":"The play was premiered at the Birmingham Rep in 2008.","cn":"这出戏于 2008 年在伯明翰轮演剧场首次公演。"},{"en":"the world premiere of his new play","cn":"他的新戏在全世界的首次公演"}]},"prof":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a professor","cn":"教授"},{"en":"the written abbreviation of professor , used in front of names","cn":"教授〔用于称谓〕"}]},"media":{"uk":"media/uk/prof__gb_1.mp3","us":"media/us/prof__us_1.mp3"},"oxford":{"phon":"prɒf","pos":"noun","senses":[{"en":"a professor","cn":"教授","ex":{"en":"a college prof","cn":"大学教授"}},{"en":"(in writing) professor","cn":"教授","ex":{"en":"Prof. Mike Harrison","cn":"迈克·哈里森教授"},"pos":"abbreviation"}]}},"profit":{"oxford":{"phon":"ˈprɒfɪt","pos":"noun","senses":[{"en":"the money that you make in business or by selling things, especially after paying the costs involved","cn":"利润；收益；赢利","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"annual/pre-tax/corporate profits","cn":"年度／税前／公司利润"}},{"en":"the advantage that you get from doing something","cn":"好处；利益；裨益","g":"[uncountable]","lab":"formal","ex":{"en":"Future lawyers could study this text with profit.","cn":"未来的律师研读这一文本也许会有裨益。"}},{"en":"to get something useful from a situation; to be useful to somebody or give them an advantage","cn":"获益；得到好处；对…有用（或有益）","ex":{"en":"Farmers are profiting from the new legislation.","cn":"新法规使农民受益。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"利润；收益；盈利","en":"A profit is an amount of money that you gain when you are paid more for something than it cost you to make, get, or do it.","ex":{"en":"The bank made pre-tax profits of £3.5 million","cn":"这家银行的税前利润为350万英镑。"}},{"pos":"VERB 动词","cn":"盈利；获取利润；赚钱","en":"If you profit from something, you earn a profit from it.","ex":{"en":"Footballers are accustomed to profiting handsomely from bonuses","cn":"足球运动员对获取丰厚的奖金已习以为常。"}},{"pos":"V-ERG 及物/不及物动词","cn":"得益（于）；对…有益；对…有好处","en":"If you profit from something, or it profits you, you gain some advantage or benefit from it.","ex":{"en":"Jennifer wasn't yet totally convinced that she'd profit from a more relaxed lifestyle","cn":"珍尼弗还不完全相信更轻松的生活方式会对她有好处。"}}]},"media":{"uk":"media/uk/profit__gb_1.mp3","us":"media/us/profit__us_1.mp3"},"examples":[{"en":"Many local people believe the development will profit them.","cn":"当地的许多人认为，这项开发将对他们有利。"},{"en":"Future lawyers could study this text with profit.","cn":"未来的律师研读这一文本也许会有裨益。"}]},"preview":{"media":{"uk":"media/uk/preview__gb_1.mp3","us":"media/us/preview__us_1.mp3"},"oxford":{"phon":"ˈpriːvjuː","pos":"noun","senses":[{"en":"an occasion at which you can see a film, a show, etc. before it is shown to the general public","cn":"预映；预演；预展","ex":{"en":"a press preview (= for journalists only)","cn":"招待新闻界的预展"}},{"en":"a description in a newspaper or a magazine that tells you about a film, a television programme, etc. before it is shown to the public","cn":"（报刊上有关电影、电视节目等的）预先评述，预告","ex":{"en":"Turn to page 12 for a preview of next week's programmes.","cn":"下周节目预告请见第 12 页。"}},{"en":"a series of short scenes from a film or television programme, shown in advance to advertise it","cn":"指电影或电视节目的预告片","lab":"North American English"},{"en":"a chance to see what something will be like before it happens or is shown","cn":"预览","ex":{"en":"Click on the print preview button.","cn":"点击打印预览按钮。"}},{"en":"to see a film, a television programme, etc. before it is shown to the general public and write an account of it for a newspaper or magazine","cn":"为（影视节目）写预评","ex":{"en":"The exhibition was previewed in last week's issue.","cn":"本刊上周对展览作了预评。"},"pos":"verb"},{"en":"to give somebody a short account of something that is going to happen, be studied, etc.","cn":"概述；扼要介绍","lab":"especially North American English","ex":{"en":"The professor previewed the course for us.","cn":"教授为我们扼要介绍了这门课程。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预演；预映；预展","en":"A preview is an opportunity to see something such as a film, exhibition, or invention before it is open or available to the public.","ex":{"en":"He had gone to see the preview of a play.","cn":"他去看一场戏剧的预演了。"}},{"pos":"VERB 动词","cn":"预先观看；为（电影等）写预评","en":"If a journalist previews something such as a film, exhibition, or invention, they see it and describe it to the public before the public see it for themselves.","ex":{"en":"He knew about the interview prior to its publication and had actually previewed the piece","cn":"这篇访谈在发表以前他就已经知道了，并且实际上还预先阅览过。"}}]},"examples":[{"en":"Turn to page 12 for a preview of next week's programmes.","cn":"下周节目预告请见第 12 页。"},{"en":"The professor previewed the course for us.","cn":"教授为我们扼要介绍了这门课程。"}]},"practical":{"media":{"uk":"media/uk/practical__gb_1.mp3","us":"media/us/practical__us_1.mp3"},"oxford":{"phon":"ˈpræktɪkl","pos":"adjective","senses":[{"en":"connected with real situations rather than with ideas or theories","cn":"实际的；真实的；客观存在的","sc":"connected with real things","ex":{"en":"to have gained practical experience of the work","cn":"获得实际工作经验"}},{"en":"right or sensible; likely to be successful","cn":"切实可行的","sc":"likely to work","ex":{"en":"I soon realized that it would have been more practical to walk.","cn":"我很快意识到步行会更实用。"}},{"en":"useful or suitable","cn":"有用的；适用的","sc":"useful","ex":{"en":"a practical little car, ideal for the city","cn":"理想的城市实用小汽车"}},{"en":"sensible and realistic","cn":"明智的；实事求是的","sc":"sensible","ex":{"en":"Let's be practical and work out the cost first.","cn":"咱们实际一点儿，先计算一下成本费用。"}},{"en":"good at making or repairing things","cn":"心灵手巧的；善于制作（或修补）的","sc":"good at making things","ex":{"en":"Bob's very practical. He does all the odd jobs around the house.","cn":"鲍勃心灵手巧，家里的零活他都包了。"}},{"en":"almost complete or total","cn":"几乎完全的；实际上的","g":"[only before noun]","sc":"almost total","ex":{"en":"She married a practical stranger.","cn":"她等于是嫁了个陌生人。"}},{"en":"a lesson or an exam in science or technology in which students have to do or make things, not just read or write about them","cn":"实习课；实践课；实验考核","ex":{"en":"a biology practical","cn":"生物学实践"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"实际的；实用的","en":"The practical aspects of something involve real situations and events, rather than just ideas and theories.","ex":{"en":"We can offer you practical suggestions on how to increase the fibre in your daily diet","cn":"我们能就如何增加你日常饮食中的纤维素量提供实际的建议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）明智的，注重实效的，务实的","en":"You describe people as practical when they make sensible decisions and deal effectively with problems.","ex":{"en":"You were always so practical, Maria","cn":"玛丽亚，你以前一向很注重实效。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（意见和方法）切实有效的，可行的","en":"Practical ideas and methods are likely to be effective or successful in a real situation.","ex":{"en":"Although the causes of cancer are being uncovered, we do not yet have any practical way to prevent it","cn":"虽然癌症的病因正被逐步揭开，但我们尚未有任何切实可行的办法来预防它。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（衣物等）实用的，适合特定用途的","en":"You can describe clothes and things in your house as practical when they are suitable for a particular purpose rather than just being fashionable or attractive.","ex":{"en":"Our clothes are lightweight, fashionable, practical for holidays.","cn":"我们的服装轻便、时尚，并且很适合度假时穿。"}},{"pos":"N-COUNT 可数名词","cn":"实验课；实践课；实验考核","en":"A practical is an examination or a lesson in which you make things or do experiments rather than simply writing answers to questions."}]},"examples":[{"en":"It wouldn't be practical for us to go all that way just for the weekend.","cn":"我们跑那么远只为了去度个周末实在很不切实际。"},{"en":"There's still another ten minutes of the game to go, but for practical purposes it's already over.","cn":"比赛虽然还有十分钟，但实际上等于已经结束了。"}]},"prioritize":{"media":{"uk":"media/uk/prioritize__gb_1.mp3","us":"media/us/prioritize__us_1.mp3"},"oxford":{"phon":"praɪˈɒrətaɪz","pos":"verb","senses":[{"en":"to put tasks, problems, etc. in order of importance, so that you can deal with the most important first","cn":"按重要性排列；划分优先顺序","g":"[transitive, intransitive]","ex":{"en":"You should make a list of all the jobs you have to do and prioritize them.","cn":"你应该把所有要做的事都列出来，并按轻重缓急排个顺序。"}},{"en":"to treat something as being more important than other things","cn":"优先处理","g":"[transitive]","lab":"formal","ex":{"en":"The organization was formed to prioritize the needs of older people.","cn":"这个机构是为优先满足老年人的需要而成立的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"优先考虑；给…优先权","en":"If you prioritize something, you treat it as more important than other things.","ex":{"en":"The government is prioritising the service sector, rather than investing in industry and production.","cn":"政府将优先投资服务行业，而非工业和生产行业。"}},{"pos":"VERB 动词","cn":"以优先顺序排列；决定…的优先顺序","en":"If you prioritize the tasks that you have to do, you decide which are the most important and do them first.","ex":{"en":"Make lists of what to do and prioritize your tasks.","cn":"将要做的事情列出来，然后决定其优先顺序。"}}]},"examples":[{"en":"You should make a list of all the jobs you have to do and prioritize them.","cn":"你应该把所有要做的事都列出来，并按轻重缓急排个顺序。"},{"en":"The organization was formed to prioritize the needs of older people.","cn":"这个机构是为优先满足老年人的需要而成立的。"}]},"preserving":{"lemma":"preserve"},"progress":{"media":{"uk":"media/uk/progress__gb_1.mp3","us":"media/us/progress__us_1.mp3"},"oxford":{"phon":"ˈprəʊɡres","pos":"noun","senses":[{"en":"the process of improving or developing, or of getting nearer to achieving or completing something","cn":"进步；进展；进程","ex":{"en":"I think we're making progress.","cn":"我认为我们正在取得进展。"}},{"en":"movement forwards or towards a place","cn":"前进；行进","ex":{"en":"She watched his slow progress down the steep slope.","cn":"她望着他慢慢走下陡坡。"}},{"en":"to improve or develop over a period of time; to make progress","cn":"进步；改进；进展","g":"[intransitive]","ex":{"en":"The course allows students to progress at their own speed.","cn":"本课程允许学生按各自的速度学习。"},"pos":"verb"},{"en":"to move forward","cn":"前进；行进","g":"[intransitive]","lab":"formal","ex":{"en":"The line of traffic progressed slowly through the town.","cn":"车流缓慢地穿过城镇。"},"pos":"verb"},{"en":"to go forward in time","cn":"（时间上）推移，流逝","g":"[intransitive]","ex":{"en":"The weather became colder as the day progressed.","cn":"天色越晚，天气就越冷。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"进步；进展","en":"Progress is the process of gradually improving or getting nearer to achieving or completing something.","ex":{"en":"The medical community continues to make progress in the fight against cancer","cn":"医学界在抗癌的斗争中不断取得进步。"}},{"pos":"N-SING 单数名词","cn":"进展；进程","en":"The progress of a situation or action is the way in which it develops.","ex":{"en":"The Chancellor is reported to have been delighted with the progress of the first day's talks","cn":"据报道，总理对第一天会谈的进展表示满意。"}},{"pos":"VERB 动词","cn":"进步；进展；发展；改进","en":"To progress means to move over a period of time to a stronger, more advanced, or more desirable state.","ex":{"en":"He will visit once a fortnight to see how his new staff are progressing","cn":"他会每两个星期来访一次，看看他的新员工进展如何。"}},{"pos":"VERB 动词","cn":"继续进行；逐步发展","en":"If events progress, they continue to happen gradually over a period of time.","ex":{"en":"As the evening progressed, sadness turned to rage","cn":"随着夜幕逐渐降临，悲伤变成了愤怒。"}},{"pos":"VERB 动词","cn":"使…发展；使…取得进展","en":"If you progress something, you cause it to develop.","ex":{"en":"Very little was done to progress the case in the first 10 or so months after K was charged.","cn":"在K被指控后最初的10个月左右，这个案子进展缓慢。"}},{"pos":"PHRASE 短语","cn":"正在进行中","en":"If something is in progress, it has started and is still continuing.","ex":{"en":"The game was already in progress when we took our seats","cn":"我们坐下来的时候，比赛已经开始了。"}}]},"examples":[{"en":"We have made great progress in controlling inflation.","cn":"我们在抑制通货膨胀方面取得了巨大进展。"},{"en":"There wasn't much traffic so we made good progress.","cn":"来往车辆不多，所以我们开得很快。"}]},"professed":{"oxford":{"phon":"prəˈfest","pos":"adjective","senses":[{"en":"used to describe a belief or a position that somebody has publicly made known","cn":"公开表明的","ex":{"en":"a professed Christian/anarchist","cn":"公开表明信仰的基督教徒；公开表明立场的无政府主义者"}},{"en":"used to describe a feeling or an attitude that somebody says they have but which may not be sincere","cn":"自称的；自诩的；假充的","ex":{"en":"These, at least, were their professed reasons for pulling out of the deal.","cn":"至少这些是他们自称退出这宗交易的理由。"}}]},"media":{"uk":"media/uk/professed__gb_1.mp3","us":"media/us/professed__us_1.mp3"},"examples":[{"en":"These, at least, were their professed reasons for pulling out of the deal.","cn":"至少这些是他们自称退出这宗交易的理由。"},{"en":"a professed Christian/anarchist","cn":"公开表明信仰的基督教徒；公开表明立场的无政府主义者"}]},"presently":{"media":{"uk":"media/uk/presently__gb_1.mp3","us":"media/us/presently__us_1.mp3"},"oxford":{"phon":"ˈprezntli","pos":"adverb","senses":[{"en":"at the time you are speaking or writing; now","cn":"此刻；现在；眼下","lab":"especially North American English","ex":{"en":"The crime is presently being investigated by the police.","cn":"警方目前正在调查这起案件。"}},{"en":"used to show that something happened after a short time","cn":"（表示很快就发生了）","ex":{"en":"Presently, the door opened again and three men stepped out.","cn":"不久，门又打开了，走出来三个人。"}},{"en":"used to show that something will happen soon","cn":"（表示即将发生）","lab":"British English","ex":{"en":"She'll be here presently.","cn":"她马上就会到这儿。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"目前；现在；此时","en":"If you say that something is presently happening, you mean that it is happening now.","ex":{"en":"She is presently developing a number of projects","cn":"她现在正着手开发多个项目。"}},{"pos":"ADV 副词","cn":"不久；随即","en":"You use presently to indicate that something happened quite a short time after the time or event that you have just mentioned.","ex":{"en":"Presently, a young woman in a white coat came in","cn":"很快，一个穿着白色外套的年轻女子走了进来。"}},{"pos":"ADV 副词","cn":"不久以后；很快；马上","en":"If you say that something will happen presently, you mean that it will happen quite soon.","ex":{"en":"'Who's Agnes?' — 'You'll be meeting her presently.'","cn":"“谁是阿格尼丝？”——“你很快就会见到她。”"}}]},"examples":[{"en":"Presently, the door opened again and three men stepped out.","cn":"不久，门又打开了，走出来三个人。"},{"en":"The crime is presently being investigated by the police.","cn":"警方目前正在调查这起案件。"}]},"prophetic":{"media":{"uk":"media/uk/prophetic__gb_1.mp3","us":"media/us/prophetic__us_1.mp3"},"oxford":{"phon":"prəˈfetɪk","pos":"adjective","senses":[{"en":"correctly stating or showing what will happen in the future","cn":"正确预言的；有预见的","ex":{"en":"Many of his warnings proved prophetic.","cn":"他的许多警告都证明是有先见之明的。"}},{"en":"like or connected with a prophet or prophets","cn":"预言家的；像预言家的；似先知的","ex":{"en":"the prophetic books of the Old Testament","cn":"《旧约圣经·先知书》"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"预言（性）的；预示的","en":"If something was prophetic, it described or suggested something that did actually happen later.","ex":{"en":"This ominous warning soon proved prophetic","cn":"这个不祥的警告很快证明是有预见性的。"}},{"pos":"ADJ 形容词","cn":"预言的；先知的；预言者的","en":"Prophetic means related to a prophecy or a prophet.","ex":{"en":"...a charming romance intermingled with scientific fact and prophetic vision.","cn":"融科学事实和先知远见于其中的一个动人浪漫故事"}}]},"examples":[{"en":"Many of his warnings proved prophetic.","cn":"他的许多警告都证明是有先见之明的。"},{"en":"the prophetic books of the Old Testament 《〈","cn":"圣经〉旧约》先知书"}]},"providing":{"media":{"uk":"media/uk/providing__gb_1.mp3","us":"media/us/providing__us_1.mp3"},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"如果；假如；只要","en":"If you say that something will happen providing or providing that something else happens, you mean that the first thing will happen only if the second thing also happens.","ex":{"en":"I do believe in people being able to do what they want to do, providing they're not hurting someone else","cn":"我真的认为人们只要不伤害别人，自己想做什么就可以做什么。"}}]},"examples":[{"en":"You can borrow the car, providing I can have it back by six o'clock.","cn":"你可以借用我的车﹐只要6点钟以前还给我就行。"}],"oxford":{"phon":"prəˈvaɪdɪŋ","pos":"conjunction","senses":[{"en":"used to say what must happen or be done to make it possible for something else to happen","cn":"如果；假如；在…条件下","ex":{"en":"We'll buy everything you produce, providing of course the price is right.","cn":"我们会购买你们生产的所有东西，当然前提是价格合适。"}}]},"base":"provide"},"practicing":{"lemma":"practice"},"profoundly":{"oxford":{"phon":"prəˈfaʊndli","pos":"adverb","senses":[{"en":"in a way that has a very great effect on somebody/something","cn":"极大地；深刻地","ex":{"en":"a profoundly disturbing programme","cn":"令人深感不安的节目"}},{"en":"very seriously; completely","cn":"严重地；完全地；彻底地","lab":"medical","ex":{"en":"profoundly deaf","cn":"完全失聪"}}]},"media":{"uk":"media/uk/profoundly__gb_1.mp3","us":"media/us/profoundly__us_1.mp3"},"examples":[{"en":"We are profoundly affected by what happens to us in childhood.","cn":"童年发生的事深深地影响着我们。"},{"en":"profoundly deaf","cn":"完全失聪"}]},"prescient":{"media":{"uk":"media/uk/prescient__gb_1.mp3","us":"media/us/prescient__us_1.mp3"},"oxford":{"phon":"ˈpresiənt","pos":"adjective","senses":[{"en":"knowing or appearing to know about things before they happen","cn":"预知的；先觉的","ex":{"en":"prescient warnings","cn":"有先见之明的警告"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"预知的；预见性的；能预见未来的","en":"If you say that someone or something was prescient, you mean that they were able to know or predict what was going to happen in the future.","ex":{"en":"...'Bob Roberts', an eerily prescient comedy about a populist multimillionaire political candidate.","cn":"《天生赢家》，一部关于一位拥有数千万家财的平民党政治候选人的怪诞预言性喜剧"}}]}},"province":{"media":{"uk":"media/uk/province__gb_1.mp3","us":"media/us/province__us_1.mp3"},"oxford":{"phon":"ˈprɒvɪns","pos":"noun","senses":[{"en":"one of the areas that some countries are divided into with its own local government","cn":"省份；（某些国家的）一级行政区","g":"[countable]","ex":{"en":"the provinces of Canada","cn":"加拿大各省"}},{"en":"all the parts of a country except the capital city","cn":"首都以外的地区；外省；外地","g":"[plural]","ex":{"en":"The show will tour the provinces after it closes in London.","cn":"伦敦的演出结束后，将到全国各地巡回演出。"}},{"en":"a person’s particular area of knowledge, interest or responsibility","cn":"知识（或兴趣、职责）范围；领域","g":"[singular]","lab":"formal","ex":{"en":"Such decisions are normally the province of higher management.","cn":"这类决定一般属于高层管理的职责范围。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"省","en":"A province is a large section of a country which has its own administration.","ex":{"en":"...the Algarve, Portugal's southernmost province.","cn":"阿尔加维， 葡萄牙最南部的省份"}},{"pos":"N-PLURAL 复数名词","cn":"外省（首都以外的地区）","en":"The provinces are all the parts of a country except the part where the capital is situated.","ex":{"en":"The government plans to transfer some 30,000 government jobs from Paris to the provinces.","cn":"政府计划将3万个左右的政府职位从巴黎转移到外省。"}},{"pos":"N-SING 单数名词","cn":"（兴趣、知识、责任的）范围，领域","en":"If you say that a subject or activity is a particular person's province, you mean that this person has a special interest in it, a special knowledge of it, or a special responsibility for it.","ex":{"en":"Arvo avoided committing himself. 'I'm afraid that's not my province,' he replied","cn":"阿尔沃不想作出承诺，“恐怕那不归我管，”他回答说。"}}]},"examples":[{"en":"The show will tour the provinces after it closes in London.","cn":"伦敦的演出结束后，将到全国各地巡回演出。"},{"en":"Such decisions are normally the province of higher management.","cn":"这类决定一般属于高层管理的职责范围。"}]},"precipice":{"media":{"uk":"media/uk/precipice__gb_1.mp3","us":"media/us/precipice__us_1.mp3"},"oxford":{"phon":"ˈpresəpɪs","pos":"noun","senses":[{"en":"a very steep side of a high cliff, mountain or rock","cn":"悬崖；峭壁","lab":"figurative","ex":{"en":"The country was now on the edge of a precipice (= very close to disaster).","cn":"这个国家现在岌岌可危。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"悬崖；峭壁","en":"A precipice is a very steep cliff on a mountain."},{"pos":"N-COUNT 可数名词","cn":"险境；危局；绝境","en":"If you say that someone is on the edge of a precipice, you mean that they are in a dangerous situation in which they are extremely close to disaster or failure.","ex":{"en":"I was beginning to admit to myself that our marriage was rolling toward the edge of a precipice","cn":"我内心开始承认我们的婚姻正走向危险的边缘。"}}]},"examples":[{"en":"( figurative ) The country was now on the edge of a precipice (= very close to disaster).","cn":"这个国家现在情势岌岌可危。"},{"en":"A loose rock tumbled over the precipice.","cn":"一块松动的岩石从悬崖上滚落下来。"}]},"prayer":{"media":{"uk":"media/uk/prayer__gb_1.mp3","us":"media/us/prayer__us_1.mp3"},"oxford":{"phon":"preə(r)","pos":"noun","senses":[{"en":"words that you say to God giving thanks or asking for help","cn":"祷告，祈祷（的内容）","g":"[countable]","lab":"North American English","ex":{"en":"to say your prayers","cn":"祷告"}},{"en":"a fixed form of words that you can say when you speak to God","cn":"祈祷文；经文","g":"[countable]","ex":{"en":"It was a prayer she had learnt as a child.","cn":"这是她儿时就学会了的祈祷文。"}},{"en":"the act or habit of praying","cn":"祷告，祈祷（的行为）","g":"[uncountable]","ex":{"en":"They knelt in prayer.","cn":"他们跪下祈祷。"}},{"en":"a religious meeting that takes place regularly in which people say prayers","cn":"祈祷会；祷告式","g":"[plural]","ex":{"en":"Muslims attend Friday prayers at the mosque.","cn":"穆斯林在清真寺做星期五祈祷。"}},{"en":"a thing that you hope for very much","cn":"企盼的事；祈望","g":"[countable, usually singular]","ex":{"en":"My prayer is that one day he will walk again.","cn":"我的企盼就是有一天他能重新走路。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"祈祷；祷告","en":"Prayer is the activity of speaking to God.","ex":{"en":"They had joined a religious order and dedicated their lives to prayer and good works","cn":"他们已加入一个宗教团体，终生都将祈祷和行善。"}},{"pos":"N-COUNT 可数名词","cn":"祈祷文；祷词","en":"A prayer is the words a person says when they speak to God.","ex":{"en":"They should take a little time and say a prayer for the people on both sides.","cn":"他们应该花点时间，为双方的人祈祷。"}},{"pos":"N-COUNT 可数名词","cn":"祈求的事；祈望","en":"You can refer to a strong hope that you have as your prayer .","ex":{"en":"This drug could be the answer to our prayers.","cn":"这种药或许可以满足我们的祈望。"}},{"pos":"N-PLURAL 复数名词","cn":"祈祷仪式","en":"A short religious service at which people gather to pray can be referred to as prayers .","ex":{"en":"He promised that the boy would be back at school in time for evening prayers.","cn":"他保证男孩会及时回到学校参加晚祈祷。"}},{"pos":"PHRASE 短语","cn":"不可能成功","en":"If you say that someone hasn't got a prayer, you mean that it is impossible for them to succeed in what they are trying to do.","ex":{"en":"She'd been caught from behind and hadn't a prayer of freeing herself.","cn":"有人从后面抓住她，她不可能脱身。"}}]},"examples":[{"en":"He arrived at that very moment, as if in answer to her prayer.","cn":"他就在那一刻到了，好像是她的祈祷应验了。"},{"en":"Their prayers were answered and the child was found safe and well.","cn":"他们的祷告应验了：小孩找到了，安然无恙。"}]},"pricing":{"media":{"uk":"media/uk/pricing__gb_1.mp3","us":"media/us/pricing__us_1.mp3"},"oxford":{"phon":"ˈpraɪsɪŋ","pos":"noun","senses":[{"en":"the act of deciding how much to charge for something","cn":"定价；作价；计价","ex":{"en":"competitive pricing","cn":"有竞争力的定价"}}]},"examples":[{"en":"competitive pricing","cn":"有竞争力的定价"},{"en":"pricing policy","cn":"定价政策"}],"base":"price"},"prophets":{"lemma":"prophet","media":{"uk":"media/ldoce/hwd/bre/1/p028-000010037.mp3","us":"media/ldoce/hwd/ame/1/p028-000010037.mp3"}},"press":{"media":{"img":["media/pic/crushing_kitchenutensils_comp.jpg","media/thumb/garlicpress.jpg"],"uk":"media/uk/press__gb_1.mp3","us":"media/us/press__us_1.mp3"},"oxford":{"phon":"pres","pos":"noun","senses":[{"en":"newspapers and magazines","cn":"报章杂志；报刊；平面媒体","g":"[singular + singular or plural verb]","sc":"newspapers","ex":{"en":"the local/national/foreign press","cn":"地方／全国／外国报刊"}},{"en":"the journalists and photographers who work for newspapers and magazines","cn":"记者；新闻工作者；新闻界","g":"[singular + singular or plural verb]","sc":"newspapers","ex":{"en":"The Press was/were not allowed to attend the trial.","cn":"庭审谢绝新闻采访。"}},{"en":"the type or amount of reports that newspapers write about somebody/something","cn":"报道；评论","g":"[singular, uncountable]","sc":"newspapers","ex":{"en":"The airline has had a bad press recently (= journalists have written unpleasant things about it).","cn":"这家航空公司最近受到新闻界的责难。"}},{"en":"a machine for printing books, newspapers, etc.; the process of printing them","cn":"印刷机；印刷","g":"[countable, uncountable]","sc":"publishing/printing","ex":{"en":"We were able to watch the books rolling off the presses.","cn":"我们可以看到书本从印刷机上源源不断地印出。"}},{"en":"a business that prints and publishes books","cn":"出版社；印刷所","g":"[countable]","sc":"publishing/printing","ex":{"en":"Oxford University Press","cn":"牛津大学出版社"}},{"en":"a piece of equipment that is used for creating pressure on things, to make them flat or to get liquid from them","cn":"压平机；压榨机；榨汁机","g":"[countable]","sc":"equipment for pressing","ex":{"en":"a trouser press","cn":"烫裤机"}},{"en":"an act of pushing something with your hand or with a tool that you are holding","cn":"挤压；推；按","g":"[countable, usually singular]","sc":"act of pushing","ex":{"en":"He gave the bell another press.","cn":"他又按了一下铃。"}},{"en":"a large number of people or things competing for space or movement","cn":"拥挤的人群（或大批事物）","g":"[singular]","sc":"crowd","ex":{"en":"the press of bodies all moving the same way","cn":"拥向同一方向的人群"}},{"en":"a large cupboard, usually with shelves, for holding clothes, books, etc.","cn":"（分层）大壁橱，衣柜，书柜，碗柜","g":"[countable]","lab":"Irish English, Scottish English，，","sc":"cupboard"},{"en":"to push part of a device, etc. in order to make it work","cn":"按，压（使启动）","g":"[transitive, intransitive]","sc":"push","ex":{"en":"to press a button/key","cn":"按下按钮／按键"},"pos":"verb"},{"en":"to push something closely against something; to be pushed in this way","cn":"（被）压，挤，推，施加压力","g":"[transitive, intransitive]","sc":"push","ex":{"en":"She pressed her face against the window.","cn":"她把脸贴在窗子上。"},"pos":"verb"},{"en":"to put something in a place by pushing it","cn":"将…塞进；把…按入","g":"[transitive]","sc":"push","ex":{"en":"He pressed a coin into her hand and moved on.","cn":"他把一枚硬币塞进她手里，然后继续向前走。"},"pos":"verb"},{"en":"to put gentle pressure on somebody’s hand or arm, especially to show care or kind feelings","cn":"握，轻捏（某人的手或臂，以示关心或友好）","g":"[transitive]","sc":"push","ex":{"en":"He gently pressed her arm, then left.","cn":"他轻轻按住她的手臂，然后就离开了。"},"pos":"verb"},{"en":"to move in the direction mentioned by pushing","cn":"（向…）拥挤，推搡着移动","g":"[intransitive]","lab":"figurative","sc":"push","ex":{"en":"The photographers pressed around the royal visitors.","cn":"摄影记者们在王室贵宾周围挤来挤去。"},"pos":"verb"},{"en":"to make strong efforts to persuade or force somebody to do something","cn":"催促；敦促；逼迫","g":"[transitive]","sc":"try to persuade","ex":{"en":"If pressed, he will admit that he knew about the affair.","cn":"如果逼问他，他就会承认对此事知情。"},"pos":"verb"},{"en":"to express or repeat something with force","cn":"坚持；反复强调","g":"[transitive]","sc":"point/claim/case","ex":{"en":"I don't want to press the point, but you do owe me $200.","cn":"我不想老提这一点，但你确实欠我 200 美元。"},"pos":"verb"},{"en":"to make something flat or smooth by using force or putting something heavy on top","cn":"把…压平；压扁","g":"[transitive]","sc":"make flat/smooth","ex":{"en":"pressed flowers (= pressed between the pages of a book)","cn":"夹在书页中间压扁的花"},"pos":"verb"},{"en":"to make clothes smooth using a hot iron","cn":"熨平；烫平","g":"[transitive]","sc":"make flat/smooth","ex":{"en":"My suit needs pressing.","cn":"我的西服该熨了。"},"pos":"verb"},{"en":"to get the juice out of fruit or vegetables by using force or weight","cn":"把…榨汁；压榨","g":"[transitive]","sc":"fruit/vegetables","pos":"verb"},{"en":"to make something from a material, using pressure","cn":"把…压成；压制","g":"[transitive]","sc":"metal","ex":{"en":"to press a CD","cn":"压制一张光盘"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"压；按；挤；推","en":"If you press something somewhere, you push it firmly against something else.","ex":{"en":"He pressed his back against the door","cn":"他后背紧紧靠在门上。"}},{"pos":"VERB 动词","cn":"按，揿（按钮或开关）","en":"If you press a button or switch, you push it with your finger in order to make a machine or device work.","ex":{"en":"Drago pressed a button and the door closed","cn":"德拉戈按了一个按钮，然后门就关上了。"}},{"pos":"VERB 动词","cn":"用力按；用力挤压；用力踩","en":"If you press something or press down on it, you push hard against it with your foot or hand.","ex":{"en":"The engine stalled. He pressed the accelerator hard","cn":"发动机熄火了。他用力踩油门。"}},{"pos":"VERB 动词","cn":"极力要求","en":"If you press for something, you try hard to persuade someone to give it to you or to agree to it.","ex":{"en":"Police might now press for changes in the law","cn":"警方现在可能竭力要求修改法律。"}},{"pos":"VERB 动词","cn":"催促；敦促；竭力劝说","en":"If you press someone, you try hard to persuade them to do something.","ex":{"en":"Trade unions are pressing him to stand firm","cn":"各工会正在竭力劝说他坚定立场。"}},{"pos":"VERB 动词","cn":"坚持；强调","en":"If someone presses their claim, demand, or point, they state it in a very forceful way.","ex":{"en":"The protest campaign has used mass strikes and demonstrations to press its demands","cn":"抗议活动通过大规模罢工和示威游行来向当局提出诉求。"}},{"pos":"VERB 动词","cn":"困扰；严重影响","en":"If an unpleasant feeling or worry presses on you, it affects you very much or you are always thinking about it.","ex":{"en":"The weight of irrational guilt pressed on her","cn":"无端的负罪感压得她喘不过气来。"}},{"pos":"VERB 动词","cn":"硬给；强加于","en":"If you press something on someone, you give it to them and insist that they take it.","ex":{"en":"All I had was money, which I pressed on her reluctant mother","cn":"我就只有钱了，她母亲虽然不愿接受，我还是硬塞给了她。"}},{"pos":"VERB 动词","cn":"熨烫；熨平","en":"If you press clothes, you iron them in order to get rid of the creases.","ex":{"en":"Vera pressed his shirt","cn":"薇拉把他的衬衫熨平了。"}},{"pos":"VERB 动词","cn":"榨取，压榨，挤压（水果或蔬菜）","en":"If you press fruits or vegetables, you squeeze them or crush them, usually in order to extract the juice.","ex":{"en":"The grapes are hand-picked and pressed","cn":"这些葡萄是精心挑选用来榨汁的。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"报纸；报刊","en":"Newspapers are referred to as the press .","ex":{"en":"Today the British press is full of articles on India's new prime minister","cn":"今天英国的报纸上登满了关于印度新任总理的文章。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"新闻记者","en":"Journalists are referred to as the press .","ex":{"en":"Christie looked relaxed and calm as he faced the press afterwards","cn":"后来面对记者的时候，克里斯蒂显得放松而镇静。"}},{"pos":"N-COUNT 可数名词","cn":"印刷机","en":"A press or a printing press is a machine used for printing things such as books and newspapers.","ex":{"en":"...the invention of the printing press","cn":"印刷机的发明"}},{"pos":"PHRASE 短语","cn":"（尤指在报纸、电视或广播上）受到批评/得到好评","en":"If someone or something gets a bad press, they are criticized, especially in the newspapers, on television, or on radio. If they get a good press, they are praised.","ex":{"en":"...the bad press that career women consistently get in this country","cn":"该国职业女性一直受到的舆论上的苛评"}},{"pos":"PHRASE 短语","cn":"控告；提起诉讼","en":"If you press charges against someone, you make an official accusation against them which has to be decided in a court of law.","ex":{"en":"I could have pressed charges against him","cn":"我本可以起诉他。"}},{"pos":"PHRASE 短语","cn":"付印；开印","en":"When a newspaper or magazine goes to press, it starts being printed.","ex":{"en":"We check prices at the time of going to press","cn":"我们会在付印的时候核对价格。"}},{"pos":"PHRASE 短语","cn":"暂时使用；临时任用","en":"To press someone or something into service means to use them temporarily for a particular purpose.","ex":{"en":"The local bar has been pressed into service as a school","cn":"当地的酒吧被暂时用作学校。"}},{"pos":"","cn":"","en":"相关词组：press ahead press on"}]},"examples":[{"en":"Every type of boat was pressed into service to rescue passengers from the sinking ferry.","cn":"为了营救下沉渡轮上的旅客，各类船只都被临时征用了。"},{"en":"‘Shall we stay here for the night?’ ‘No, let's press on.’ “","cn":"我们今晚在这里住下好吗？” “不，咱们继续走。”"}]},"prominent":{"media":{"uk":"media/uk/prominent__gb_1.mp3","us":"media/us/prominent__us_1.mp3"},"oxford":{"phon":"ˈprɒmɪnənt","pos":"adjective","senses":[{"en":"important or well known","cn":"重要的；著名的；杰出的","ex":{"en":"a prominent politician","cn":"杰出的政治家"}},{"en":"easily seen","cn":"显眼的；显著的；突出的","ex":{"en":"The church tower was a prominent feature in the landscape.","cn":"教堂的尖塔曾经是此地景观的重要特色。"}},{"en":"sticking out from something","cn":"突出的；凸现的","ex":{"en":"a prominent nose","cn":"高鼻子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重要的；杰出的；著名的","en":"Someone who is prominent is important.","ex":{"en":"...a prominent member of the Law Society.","cn":"法律协会的重要成员"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显著的；突出的；鲜艳的；引人注目的","en":"Something that is prominent is very noticeable or is an important part of something else.","ex":{"en":"Here the window plays a prominent part in the design.","cn":"这里窗户在设计中起着非常重要的作用。"}}]},"examples":[{"en":"The church tower was a prominent feature in the landscape.","cn":"教堂的尖塔曾经是此地景观的重要特色。"},{"en":"The photographs were prominently displayed on her desk.","cn":"几张照片摆在她桌子上显眼的位置。"}]},"prospective":{"media":{"uk":"media/uk/prospective__gb_1.mp3","us":"media/us/prospective__us_1.mp3"},"oxford":{"phon":"prəˈspektɪv","pos":"adjective","senses":[{"en":"expected to do something or to become something","cn":"有望的；可能的；预期的；潜在的","ex":{"en":"a prospective buyer","cn":"可能的买主"}},{"en":"expected to happen soon","cn":"即将发生的；行将来临的","ex":{"en":"They are worried about prospective changes in the law.","cn":"他们担心即将修改法律。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"想要成为的；可能成为的","en":"You use prospective to describe someone who wants to be the thing mentioned or who is likely to be the thing mentioned.","ex":{"en":"The story should act as a warning to other prospective buyers","cn":"这篇报道应该对其他潜在的购买者起到警示作用。"}},{"pos":"ADJ 形容词","cn":"可能即将发生的","en":"You use prospective to describe something that is likely to happen soon.","ex":{"en":"...the terms of the prospective deal.","cn":"可能达成的交易的条款"}}]},"examples":[{"en":"They are worried about prospective changes in the law.","cn":"他们担心即将修改法律。"},{"en":"a prospective buyer","cn":"可能的买主"}]},"profound":{"media":{"uk":"media/uk/profound__gb_1.mp3","us":"media/us/profound__us_1.mp3"},"oxford":{"phon":"prəˈfaʊnd","pos":"adjective","senses":[{"en":"very great; felt or experienced very strongly","cn":"巨大的；深切的；深远的","ex":{"en":"profound changes in the earth’s climate","cn":"地球气候的巨大变化"}},{"en":"showing great knowledge or understanding","cn":"知识渊博的；理解深刻的；深邃的","ex":{"en":"profound insights","cn":"精辟的见解"}},{"en":"needing a lot of study or thought","cn":"艰深的；玄奥的","ex":{"en":"profound questions about life and death","cn":"生死方面的玄奥问题"}},{"en":"very serious; complete","cn":"严重的；完全的；彻底的","lab":"medical","ex":{"en":"profound disability","cn":"严重残疾"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"深刻的；强烈的；巨大的","en":"You use profound to emphasize that something is very great or intense.","ex":{"en":"...discoveries which had a profound effect on many areas of medicine.","cn":"对很多医学领域产生了深刻影响的发现"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"深刻的；深奥的；知识渊博的","en":"A profound idea, work, or person shows great intellectual depth and understanding.","ex":{"en":"This is a book full of profound, original and challenging insights.","cn":"这本书充满了深刻、新颖、令人深思的见解。"}}]},"examples":[{"en":"My father's death had a profound effect on us all.","cn":"父亲的去世深深地影响了我们全家。"},{"en":"profound changes in the earth's climate","cn":"地球气候的巨大变化"}]},"protect":{"media":{"uk":"media/uk/protect__gb_1.mp3","us":"media/us/protect__us_1.mp3"},"oxford":{"phon":"prəˈtekt","pos":"verb","senses":[{"en":"to make sure that somebody/something is not harmed, injured, damaged, etc.","cn":"保护；防护","g":"[transitive, intransitive]","ex":{"en":"to protect children/citizens/civilians/consumers/workers","cn":"保护儿童／公民／平民／消费者／工人"}},{"en":"to introduce laws that make it illegal to kill, harm or damage a particular animal, area of land, building, etc.","cn":"（制定法律）保护","g":"[transitive, usually passive]","ex":{"en":"a protected area/species","cn":"受保护的地区／物种"}},{"en":"to help an industry in your own country by taxing goods from other countries so that there is less competition","cn":"（通过征关税）保护（国内企业）；实行贸易保护","g":"[transitive, usually passive]","ex":{"en":"protected markets","cn":"受保护的市场"}},{"en":"to provide somebody/something with insurance against fire, injury, damage, etc.","cn":"投保；为…买保险","g":"[transitive, intransitive]","ex":{"en":"Many policies do not protect you against personal injury.","cn":"许多保单都不保障人身伤害。"}},{"en":"to limit access to data, a web page, etc., for example by using passwords or encryption (= special codes)","cn":"保护（数据、网页等）","g":"[transitive]","lab":"computing","ex":{"en":"Security products are designed to protect information from unauthorized access.","cn":"安保产品的设计旨在保护信息免遭非法进入。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"保护；防护","en":"To protect someone or something means to prevent them from being harmed or damaged.","ex":{"en":"So, what can women do to protect themselves from heart disease?","cn":"那么，女性怎样做才能使自己不得心脏病呢？"}},{"pos":"VERB 动词","cn":"（保险单）为…提供保险","en":"If an insurance policy protects you against an event such as death, injury, fire, or theft, the insurance company will give you or your family money if that event happens.","ex":{"en":"Many manufacturers have policies to protect themselves against blackmailers.","cn":"许多厂家都购买了保险，以防遭到敲诈。"}}]},"examples":[{"en":"Troops have been sent to protect aid workers against attack.","cn":"已经派出部队保护援助工作人员免遭袭击。"},{"en":"Each company is fighting to protect its own commercial interests.","cn":"每家公司都在奋力保护自己的商业利益。"}]},"priority":{"media":{"uk":"media/uk/priority__gb_1.mp3","us":"media/us/priority__us_1.mp3"},"oxford":{"phon":"praɪˈɒrəti","pos":"noun","senses":[{"en":"something that you think is more important than other things and should be dealt with first","cn":"优先事项；最重要的事；首要事情","g":"[countable]","lab":"North American English","ex":{"en":"a high/low priority","cn":"重点／非重点项目"}},{"en":"the most important place among various things that have to be done or among a group of people","cn":"优先；优先权；重点","g":"[uncountable]","ex":{"en":"Club members will be given priority.","cn":"俱乐部成员享有优先权。"}},{"en":"the right of a vehicle to go before other traffic at a particular place on a road","cn":"（车辆的）优先通行权","g":"[uncountable]","lab":"British English","ex":{"en":"Buses have priority at this junction.","cn":"在这个路口，公共汽车有优先通行权。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"优先事项；最重要的事；当务之急","en":"If something is a priority, it is the most important thing you have to do or deal with, or must be done or dealt with before everything else you have to do.","ex":{"en":"Being a parent is her first priority","cn":"做好母亲是她的头等大事。"}},{"pos":"PHRASE 短语","cn":"优先考虑；给…优先权","en":"If you give priority to something or someone, you treat them as more important than anything or anyone else.","ex":{"en":"The school will give priority to science, maths and modern languages","cn":"学校将重点发展理科、数学和现代语言。"}},{"pos":"PHRASE 短语","cn":"优先于；比…重要","en":"If something takes priority or has priority over other things, it is regarded as being more important than them and is dealt with first.","ex":{"en":"The fight against inflation took priority over measures to combat the deepening recession","cn":"抵制通货膨胀比抑制日益加剧的经济衰退更为重要。"}}]},"examples":[{"en":"Priority cases, such as homeless families, get dealt with first.","cn":"优先事项，比如无家可归家庭的问题，得到优先处理。"},{"en":"Financial security was high on his list of priorities.","cn":"在他的心目中，财政稳固是十分重要的一环。"}]},"productivity":{"media":{"uk":"media/uk/productivity__gb_1.mp3","us":"media/us/productivity__us_1.mp3"},"oxford":{"phon":"ˌprɒdʌkˈtɪvəti","pos":"noun","senses":[{"en":"the rate at which a worker, a company or a country produces goods, and the amount produced, compared with how much time, work and money is needed to produce them","cn":"生产率；生产效率","ex":{"en":"high/improved/increased productivity","cn":"高的／提高了的／增长了的生产率"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"生产力；生产率；生产能力","en":"Productivity is the rate at which goods are produced.","ex":{"en":"The third-quarter results reflect continued improvements in productivity","cn":"第三季度的结果表明生产率持续上升。"}}]},"examples":[{"en":"Wage rates depend on levels of productivity.","cn":"工资水平取决于生产量的多寡。"},{"en":"high/improved/increased productivity","cn":"高的/提高了的/增长了的生产率"}]},"pretended":{"lemma":"pretend","media":{"uk":"media/ldoce/hwd/bre/c/pretended0205.mp3","us":"media/ldoce/hwd/ame/f/pretended.mp3"}},"prevents":{"lemma":"prevent","media":{"uk":"media/uk/prevent__gb_1.mp3","us":"media/us/prevent__us_1.mp3"}},"practised":{"oxford":{"phon":"ˈpræktɪst","pos":"adjective","senses":[{"en":"good at doing something because you have been doing it regularly","cn":"熟练的；老到的；内行的","ex":{"en":"She's only 18 but she's already a practised composer.","cn":"她才 18 岁，但已成了老练的作曲家。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"老道的；经验丰富的；内行的；熟练的","en":"Someone who is practised at doing something is good at it because they have had experience and have developed their skill at it.","ex":{"en":"Once you are practised at this sort of relaxation you will feel quite refreshed afterwards.","cn":"一旦你熟悉了这种放松方式，在放松之后就会感到神清气爽。"}}]},"media":{"uk":"media/uk/practised__gb_1.mp3","us":"media/us/practised__us_1.mp3"},"examples":[{"en":"She's only 18 but she's already a practised composer.","cn":"她才 18 岁，但已成了老练的作曲家。"},{"en":"He has good ideas but he isn't practised in the art of marketing.","cn":"他有好的构想，但推销技巧却嫌生嫩。"}],"base":"practise"},"presses":{"lemma":"press","media":{"img":["media/pic/crushing_kitchenutensils_comp.jpg","media/thumb/garlicpress.jpg","media/pic/squeeze_comp.jpg"],"uk":"media/uk/press__gb_1.mp3","us":"media/us/press__us_1.mp3"}},"prophet":{"oxford":{"phon":"ˈprɒfɪt","pos":"noun","senses":[{"en":"(in the Christian, Jewish and Muslim religions) a person sent by God to teach the people and give them messages from God","cn":"（基督教、犹太教和伊斯兰教的）先知","g":"[countable]","ex":{"en":"Some believe that he was not a true prophet.","cn":"有人认为他不是真正的预言家。"}},{"en":"Muhammad, through whom the Koran was revealed and the religion of Islam established and completed","cn":"先知穆罕默德（伊斯兰教的创始人）","g":"[singular]"},{"en":"a person who claims to know what will happen in the future","cn":"预言家；预言者","g":"[countable]"},{"en":"a person who teaches or supports a new idea, theory, etc.","cn":"倡导者；拥护者；鼓吹者","g":"[countable]","ex":{"en":"William Morris was one of the early prophets of socialism.","cn":"威廉·莫里斯是社会主义的早期传播者之一。"}},{"en":"the name used for some books of the Old Testament and the Hebrew Bible","cn":"（《旧约圣经》和《希伯来圣经》中的）先知书","g":"[plural]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"先知","en":"A prophet is a person who is believed to be chosen by God to say the things that God wants to tell people.","ex":{"en":"...the sacred name of the Holy Prophet of Islam.","cn":"伊斯兰先知的圣名"}},{"pos":"N-COUNT 可数名词","cn":"预言者；预言家","en":"A prophet is someone who predicts that something will happen in the future.","ex":{"en":"I promised myself I'd defy all the prophets of doom and battle back to fitness.","cn":"我发誓要打破所有的死亡预言，力争恢复健康。"}}]},"media":{"uk":"media/uk/prophet__gb_1.mp3","us":"media/us/prophet__us_1.mp3"},"examples":[{"en":"William Morris was one of the early prophets of socialism.","cn":"威廉 · 莫里斯是社会主义的早期传播者之一。"},{"en":"Gandhi was the prophet of non-violent protest.","cn":"甘地是非暴力抗议的倡导者。"}]},"prove":{"media":{"uk":"media/uk/prove__gb_1.mp3","us":"media/us/prove__us_1.mp3"},"oxford":{"phon":"pruːv","pos":"verb","senses":[{"en":"to use facts, evidence, etc. to show that something is true","cn":"证明；证实","g":"[transitive]","sc":"show something is true","ex":{"en":"They hope this new evidence will prove her innocence.","cn":"他们希望这一新证据能证明她无罪。"}},{"en":"if something proves dangerous, expensive, etc. or if it proves to be dangerous, etc., you discover that it is dangerous, etc. over a period of time","cn":"后来被发现是；最终显现为","sc":"be","ex":{"en":"The strategy has proved successful.","cn":"已经证明这个战略是成功的。"}},{"en":"to show other people how good you are at doing something or that you are capable of doing something","cn":"展现，展示，显示（自己的才能）","g":"[transitive]","sc":"yourself","ex":{"en":"He constantly feels he has to prove himself to others.","cn":"他时常觉得自己必须向人一展身手。"}},{"en":"to show other people that you are a particular type of person or that you have a particular quality","cn":"显示（自己）是；向人证明（自己）是","g":"[transitive]","sc":"yourself","ex":{"en":"He proved himself determined to succeed.","cn":"他向人证明了自己不达目的不罢休。"}},{"en":"to swell (= become larger or rounder) before being baked because of the action of yeast; to leave bread dough to prove","cn":"发酵","g":"[intransitive, transitive]","sc":"of bread","ex":{"en":"While the dough is proving, crumble the feta and chop the olives.","cn":"当面团发酵时，将羊乳酪弄碎并切碎橄榄。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"证明是；原来是；结果是","en":"If something proves to be true or to have a particular quality, it becomes clear after a period of time that it is true or has that quality.","ex":{"en":"We have been accused of exaggerating before, but unfortunately all our reports proved to be true","cn":"以前一直有人指责我们夸大事实，但遗憾的是，我们所有的报道都证明是真实的。"}},{"pos":"VERB 动词","cn":"证明；证实","en":"If you prove that something is true, you show by means of argument or evidence that it is definitely true.","ex":{"en":"You brought this charge. You prove it!","cn":"你提出了这项控告。你拿出证据来！"}},{"pos":"VERB 动词","cn":"证明；显示","en":"If you prove yourself to have a certain good quality, you show by your actions that you have it.","ex":{"en":"Margaret proved herself to be a good mother","cn":"玛格丽特证明了自己是个好妈妈。"}},{"pos":"PHRASE 短语","cn":"证明自己的能力（或知识）","en":"If you prove a point, you show other people that you know something or can do something, although your action may have no other purpose.","ex":{"en":"They made a 3,000 mile detour simply to prove a point.","cn":"他们绕行3,000英里只是为了证明自己能够做到。"}}]},"examples":[{"en":"In this country, you are innocent until proved guilty.","cn":"在这个国家，一个人在被证明有罪之前是清白的。"},{"en":"The promotion proved to be a turning point in his career.","cn":"这次提升最后成了他职业生涯的一个转折点。"}]},"president":{"media":{"uk":"media/uk/president__gb_1.mp3","us":"media/us/president__us_1.mp3"},"oxford":{"phon":"ˈprezɪdənt","pos":"noun","senses":[{"en":"the leader of a republic, for example the US","cn":"总统；国家主席","lab":"especially North American English","ex":{"en":"Several presidents attended the funeral.","cn":"好几位总统参加了葬礼。"}},{"en":"the person in charge of some organizations, clubs, colleges, etc.","cn":"（机构、俱乐部、学院等的）会长，院长，主席","ex":{"en":"to be made president of the students’ union","cn":"当选学生会主席"}},{"en":"the person in charge of a bank or a commercial organization","cn":"银行行长；总经理；董事长；总裁","lab":"especially North American English","ex":{"en":"the bank president","cn":"银行行长"}}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"总统；国家主席","en":"The president of a country that has no king or queen is the person who is the head of state of that country.","ex":{"en":"...President Mubarak","cn":"穆巴拉克总统"}},{"pos":"N-COUNT 可数名词","cn":"院长；校长；会长；总裁；董事长","en":"The president of an organization is the person who has the highest position in it.","ex":{"en":"Research and marketing operations will be Mr. Furlaud's job as president of the new company.","cn":"作为新公司的总裁，弗劳德先生将负责调研和市场运作。"}}]},"examples":[{"en":"President Obama is due to visit the country next month.","cn":"奥巴马总统定于下月访问该国。"},{"en":"Several presidents attended the funeral.","cn":"好几位总统参加了葬礼。"}]},"primitive":{"media":{"uk":"media/uk/primitive__gb_1.mp3","us":"media/us/primitive__us_1.mp3"},"oxford":{"phon":"ˈprɪmətɪv","pos":"adjective","senses":[{"en":"belonging to a very simple society with no industry, etc.","cn":"原始的；远古的","g":"[usually before noun]","ex":{"en":"a primitive society","cn":"原始社会"}},{"en":"belonging to an early stage in the development of humans or animals","cn":"原始的；（人类或动物）发展早期的","g":"[usually before noun]","ex":{"en":"primitive man","cn":"原始人"}},{"en":"very simple and old-fashioned, especially when something is also not convenient and comfortable","cn":"简陋的；落后的；发展水平低的","ex":{"en":"The methods of communication used during the war were primitive by today's standards.","cn":"按今天的标准，大战时期使用的通信方法非常落后。"}},{"en":"very strong and not based on reason, as if from the earliest period of human life","cn":"出于原始天性的","g":"[usually before noun]","ex":{"en":"a primitive instinct","cn":"原始本能"}},{"en":"an artist of the period before the Renaissance; an example of work from this period","cn":"文艺复兴前的艺术家（或作品）","pos":"noun"},{"en":"an artist who paints in a very simple style like a child; an example of the work of such an artist","cn":"原始派画家（或作品）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"原始的；远古的；未开化的","en":"Primitive means belonging to a society in which people live in a very simple way, usually without industries or a writing system.","ex":{"en":"...studies of primitive societies.","cn":"对原始社会的研究"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动植物）原始的，低等的，进化初期的","en":"Primitive means belonging to a very early period in the development of an animal or plant.","ex":{"en":"...primitive whales","cn":"原始鲸"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古老的；简陋的","en":"If you describe something as primitive, you mean that it is very simple in style or very old-fashioned.","ex":{"en":"The conditions are primitive by any standards","cn":"无论用什么标准来衡量，其条件都很简陋。"}}]},"examples":[{"en":"The methods of communication used during the war were primitive by today's standards.","cn":"按今天的标准，大战时期使用的通讯方法非常落后。"},{"en":"The facilities on the campsite were very primitive.","cn":"营地的设施非常简陋。"}]},"protective":{"media":{"uk":"media/uk/protective__gb_1.mp3","us":"media/us/protective__us_1.mp3"},"oxford":{"phon":"prəˈtektɪv","pos":"adjective","senses":[{"en":"providing or intended to provide protection","cn":"保护的；防护的","g":"[only before noun]","ex":{"en":"Workers should wear full protective clothing.","cn":"工人应该穿着全套防护服。"}},{"en":"having or showing a wish to protect somebody/something","cn":"出于（对…的）保护","ex":{"en":"He put a protective arm around her shoulders.","cn":"他呵护地用胳膊搂住她的肩膀。"}},{"en":"intended to give an advantage to your own country’s industry","cn":"贸易保护的；实行关税保护的","ex":{"en":"protective tariffs","cn":"保护性关税"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"保护的；防护的","en":"Protective means designed or intended to protect something or someone from harm.","ex":{"en":"Protective gloves reduce the absorption of chemicals through the skin","cn":"防护手套可以减少皮肤对化学物质的吸收。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"呵护的；有保护欲的","en":"If someone is protective towards you, they look after you and show a strong desire to keep you safe.","ex":{"en":"He is very protective towards his mother","cn":"他对他的母亲呵护备至。"}}]},"examples":[{"en":"She had been fiercely protective towards him as a teenager.","cn":"他十几岁时，她曾极力呵护他。"},{"en":"He put a protective arm around her shoulders.","cn":"他呵护地用胳膊搂住她的肩膀。"}]},"problem-solving":{"oxford":{"phon":"ˈprɒbləm sɒlvɪŋ","pos":"noun","senses":[{"en":"the act of finding ways of dealing with problems","cn":"寻求答案；解决问题","ex":{"en":"to develop problem-solving skills and strategies","cn":"培养解决问题的技能和策略"}}]},"media":{"uk":"media/uk/problem_solving_1_gb_1.mp3","us":"media/us/problem_solving_1_us_1.mp3"},"examples":[{"en":"tasks that involve problem-solving","cn":"包括解决问题的工作任务"},{"en":"employees with good problem-solving skills","cn":"具备良好解决问题能力的雇员"}]},"protocol":{"media":{"uk":"media/uk/protocol__gb_1.mp3","us":"media/us/protocol__us_1.mp3"},"oxford":{"phon":"ˈprəʊtəkɒl","pos":"noun","senses":[{"en":"a system of fixed rules and formal behaviour used at official meetings, usually between governments","cn":"礼仪；外交礼节","g":"[uncountable]","ex":{"en":"a breach of protocol","cn":"违反外交礼节"}},{"en":"the first or original version of an agreement, especially a treaty between countries, etc.; an extra part added to an agreement or treaty","cn":"条约草案；议定书；（协议或条约的）附件","g":"[countable]","lab":"specialist","ex":{"en":"the first Geneva Protocol","cn":"《日内瓦四公约》第一议定书"}},{"en":"a set of rules that control the way data is sent between computers","cn":"（数据传输的）协议","g":"[countable]","lab":"computing"},{"en":"a plan for performing a scientific experiment or medical treatment","cn":"科学实验计划；医疗方案","g":"[countable]","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"礼仪；社交礼节","en":"Protocol is a system of rules about the correct way to act in formal situations.","ex":{"en":"He has become something of a stickler for the finer observances of royal protocol.","cn":"他已经变得非常刻板，哪怕是最细微的皇室礼仪也会遵循。"}},{"pos":"N-COUNT 可数名词","cn":"（信息交换）协议","en":"A protocol is a set of rules for exchanging information between computers."},{"pos":"N-COUNT 可数名词","cn":"议定书；协议","en":"A protocol is a written record of a treaty or agreement that has been made by two or more countries.","ex":{"en":"...the Montreal Protocol to phase out use and production of CFCs","cn":"逐步停止使用及生产含氯氟烃的《蒙特利尔议定书》"}},{"pos":"N-COUNT 可数名词","cn":"治疗方案；科学实验计划","en":"A protocol is a plan for a course of medical treatment, or a plan for a scientific experiment.","ex":{"en":"...the detoxification protocol.","cn":"戒毒方案"}}]},"examples":[{"en":"It is set out in a legally binding protocol which forms part of the treaty.","cn":"这在有法律约束力的、属于条约一部分的附件中有说明。"},{"en":"the first Geneva Protocol 《","cn":"日内瓦四公约》第一议定书"}]},"preserve":{"oxford":{"phon":"prɪˈzɜːv","pos":"verb","senses":[{"en":"to keep a particular quality, feature, etc.; to make sure that something is kept","cn":"保护；维护；保留","ex":{"en":"He was anxious to preserve his reputation.","cn":"他急于维护自己的名声。"}},{"en":"to keep something in its original state in good condition","cn":"维持…的原状；保存；保养","g":"[often passive]","lab":"humorous","ex":{"en":"a perfectly preserved 14th century house","cn":"保存完好的 14 世纪宅第"}},{"en":"to prevent something, especially food, from decaying (= being destroyed by natural processes) by treating it in a particular way","cn":"防止…腐坏；保鲜","ex":{"en":"Wax polish preserves wood and leather.","cn":"上光蜡可保护木材和皮革。"}},{"en":"to keep somebody/something alive, or safe from harm or danger","cn":"使继续存活；保护；保全","ex":{"en":"The society was set up to preserve endangered species from extinction.","cn":"成立这个协会是为了保护濒危物种不致灭绝。"}},{"en":"an activity, a job, an interest, etc. that is thought to be suitable for one particular person or group of people","cn":"（某人或群体活动、工作等的）专门领域","g":"[singular]","ex":{"en":"Football is no longer the preserve of men.","cn":"足球再也不是男人的专利了。"},"pos":"noun"},{"en":"a type of jam made by boiling fruit with a large amount of sugar","cn":"果酱","g":"[countable, usually plural, uncountable]","pos":"noun"},{"en":"a type of pickle made by cooking vegetables with salt or vinegar","cn":"腌菜；泡菜","g":"[countable, usually plural, uncountable]","lab":"especially British English","pos":"noun"},{"en":"a piece of land that is a protected area for animals, plants, etc.","cn":"（动植物）保护区；自然保护区","g":"[countable]","lab":"North American English","pos":"noun"},{"en":"an area of private land or water where animals and fish are kept for people to hunt","cn":"私人渔猎场（或保留地）","g":"[countable]","ex":{"en":"This land is protected as a wildlife preserve.","cn":"这片土地作为野生动物保护区而得到保护。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"保持，维持（原状）","en":"If you preserve a situation or condition, you make sure that it remains as it is, and does not change or end.","ex":{"en":"We will do everything to preserve peace.","cn":"我们会尽全力维持和平。"}},{"pos":"VERB 动词","cn":"保护；保存；维护","en":"If you preserve something, you take action to save it or protect it from damage or decay.","ex":{"en":"We need to preserve the forest","cn":"我们需要保护森林。"}},{"pos":"VERB 动词","cn":"保存，腌制（食物）","en":"If you preserve food, you treat it in order to prevent it from decaying so that you can store it for a long time.","ex":{"en":"I like to make puree, using only enough sugar to preserve the plums.","cn":"我喜欢做果泥，只需要用一点糖把李子腌一下。"}},{"pos":"N-PLURAL 复数名词","cn":"蜜饯；果酱","en":"Preserves are foods such as jam that are made by cooking fruit with a large amount of sugar so that they can be stored for a long time."},{"pos":"N-COUNT 可数名词","cn":"专属工作；独占的活动领域","en":"If you say that a job or activity is the preserve of a particular person or group of people, you mean that they are the only ones who take part in it.","ex":{"en":"The conduct of foreign policy is largely the preserve of the president","cn":"外交政策事宜主要由总统专门负责。"}},{"pos":"N-COUNT 可数名词","cn":"保护区","en":"A nature preserve is an area of land or water where animals are protected from hunters.","ex":{"en":"...Pantanal, one of the world's great wildlife preserves.","cn":"潘塔纳尔，世界上最大的野生动物保护区之一"}}]},"media":{"uk":"media/uk/preserve__gb_1.mp3","us":"media/us/preserve__us_1.mp3"},"examples":[{"en":"The society was set up to preserve endangered species from extinction.","cn":"成立这个协会是为了保护濒危物种不致灭绝。"},{"en":"( humorous ) Is he really 60? He's remarkably well preserved.","cn":"他真有 60 岁了吗？他真会保养啊。"}]},"preaching":{"oxford":{"phon":"priːtʃ","pos":"verb","senses":[{"en":"to give a religious talk in a public place, especially in a church during a service","cn":"布道，讲道（尤指教堂中礼拜时）"},{"en":"to tell people about a particular religion, way of life, system, etc. in order to persuade them to accept it","cn":"宣传，宣扬，宣讲（教义、生活方式、体制等）"}]}},"promoted":{"lemma":"promote"},"promised":{"lemma":"promise"},"provoked":{"lemma":"provoke"},"protecting":{"lemma":"protect"},"privileges":{"lemma":"privilege"},"proclaims":{"lemma":"proclaim"},"procedures":{"lemma":"procedure"},"projects":{"lemma":"project"},"practices":{"lemma":"practice"},"printers":{"lemma":"printer"},"proclamations":{"lemma":"proclamation"},"priorities":{"lemma":"priority"},"prefers":{"lemma":"prefer"},"problems":{"lemma":"problem"},"preferred":{"lemma":"prefer"},"presidents":{"lemma":"president"},"presents":{"lemma":"present"},"promenading":{"oxford":{"phon":"ˌprɒməˈnɑːd","pos":"noun","senses":[{"en":"( both BrE ) ( becoming old-fashioned ) a public place for walking, usually a wide path beside the sea","cn":"公共散步场所；（常指）滨海步行大道"},{"en":"( old-fashioned ) a walk that you take for pleasure or exercise, especially by the sea, in a public park, etc. （","cn":"尤指在海滨、公园等的）散步，漫步"}]}},"primates":{"oxford":{"phon":"ˈpraɪmeɪt","pos":"noun","senses":[{"en":"any animal that belongs to the group of mammals that includes humans, apes and monkeys","cn":"灵长类；灵长目动物"},{"en":"an archbishop (= a priest of very high rank in the Christian Church)","cn":"大主教；总主教"}]},"media":{"img":["media/pic/primates_comp.jpg"]}},"properties":{"lemma":"property"},"productions":{"lemma":"production"},"protects":{"lemma":"protect"},"proceeded":{"lemma":"proceed"},"preferences":{"lemma":"preference"},"prospects":{"lemma":"prospect"},"produced":{"lemma":"produce"},"professors":{"lemma":"professor"},"programs":{"lemma":"program"},"prevented":{"lemma":"prevent"},"protesters":{"lemma":"protester"},"proposed":{"lemma":"propose","media":{"uk":"media/ldoce/hwd/bre/e/proposed0205.mp3","us":"media/ldoce/hwd/ame/4/laadproposed.mp3"}},"presaged":{"oxford":{"phon":"ˈpresɪdʒ","pos":"verb","senses":[{"en":"( literary ) to be a warning or sign that sth will happen, usually sth unpleasant","cn":"预兆，警示，预言（尤指不祥之事）"}]}},"provides":{"lemma":"provide"},"pressures":{"lemma":"pressure"},"proprietors":{"lemma":"proprietor"},"providers":{"oxford":{"phon":"prəˈvaɪdə(r)","pos":"noun","senses":[{"en":"a person or an organization that supplies sb with sth they need or want","cn":"供应者；提供者；供养人"}]}},"proving":{"lemma":"prove"},"praying":{"lemma":"pray"},"prayers":{"lemma":"prayer"},"priced":{"lemma":"price"},"protesting":{"lemma":"protest"},"principles":{"lemma":"principle"},"predicted":{"lemma":"predict"},"preparations":{"lemma":"preparation"},"prettiest":{"lemma":"pretty"},"proposes":{"lemma":"propose"},"prawns":{"oxford":{"phon":"prɔːn","pos":"noun","senses":[{"en":"a shellfish with ten legs and a long tail, that can be eaten. Prawns turn pink when cooked.","cn":"对虾；大虾；明虾"}]}},"protected":{"lemma":"protect","media":{"uk":"media/ldoce/hwd/bre/9/ld41protected.mp3","us":"media/ldoce/hwd/ame/9/ld41protected.mp3"}},"prospered":{"oxford":{"phon":"ˈprɒspə(r)","pos":"verb","senses":[{"en":"to develop in a successful way; to be successful, especially in making money","cn":"繁荣；兴旺；成功；发达"}]}},"prices":{"lemma":"price"},"promises":{"lemma":"promise"},"protested":{"lemma":"protest"},"proved":{"lemma":"prove"},"prowlers":{"oxford":{"phon":"ˈpraʊlə(r)","pos":"noun","senses":[{"en":"a person who follows sb or who moves around quietly outside their house, especially at night, in order to frighten them, harm them or steal sth from them （","cn":"图谋不轨的）潜行者"}]}},"propped":{"oxford":{"phon":"prɒp","pos":"noun","senses":[{"en":"a piece of wood, metal, etc. used to support sth or keep it in position","cn":"支柱；支撑物"},{"en":"a person or thing that gives help or support to sb/sth that is weak","cn":"支持者；支柱；后盾"}]}},"processes":{"lemma":"process"},"professionals":{"lemma":"professional"},"preparing":{"lemma":"prepare"},"precepts":{"oxford":{"phon":"ˈpriːsept","pos":"noun","senses":[{"en":"a rule about how to behave or what to think （","cn":"思想、行为的）准则，规范"}]}},"producing":{"lemma":"produce"},"preventing":{"lemma":"prevent"},"precautions":{"lemma":"precaution"},"presented":{"lemma":"present"},"priming":{"lemma":"prime"},"produces":{"lemma":"produce"},"presenting":{"lemma":"present"},"proves":{"lemma":"prove"},"preceded":{"lemma":"precede"},"promoting":{"lemma":"promote"},"presumption":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"假定；假设","en":"A presumption is something that is accepted as true but is not certain to be true.","ex":{"en":"...the presumption that a defendant is innocent until proved guilty","cn":"被告在被证实有罪之前都被视为无罪的假定"}},{"pos":"N-UNCOUNT 不可数名词","cn":"擅自；放肆；冒昧","en":"If you describe someone's behaviour as presumption, you disapprove of it because they are doing something that they have no right to do.","ex":{"en":"They were angered by his presumption.","cn":"他们对他的放肆感到非常愤怒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you think is true because it is very likely","cn":"假定﹔推测﹔设想"},{"en":"the act of thinking something is true, bad, or good until it is shown to not be true, bad, or good 〔","cn":"无证据的〕推定﹐认定"},{"en":"behaviour that seems rude and too confident","cn":"放肆﹐冒昧﹔自以为是"}]},"vocab":{"pos":"n","senses":[{"en":"The noun presumption pretty much means jumping to conclusions. It is taking something for granted — an idea, an answer, an event — without having any real knowledge about it, and that is usually not a good thing."}]},"collocations":{"phrases":["ADJ. strong | general There is a general presumption that fatty foods are bad for your heart.","PREP. ~ about The argument is based on certain presumptions about human nature. | ~ against the presumption against changes in the common la"]},"media":{"uk":"media/ldoce/hwd/bre/4/presumption0205.mp3","us":"media/ldoce/hwd/ame/9/presumption.mp3"},"examples":[{"en":"Everyone is entitled to the presumption of innocence until they are proved to be guilty.","cn":"在被证明有罪以前，每一个人都应被假定无辜。"},{"en":"There is a general presumption that the doctor knows best.","cn":"一般人都以为医生最了解情况。"}],"oxford":{"phon":"prɪˈzʌmpʃn","pos":"noun","senses":[{"en":"something that is thought to be true or likely","cn":"假设；假定","g":"[countable]","ex":{"en":"There is a general presumption that the doctor knows best.","cn":"一般人都以为医生最了解情况。"}},{"en":"behaviour that is too confident and shows a lack of respect for other people","cn":"非分的行为；妄自尊大","g":"[uncountable]","lab":"formal","ex":{"en":"She was infuriated by his presumption in not consulting her first.","cn":"她对他没有先咨询她的想法感到愤怒。"}},{"en":"the act of supposing that something is true, although it has not yet been proved or is not certain","cn":"推定；假定；假设","g":"[uncountable, countable]","lab":"law","ex":{"en":"Everyone is entitled to the presumption of innocence until they are proved to be guilty.","cn":"在被证明有罪之前，每个人都应被假定无罪。"}}]}},"prowess":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"深厚的造诣；高超的技艺","en":"Someone's prowess is their great skill at doing something.","ex":{"en":"He's always bragging about his prowess as a cricketer","cn":"他总是吹嘘自己板球水平高超。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"great skill at doing something 〔","cn":"做某事的〕高超技艺"}]},"vocab":{"pos":"n","senses":[{"en":"Prowess means exceptional skill or ability. Your sailing prowess might save your life in a storm, while someone with less experience might make mistakes."}]},"collocations":{"phrases":["ADJ. academic, athletic, golfing, intellectual, military, physical, sexual, sporting, technical, etc.","VERB + PROWESS demonstrate, show | boast about/of | admire | be famed/famous for","PREP. ~ as He boasted of his prowess as a lover. | ~ at her prowess at tennis | ~ in The Gurkhas are famed for their prowess in battle. | ~ "]},"media":{"uk":"media/ldoce/hwd/bre/8/prowess0205.mp3","us":"media/ldoce/hwd/ame/3/prowess.mp3"},"examples":[{"en":"academic/sporting prowess","cn":"学术/体育运动造诣"},{"en":"his physical prowess","cn":"他优异的体能"}],"oxford":{"phon":"ˈpraʊəs","pos":"noun","senses":[{"en":"great skill at doing something","cn":"非凡的技能；高超的技艺；造诣","ex":{"en":"academic/sporting prowess","cn":"学术／体育运动造诣"}}]}},"provocation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"挑衅；煽动；刺激；激怒","en":"If you describe a person's action as provocation or a provocation, you mean that it is a reason for someone else to react angrily, violently, or emotionally.","ex":{"en":"He denies murder on the grounds of provocation","cn":"他否认激情杀人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an action or event that makes someone angry or upset, or is intended to do this","cn":"激怒﹔挑衅﹔挑衅性事件"}]},"vocab":{"pos":"n","senses":[{"en":"A provocation makes someone angry or sometimes even violent. Telling a professional boxer how ugly he is would be considered a provocation — one that might get you punched in the face."}]},"collocations":{"phrases":["ADJ. extreme, severe | deliberate","QUANT. element The victim's conduct had involved an element of provocation.","VERB + PROVOCATION respond to","PREP. under ~ The crime was committed under provocation. | without ~ She attacked him without provocation.","PHRASES at the least/slightest provocation He would lose his temper at the slightest provocation."]},"media":{"uk":"media/ldoce/hwd/bre/0/provocation0205.mp3","us":"media/ldoce/hwd/ame/1/provocation.mp3"},"examples":[{"en":"So far the police have refused to respond to their provocations.","cn":"截至目前为止，警方并未对他们的挑衅作出反应。"},{"en":"The terrorists can strike at any time without provocation.","cn":"恐怖分子可能无缘无故地随时攻击。"}],"oxford":{"phon":"ˌprɒvəˈkeɪʃn","pos":"noun","senses":[{"en":"the act of doing or saying something deliberately in order to make somebody angry or upset; something that is done or said to cause this","cn":"挑衅；刺激；激怒","ex":{"en":"He fired a shot without any provocation.","cn":"他在没有任何挑衅的情况下开了一枪。"}}]}},"preoccupation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"念念不忘；执著","en":"If you have a preoccupation with something or someone, you keep thinking about them because they are important to you.","ex":{"en":"Karouzos's poetry shows a profound preoccupation with the Orthodox Church","cn":"卡鲁佐斯的诗歌表明他对东正教的执着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"全神贯注；入神","en":"Preoccupation is a state of mind in which you think about something so much that you do not consider other things to be important.","ex":{"en":"It was hard for him to be aware of her; he kept sinking back into black preoccupation.","cn":"他很难意识到她的存在；他一直沉浸在沮丧中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonably strong and continuous interest in someone or something, so that you cannot stop thinking about them and your behaviour is seriously affected","cn":""},{"en":"a very strong desire for something or interest in something, especially one that affects a lot of people at the same time","cn":""},{"en":"an unnaturally strong interest in or love for someone or something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Preoccupation is a state where you're absorbed in something. You may have a preoccupation with video games or Hello Kitty, for example, if you can't keep your mind off those things."}]},"collocations":{"phrases":["ADJ. current, present, recent | central, chief, main, major Their chief preoccupation was how to feed their families. | constant, continuing","PREP. ~ for By now this had become a major preoccupation for him. | ~ with his growing preoccupation with death"]},"media":{"uk":"media/ldoce/hwd/bre/f/preoccupation0205.mp3","us":"media/ldoce/hwd/ame/4/preoccupation.mp3"},"examples":[{"en":"She found his preoccupation with money irritating.","cn":"她对他一心只想着钱感到很厌烦。"},{"en":"She spoke slowly, in a state of preoccupation.","cn":"她说话慢吞吞的，显得心事重重。"}],"oxford":{"phon":"priˌɒkjuˈpeɪʃn","pos":"noun","senses":[{"en":"a state of thinking about something continuously; something that you think about frequently or for a long time","cn":"盘算；思虑；长久思考的事情","g":"[uncountable, countable]","ex":{"en":"She found his preoccupation with money irritating.","cn":"她对他一心只想着钱感到很厌烦。"}},{"en":"a mood created by thinking or worrying about something and ignoring everything else","cn":"心事重重；忧心忡忡；全神贯注","g":"[uncountable]","ex":{"en":"She spoke slowly, in a state of preoccupation.","cn":"她说话慢吞吞的，显得心事重重。"}}]}},"prosecution":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"起诉；检举；告发","en":"Prosecution is the action of charging someone with a crime and putting them on trial.","ex":{"en":"Yesterday the head of government called for the prosecution of those responsible for the deaths.","cn":"昨天，政府首脑要求起诉那些该为这些人的死负责的人。"}},{"pos":"N-SING 单数名词","cn":"公诉的律师；控方律师","en":"The lawyers who try to prove that a person on trial is guilty are called the prosecution .","ex":{"en":"Colonel Pugh, for the prosecution, said that the offences occurred over a six-year period.","cn":"皮尤上校为控方律师作证时说这些罪行是在6年的时间里犯下的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the group of lawyers in a court of law who try to prove that the person accused of a crime is guilty","cn":""},{"en":"the lawyer who officially accuses someone of a crime or offence in a court of law and tries to prove that they are guilty","cn":""},{"en":"a government lawyer in the US who works with the police and in the courts on legal cases against people who have been charged with a crime","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You know the lawyers who try to make the jury believe the guy on trial for stealing the bananas actually stole the bananas? That team of lawyers is known as the prosecution ."}]},"collocations":{"phrases":["ADJ. criminal, private | successful | impending, possible He faces possible prosecution.","VERB + PROSECUTION bring, initiate | be liable to, face, risk | escape | lead to, result in","PREP. ~ against The police brought a prosecution against the driver involved. | ~ for Prosecutions for water pollution more than doubled.","PHRASES immunity from prosecution 2 lawyers trying to prove sb's guilt","PROSECUTION + VERB prove sth | allege sth, claim sth The prosecution alleged that he murdered his wife.","PROSECUTION + NOUN case, evidence | counsel, lawyer, witness | costs","PREP. for the ~ a witness for the prosecution"]},"media":{"uk":"media/ldoce/hwd/bre/d/prosecution0205.mp3","us":"media/ldoce/hwd/ame/f/prosecution.mp3"},"examples":[{"en":"Prosecution for a first minor offence rarely leads to imprisonment.","cn":"因初犯轻罪被控者很少被判监禁。"},{"en":"He threatened to bring a private prosecution against the doctor.","cn":"他威胁要对医生提起民事诉讼。"}],"oxford":{"phon":"ˌprɒsɪˈkjuːʃn","pos":"noun","senses":[{"en":"the process of trying to prove in court that somebody is guilty of a crime (= of prosecuting them); the process of being officially charged with a crime in court","cn":"（被）起诉，检举，诉讼","g":"[uncountable, countable]","lab":"especially North American English","ex":{"en":"Prosecution for a first minor offence rarely leads to imprisonment.","cn":"因初犯轻罪被控者很少被判监禁。"}},{"en":"a person or an organization that prosecutes somebody in court, together with the lawyers, etc.","cn":"原告，控方（包括原告和原告律师等）","g":"[singular + singular or plural verb]","ex":{"en":"He was a witness for the prosecution.","cn":"他是原告证人。"}},{"en":"the act of making something happen or continue","cn":"实施；从事；继续进行","g":"[uncountable]","lab":"formal"}]}},"prototype":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"原型；样品；样本","en":"A prototype is a new type of machine or device which is not yet ready to be made in large numbers and sold.","ex":{"en":"Chris Retzler has built a prototype of a machine called the wave rotor.","cn":"克里斯·雷茨勒已制造出了一种叫波转子的机器的样机。"}},{"pos":"N-COUNT 可数名词","cn":"模范；典型","en":"If you say that someone or something is a prototype of a type of person or thing, you mean that they are the first or most typical one of that type.","ex":{"en":"He was the prototype of the elder statesman.","cn":"他是老一辈政治家的典型。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that has never been done or achieved by anyone before and is therefore surprising or exciting","cn":""},{"en":"the first model of something, especially of a machine or a new invention, that is often improved in later models","cn":""},{"en":"something such as a picture or a piece of writing that is not a copy but is the one produced for the first time by the artist or writer themselves","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A prototype is the original model, like a sample on which to base future designs. A company designing a new toaster will first design and build a prototype , to test it out and see if it's any good."}]},"collocations":{"phrases":["ADJ. pre-production | working","VERB + PROTOTYPE build, develop | test","PROTOTYPE + NOUN stage The car is presently at the prototype stage.","PREP. ~ for The team is developing a prototype for a digital compact camera. | ~ of He is working on the prototype of a new type of ventilat"]},"media":{"uk":"media/ldoce/hwd/bre/8/prototype0205.mp3","us":"media/ldoce/hwd/ame/0/prototype.mp3"},"examples":[{"en":"the prototype of the modern bicycle","cn":"现代自行车的雏形"},{"en":"a working prototype of the new car","cn":"新车的工作原型"}],"oxford":{"phon":"ˈprəʊtətaɪp","pos":"noun","senses":[{"en":"the first design of something from which other forms are copied or developed","cn":"原型；雏形；最初形态","ex":{"en":"the prototype of the modern bicycle","cn":"现代自行车的雏形"}}]}},"preliminary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"预备的；初步的","en":"Preliminary activities or discussions take place at the beginning of an event, often as a form of preparation.","ex":{"en":"Preliminary results show the Republican party with 11 percent of the vote","cn":"初步结果显示共和党获得了11%的选票。"}},{"pos":"N-COUNT 可数名词","cn":"准备工作；初步行动","en":"A preliminary is something that you do at the beginning of an activity, often as a form of preparation.","ex":{"en":"It had taken about ten minutes to cover the preliminaries","cn":"准备工作大概花了10分钟。"}},{"pos":"N-COUNT 可数名词","cn":"预赛；初赛；初试","en":"A preliminary is the first part of a competition to see who will go on to the main competition.","ex":{"en":"The winner of each preliminary goes through to the final.","cn":"每场初赛的获胜者进入决赛。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings, costs etc that exist or are experienced at the beginning of an event or process","cn":""},{"en":"close to the beginning of an event, story, period of time etc","cn":""},{"en":"happening at the beginning of a process or event, especially in order to prepare for the rest of it","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Preliminary means something that comes before something else. If you want to run in the race, you have to place in the top third of the preliminary round. It can also mean \"early\"––the preliminary results are in, and you've won!"}]},"collocations":{"phrases":["ADJ. essential, necessary, useful | usual After the usual preliminaries the meeting began.","PREP. as a ~ The two presidents met today, as a preliminary to resuming the peace talks. | without preliminaries She began speaking intensel"]},"media":{"uk":"media/ldoce/hwd/bre/1/preliminary_ad0205.mp3","us":"media/ldoce/hwd/ame/9/preliminary1.mp3"},"examples":[{"en":"After a few preliminary remarks he announced the winners.","cn":"说了几句开场白之后，他即宣布优胜者名单。"},{"en":"I'll skip the usual preliminaries and come straight to the point.","cn":"闲话少说，我就直接进入正题。"}],"oxford":{"phon":"prɪˈlɪmɪnəri","pos":"adjective","senses":[{"en":"happening before a more important action or event","cn":"预备性的；初步的；开始的","ex":{"en":"After a few preliminary remarks he announced the winners.","cn":"说了几句开场白之后，他即宣布优胜者名单。"}},{"en":"a preliminary is an action or event that is done in preparation for something","cn":"初步行动（或活动）；预备性措施","ex":{"en":"I'll skip the usual preliminaries and come straight to the point.","cn":"闲话少说，我就直接进入正题。"},"pos":"noun"}]}},"proclaim":{"collins":{"senses":[{"pos":"VERB 动词","cn":"宣布；声明；公布","en":"If people proclaim something, they formally make it known to the public.","ex":{"en":"The Boers rebelled against British rule, proclaiming their independence on 30 December 1880","cn":"布尔人反抗英国统治，并于1880年12月30日宣布独立。"}},{"pos":"VERB 动词","cn":"明确表示；清楚地表明","en":"If you proclaim something, you state it in an emphatic way.","ex":{"en":"'I think we have been heard today,' he proclaimed","cn":"“我想今天我们说的大家都听见了，”他明确地说。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say publicly or officially that something important is true or exists","cn":"宣布﹐声明"},{"en":"to show something clearly or be a sign of something","cn":"显示﹐表明"}]},"vocab":{"pos":"v","senses":[{"en":"\"I proclaim the Olympic Games open.\" Every two years with words similar to these, the Olympic games officially begin. To proclaim is to exclaim or declare."}]},"collocations":{"phrases":["ADV. loudly | formally, officially | openly, publicly | proudly | unilaterally The district unilaterally proclaimed its independence from th","VERB + PROCLAIM seem to His classic boyish looks seemed to proclaim his good humour and openness.","PREP. as Everyone is proclaiming him as the next president. | to proclaiming her innocence to the world"]},"media":{"uk":"media/ldoce/hwd/bre/f/proclaim0205.mp3","us":"media/ldoce/hwd/ame/f/proclaim.mp3"},"examples":[{"en":"The senator proclaimed how shocked he was at the news.","cn":"那名参议员声称他听到这消息时是多么的震惊。"},{"en":"This building, more than any other, proclaims the character of the town.","cn":"这座建筑比任何其他建筑都能代表本城的特色。"}],"oxford":{"phon":"prəˈkleɪm","pos":"verb","senses":[{"en":"to publicly and officially tell people about something important","cn":"宣布；宣告；声明","ex":{"en":"The president proclaimed a state of emergency.","cn":"总统宣布了紧急状态。"}},{"en":"to show something clearly; to be a sign of something","cn":"明确显示；成为标志；表明","ex":{"en":"This building, more than any other, proclaims the character of the town.","cn":"这座建筑比任何其他建筑都能代表本城的特色。"}}]}},"printer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"打印机","en":"A printer is a machine that can be connected to a computer in order to make copies on paper of documents or other information held by the computer."},{"pos":"N-COUNT 可数名词","cn":"印刷工人；印刷厂；印刷公司","en":"A printer is a person or company whose job is printing things such as books.","ex":{"en":"The manuscript had already been sent off to the printers.","cn":"原稿已经寄给印刷厂了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine which is connected to a computer and can make a printed record of computer information 〔","cn":"与计算机连接的〕打印机"},{"en":"someone who is employed in the trade of printing","cn":"印刷业从业人员﹐印刷工"}]},"collocations":{"phrases":["ADJ. book | lithographic | commercial | master | jobbing","PRINTER + VERB print sth, run sth off The printer has run off 2,000 copies of the leaflet. • Note at JOB 2 machine","ADJ. black-and-white, colour | computer | desktop | bubblejet, daisy wheel, dot matrix, inkjet, laser, line, page | compatible","VERB + PRINTER control, drive | connect Coonect the printer to your PC with a printer cable.","PRINTER + VERB print (sth), work The printer won't print for some reason.","PRINTER + NOUN cable | port | ribbon | driver | icon •"]},"media":{"uk":"media/ldoce/hwd/bre/b/printer0205.mp3","us":"media/ldoce/hwd/ame/6/printer.mp3"},"examples":[{"en":"a colour/laser printer","cn":"彩色/激光打印机"},{"en":"a laser printer","cn":"激光打印机"}],"oxford":{"phon":"ˈprɪntə(r)","pos":"noun","senses":[{"en":"a machine for printing text on paper, especially one connected to a computer","cn":"打印机（尤指与计算机相连的）","ex":{"en":"a colour printer","cn":"彩色打印机"}},{"en":"a person or a company whose job is printing books, etc.","cn":"印刷商；印刷工人；印刷公司"},{"en":"a place where books, etc. are printed","cn":"印刷厂"}]}},"prerogative":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特权；独有的权力；专利","en":"If something is the prerogative of a particular person or group, it is a privilege or a power that only they have.","ex":{"en":"Constitutional changes are exclusively the prerogative of the parliament","cn":"修改宪法是议会独有的权力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special right or advantage given to a person or group, because of their high social position, because they are a member of a club etc","cn":""},{"en":"a special right that only a particular person or group has because of their importance or position","cn":""},{"en":"a right that you should have because you have been born into a particular family, country, class etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A prerogative is someone's special right or privilege. As Bobby Brown once sang, \"I don't need permission / Make my own decisions / That's my prerogative .\""}]},"collocations":{"phrases":["ADJ. exclusive, sole Making such decisions is not the sole prerogative of managers. | judicial, managerial, royal | personal","VERB + PREROGATIVE enjoy, have one of the prerogatives enjoyed by the president | exercise, use You can of course exercise your prerogative "]},"media":{"uk":"media/ldoce/hwd/bre/d/prerogative0205.mp3","us":"media/ldoce/hwd/ame/8/prerogative.mp3"},"examples":[{"en":"In many countries education is still the prerogative of the rich.","cn":"在许多国家接受教育仍然是富人的特权。"},{"en":"the royal prerogative (= the special rights of a king or queen)","cn":"君主特权"}],"oxford":{"phon":"prɪˈrɒɡətɪv","pos":"noun","senses":[{"en":"a right or advantage belonging to a particular person or group because of their importance or social position","cn":"特权；优先权","ex":{"en":"In many countries education is still the prerogative of the rich.","cn":"在许多国家接受教育仍然是富人的特权。"}}]}},"preservative":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"防腐剂；保护剂","en":"A preservative is a chemical that prevents things from decaying. Some preservatives are added to food, and others are used to treat wood or metal.","ex":{"en":"Nitrates are used as preservatives in food manufacture","cn":"硝酸盐在食品加工业中被用作防腐剂。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance that is used to prevent things from decaying, for example food or wood","cn":"防腐剂"}]},"collocations":{"phrases":["ADJ. food, wood | artificial Our products contain no artificial preservatives or colourings.","VERB + PRESERVATIVE apply, treat sth with Make sure the panels are treated with a wood preservative."]},"media":{"uk":"media/ldoce/hwd/bre/e/preservative0205.mp3","us":"media/ldoce/hwd/ame/e/preservative.mp3"},"examples":[{"en":"The juice contains no artificial preservatives.","cn":"这种果汁不含人工防腐剂。"},{"en":"(a) wood preservative","cn":"木材防腐剂"}],"oxford":{"phon":"prɪˈzɜːvətɪv","pos":"adjective","senses":[{"en":"preventing food or wood from decaying (= being destroyed by natural processes)","cn":"防腐剂；保护剂","ex":{"en":"the preservative effects of freezing","cn":"冷冻的防腐保护作用。"}},{"en":"a substance used to prevent food or wood from decaying (= being destroyed by natural processes)","cn":"防腐剂","lab":"British English","ex":{"en":"The juice contains no artificial preservatives.","cn":"这种果汁不含人工防腐剂。"},"pos":"noun"}]}},"protester":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抗议者；反对者","en":"Protesters are people who protest publicly about an issue.","ex":{"en":"The protesters say the government is corrupt and inefficient.","cn":"抗议者称政府腐败无能。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who believes that all war and violence is wrong","cn":""},{"en":"strongly against war, especially a war that your country is fighting at the present time","cn":""},{"en":"a group of people or countries that are peace-loving believe strongly in peace rather than war","cn":""}]},"collocations":{"phrases":["ADJ. student | anti-government, anti-nuclear, peace, political | peaceful, unarmed | angry","VERB + PROTESTER arrest","PROTESTER + VERB call for sth, demand sth | march | demonstrate, gather | clash, fight Protesters clashed with police outside the embassy.","PREP. ~ against The streets were crowded with protesters against the war."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeprotester.mp3","us":"media/ldoce/hwd/ame/c/laadprotester.mp3"},"examples":[{"en":"Thousands of protesters marched through the city.","cn":"数千人游行抗议，走过全城。"}],"oxford":{"phon":"prəˈtestə(r)","pos":"noun","senses":[{"en":"a person who makes a public protest","cn":"（公开）抗议者，反对者","ex":{"en":"Thousands of protesters marched through the city.","cn":"数千人游行抗议，走过全城。"}}]}},"practicable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（任务、计划或想法）切实可行的，行得通的","en":"If a task, plan, or idea is practicable, people are able to carry it out.","ex":{"en":"It is not reasonably practicable to offer her the original job back","cn":"让她继续做原来的工作在情理上行不通。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a practicable way of doing something is possible in a particular situation","cn":"可行的﹐行得通的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is practicable is something that can be reasonably done. Look at the word within the word, practice , plus the suffix -able , and you have something that is able to be put into practice, or practicable ."}]},"collocations":{"phrases":["VERBS be, prove, seem | become","ADV. perfectly | reasonably We will do this as soon as is reasonably practicable. | not very","PHRASES as far/soon as practicable"]},"media":{"uk":"media/ldoce/hwd/bre/3/practicable0205.mp3","us":"media/ldoce/hwd/ame/1/laadpracticable.mp3"},"examples":[{"en":"Employers should provide a safe working environment, as far as is reasonably practicable.","cn":"只要条件许可，雇主就须提供安全的工作环境。"},{"en":"The only practicable alternative is to postpone the meeting.","cn":"另外唯一可行的办法就是推迟会期。"}],"oxford":{"phon":"ˈpræktɪkəbl","pos":"adjective","senses":[{"en":"able to be done; likely to be successful","cn":"可行的；行得通的","ex":{"en":"at the earliest practicable opportunity","cn":"在尽可能早的时机"}}]}},"prospectus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（学校、公司等的）章程，简章，说明书","en":"A prospectus is a detailed document produced by a college, school, or company, which gives details about it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very short book with paper covers that usually contains information on one particular subject","cn":""},{"en":"a thin book with paper covers that gives information on something you may want to buy or advertises something","cn":""},{"en":"a small book or piece of paper, often only one or two folded pages, that advertises something or gives information on a particular subject","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A prospectus is a written catalog or brochure that offers a plan, as of school courses to take or which stocks to buy. The idea of a prospectus is to offer a variety of options and a plan of action."}]},"collocations":{"phrases":["ADJ. detailed | college, school","QUANT. copy","VERB + PROSPECTUS browse through, leaf through, look through | produce"]},"media":{"uk":"media/ldoce/hwd/bre/f/prospectus0205.mp3","us":"media/ldoce/hwd/ame/d/prospectus.mp3"},"oxford":{"phon":"prəˈspektəs","pos":"noun","senses":[{"en":"a book, document or web page that gives information about a school, college, etc. in order to advertise it","cn":"（学校的）简章，简介"},{"en":"a document that gives information about a company’s shares before they are offered for sale","cn":"（企业的）招股说明书，募股章程","lab":"business"}]}},"prejudiced":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心怀偏见的；有成见的；偏爱的","en":"A person who is prejudiced against someone has an unreasonable dislike of them. A person who is prejudiced in favour of someone has an unreasonable preference for them.","ex":{"en":"Some landlords and landladies are racially prejudiced","cn":"一些房东有种族偏见。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"treating someone unfairly and having an unreasonable dislike of them because of their race, sex etc, or because they are old, disabled etc","cn":""},{"en":"treating someone unfairly because of their race","cn":""},{"en":"treating someone unfairly because of their sex","cn":""}]},"collocations":{"phrases":["VERBS be, seem","ADV. deeply, extremely | racially","PREP. against He's deeply prejudiced against women."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeprejudiced.mp3","us":"media/ldoce/hwd/ame/1/prejudiced.mp3"},"examples":[{"en":"( humorous ) I think it's an excellent article, but then I'm prejudiced — I wrote it.","cn":"我认为那篇文章相当出色；不过，我有些偏心，那是我写的嘛！"},{"en":"They are prejudiced against older applicants.","cn":"他们对年长一些的申请人抱有成见。"}],"oxford":{"phon":"ˈpredʒədɪst","pos":"adjective","senses":[{"en":"having an unreasonable dislike of or preference for somebody/something, especially based on their race, religion, sex, etc.","cn":"有偏见的；带成见的；偏爱的；偏心的","lab":"humorous","ex":{"en":"Few people will admit to being racially prejudiced.","cn":"很少有人会承认自己有种族偏见。"}}]},"base":"prejudice"},"prohibition":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（美国1919年至1933年间的）禁酒令；禁酒令时期","en":"In the United States, Prohibition was the law that prevented the manufacture, sale, and transporting of alcoholic drinks between 1919 and 1933. Prohibition also refers to the period when this law existed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of saying that something is illegal 〔","cn":"法律〕禁止"},{"en":"an order stopping something","cn":"禁令﹐禁律"}]},"vocab":{"pos":"n","senses":[{"en":"Prohibition is the act of forbidding or outlawing something, like when my mom placed a prohibition on watching TV during dinner (causing everyone to skip dinner)."}]},"collocations":{"phrases":["ADJ. absolute, total | general | legal, statutory","VERB + PROHIBITION impose | abolish, lift","PROHIBITION + NOUN notice, order The prohibition order meant that the book could not be sold in this country.","PREP. ~ against prohibition against sales to under-18s of alcohol | ~ of a treaty for the prohibition of nuclear tests | ~ on the prohibitio"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41prohibition2.mp3","us":"media/ldoce/hwd/ame/c/ld46prohibition.mp3"},"examples":[{"en":"a prohibition against selling alcohol to people under the age of 18","cn":"禁止向 18 岁以下青少年售酒的法令"},{"en":"the prohibition of smoking in public areas","cn":"禁止在公共场所吸烟的规定"}],"oxford":{"phon":"ˌprəʊɪˈbɪʃn","pos":"noun","senses":[{"en":"the act of stopping something being done or used, especially by law","cn":"（尤指通过法律的）禁止，阻止","g":"[uncountable]","lab":"formal","ex":{"en":"the prohibition of smoking in public areas","cn":"禁止在公共场所吸烟的规定"}},{"en":"a law or a rule that stops something being done or used","cn":"禁令；禁律","g":"[countable]","lab":"formal","ex":{"en":"a prohibition against selling alcohol to people under the age of 18","cn":"禁止向 18 岁以下青少年售酒的法令"}},{"en":"(in the US) the period of time from 1920 to 1933 when it was illegal to make and sell alcoholic drinks","cn":"（1920 至 1933 年美国的）禁酒时期","g":"[uncountable]","ex":{"en":"a Prohibition-era speakeasy","cn":"禁酒时期的地下酒吧"}}]}},"presenter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（广播或电视节目的）主持人","en":"A radio or television presenter is a person who introduces the items in a particular programme.","ex":{"en":"Most people think being a television presenter is exciting","cn":"很多人认为当电视节目主持人是一件刺激的事情。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone on a television or radio programme who tells you what the programme will be about, and introduces the other people in it","cn":""},{"en":"someone on a television or radio programme who tells you what the programme will be about, or who tells you about a sports game as it is happening","cn":""},{"en":"someone who introduces the people on a show and who talks to people or about reports or scenes included in the programme - use this especially about talk shows, game shows, or quiz shows","cn":""}]},"collocations":{"phrases":["ADJ. radio, television/TV | BBC, ITV, etc. | programme, sports a BBC sports presenter • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/c/presenter0205.mp3","us":"media/ldoce/hwd/ame/4/presenter.mp3"},"examples":[{"en":"a TV presenter","cn":"电视节目主持人"},{"en":"conference presenters","cn":"会议发言人"}],"oxford":{"phon":"prɪˈzentə(r)","pos":"noun","senses":[{"en":"a person who introduces the different sections of a radio or television programme","cn":"（广播、电视）节目主持人","lab":"British English","ex":{"en":"a TV presenter","cn":"电视节目主持人"}},{"en":"a person who makes a speech or talks to an audience about a particular subject","cn":"演讲人；发言人","ex":{"en":"conference presenters","cn":"会议发言人"}},{"en":"a person who gives somebody a prize at a ceremony","cn":"（仪式上的）颁奖人","lab":"North American English"}]}},"preconception":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"事先形成的看法；先入之见；成见","en":"Your preconceptions about something are beliefs formed about it before you have enough information or experience.","ex":{"en":"Did you have any preconceptions about the sort of people who did computing?","cn":"你对从事计算机工作的人有什么成见吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a belief or opinion that you have already formed before you know the actual facts, and that may be wrong","cn":"事先形成的看法[想法]﹔先入之见﹐成见"}]},"collocations":{"phrases":["VERB + PRECONCEPTION have | fit in with We like this approach because it fits in with our own preconceptions. | challenge, get away from It ","PREP. with/without ~s It's important that you come to this task with no preconceptions. | ~ about Most people have preconceptions about old "]},"media":{"uk":"media/ldoce/hwd/bre/3/preconception0205.mp3","us":"media/ldoce/hwd/ame/e/preconception.mp3"},"examples":[{"en":"a book that will challenge your preconceptions about rural life","cn":"一本改变你对农村生活成见的书"},{"en":"I had the same preconceptions about life in South Africa that many people have.","cn":"我对南非的生活抱有和许多人一样的成见。"}],"oxford":{"phon":"ˌpriːkənˈsepʃn","pos":"noun","senses":[{"en":"an idea or opinion that is formed before you have enough information or experience","cn":"事先形成的观念；先入之见；预想；成见","ex":{"en":"a book that will challenge your preconceptions about rural life","cn":"一本改变你对农村生活成见的书"}}]}},"presentable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"像样的；体面的","en":"If you say that someone looks presentable, you mean that they look fairly tidy or attractive.","ex":{"en":"She managed to make herself presentable in time for work.","cn":"她想方设法让自己在工作时间穿得更像样。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拿得出手的；像样的；令人满意的","en":"If you describe something as presentable, you mean that it is acceptable or quite good.","ex":{"en":"His score of 29 had helped Leicestershire reach a presentable total","cn":"他拿下29分，帮助莱斯特郡队获得了一个不错的总成绩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wearing good or expensive clothes","cn":""},{"en":"if you look smart or your clothes are smart , you are dressed in an attractive way and you look very tidy","cn":""},{"en":"If you look neat or if you have neat clothes, the clothes you are wearing are clean, ironed, and fit you properly","cn":""}]},"collocations":{"phrases":["VERBS be, look | make sb Could you try and make yourself a little more presentable?","ADV. very | perfectly She was not exactly good-looking, but perfectly presentable. | quite, reasonably"]},"media":{"uk":"media/ldoce/hwd/bre/8/presentable0205.mp3","us":"media/ldoce/hwd/ame/8/presentable.mp3"},"examples":[{"en":"You're going to have to do a lot more work on this essay before it's presentable.","cn":"你的这篇文章还得多加润饰才能交得出手。"},{"en":"I must go and make myself presentable before the guests arrive.","cn":"趁客人还没到，我得去打扮一下好见人。"}],"oxford":{"phon":"prɪˈzentəbl","pos":"adjective","senses":[{"en":"looking clean and attractive and suitable to be seen in public","cn":"像样的；体面的","ex":{"en":"I must go and make myself presentable before the guests arrive.","cn":"趁客人还没到，我得去打扮一下好见人。"}},{"en":"acceptable","cn":"可接受的；符合要求的","ex":{"en":"You're going to have to do a lot more work on this essay before it's presentable.","cn":"你的这篇文章还得多加润饰才能交得出手。"}}]}},"prospero":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the main character in the play The Tempest by William shakespeare","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000010041.mp3","us":"media/ldoce/hwd/ame/6/prospero_.mp3"},"oxford":{"phon":"ˈprɒspərəʊ","pos":"","senses":[{"en":"the main character in Shakespeare's play The Tempest","cn":"莎士比亚戏剧《暴风雨》中的主要角色"}]}},"pragmatic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讲求实效的；实用的；务实的","en":"A pragmatic way of dealing with something is based on practical considerations, rather than theoretical ones. A pragmatic person deals with things in a practical way.","ex":{"en":"Robin took a pragmatic look at her situation.","cn":"罗宾实际地考虑了一下她的处境。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is sensible is unlikely to do anything stupid, because they judge situations well and make good decisions","cn":""},{"en":"someone who is reasonable makes sensible decisions that are fair to everyone","cn":""},{"en":"someone who is responsible can be trusted to do what they should do and to think about the results of their actions","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"To describe a person or a solution that takes a realistic approach, consider the adjective pragmatic . The four-year-old who wants a unicorn for her birthday isn't being very pragmatic."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. highly, very | entirely, purely, utterly | essentially, largely Our approach is essentially pragmatic. | quite, rather","PREP. about They're pragmatic about the spending cuts."]},"media":{"uk":"media/ldoce/hwd/bre/d/pragmatic0205.mp3","us":"media/ldoce/hwd/ame/1/pragmatic.mp3"},"examples":[{"en":"a pragmatic approach to management problems","cn":"对管理问题采取的务实做法"},{"en":"Williams took a more pragmatic approach to management problems.","cn":"威廉斯在管理问题上采用的是一种更务实的做法。"}],"oxford":{"phon":"præɡˈmætɪk","pos":"adjective","senses":[{"en":"solving problems in a practical and sensible way rather than by having fixed ideas or theories","cn":"实用的；讲求实效的；务实的","ex":{"en":"a pragmatic approach to management problems","cn":"对管理问题采取的务实做法"}}]}},"preferable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"更好的；更可取的；更合适的","en":"If you say that one thing is preferable to another, you mean that it is more desirable or suitable.","ex":{"en":"A big earthquake a long way off is preferable to a smaller one nearby","cn":"远处发生大地震总比在附近发生小地震好。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the comparative of good","cn":""},{"en":"better, especially in quality","cn":""},{"en":"more suitable or useful – used when saying which one you prefer","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When one thing seems like a better option than another, it is preferable . If you would rather have chocolate ice cream than vanilla, it means that chocolate is preferable to you."}]},"collocations":{"phrases":["VERBS be, seem | become | remain | consider sth","ADV. far, greatly, infinitely, vastly","PREP. to Death was considered vastly preferable to dishonour."]},"media":{"uk":"media/ldoce/hwd/bre/1/preferable0205.mp3","us":"media/ldoce/hwd/ame/4/preferable.mp3"},"examples":[{"en":"We're looking for a new house, preferably one near the school.","cn":"我们正在找新房子，最好是靠近学校的。"},{"en":"He finds country life infinitely preferable to living in the city.","cn":"他觉得乡村生活比都市生活称心得多。"}],"oxford":{"phon":"ˈprefrəbl","pos":"adjective","senses":[{"en":"more attractive or more suitable; to be preferred to something","cn":"较适合；更可取","ex":{"en":"Anything was preferable to the tense atmosphere at home.","cn":"什么都比家里的紧张气氛好。"}}]}},"prairie":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（北美的）大草原","en":"A prairie is a large area of flat, grassy land in North America. Prairies have very few trees."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wide open area of fairly flat land in North America which is covered in grass or wheat 〔","cn":"北美洲的〕大草原"}]},"vocab":{"pos":"n","senses":[{"en":"A prairie is a plain of grassy land without many trees. If you're raising cattle, find some prairie land to let them roam around on."}]},"collocations":{"phrases":["ADJ. high, rolling, wide | American","VERB + PRAIRIE cross a train of covered wagons crossing the wide American prairies","PRAIRIE + NOUN dog","PREP. across the ~ their route across the prairie | on the ~ settlers' houses on the prairies of Canada"]},"media":{"uk":"media/ldoce/hwd/bre/8/prairie_las2_br.mp3","us":"media/ldoce/hwd/ame/e/prairie.mp3"},"oxford":{"phon":"ˈpreəri","pos":"noun","senses":[{"en":"a flat, wide area of land in North America and Canada, without many trees and originally covered with grass","cn":"北美草原；新大陆北部草原（美国北部和加拿大）","ex":{"en":"Only about 5 per cent of native prairie is left in Kansas.","cn":"堪萨斯州只剩下约 5% 的本土草原。"}}]}},"premium":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保险费；保险金","en":"A premium is a sum of money that you pay regularly to an insurance company for an insurance policy.","ex":{"en":"It is too early to say whether insurance premiums will be affected.","cn":"现在说保险费是否会受影响还为时过早。"}},{"pos":"N-COUNT 可数名词","cn":"额外费用；加付款；加价","en":"A premium is a sum of money that you have to pay for something in addition to the normal cost.","ex":{"en":"Even if customers want 'solutions', most are not willing to pay a premium for them","cn":"即使顾客想得到“解决方案”，他们大多数也不愿意为此支付额外费用。"}},{"pos":"ADJ 形容词","cn":"优质的；高端的","en":"Premium goods are of a higher than usual quality and are often expensive.","ex":{"en":"At the premium end of the market, business is booming.","cn":"高端市场业务繁荣。"}},{"pos":"PHRASE 短语","cn":"紧缺的；稀缺的；难以得到的","en":"If something is at a premium, it is wanted or needed, but is difficult to get or achieve.","ex":{"en":"If space is at a premium, choose adaptable furniture that won't fill the room.","cn":"如果空间有限，就选择一些不会把房间占得很满的可改装家具。"}},{"pos":"PHRASE 短语","cn":"超出平常价，以高价（买进或售出）","en":"If you buy or sell something at a premium, you buy or sell it at a higher price than usual, for example because it is in short supply.","ex":{"en":"He eventually sold the shares back to the bank at a premium.","cn":"他最后以高价把股票回售给银行。"}},{"pos":"PHRASE 短语","cn":"高度重视","en":"If you place a high premium on a quality or characteristic or put a high premium on it, you regard it as very important.","ex":{"en":"I place a high premium on what someone is like as a person","cn":"我非常重视一个人的人品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that you pay for something, especially when it is only one part of the total amount you have to pay","cn":""},{"en":"a regular payment you make to pay back money that you have borrowed or to pay for things that you have already received","cn":""},{"en":"part of the cost of something that you pay before you get it, so that it will not be sold to anyone else","cn":""}]},"vocab":{"pos":"1 n 2 adj n","senses":[{"en":"If your home or business is damaged by fire and you receive a payment from your insurance company, that payment's called a premium ."}]},"collocations":{"phrases":["ADJ. high | additional, extra | price","VERB + PREMIUM pay Electricity companies pay a premium for renewable energy. | charge | place, put","PREMIUM + NOUN price","PREP. at a ~ Good student accommodation is at a premium (= difficult to obtain and therefore expensive) . | ~ of bought at a premium of 40 p","ADJ. annual, monthly, regular | high, low Intense competition has kept premiums low. | insurance","VERB + PREMIUM pay | keep up We're struggling to keep up our premiums. | increase, raise The insurance company has increased our premiums. |","PREMIUM + VERB go up, rise | fall, go down","PREMIUM + NOUN payment, rate"]},"media":{"uk":"media/ldoce/hwd/bre/2/premium_n0205.mp3","us":"media/ldoce/hwd/ame/5/premium.mp3"},"examples":[{"en":"A premium of 10% is paid out after 20 years. * 20","cn":"年后要付清 10% 的额外费用。"},{"en":"Shares are selling at a premium.","cn":"这种股票以高于面值的价格出售。"}],"oxford":{"phon":"ˈpriːmiəm","pos":"noun","senses":[{"en":"an amount of money that you pay once or regularly for an insurance policy","cn":"保险费","lab":"British English","ex":{"en":"a monthly premium of £6.25","cn":"每月 6.25 英镑的保险费"}},{"en":"an extra payment added to the basic rate","cn":"额外费用；附加费","ex":{"en":"You have to pay a high premium for express delivery.","cn":"快递须付高额的附加费。"}},{"en":"very high (and higher than usual); of high quality","cn":"高昂的；优质的","ex":{"en":"premium prices/products","cn":"奇高的价格；优质产品"},"pos":"adjective"}]}},"procession":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（走路、骑马、开车等的）队伍，行列","en":"A procession is a group of people who are walking, riding, or driving in a line as part of a public event.","ex":{"en":"...a funeral procession.","cn":"出殡的队伍"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of people who are standing behind each other or next to each other","cn":""},{"en":"a line of people who have been arranged to stand or sit next to each other, especially when there are several lines of people arranged one behind another","cn":""},{"en":"a number of people who are standing one behind another, waiting to do something","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A procession of mimes walking through the streets of your town would be surprising and somewhat terrifying. A line or group of people moving together in a deliberate way is a procession ."}]},"collocations":{"phrases":["ADJ. grand, great, large, long | little, small | public, street | slow, solemn, stately | colourful | ceremonial | triumphal | constant, end","VERB + PROCESSION head, lead The mayor of the town led the procession to the central square.","PROCESSION + VERB make its way, move, pass, wind (its way) The funeral procession moved slowly down the avenue. The solemn procession wound ","PREP. in (a/the) ~ The children marched in procession behind the band. | ~ of a procession of circus performers"]},"media":{"uk":"media/ldoce/hwd/bre/b/procession0205.mp3","us":"media/ldoce/hwd/ame/d/procession.mp3"},"examples":[{"en":"A procession of waiters appeared bearing trays of food.","cn":"一长列服务生端着一盘一盘饭菜出现了。"},{"en":"Groups of unemployed people from all over the country marched in procession to the capital.","cn":"来自全国的失业群众列队向首都进发。"}],"oxford":{"phon":"prəˈseʃn","pos":"noun","senses":[{"en":"a line of people or vehicles that move along slowly, especially as part of a ceremony; the act of moving in this way","cn":"（人或车辆的）队列，行列；列队行进；游行","g":"[countable, uncountable]","ex":{"en":"a funeral procession","cn":"送葬的队列"}},{"en":"a number of people who come one after the other","cn":"（一个接着一个而来的）一队人，一列人","g":"[countable]","ex":{"en":"A procession of waiters appeared bearing trays of food.","cn":"一长列服务生端着一盘盘食物出现了。"}}]}},"precedence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"优先；优先权","en":"If one thing takes precedence over another, it is regarded as more important than the other thing.","ex":{"en":"Have as much fun as possible at college, but don't let it take precedence over work","cn":"在大学要尽情娱乐，但不要把它看得比学习还重要。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most important thing, which needs to be dealt with before anything else or given more attention than anything else","cn":""},{"en":"something that is urgent must be dealt with or done as soon as possible, especially because something very bad could happen if it is not","cn":""},{"en":"to be the most important and urgent of all the things that have to be done, especially by a government or company","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Notice the verb \"precede\" in the noun precedence , and you'll be able to remember that precedence is the act of preceding, of coming before — either in time or in rank."}]},"collocations":{"phrases":["ADJ. historical","VERB + PRECEDENCE have, take | give sb/sth You should give your schoolwork precedence. | claim The French kings claimed precedence over thos","PREP. ~ over The needs of the patient take precedence over those of the student doctor.","PHRASES in order of precedence The guests were seated strictly in order of precedence."]},"media":{"uk":"media/ldoce/hwd/bre/d/precedence0205.mp3","us":"media/ldoce/hwd/ame/a/precedence.mp3"},"examples":[{"en":"She had to learn that her wishes did not take precedence over other people's needs.","cn":"她必须懂得自己的愿望不能先于别人的需要。"},{"en":"The speakers came on to the platform in order of precedence (= the most important one first).","cn":"演讲人按行辈鱼贯上台。"}],"oxford":{"phon":"ˈpresɪdəns","pos":"noun","senses":[{"en":"the condition of being more important than somebody else and therefore coming or being dealt with first","cn":"优先；优先权","ex":{"en":"She had to learn that her wishes did not take precedence over other people's needs.","cn":"她必须懂得，自己的愿望不能先于别人的需要。"}}]}},"precede":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发生在…之前；先于","en":"If one event or period of time precedes another, it happens before it.","ex":{"en":"Intensive negotiations between the main parties preceded the vote","cn":"主要政党在选举前进行了集中的谈判。"}},{"pos":"VERB 动词","cn":"（顺序、位置）先于，在…前面","en":"If you precede someone somewhere, you go in front of them.","ex":{"en":"He gestured to Alice to precede them from the room","cn":"他给艾丽斯做手势，让她在他们前面离开房间。"}},{"pos":"VERB 动词","cn":"（句、段、章节）在…之前","en":"A sentence, paragraph, or chapter that precedes another one comes just before it.","ex":{"en":"Look at the information that precedes the paragraph in question","cn":"查看正在讨论的这段文字前面的信息。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"before something or someone else in a list, series, or set","cn":""},{"en":"to happen or exist before something or someone else","cn":""},{"en":"before another person in a group of people who are waiting to do something","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To precede is to come before. A short speech will precede the dinner. As you walk down the garden path, the bed of roses precedes the holly bush. When marching into the room, the younger kids precede the older ones."}]},"collocations":{"phrases":["ADV. directly, immediately in the moments which immediately preceded the earthquake"]},"media":{"uk":"media/ldoce/hwd/bre/c/precede0205.mp3","us":"media/ldoce/hwd/ame/5/precede.mp3"},"examples":[{"en":"His resignation was preceded by weeks of speculation.","cn":"在他辞职之前，有关的猜测已持续了几个星期。"},{"en":"She preceded her speech with a vote of thanks to the committee.","cn":"她讲话的开头是对委员会的鸣谢。"}],"oxford":{"phon":"prɪˈsiːd","pos":"verb","senses":[{"en":"to happen before something or come before something/somebody in order","cn":"在…之前发生（或出现）；先于","ex":{"en":"the years preceding the war","cn":"战前的几年"}},{"en":"to go in front of somebody","cn":"走在…前面","ex":{"en":"She preceded him out of the room.","cn":"她先于他走出屋子。"}},{"en":"to do or say something to introduce something else","cn":"以…开始（或引导）","ex":{"en":"She preceded her speech with a vote of thanks to the committee.","cn":"她讲话的开头是对委员会的鸣谢。"}}]}},"proposition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（难办或诱人的）事情，任务","en":"If you describe something such as a task or an activity as, for example, a difficult proposition or an attractive proposition, you mean that it is difficult or pleasant to do.","ex":{"en":"Making easy money has always been an attractive proposition","cn":"轻松赚钱总是件诱人的事。"}},{"pos":"N-COUNT 可数名词","cn":"见解；观点","en":"A proposition is a statement or an idea which people can consider or discuss to decide whether it is true.","ex":{"en":"The proposition that democracies do not fight each other is based on a tiny historical sample.","cn":"认为民主国家互不争斗的观点是以一个极小的历史样本为根据的。"}},{"pos":"N-COUNT 可数名词","cn":"（美国的）法律修正案","en":"In the United States, a proposition is a question or statement about an issue of public policy which appears on a voting paper so that people can vote for or against it.","ex":{"en":"Vote Yes on Proposition 136, but No on Propositions 129, 133 and 134.","cn":"对第136号修正案投赞成票，但对第129号、133号和134号修正案投反对票。"}},{"pos":"N-COUNT 可数名词","cn":"提议；建议；提案","en":"A proposition is an offer or a suggestion that someone makes to you, usually concerning some work or business that you might be able to do together.","ex":{"en":"You came to see me at my office the other day with a business proposition","cn":"几天前你带着一份商业提案来我的办公室见我。"}},{"pos":"VERB 动词","cn":"向…提出下流的要求；向…提出猥亵的要求","en":"If someone who you do not know very well propositions you, they suggest that you have sex with them.","ex":{"en":"He had allegedly tried to proposition a colleague.","cn":"据说他曾试图向一名同事求欢。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that someone suggests","cn":""},{"en":"a formal or official suggestion that something should be done","cn":""},{"en":"a suggestion made, for example, by an official person or group, especially a suggestion that is contained in a report","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A proposition is a proposed plan of action, a detailed suggestion. You might consider your friend's suggestion to set up a neighborhood snow-shoveling business after the blizzard a winning proposition ."}]},"collocations":{"phrases":["ADJ. attractive, tempting | feasible, practical, viable | business, commercial, economic, paying","VERB + PROPOSITION put to sb Ring up your agent in New York and put your proposition to him. 2 problem/task","ADJ. tough, tricky | different He's a different proposition from his father?much less tolerant. 3 idea/opinion","ADJ. basic, central, fundamental | true | extreme | abstract, causal, empirical, ethical, existential, general, theoretical, universal","QUANT. set","VERB + PROPOSITION express, put forward","PROPOSITION + VERB concern sth, relate to sth","PREP. ~ about The book puts forward a number of extreme propositions about the nature of language."]},"media":{"uk":"media/ldoce/hwd/bre/4/proposition_n0205.mp3","us":"media/ldoce/hwd/ame/d/proposition1.mp3"},"examples":[{"en":"Getting a work permit in the UK is not always a simple proposition.","cn":"在英国获得工作许可证往往不是一件简单的事情。"},{"en":"Her assessment is based on the proposition that power corrupts.","cn":"她的分析是建立在权力使人堕落的观点上的。"}],"oxford":{"phon":"ˌprɒpəˈzɪʃn","pos":"noun","senses":[{"en":"an idea or a plan of action that is suggested, especially in business","cn":"提议，建议，计划（尤指业务上的）","ex":{"en":"I'd like to put a business proposition to you.","cn":"我想向您提个业务上的建议。"}},{"en":"a thing that you intend to do; a problem, task or person to be dealt with","cn":"打算做的事；待处理的问题（或事情）；需要应付的人","ex":{"en":"Getting a work permit in the UK is not always a simple proposition.","cn":"在英国获得工作许可证往往不是一件简单的事情。"}},{"en":"(in the US) a suggested change to the law that people can vote on","cn":"（美国）法律修正议案","ex":{"en":"How did you vote on Proposition 8?","cn":"对于第 8 项修正案你是怎么投的票？"}},{"en":"a statement that expresses an opinion","cn":"见解；主张；观点","lab":"formal","ex":{"en":"Her assessment is based on the proposition that power corrupts.","cn":"她的分析是建立在权力使人堕落的观点上的。"}},{"en":"a statement of a theorem, and an explanation of how it can be proved","cn":"命题","lab":"mathematics","ex":{"en":"First of all we need to examine whether this proposition is true.","cn":"首先我们需要检验这个命题是否正确。"}},{"en":"to say in a direct way to somebody that you would like to have sex with them","cn":"求欢","ex":{"en":"She was propositioned by a strange man in the bar.","cn":"酒吧里有个陌生男人向她求欢。"},"pos":"verb"}]}},"prescribe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"开（药、处方）","en":"If a doctor prescribes medicine or treatment for you, he or she tells you what medicine or treatment to have.","ex":{"en":"Our doctor diagnosed a throat infection and prescribed antibiotic and junior aspirin","cn":"我们的医生诊断是喉部感染，并且开了一些抗生素和小剂量阿司匹林。"}},{"pos":"VERB 动词","cn":"（人、法律、规则）规定，指定","en":"If a person or set of laws or rules prescribes an action or duty, they state that it must be carried out.","ex":{"en":"...article II of the constitution, which prescribes the method of electing a president","cn":"规定了总统选举方法的宪法第二条"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say what medicine or treatment a sick person should have","cn":"开〔药〕；给…开处方"},{"en":"to state officially what should be done in a particular situation","cn":"规定﹐指定"}]},"vocab":{"pos":"v","senses":[{"en":"To prescribe is make orders or give directions for something to be done. These days, the word is mainly used by doctors who prescribe medications to take."}]},"collocations":{"phrases":["ADV. legally The drug can no longer be legally prescribed. | medically, medicinally","PREP. for drugs prescribed for high blood pressure This drug is often prescribed for women with heart trouble. 2 what should/should not be d","ADV. narrowly, rigidly, strictly, tightly The curriculum is rigidly prescribed from an early age. Everything about her life was strictly pre"]},"media":{"uk":"media/ldoce/hwd/bre/b/prescribe0205.mp3","us":"media/ldoce/hwd/ame/5/prescribe.mp3"},"examples":[{"en":"Police regulations prescribe that an officer's number must be clearly visible.","cn":"警政制度规定，警察的番号必须清晰可见。"},{"en":"The prescribed form must be completed and returned to this office.","cn":"必须把指定的表格填好并交回本办事处。"}],"oxford":{"phon":"prɪˈskraɪb","pos":"verb","senses":[{"en":"to tell somebody to take a particular medicine or have a particular treatment; to write a prescription for a particular medicine, etc.","cn":"给…开（药）；让…采用（疗法）；开（处方）","ex":{"en":"Valium is usually prescribed to treat anxiety.","cn":"安定剂通常用于治疗焦躁。"}},{"en":"to say what should be done or how something should be done","cn":"规定；命令；指示","ex":{"en":"The prescribed form must be completed and returned to this office.","cn":"必须把指定的表格填好并交回本办事处。"}}]}},"projector":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"投影仪；放映机","en":"A projector is a machine that projects films or slides onto a screen or wall.","ex":{"en":"...a 35-millimetre slide projector.","cn":"35毫米的幻灯机"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that makes a film or picture appear on a screen or flat surface","cn":"电影放映机﹔投影仪"}]},"collocations":{"phrases":["ADJ. overhead | cine, film, slide, video","VERB + PROJECTOR switch off/on | operate"]},"media":{"uk":"media/ldoce/hwd/bre/1/projector0205.mp3","us":"media/ldoce/hwd/ame/8/projector.mp3"},"oxford":{"phon":"prəˈdʒektə(r)","pos":"noun","senses":[{"en":"a piece of equipment for projecting photographs, films or computer slides onto a screen","cn":"放映机；投影仪"}]}},"premonition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指不祥的）预感，预兆","en":"If you have a premonition, you have a feeling that something is going to happen, often something unpleasant.","ex":{"en":"He had an unshakable premonition that he would die.","cn":"他有一种强烈的预感，觉得自己会死。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to know that something is going to happen before it actually happens","cn":""},{"en":"to have a clear idea of something that will happen in the future, especially important changes in a situation","cn":""},{"en":"to know or think you know what is going to happen because there are signs that it will","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Some people claim to have premonitions , such as a dream about a friend they haven't seen in years the night before the friend dies. A premonition is a warning that comes in advance, or a feeling that something is going to happen."}]},"collocations":{"phrases":["ADJ. shudder","VERB + PREMONITION feel, have","PREP. ~ about Perhaps he had a premonition about what might happen in London. | ~ of I wonder if she had a premonition of her own fate."]},"media":{"uk":"media/ldoce/hwd/bre/7/premonition0205.mp3","us":"media/ldoce/hwd/ame/b/premonition.mp3"},"examples":[{"en":"He had a premonition that he would never see her again.","cn":"他有一种再也见不到她的预感。"},{"en":"( formal ) a premonitory dream","cn":"预兆性的梦"}],"oxford":{"phon":"ˌpreməˈnɪʃn","pos":"noun","senses":[{"en":"a feeling that something is going to happen, especially something unpleasant","cn":"（尤指不祥的）预感","ex":{"en":"a premonition of disaster","cn":"大祸临头的预感"}}]}},"pram":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿车","en":"A pram is a small vehicle in which a baby can lie as it is pushed along."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small vehicle with four wheels in which a baby can lie down while it is being pushed （","cn":"四轮手推）婴儿车"}]},"collocations":{"phrases":["VERB + PRAM push, wheel","PREP. in a/the ~ She was pushing her baby along in a pram."]},"media":{"uk":"media/ldoce/hwd/bre/2/pram0205.mp3","us":"media/ldoce/hwd/ame/2/ld41pram.mp3","img":["media/thumb/pram.jpg"]},"examples":[{"en":"a young woman pushing a pram","cn":"推着婴儿车的年轻女子"}],"oxford":{"phon":"præm","pos":"noun","senses":[{"en":"a small vehicle on four wheels for a baby to go out in, pushed by a person on foot","cn":"婴儿车","ex":{"en":"She was pushing her baby along in a pram.","cn":"她把宝宝放在婴儿车里推着走。"}}]}},"pregnancy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"怀孕（期）；妊娠（期）","en":"Pregnancy is the condition of being pregnant or the period of time during which a female is pregnant.","ex":{"en":"It would be wiser to cut out all alcohol during pregnancy","cn":"在怀孕期间最好滴酒不沾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the length of time a human or animal baby develops in its mother's body","cn":""},{"en":"if a woman has a miscarriage the baby comes out of her body far too early for it to be able to live","cn":""},{"en":"a baby that is stillborn is born dead but fully developed","cn":""}]},"collocations":{"phrases":["ADJ. early | late | full-term, post-term | easy, healthy, normal | difficult She had a difficult pregnancy with her first child. | teenage |","VERB + PREGNANCY have | avoid, prevent taking precautions to avoid pregnancy | continue (with), keep the difficult decision about whether to","PREGNANCY + VERB be at/go to (full) term","PREGNANCY + NOUN test a home pregnancy test kit","PREP. during/in (a/the) ~ Lower blood pressure is common in early pregnancy. | throughout (a/the) ~ You will be tested throughout your pregn"]},"media":{"uk":"media/ldoce/hwd/bre/2/pregnancy0205.mp3","us":"media/ldoce/hwd/ame/a/pregnancy.mp3"},"examples":[{"en":"Many women experience sickness during pregnancy.","cn":"许多妇女在怀孕期都会有恶心现象。"},{"en":"the increase in teenage pregnancies","cn":"十几岁少女怀孕率的上升"}],"oxford":{"phon":"ˈpreɡnənsi","pos":"noun","senses":[{"en":"the state of being pregnant","cn":"妊娠；怀孕","lab":"especially US English","ex":{"en":"a pregnancy test","cn":"妊娠检查"}}]}},"profile":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"侧面像；侧影像","en":"Your profile is the outline of your face as it is seen when someone is looking at you from the side.","ex":{"en":"His handsome profile was turned away from us.","cn":"他英俊的侧影从我们眼前转开了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（从）侧面（看）","en":"If you see someone in profile, you see them from the side.","ex":{"en":"This picture shows the girl in profile.","cn":"这张照片照的是女孩的侧面。"}},{"pos":"N-COUNT 可数名词","cn":"人物简介；传略","en":"A profile of someone is a short article or programme in which their life and character are described.","ex":{"en":"A newspaper published profiles of the candidates' wives.","cn":"一家报纸刊登了几位候选人夫人的简介。"}},{"pos":"VERB 动词","cn":"为…作传略","en":"To profile someone means to give an account of that person's life and character.","ex":{"en":"Tamar Golan, a Paris-based journalist, profiles the rebel leader.","cn":"驻巴黎记者塔玛·戈兰对反叛者的首领进行了介绍。"}},{"pos":"PHRASE 短语","cn":"高调/低调；高姿态/低姿态","en":"If someone has a high profile, people notice them and what they do. If you keep a low profile, you avoid doing things that will make people notice you.","ex":{"en":"...a move that would give Egypt a much higher profile in the upcoming peace talks","cn":"能使埃及在未来的和谈中更加引人关注的举动"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make a special effort to be normal, inoffensive, or quiet, so that people will not pay attention to you","cn":""},{"en":"to make someone pay attention to one thing or person, either deliberately or without intending to, so that they do not pay attention to another","cn":""},{"en":"to make someone stop paying attention to something important, either deliberately or without intending to","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"If a magazine editor asks you to write a profile of an up-and-coming novelist, she's asking you to write a biographical sketch, to give the readers a sense of the novelist as a person."}]},"collocations":{"phrases":["ADJ. beautiful, handsome | strong | three-quarter","VERB + PROFILE present","PREP. in ~ The painting shows her in profile.","PHRASES sb's best profile He presented his best profile to the camera. 2 description of sb/sth","ADJ. detailed | age, career, psychological | company, customer | financial, social","VERB + PROFILE build up, construct, develop","PREP. ~ of The data will enable us to construct a profile of the firm's customers. 3 public image","ADJ. high, low She decided to keep a low profile until the scandal had died down. | public | political | corporate"]},"media":{"img":["media/ldoce/img/ldoce_273.png"],"uk":"media/ldoce/hwd/bre/9/profile_n0205.mp3","us":"media/ldoce/hwd/ame/5/profile1.mp3"},"examples":[{"en":"We first build up a detailed profile of our customers and their requirements.","cn":"首先，我们建立起我们的客户及其需求的详细资料。"},{"en":"You can update your Facebook profile (= your description of yourself on a social networking website).","cn":"你可以更新你在“脸谱”网站上的个人资料。"}],"oxford":{"phon":"ˈprəʊfaɪl","pos":"noun","senses":[{"en":"a description of somebody/something that gives useful information","cn":"概述；简介；传略","ex":{"en":"We first build up a detailed profile of our customers and their requirements.","cn":"首先，我们建立起我们的客户及其需求的详细资料。"}},{"en":"the general impression that somebody/something gives to the public and the amount of attention they receive","cn":"印象；形象","ex":{"en":"Her popularity has done great things for the profile of the sport.","cn":"她的知名度对推广这项运动已经起到非常大的作用。"}},{"en":"the outline of a person’s face when you look from the side, not the front","cn":"面部的侧影；侧面轮廓","ex":{"en":"his strong profile","cn":"他轮廓清晰的侧影"}},{"en":"the edge or outline of something that you see against a background","cn":"外形；轮廓","ex":{"en":"the profile of the tower against the sky","cn":"天空映衬下塔楼的轮廓"}},{"en":"to give or write a description of somebody/something that gives the most important information","cn":"扼要介绍；概述；写简介","ex":{"en":"His career is profiled in this month's journal.","cn":"这期月刊概述了他的工作生涯。"},"pos":"verb"}]}},"predicament":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"困境；艰难的处境；尴尬的境地","en":"If you are in a predicament, you are in an unpleasant situation that is difficult to get out of.","ex":{"en":"Hank explained our predicament","cn":"汉克说明了我们的艰难处境。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a difficult or unpleasant situation in which you do not know what to do, or in which you have to make a difficult choice","cn":"困境﹐窘况﹐尴尬的处境"}]},"vocab":{"pos":"n","senses":[{"en":"If you're engaged to get married, but suddenly fall in love with someone else, you have got yourself in quite a predicament. A predicament is a difficult, confusing, and unpleasant situation."}]},"collocations":{"phrases":["ADJ. awful, awkward, dire, worse Other companies are in an even worse predicament than ourselves. | current, present | financial, personal","VERB + PREDICAMENT be in, find yourself in, get into Many young people find themselves in this predicament. | place sb in, put sb in | escap","PREP. in a/the ~ Now I really wa s in a dire predicament ."]},"media":{"uk":"media/ldoce/hwd/bre/6/predicament0205.mp3","us":"media/ldoce/hwd/ame/e/predicament.mp3"},"examples":[{"en":"I'm in a terrible predicament.","cn":"我的处境十分尴尬。"},{"en":"the club's financial predicament","cn":"俱乐部的财政困境"}],"oxford":{"phon":"prɪˈdɪkəmənt","pos":"noun","senses":[{"en":"a difficult or an unpleasant situation, especially one where it is difficult to know what to do","cn":"尴尬的处境；困境；窘境","ex":{"en":"the club’s financial predicament","cn":"俱乐部的财政困境"}}]}},"prostitution":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"卖淫","en":"Prostitution means having sex with people in exchange for money.","ex":{"en":"She eventually drifts into prostitution.","cn":"她最终沦为妓女。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, usually a woman, who has sex with people for money","cn":""},{"en":"a woman who has sex with men for money","cn":""},{"en":"a woman who has sex with men for money and arranges to meet them by telephone","cn":""}]},"collocations":{"phrases":["ADJ. child, female, juvenile, male","VERB + PROSTITUTION be involved in | turn to Some turned to prostitution in order to survive.","PROSTITUTION + NOUN trade There is a long-standing prostitution trade in the port."]},"media":{"uk":"media/ldoce/hwd/bre/c/prostitution0205.mp3","us":"media/ldoce/hwd/ame/f/prostitution.mp3"},"examples":[{"en":"Many women were forced into prostitution.","cn":"许多妇女被迫为娼。"},{"en":"child prostitution","cn":"儿童卖淫"}],"oxford":{"phon":"ˌprɒstɪˈtjuːʃn","pos":"noun","senses":[{"en":"the work of a prostitute","cn":"卖淫；为娼；当男妓","ex":{"en":"Many women were forced into prostitution.","cn":"许多妇女被迫为娼。"}},{"en":"the use of your abilities on something of little value","cn":"才能的滥用（或糟蹋）","lab":"formal"}]}},"practise":{"collins":{"senses":[{"pos":"VERB 动词","cn":"练习；训练","en":"If you practise something, you keep doing it regularly in order to be able to do it better.","ex":{"en":"Lauren practises the piano every day","cn":"劳伦每天练习钢琴。"}},{"pos":"VERB 动词","cn":"奉行（风俗、宗教等活动）；实践（手艺）","en":"When people practise something such as a custom, craft, or religion, they take part in the activities associated with it.","ex":{"en":"...countries which practise multi-party politics","cn":"实行多党政体的国家"}},{"pos":"VERB 动词","cn":"干（坏事）；作（恶）；施（虐）","en":"If something cruel is regularly done to people, you can say that it is practised on them.","ex":{"en":"There are consistent reports of electrical torture being practised on inmates.","cn":"一直有报道称犯人被施以电刑。"}},{"pos":"VERB 动词","cn":"从（医）；从事（律师工作）；执业","en":"Someone who practises medicine or law works as a doctor or a lawyer.","ex":{"en":"In Belgium only qualified doctors may practise alternative medicine","cn":"在比利时只有资质合格的医生才能从事非传统医学工作。"}},{"pos":"","cn":"","en":"to practise what you preach→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do an activity many times in order to improve your skill or to prepare for a test","cn":"练习"},{"en":"to practise physical movements or activities in preparation for a race or game","cn":"训练"},{"en":"to practise a play, speech, or music in preparation for a public performance","cn":"排练，预演"}]},"vocab":{"pos":"v","senses":[{"en":"The word practise is a variant spelling for the verb practice . American English spells both the noun and verb forms practice . For the Brits, the noun form is still spelled practice , but the verb is practise ."}]},"collocations":{"phrases":["ADV. hard | regularly","PREP. for She's practising hard for the piano competition. | on I learned hairdressing by practising on my sister."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdepractise.mp3","us":"media/ldoce/hwd/ame/d/laadpractise.mp3"},"examples":[{"en":"There are over 50 000 solicitors practising in England and Wales.","cn":"英格兰和威尔士共有 5 万多名律师执业。"},{"en":"Do you still practise your religion?","cn":"你还奉行你的宗教信仰吗？"}],"oxford":{"phon":"ˈpræktɪs","pos":"verb","senses":[{"en":"to do an activity or train regularly so that you can improve your skill","cn":"练习；实习；训练","g":"[intransitive, transitive]","ex":{"en":"You need to practise every day.","cn":"你需要每天练习。"}},{"en":"to work as a doctor, lawyer, etc.","cn":"从事（医务、法律工作等）；执业","g":"[intransitive, transitive]","ex":{"en":"There are over 50 000 solicitors practising in England and Wales.","cn":"英格兰和威尔士共有 5 万多名律师执业。"}},{"en":"to do something regularly as part of your normal behaviour","cn":"经常做；养成…的习惯","g":"[transitive]","lab":"formal","ex":{"en":"to practise self-restraint/safe sex","cn":"培养自制力；实行安全性行为"}}]}},"prejudice":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"偏见；成见","en":"Prejudice is an unreasonable dislike of a particular group of people or things, or a preference for one group of people or things over another.","ex":{"en":"There was a deep-rooted racial prejudice long before the two countries became rivals and went to war","cn":"早在这两个国家成为敌人并且兵戎相见之前，它们之间就有了根深蒂固的种族偏见。"}},{"pos":"VERB 动词","cn":"使有成见；使有偏见；使出现偏袒","en":"If you prejudice someone or something, you influence them so that they are unfair in some way.","ex":{"en":"I think your South American youth has prejudiced you","cn":"我认为你在南美度过的青少年时代让你产生了偏见。"}},{"pos":"VERB 动词","cn":"损害；危害；使更糟糕","en":"If someone prejudices another person's situation, they do something which makes it worse than it should be.","ex":{"en":"Her study was not in any way intended to prejudice the future development of the college","cn":"她的研究绝对无意损害这所大学未来的发展。"}},{"pos":"PHRASE 短语","cn":"无损于；没有对…造成不利；没有对…带来改变","en":"If you take an action without prejudice to an existing situation, your action does not change or harm that situation.","ex":{"en":"We accept the outcome of the inquiry, without prejudice to the unsettled question of territorial waters.","cn":"我们接受了调查结果，并没有使悬而未决的领海问题进一步恶化。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable dislike and distrust of people who are different from you in some way, especially because of their race, sex, religion etc 〔","cn":"尤指基于种族、性别、宗教等的〕偏见，歧视"},{"en":"the practice of treating one group of people differently from another in an unfair way","cn":"歧视"},{"en":"an unreasonable refusal to accept beliefs, customs, and ways of thinking that are different from your own","cn":"不容异己，偏狭"}]},"vocab":{"pos":"n v","senses":[{"en":"If you have a negative attitude towards someone based on race or ethnicity rather than personal experience, you might be accused of prejudice ."}]},"collocations":{"phrases":["ADJ. deep, deep-rooted, deep-seated, strong | blatant | serious, unfair (both law) | personal | old It's hard to break down old prejudices. ","VERB + PREJUDICE have, hold We all have prejudices of some kind. | air, express He sat there airing his personal prejudices. | arouse, feed,","PREP. ~ about a book written to challenge prejudices about disabled people | ~ against deep-rooted prejudice against homosexuals | ~ among p","PHRASES a victim of prejudice"]},"media":{"uk":"media/ldoce/hwd/bre/b/prejudice_n0205.mp3","us":"media/ldoce/hwd/ame/1/prejudice1.mp3"},"examples":[{"en":"There is little prejudice against workers from other EU states.","cn":"对来自其他欧盟国家的劳工可说并无偏见。"},{"en":"The prosecution lawyers have been trying to prejudice the jury against her.","cn":"控方律师一直力图使陪审团对她产生偏见。"}],"oxford":{"phon":"ˈpredʒədɪs","pos":"noun","senses":[{"en":"an unreasonable dislike of or preference for a person, group, custom, etc., especially when it is based on their race, religion, sex, etc.","cn":"偏见；成见","lab":"British English","ex":{"en":"a victim of racial prejudice","cn":"种族偏见的受害者"}},{"en":"to influence somebody so that they have an unfair or unreasonable opinion about somebody/something","cn":"使怀有（或产生）偏见","ex":{"en":"The prosecution lawyers have been trying to prejudice the jury against her.","cn":"控方律师一直力图使陪审团对她产生偏见。"},"pos":"verb"},{"en":"to have a harmful effect on something","cn":"损害；有损于","lab":"formal","ex":{"en":"Any delay will prejudice the child's welfare.","cn":"任何延误都会损及这个孩子的身心健康。"},"pos":"verb"}]}},"protein":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"蛋白质","en":"Protein is a substance found in food and drink such as meat, eggs, and milk. You need protein in order to grow and be healthy.","ex":{"en":"Fish was a major source of protein for the working man.","cn":"鱼肉曾是劳动者的主要蛋白质来源。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of several natural substances that exist in food such as meat, eggs, and beans, and which your body needs in order to grow and remain strong and healthy","cn":"蛋白质"}]},"vocab":{"pos":"n","senses":[{"en":"Protein makes up your nails, your hair, and the egg on your plate. This nitrogenous substance we call protein consists of chains of amino acids and is necessary for life functions."}]},"collocations":{"phrases":["ADJ. essential | natural | animal, vegetable","VERB + PROTEIN be high/rich in, contain, supply Cereals supply essential protein and vitamins. | produce","PROTEIN + NOUN content | intake | deficiency","PHRASES a high/low protein diet, a source of protein"]},"media":{"uk":"media/ldoce/hwd/bre/e/protein0205.mp3","us":"media/ldoce/hwd/ame/1/protein.mp3"},"examples":[{"en":"Peas, beans and lentils are a good source of vegetable protein.","cn":"豌豆、豆荚和扁豆是植物蛋白质的丰富来源。"},{"en":"essential proteins and vitamins","cn":"必不可少的蛋白质和维生素"}],"oxford":{"phon":"ˈprəʊtiːn","pos":"noun","senses":[{"en":"a substance, found within all living things, that forms the structure of muscles, organs, etc. There are many different proteins and they are an essential part of what humans and animals eat to help them grow and stay healthy.","cn":"蛋白质","ex":{"en":"essential proteins and vitamins","cn":"必不可少的蛋白质和维生素"}}]}},"progression":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"进展；发展；演变","en":"A progression is a gradual development from one state to another.","ex":{"en":"Both drugs slow the progression of HIV, but neither cures the disease","cn":"这两种药物都可以延缓艾滋病病情发展，但是都不能治愈这种疾病。"}},{"pos":"N-COUNT 可数名词","cn":"（事件的）一连串，一系列，连续","en":"A progression of things is a number of things which come one after the other.","ex":{"en":"...a progression of habitats from dry meadows through marshes to open water.","cn":"从干燥的草地到沼泽地再到开阔的水面的一系列栖息地"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long, gradual process during which something develops and changes, usually becoming more advanced","cn":""},{"en":"a development from one situation or state to a better or more advanced one","cn":""},{"en":"a gradual process of change or development","cn":"变化﹐发展"}]},"vocab":{"pos":"n","senses":[{"en":"A progression is a series that advances in a logical and predictable pattern. In mathematics, for example, the series 2, 4, 6, 8 is an arithmetic progression . If asked to give the next number, most people would reply 10."}]},"collocations":{"phrases":["ADJ. rapid | gradual, slow, steady | smooth | upward | linear, logical, natural By a logical progression of thought, she worked out why the ","PREP. ~ from &hellip; to &hellip; his progression from chubby teenager to handsome movie star | ~ through Her progression through the grades","PHRASES the progression of a disease one of the later stages in the progression of the disease"]},"media":{"uk":"media/ldoce/hwd/bre/1/progression0205.mp3","us":"media/ldoce/hwd/ame/2/progression.mp3"},"examples":[{"en":"a natural progression from childhood to adolescence","cn":"从童年到青少年的自然过渡"},{"en":"the rapid progression of the disease","cn":"病情的迅速发展"}],"oxford":{"phon":"prəˈɡreʃn","pos":"noun","senses":[{"en":"the process of developing gradually from one stage or state to another","cn":"（进入另一阶段的）发展；前进；进程","g":"[uncountable, countable]","ex":{"en":"opportunities for career progression","cn":"事业发展的机遇"}},{"en":"a number of things that come in a series","cn":"系列；序列；连续","g":"[countable]"}]}},"prophecy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"预言","en":"A prophecy is a statement in which someone says they strongly believe that a particular thing will happen.","ex":{"en":"The youth, too, fulfilled the prophecy.","cn":"那个年轻人，同样地，让预言说中了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement saying what you think will happen in the future","cn":""},{"en":"a public statement saying what is likely to happen with the weather or with the economic or political situation, based on special or technical knowledge","cn":""},{"en":"a statement that says something will happen, especially made by someone with religious or magical powers","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If a fortune teller made a prophecy that you were going to become a billionaire in your lifetime, you'd be pretty excited. A prophecy is a prediction, or a magical look into the future."}]},"collocations":{"phrases":["ADJ. Biblical, Messianic, Old Testament | self-fulfilling low expectations that become a self-fulfilling prophecy","VERB + PROPHECY make | fulfil","PREP. ~ about Macbeth believed the witches' prophecy about his future. | ~ of The poem contains a bleak prophecy of war and ruin.","PHRASES the gift of prophecy"]},"media":{"uk":"media/ldoce/hwd/bre/c/prophecy0205.mp3","us":"media/ldoce/hwd/ame/0/laadprophecy.mp3"},"examples":[{"en":"She was believed to have the gift of prophecy.","cn":"据信她有预言的天赋。"},{"en":"to fulfil a prophecy (= make it come true)","cn":"实现预言"}],"oxford":{"phon":"ˈprɒfəsi","pos":"noun","senses":[{"en":"a statement that something will happen in the future, especially one made by somebody with religious or magic powers","cn":"预言","g":"[countable]","ex":{"en":"to fulfil a prophecy (= make it come true)","cn":"实现预言"}},{"en":"the power of being able to say what will happen in the future","cn":"预言能力","g":"[uncountable]","lab":"formal","ex":{"en":"She was believed to have the gift of prophecy.","cn":"据信她有预言的天赋。"}}]}},"prescription":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"处方；药方","en":"A prescription is the piece of paper on which your doctor writes an order for medicine and which you give to a chemist or pharmacist to get the medicine.","ex":{"en":"You will have to take your prescription to a chemist.","cn":"你得拿着处方去找药剂师。"}},{"pos":"N-COUNT 可数名词","cn":"处方药","en":"A prescription is a medicine which a doctor has told you to take.","ex":{"en":"The prescription Ackerman gave me isn't doing any good.","cn":"阿克曼给我开的药没有任何疗效。"}},{"pos":"N-COUNT 可数名词","cn":"对策；解决方案","en":"A prescription is a proposal or a plan which gives ideas about how to solve a problem or improve a situation.","ex":{"en":"...the economic prescriptions of Ireland's main political parties.","cn":"爱尔兰主要政党的经济对策"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of paper on which a doctor writes what medicine a sick person should have, so that they can get it from a pharmacist","cn":"处方﹐药方"},{"en":"a particular medicine or treatment ordered by a doctor for a sick person 〔","cn":"医生开的〕处方药﹔治疗方法"},{"en":"a drug that you get on prescription can only be obtained with a written order from the doctor","cn":"凭处方的﹐根据药方的"}]},"vocab":{"pos":"n adj","senses":[{"en":"A prescription is an order written by a doctor for someone to get a drug that is not available without this permission. If you get a bad ear infection, you'll need a prescription for antibiotics."}]},"collocations":{"phrases":["ADJ. medical | free people who get free prescriptions | repeat I just get a repeat prescription every week.","VERB + PRESCRIPTION give sb, write (out) | make up Would you like to wait while the pharmacist makes up your prescription?","PRESCRIPTION + NOUN charge | drug, medicine","PREP. on ~ Some drugs are only available on prescription. | ~ for the usual prescription for asthma She gave him a prescription for antibiot"]},"media":{"uk":"media/ldoce/hwd/bre/d/prescription0205.mp3","us":"media/ldoce/hwd/ame/c/prescription.mp3"},"examples":[{"en":"They are not available without a prescription.","cn":"这些药没有处方不能出售。"},{"en":"The pharmacist will make up your prescription.","cn":"药剂师会给你依处方配药。"}],"oxford":{"phon":"prɪˈskrɪpʃn","pos":"noun","senses":[{"en":"an official piece of paper on which a doctor writes the type of medicine you should have, and which enables you to get it from a chemist's","cn":"处方；药方","g":"[countable]","lab":"British English","ex":{"en":"The doctor gave me a prescription for antibiotics.","cn":"医生给我开了抗生素。"}},{"en":"medicine that your doctor has ordered for you","cn":"医生开的药","g":"[countable]","ex":{"en":"The pharmacist will make up your prescription.","cn":"药剂师会给你依处方配药。"}},{"en":"the act of prescribing medicine","cn":"开处方；开药","g":"[uncountable]","ex":{"en":"The prescription of drugs is a doctor's responsibility.","cn":"开药是医生的责任。"}},{"en":"a plan or a suggestion for making something happen or for improving it","cn":"计划；建议；秘诀","g":"[countable]","lab":"formal","ex":{"en":"a prescription for happiness","cn":"增进幸福的秘诀"}}]}},"proficiency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"熟练；精通","en":"If you show proficiency in something, you show ability or skill at it.","ex":{"en":"Evidence of basic proficiency in English is part of the admission requirement.","cn":"英语基本熟练是入学条件之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a good standard of ability and skill","cn":"熟练﹔精通"}]},"vocab":{"pos":"n","senses":[{"en":"If you have proficiency with something, you are pretty good at it. If you have proficiency with Spanish, you can understand and communicate well in that language."}]},"collocations":{"phrases":["ADJ. considerable, great | technical | language, oral, reading, written | cycling, skiing, etc.","QUANT. degree, level He taught himself to carve to a high degree of proficiency.","VERB + PROFICIENCY acquire, develop, increase He acquired greater proficiency after a three-month intensive course. | demonstrate, show","PROFICIENCY + NOUN examination, test a language proficiency test | certificate","PREP. ~ in a certificate for proficiency in English"]},"media":{"uk":"media/ldoce/hwd/bre/7/proficiency0205.mp3","us":"media/ldoce/hwd/ame/2/laadproficiency.mp3"},"examples":[{"en":"a high level of oral proficiency in English","cn":"一口流利的英语"},{"en":"to develop proficiency","cn":"提高熟练程度"}],"oxford":{"phon":"prəˈfɪʃnsi","pos":"noun","senses":[{"en":"the ability to do something well because of training and practice","cn":"熟练;精通","ex":{"en":"to develop proficiency","cn":"提高熟练程度"}}]}},"presidency":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总统职位；总裁职位；主席职位","en":"The presidency of a country or organization is the position of being the president or the period of time during which someone is president.","ex":{"en":"Britain will support him as a candidate for the presidency of the organisation","cn":"英国会支持他竞选这个组织的主席职位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the position of being the president of a country or organization, or the period of time during which someone is president","cn":"总统[主席﹐总裁]的职位[任期]"}]},"collocations":{"phrases":["ADJ. directly-elected | executive, federal","VERB + PRESIDENCY be nominated for, run for, stand for | be elected to | assume, take on/over | hold She held the presidency of the associat","PREP. into sb's ~ Three years into his presidency, he is more popular than ever. | under sb's ~ under the presidency of George W. Bush."]},"media":{"uk":"media/ldoce/hwd/bre/1/presidency0205.mp3","us":"media/ldoce/hwd/ame/5/presidency.mp3"},"examples":[{"en":"He was a White House official during the Bush presidency.","cn":"他是布什任总统时的白宫官员。"},{"en":"the current holder of the EU presidency","cn":"现任欧盟主席"}],"oxford":{"phon":"ˈprezɪdənsi","pos":"noun","senses":[{"en":"the job of being president of a country or an organization; the period of time somebody holds this job","cn":"总统（或主席）的职位；总统（或主席）任期","ex":{"en":"the current holder of the EU presidency","cn":"现任欧盟主席"}}]}},"probation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"缓刑期","en":"Probation is a period of time during which a person who has committed a crime has to obey the law and be supervised by a probation officer, rather than being sent to prison.","ex":{"en":"The thief was put on probation for two years.","cn":"这个小偷被处以两年缓刑。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"试用期；见习期","en":"Probation is a period of time during which someone is judging your character and ability while you work, in order to see if you are suitable for that type of work.","ex":{"en":"Employee appointment to the Council will be subject to a term of probation of 6 months","cn":"被任命到理事会的员工将有6个月的见习期。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a system that allows some criminals not to go to prison or to leave prison, if they behave well and see a probation officer regularly, for a particular period of time","cn":"缓刑（制）"},{"en":"a period of time, during which an employer can see if a new worker is suitable","cn":"试用（期）﹐见习（期）"},{"en":"a period of time in which you must improve your work or behave well so that you will not have to leave your job 〔","cn":"留任〕察看期"}]},"vocab":{"pos":"n","senses":[{"en":"A probation is a period of time when a criminal needs to be on their best behavior: they're not in jail (yet or anymore) but they have to do certain things demanded by the court."}]},"collocations":{"phrases":["ADJ. give sb, place sb on, put sb on, sentence sb to He was placed on probation for two years. She was sentenced to a year's probation. | re","PROBATION + NOUN order He was under a probation order for attacking a photographer. | officer | service | hostel | period Once your probatio","PREP. on ~ The judge put her on probation for a year. He joined the company on six months' probation."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeprobation.mp3","us":"media/ldoce/hwd/ame/a/probation.mp3"},"examples":[{"en":"He was given two years' probation.","cn":"他被判缓刑两年。"},{"en":"The prisoner was put on probation.","cn":"犯人已获缓刑。"}],"oxford":{"phon":"prəˈbeɪʃn","pos":"noun","senses":[{"en":"a system that allows a person who has committed a crime not to go to prison if they behave well and if they see an official (called a probation officer) regularly for a fixed period of time","cn":"缓刑制；缓刑","lab":"law","ex":{"en":"He was given two years' probation.","cn":"他被判缓刑两年。"}},{"en":"a time of training and testing when you start a new job to see if you are suitable for the work","cn":"试用期；见习期；考察期","ex":{"en":"a period of probation","cn":"试用期"}},{"en":"a fixed period of time during which a student who has behaved badly or not worked hard must improve their work or their behaviour","cn":"试读，试读期（为表现不理想的学生而设）","lab":"North American English"}]}},"proxy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"代表；代替","en":"If you do something by proxy, you arrange for someone else to do it for you.","ex":{"en":"Those not attending the meeting may vote by proxy.","cn":"那些未出席会议的可以请他人代为投票。"}},{"pos":"N-COUNT 可数名词","cn":"代理人；代替者；替代物","en":"A proxy is a person or thing that is acting or being used in the place of someone or something else.","ex":{"en":"Price differences are used as a proxy for differences in quality.","cn":"一分钱一分货。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do something by proxy, you arrange for someone else to do it for you","cn":"由委托人代理"},{"en":"someone who you choose to represent you, especially to vote for you 〔","cn":"由个人委托的〕代理人﹐代表〔尤指代人投票〕"},{"en":"something used to represent something else that you want to measure 〔","cn":"用于度量某物的〕指标"}]},"vocab":{"pos":"n","senses":[{"en":"Don't feel like going to the grocery store today? See if you can send your brother as a proxy , meaning he's a substitute authorized to act for you."}]},"collocations":{"phrases":["VERB + PROXY appoint You may appoint a proxy to vote for you.","PROXY + VERB vote | attend (sth) Your proxy may attend the meeting if you are unable to attend.","PROXY + NOUN vote, voting | card, form","PREP. by ~ If you will not be able to vote on polling day, you may vote by proxy. | ~ for Husbands are discouraged from voting as proxy for ","PHRASES a form of proxy We enclose a form of proxy for use at the Annual General Meeting."]},"media":{"uk":"media/ldoce/hwd/bre/c/proxy_n0205.mp3","us":"media/ldoce/hwd/ame/b/proxy.mp3"},"examples":[{"en":"The number of patients on a doctor's list was seen as a good proxy for assessing how hard they work.","cn":"医生诊单上的病人数被看作是衡量他们工作努力程度的可靠指标。"},{"en":"Your proxy will need to sign the form on your behalf.","cn":"你的代理人将须代表你在表格上签字。"}],"oxford":{"phon":"ˈprɒksi","pos":"noun","senses":[{"en":"the authority that you give to somebody to do something for you, when you cannot do it yourself","cn":"代理权；代表权","g":"[uncountable]","ex":{"en":"You can vote either in person or by proxy.","cn":"你可以亲自投票或请人代理。"}},{"en":"a person who has been given the authority to represent somebody else","cn":"代理人；受托人；代表","g":"[countable, uncountable]","ex":{"en":"Your proxy will need to sign the form on your behalf.","cn":"你的代理人将须代表你在表格上签字。"}},{"en":"something that you use to represent something else that you are trying to measure or calculate","cn":"（测算用的）代替物，指标","g":"[countable]","lab":"formal or specialist","ex":{"en":"The number of patients on a doctor's list was seen as a good proxy for assessing how hard they work.","cn":"医生诊单上的病人数被看作是衡量他们工作努力程度的可靠指标。"}}]}},"prostitute":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妓女；娼妓","en":"A prostitute is a person, usually a woman, who has sex with men in exchange for money.","ex":{"en":"He admitted last week he paid for sex with a prostitute.","cn":"他承认上个星期嫖娼了。"}},{"pos":"VERB 动词","cn":"（使）沦为娼妓","en":"If someone prostitutes a woman or if a woman prostitutes herself, she has sex or is made to have sex with men for money.","ex":{"en":"...this terrible story of famine and a woman who's forced to prostitute herself in order to get food.","cn":"这个关于饥荒和一个女人为了糊口被迫沦为娼妓的悲惨故事"}},{"pos":"VERB 动词","cn":"（为名利）出卖（才能）","en":"If you prostitute yourself or your talents, you do work for money or to be famous, rather than because you think it is good work or the right thing to do.","ex":{"en":"Higher education is being forced to prostitute itself to market forces.","cn":"高等教育被迫向市场需求妥协。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, usually a woman, who has sex with people for money","cn":""},{"en":"a woman who has sex with men for money","cn":""},{"en":"a woman who has sex with men for money and arranges to meet them by telephone","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A prostitute is someone who gets paid to have sex — the word usually refers to a woman, but there are male prostitutes as well."}]},"collocations":{"phrases":["ADJ. common She was arrested and charged with being a common prostitute. | child, female, girl, male | former, reformed a book written by a ","VERB + PROSTITUTE be, work as | go to, use, visit the men who use prostitutes | control He was arrested on charges of controlling prostitute","PROSTITUTE + VERB solicit The prostitutes solicit openly here."]},"media":{"uk":"media/ldoce/hwd/bre/f/prostitute_n0205.mp3","us":"media/ldoce/hwd/ame/9/prostitute1.mp3"},"examples":[{"en":"Many felt he was prostituting his talents by writing Hollywood scripts.","cn":"许多人觉得他给好莱坞写剧本是滥用自己的才华。"},{"en":"Friends from the theater criticized him for prostituting his talent in the movies.","cn":"戏剧界的朋友批评他从事电影业是糟蹋自己的才华。"}],"oxford":{"phon":"ˈprɒstɪtjuːt","pos":"noun","senses":[{"en":"a person who has sex for money","cn":"卖淫者；娼妓；妓女；男妓","ex":{"en":"men who use prostitutes","cn":"嫖娼的男子"}},{"en":"to use your skills, abilities, etc. to do something that earns you money but that other people do not respect because you are capable of doing something better","cn":"滥用才能；糟蹋自己","lab":"disapproving","ex":{"en":"Many felt he was prostituting his talents by writing Hollywood scripts.","cn":"许多人觉得他给好莱坞写剧本是滥用自己的才华。"},"pos":"verb"},{"en":"to work as a prostitute","cn":"卖淫；出卖肉体","pos":"verb"}]}},"prose":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"散文；白话文；散文体","en":"Prose is ordinary written language, in contrast to poetry.","ex":{"en":"Shute's prose is stark and chillingly unsentimental","cn":"舒特的散文平铺直叙，没有感情，让人感觉冷冰冰的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"written language in its usual form, as opposed to poetry","cn":"散文〔与诗歌相对的文体〕"}]},"vocab":{"pos":"n","senses":[{"en":"Prose is so-called \"ordinary writing\" — made up of sentences and paragraphs, without any metrical (or rhyming) structure."}]},"collocations":{"phrases":["ADJ. clear, plain, simple | elegant, flowing, rhythmic | flowery, purple (= elaborate or exaggerated in style) | descriptive | discursive | ","QUANT. piece","VERB + PROSE write (in)","PROSE + NOUN works, writing | writer | style | narrative | passage, text | fiction","PREP. in ~ a passage in prose"]},"media":{"uk":"media/ldoce/hwd/bre/e/prose0205.mp3","us":"media/ldoce/hwd/ame/2/prose.mp3"},"examples":[{"en":"the author's clear elegant prose (= style of writing)","cn":"作者清雅的散文"}],"oxford":{"phon":"prəʊz","pos":"noun","senses":[{"en":"writing that is not poetry","cn":"散文","ex":{"en":"the author’s clear elegant prose (= style of writing)","cn":"作者清雅的散文"}}]}},"privilege":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某人或某团体独享的）特权，优惠","en":"A privilege is a special right or advantage that only one person or group has.","ex":{"en":"The Russian Federation has issued a decree abolishing special privileges for government officials.","cn":"俄罗斯联邦已经颁布法令废除政府官员的特权。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（常指因财富、社会地位而享有的）特权，优惠","en":"If you talk about privilege, you are talking about the power and advantage that only a small group of people have, usually because of their wealth or their high social class.","ex":{"en":"Pironi was the son of privilege and wealth, and it showed","cn":"皮罗尼出身于有钱有势的豪门，这看得出来。"}},{"pos":"N-SING 单数名词","cn":"荣幸；荣耀","en":"You can use privilege in expressions such as be a privilege or have the privilege when you want to show your appreciation of someone or something or to show your respect.","ex":{"en":"It must be a privilege to know such a man","cn":"认识这样的人肯定很荣幸。"}},{"pos":"VERB 动词","cn":"特殊对待；给予…特权；给予…优待","en":"To privilege someone or something means to treat them better or differently than other people or things rather than treat them all equally.","ex":{"en":"We want to privilege them because without the top graduate students, we can't remain a top university","cn":"我们希望给予这些最顶尖的研究生特别照顾，因为没有他们，我们就无法继续处于一流大学之列。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that makes someone more likely to be successful, especially compared to other people","cn":""},{"en":"something or someone that is valuable because they help you to succeed","cn":""},{"en":"a special advantage or right that only a few people have, for example because their family is rich or because they have an important job","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A privilege is a special advantage not enjoyed by everyone. If you're very snooty, you probably don't allow just anyone the privilege of being your friend."}]},"collocations":{"phrases":["ADJ. exclusive, special Club members have special privileges, like free use of the pool. | class | diplomatic","VERB + PRIVILEGE enjoy, exercise, have | accord sb, give sb, grant sb | abuse He was accused of abusing his diplomatic privileges. | revoke,","ADJ. enormous, great, rare, real It is a great privilege to be attending this conference. | doubtful, dubious I was given the dubious privil","VERB + PRIVILEGE have She had the rare privilege of a viewing of his private art collection. | give sb"]},"media":{"uk":"media/ldoce/hwd/bre/e/privilege_n0205.mp3","us":"media/ldoce/hwd/ame/4/privilege.mp3"},"examples":[{"en":"Education should be a universal right and not a privilege.","cn":"教育应当是全民共有的而非少数人独享的权利。"},{"en":"As a member of the nobility, his life had been one of wealth and privilege.","cn":"身为贵族中的一员，他过着有钱有势的生活。"}],"oxford":{"phon":"ˈprɪvəlɪdʒ","pos":"noun","senses":[{"en":"a special right or advantage that a particular person or group of people has","cn":"特殊权利；优惠待遇","g":"[countable]","ex":{"en":"Education should be a universal right and not a privilege.","cn":"教育应当是全民共有的而非少数人独享的权利。"}},{"en":"the rights and advantages that rich and powerful people in a society have","cn":"（有钱有势者的）特权，特殊待遇","g":"[uncountable]","lab":"disapproving","ex":{"en":"As a member of the nobility, his life had been one of wealth and privilege.","cn":"身为贵族中的一员，他过着有钱有势的生活。"}},{"en":"something that you are proud and lucky to have the opportunity to do","cn":"荣幸；荣耀；光荣","g":"[singular]","ex":{"en":"I hope to have the privilege of working with them again.","cn":"但愿有幸与他们再度合作。"}},{"en":"a special right to do or say things without being punished","cn":"免责特权","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"parliamentary privilege (= the special right of members of parliament to say particular things without risking legal action)","cn":"议会言论免责权"}},{"en":"to give somebody/something special rights or advantages that others do not have","cn":"给予特权；特别优待","ex":{"en":"education policies that privilege the children of wealthy parents","cn":"特别优遇富家子弟的教育政策"},"pos":"verb"}]}},"prudent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"审慎的；慎重的；精明的","en":"Someone who is prudent is sensible and careful.","ex":{"en":"It is always prudent to start any exercise programme gradually at first","cn":"刚开始一项锻炼计划时循序渐进总是明智的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sensible and careful, especially by trying to avoid unnecessary risks","cn":"明智谨慎的﹐慎重的﹐审慎的"}]},"vocab":{"pos":"adj","senses":[{"en":"Describe an action as prudent if it is the wise thing to do under the existing circumstances. If you're getting in trouble, it is probably prudent to keep your mouth closed and just listen."}]},"collocations":{"phrases":["VERBS be, seem | consider sth, think sth We thought it prudent to telephone first.","ADV. extremely, very | reasonably"]},"media":{"uk":"media/ldoce/hwd/bre/2/prudent0205.mp3","us":"media/ldoce/hwd/ame/5/prudent.mp3"},"examples":[{"en":"It might be more prudent to get a second opinion before going ahead.","cn":"行动之前再征求一下意见也许更为慎重。"},{"en":"a prudent decision/investment","cn":"审慎的决定/投资"}],"oxford":{"phon":"ˈpruːdnt","pos":"adjective","senses":[{"en":"sensible and careful when you make judgements and decisions; avoiding unnecessary risks","cn":"谨慎的；慎重的；精明的","ex":{"en":"a prudent businessman","cn":"精明的商人"}}]}},"provoke":{"collins":{"senses":[{"pos":"VERB 动词","cn":"挑衅；煽动；激怒；刺激","en":"If you provoke someone, you deliberately annoy them and try to make them behave aggressively.","ex":{"en":"He started beating me when I was about fifteen but I didn't do anything to provoke him","cn":"在我快15岁时他开始打我，可我并没有任何招惹他的举动。"}},{"pos":"VERB 动词","cn":"激起；引起","en":"If something provokes a reaction, it causes it.","ex":{"en":"His election success has provoked a shocked reaction","cn":"他的当选引起一片震惊。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately say or do something in order to make someone angry, especially because you enjoy making them angry","cn":""},{"en":"to make someone feel angry with you by doing something that they do not like","cn":""},{"en":"to deliberately encourage people to cause trouble, fight, argue etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Anything that brings about a strong reaction can be said to provoke . You can provoke that lion if you want. But if he responds by attacking, don't come running to me."}]},"collocations":{"phrases":["ADV. deliberately | inevitably The suggestion inevitably provoked outrage from student leaders. | immediately | eventually, finally","VERB + PROVOKE try to | be likely to The report is likely to provoke discussion of this issue. | be designed to, be intended to","PREP. into She had been trying to provoke her sister into an argument. | to Their laughter provoked him to anger.","PHRASES be easily provoked He was sensitive and easily provoked."]},"media":{"uk":"media/ldoce/hwd/bre/8/provoke0205.mp3","us":"media/ldoce/hwd/ame/2/provoke.mp3"},"examples":[{"en":"The lawyer claimed his client was provoked into acts of violence by the defendant.","cn":"律师声称，他的当事人是受到被告的挑衅才采取暴力行动的。"},{"en":"Dairy products may provoke allergic reactions in some people.","cn":"乳制品可能会引起某些人的过敏反应。"}],"oxford":{"phon":"prəˈvəʊk","pos":"verb","senses":[{"en":"to cause a particular reaction or have a particular effect","cn":"激起；引起；引发","ex":{"en":"The announcement provoked a storm of protest.","cn":"这个声明激起了抗议的风潮。"}},{"en":"to say or do something that you know will annoy somebody so that they react in an angry way","cn":"挑衅；激怒；刺激","ex":{"en":"Be careful what you say—he's easily provoked.","cn":"说话要小心，他这个人一惹就火儿。"}}]}},"provence":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an area in southeast France which includes the coast of the Mediterranean Sea and the hills and mountains away from the coast. It is known for producing wine, fruit, olive oil and lavender (= a strong-smelling purple flower ) . Its beaches, beautiful countrysi","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000010049.mp3","us":"media/ldoce/hwd/ame/2/p028-000010049.mp3"}},"pretence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"假装；做作；矫饰","en":"A pretence is an action or way of behaving that is intended to make people believe something that is not true.","ex":{"en":"Welland made a pretence of writing a note in his pad","cn":"韦兰假装在便笺薄上做笔记。"}},{"pos":"PHRASE 短语","cn":"以虚假的借口；以欺骗的手段","en":"If you do something under false pretences, you do it when people do not know the truth about you and your intentions.","ex":{"en":"I could not go on living with a man who had married me under false pretences","cn":"我再也不能和一个靠谎言骗我结婚的男人继续生活下去了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to pretend that something is true, especially in order to deceive people","cn":""},{"en":"a situation in which people pretend that something is true and behave as if it were true, especially when everyone really knows that it is not true","cn":""},{"en":"an attempt to deceive people by pretending that something is true, especially if it is easy for people to see that it is not true","cn":""}]},"collocations":{"phrases":["ADJ. elaborate It was all an elaborate pretence.","VERB + PRETENCE keep up, maintain, sustain I don't know how long I can keep up this pretence. | abandon, drop, give up","PRETENCE + VERB be over Now that the pretence was over, he could tell them what he really thought.","PREP. under the ~ of He tried to get close to her under the pretence of examining the pictures on the wall. | ~ at His pretence at friendlin","PHRASES make a/little/no pretence I make no pretence to be an expert on the subject. | by/under false pretences obtaining money under false "]},"media":{"uk":"media/ldoce/hwd/bre/7/pretence0205.mp3","us":"media/ldoce/hwd/ame/5/pretense.mp3"},"examples":[{"en":"By the end of the evening she had abandoned all pretence of being interested.","cn":"到晚会快结束时，她已将假装出来的兴趣抛得一干二净了。"},{"en":"Their friendliness was only pretence.","cn":"他们的友善态度只不过是装出来的。"}],"oxford":{"phon":"prɪˈtens","pos":"noun","senses":[{"en":"the act of behaving in a particular way, in order to make other people believe something that is not true","cn":"假象；伪装；虚伪的表现","g":"[uncountable, singular]","ex":{"en":"Their friendliness was only pretence.","cn":"他们的友善态度只不过是装出来的。"}},{"en":"a claim that you have a particular quality or skill","cn":"妄称；自称；标榜","g":"[uncountable, countable, usually singular]","lab":"formal or literary","ex":{"en":"A judge should have at least some pretence to objectivity.","cn":"法官至少应该有一定程度的客观性。"}}]}},"pregnant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怀孕的；妊娠的","en":"If a woman or female animal is pregnant, she has a baby or babies developing in her body.","ex":{"en":"Lena got pregnant and married","cn":"莉娜怀孕并结婚了。"}},{"pos":"ADJ 形容词","cn":"耐人寻味的；意味深长的；心照不宣的","en":"A pregnant silence or moment has a special meaning which is not obvious but which people are aware of.","ex":{"en":"There was a long, pregnant silence.","cn":"当时出现了长时间耐人寻味的沉默。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to have a baby developing in your body - used especially when you are telling someone that you or another person is going to have a baby","cn":""},{"en":"to have a baby developing inside you","cn":""},{"en":"a woman who is going to have a baby","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are pregnant, you are carrying a developing baby in your body (and you are definitely a woman). Pregnant women take excellent care of their health — good for them and good for the baby."}]},"collocations":{"phrases":["VERBS be, look | become, fall (informal) , get | get sb, make sb He got her pregnant.","ADV. heavily, very","PREP. by She was pregnant by a former client.","PHRASES six weeks, three months, etc. pregnant"]},"media":{"uk":"media/ldoce/hwd/bre/f/pregnant0205.mp3","us":"media/ldoce/hwd/ame/4/pregnant.mp3"},"examples":[{"en":"He got his girlfriend pregnant and they're getting married.","cn":"他让女友怀孕了，因此他们即将结婚。"},{"en":"I was pregnant with our third child at the time.","cn":"当时我正怀着我们的第三个孩子。"}],"oxford":{"phon":"ˈpreɡnənt","pos":"adjective","senses":[{"en":"having a baby or young animal developing inside her/its body","cn":"妊娠的；怀孕的","lab":"especially US English","ex":{"en":"My wife is pregnant.","cn":"我妻子怀孕了。"}},{"en":"full of a quality or feeling","cn":"饱含；充溢着","lab":"formal","ex":{"en":"Her silences were pregnant with criticism.","cn":"她的沉默里充满了批评之意。"}}]}},"pretext":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"借口；托词","en":"A pretext is a reason which you pretend has caused you to do something.","ex":{"en":"They wanted a pretext for subduing the region by force","cn":"他们想找借口用武力征服这个地区。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a reason that you give to explain why you have done something bad, or not done something that you should have done – especially one that is not completely true","cn":""},{"en":"an untrue reason that you give for doing or not doing something, in order to hide the real reason","cn":""},{"en":"what makes something happen, or what makes someone do something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Pretext is a false reason given for doing something. If you catch your mother going through your drawers, and she says she was just tidying up, cleaning was her pretext for snooping."}]},"collocations":{"phrases":["VERB + PRETEXT give sb, provide (sb with) | find, invent He considered inventing some pretext for calling her.","PREP. on a/the ~ He disappeared into his study on the pretext that he had work to do there. | under a/the ~ Under the pretext of checking he","PHRASES at/on the slightest pretext He keeps popping into my office on the slightest pretext."]},"media":{"uk":"media/ldoce/hwd/bre/7/pretext0205.mp3","us":"media/ldoce/hwd/ame/c/pretext.mp3"},"examples":[{"en":"He left the party early on the pretext of having work to do.","cn":"他借口有事要处理，早早离开了聚会。"},{"en":"The incident was used as a pretext for intervention in the area.","cn":"这次事件成了干涉那个地区的借口。"}],"oxford":{"phon":"ˈpriːtekst","pos":"noun","senses":[{"en":"a false reason that you give for doing something, usually something bad, in order to hide the real reason; an excuse","cn":"借口；托词","ex":{"en":"The incident was used as a pretext for intervention in the area.","cn":"这次事件被用作干涉那个地区的借口。"}}]}},"prolific":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（作家、画家或作曲家）多产的，作品丰富的","en":"A prolific writer, artist, or composer produces a large number of works.","ex":{"en":"She is a prolific writer of novels and short stories","cn":"她是一位多产的作家，写了很多小说和短篇故事。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（运动员）得分多的，比赛中获胜多的","en":"A prolific sports player scores a lot of goals or wins a lot of matches or races.","ex":{"en":"Another prolific scorer is Dean Saunders.","cn":"另外一个得分高手是迪安·桑德斯。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人、动物、植物）多育的，多产的，高产的","en":"An animal, person, or plant that is prolific produces a large number of babies, young plants, or fruit.","ex":{"en":"They are prolific breeders, with many hens laying up to six eggs.","cn":"他们都是多产的饲养员，养的母鸡很多都可以下6个蛋之多。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动物）众多的，大批的","en":"If animals are prolific somewhere, there are a lot of them there.","ex":{"en":"All the big game congregate here, and birdlife is particularly prolific.","cn":"所有的大型野兽都聚集在这里，鸟类尤其丰富。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"doing a job efficiently with good results, especially by producing a large quantity of something","cn":""},{"en":"a writer or artist who is prolific produces a large number of works","cn":""},{"en":"a prolific artist, writer etc produces many works of art, books etc 〔","cn":"艺术家﹑作家等〕多产的﹐作品丰富的"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone or something that is prolific is fruitful or highly productive. A prolific songwriter can churn out five hit tunes before breakfast."}]},"collocations":{"phrases":["VERBS be","ADV. exceptionally, extraordinarily, extremely, highly, immensely, incredibly, very | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/7/prolific0205.mp3","us":"media/ldoce/hwd/ame/c/prolific.mp3"},"examples":[{"en":"one of the most prolific periods in her career","cn":"她的创作生涯中成果最丰的时期之一"},{"en":"a pop star with a prolific following of teenage fans","cn":"拥有大批少男少女歌迷的流行歌星"}],"oxford":{"phon":"prəˈlɪfɪk","pos":"adjective","senses":[{"en":"producing many works, etc.","cn":"多产的；创作丰富的","ex":{"en":"a prolific author","cn":"多产的作家"}},{"en":"producing a lot of fruit, flowers, young, etc.","cn":"丰硕的；多产的；多育的","ex":{"en":"prolific plant growth","cn":"植物多产生长"}},{"en":"able to produce enough food, etc. to keep many animals and plants alive","cn":"富饶的；富庶的；肥沃的","ex":{"en":"prolific rivers","cn":"富饶的河川"}},{"en":"existing in large numbers","cn":"众多的；许多的","ex":{"en":"a pop star with a prolific following of teenage fans","cn":"拥有大批少男少女歌迷的流行歌星"}}]}},"provocative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"挑衅的；煽动的；激怒的；刺激的","en":"If you describe something as provocative, you mean that it is intended to make people react angrily or argue against it.","ex":{"en":"He has made a string of outspoken and sometimes provocative speeches in recent years","cn":"他近些年发表了一连串直言不讳、有时带煽动性的演说。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激发性欲的；挑逗的","en":"If you describe someone's clothing or behaviour as provocative, you mean that it is intended to make someone feel sexual desire.","ex":{"en":"Some adolescents might be more sexually mature and provocative than others.","cn":"一些青少年可能相比同龄人在性方面更成熟、更具挑逗性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attractive","cn":""},{"en":"seeming to show strong sexual feelings and a desire for sexual pleasure","cn":""},{"en":"intended to make someone feel sexually excited","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is provocative , it provokes a reaction. A provocative , or low cut blouse might make people think you're sexy. A provocative statement, such as \"I hate babies,\" will get another kind of reaction."}]},"collocations":{"phrases":["VERBS be, seem | consider sth","ADV. extremely, highly, very | rather | deliberately | unnecessarily 2 intending to cause sexual excitement","VERBS be, look","ADV. highly, very | unconsciously | sexually"]},"media":{"uk":"media/ldoce/hwd/bre/6/provocative0205.mp3","us":"media/ldoce/hwd/ame/f/provocative.mp3"},"examples":[{"en":"He doesn't really mean that — he's just being deliberately provocative.","cn":"他不是真有此意，只不过是存心挑逗一下罢了。"},{"en":"a provocative remark","cn":"煽动性的言论"}],"oxford":{"phon":"prəˈvɒkətɪv","pos":"adjective","senses":[{"en":"intended to make people angry or upset; intended to make people argue about something","cn":"挑衅的；煽动性的；激起争端的","ex":{"en":"a provocative remark","cn":"煽动性的言论"}},{"en":"intended to make somebody sexually excited","cn":"引诱的；激起性欲的","ex":{"en":"a provocative smile","cn":"撩人的一笑"}}]}},"prostrate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使（自己）俯伏；使（自己）拜倒","en":"If you prostrate yourself, you lie down flat on the ground, on your front, usually to show respect for God or a person in authority.","ex":{"en":"They prostrated themselves before their king.","cn":"他们向国王跪拜行礼。"}},{"pos":"ADJ 形容词","cn":"俯卧的；平卧的","en":"If you are lying prostrate, you are lying flat on the ground, on your front.","ex":{"en":"Percy was lying prostrate, his arms outstretched and his eyes closed.","cn":"珀西闭着眼四仰八叉地平躺着。"}},{"pos":"ADJ 形容词","cn":"衰竭的；沮丧的；一蹶不振的","en":"If someone is prostrate, they are so distressed or affected by a very bad experience that they are unable to do anything at all.","ex":{"en":"Immediately after my father's death my stepmother was prostrate","cn":"我父亲死后，我的继母一下就垮了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lying on your front with your face towards the ground","cn":"俯卧的﹔趴着的"},{"en":"too shocked, upset, weak etc to be able to do anything","cn":"震惊[难过，衰弱等]至极的"},{"en":"to lie on your front with your face towards the ground, especially as an act of religious worship or as a sign of your willingness to obey someone","cn":"拜倒﹐匍匐〔尤表示顺从或宗教崇拜〕"}]},"vocab":{"pos":"adj v","senses":[{"en":"The verb prostrate means \"to make helpless or defenseless.\" Illness, injury, food poisoning, grief — any of these things can prostrate people, or lying down in a helpless position."}]},"collocations":{"phrases":["VERBS be, lie lying prostrate on the ground | fall They fell prostrate before the king."]},"media":{"uk":"media/ldoce/hwd/bre/a/prostrate_adj0205.mp3","us":"media/ldoce/hwd/ame/f/l3prostrate.mp3"},"examples":[{"en":"He was expecting to find her prostrated by the tragedy.","cn":"他以为这场悲剧会使她一蹶不振。"},{"en":"He stumbled over Luke's prostrate body.","cn":"他绊倒在卢克俯卧的身躯上。"}],"oxford":{"phon":"ˈprɒstreɪt","pos":"adjective","senses":[{"en":"lying on the ground and facing downwards","cn":"俯卧的；趴着的；俯伏的","ex":{"en":"They fell prostrate in worship.","cn":"他们拜倒在地。"}},{"en":"so shocked, upset, etc. that you cannot do anything","cn":"给（悲伤等）压倒","ex":{"en":"She was prostrate with grief after her son's death.","cn":"她因丧子悲痛欲绝。"}},{"en":"to lie on your front with your face looking downwards, especially as a way of showing respect for God or a god","cn":"俯伏；拜倒","pos":"verb"},{"en":"to make somebody feel weak, shocked, and unable to do anything","cn":"使一筹莫展；使无能为力","g":"[usually passive]","ex":{"en":"He was expecting to find her prostrated by the tragedy.","cn":"他以为这场悲剧会使她一蹶不振。"},"pos":"verb"}]}},"proclamation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宣布；声明；公布","en":"A proclamation is a public announcement about something important, often about something of national importance.","ex":{"en":"...a proclamation of independence.","cn":"独立声明"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official public statement about something that is important, or when someone makes such a statement","cn":"公告﹔声明（书）﹐宣言"}]},"vocab":{"pos":"n","senses":[{"en":"A proclamation is a formal public statement. If the mayor of your town issued a proclamation honoring the state champion field hockey team, this is an official statement of praise and celebration."}]},"collocations":{"phrases":["ADJ. official, public, royal","VERB + PROCLAMATION issue, make","PROCLAMATION + VERB forbid sth, prohibit sth","PREP. by ~ The government restricted the use of water by proclamation."]},"media":{"uk":"media/ldoce/hwd/bre/9/proclamation0205.mp3","us":"media/ldoce/hwd/ame/b/proclamation.mp3"},"examples":[{"en":"The authorities issued a proclamation forbidding public meetings.","cn":"当局发布了公告﹐禁止公开集会。"},{"en":"the proclamation of Lithuania’s independence","cn":"立陶宛独立宣言"}],"oxford":{"phon":"ˌprɒkləˈmeɪʃn","pos":"noun","senses":[{"en":"an official statement about something important that is made to the public; the act of making an official statement","cn":"宣言；公告；声明","ex":{"en":"The King issued a proclamation dissolving Parliament.","cn":"国王发布公告解散议会。"}}]}},"projection":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预计；预测；估计","en":"A projection is an estimate of a future amount.","ex":{"en":"...the company's projection of 11 million visitors for the first year.","cn":"公司对第一年将有1,100万游客的预测"}},{"pos":"N-UNCOUNT 不可数名词","cn":"投射；放映","en":"The projection of a film or picture is the act of projecting it onto a screen or wall.","ex":{"en":"They took me into a projection room to see a picture.","cn":"他们把我带到放映室去看一张图。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement or calculation about what something will be in the future or was in the past, based on information available now 〔","cn":"对于未来情况的〕预测﹔〔对过去的〕估算"},{"en":"something that sticks out from a surface","cn":"凸出物"},{"en":"the act of projecting a film or picture onto a screen 〔","cn":"幻灯片的〕投射﹐投影﹔〔电影的〕放映"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n 5 n ","senses":[{"en":"When you push something away from a central structure, that's called projection . If you predict that the Jets will win tomorrow's game, that's a projection, too — you're pushing your mind away from the present and into the future."}]},"collocations":{"phrases":["ADJ. current, latest | forward, future | population | financial, profit, sales","VERB + PROJECTION make | revise","PREP. on &hellip; ~s On current projections, there will be more than ten million people 65 or over in 2010. | ~ about He declined to make pr"]},"media":{"uk":"media/ldoce/hwd/bre/1/projection0205.mp3","us":"media/ldoce/hwd/ame/c/projection.mp3"},"examples":[{"en":"The idea of God is a projection of humans' need to have something greater than themselves.","cn":"人类需要有强于自身的形象；上帝就是这个想法的投射。"},{"en":"the projection of three-dimensional images on a computer screen","cn":"在电脑屏幕上显示的立体影像"}],"oxford":{"phon":"prəˈdʒekʃn","pos":"noun","senses":[{"en":"an estimate or a statement of what figures, amounts, or events will be in the future, or what they were in the past, based on what is happening now","cn":"预测；推断；设想","g":"[countable]","sc":"estimate","ex":{"en":"to make forward/backward projections of population figures","cn":"推断未来／过去的人口数量"}},{"en":"the act of putting an image of something onto a surface; an image that is shown in this way","cn":"投射；放映；投影；放映的影像","g":"[uncountable, countable]","sc":"of image","ex":{"en":"the projection of three-dimensional images on a computer screen","cn":"在电脑屏幕上显示的立体影像"}},{"en":"a solid shape or object as represented on a flat surface","cn":"投影图","g":"[countable]","lab":"specialist","sc":"of solid shape","ex":{"en":"map projections","cn":"地图投影"}},{"en":"something that sticks out from a surface","cn":"突起物；隆起物","g":"[countable]","sc":"something that sticks out","ex":{"en":"tiny projections on the cell","cn":"细胞上的小尖突出物"}},{"en":"the act of making your voice, a sound, etc. audible (= able to be heard) at a distance","cn":"（嗓音或声音的）发送，传送，放开","g":"[uncountable]","sc":"of voice/sound","ex":{"en":"voice projection","cn":"嗓音的放开"}},{"en":"the act of imagining that somebody else is thinking the same as you and is reacting in the same way","cn":"投射（不自觉地把自己的思想等加诸他人）","g":"[uncountable]","sc":"psychology"},{"en":"the act of giving a form and structure to inner thoughts and feelings","cn":"（思想感情的）体现，形象化","g":"[countable, uncountable]","sc":"of thoughts/feelings","ex":{"en":"The idea of God is a projection of humans' need to have something greater than themselves.","cn":"人类需要有强于自身的形象，上帝就是这一需要的体现。"}}]}},"prolong":{"collins":{"senses":[{"pos":"VERB 动词","cn":"延长；拉长；拖长","en":"To prolong something means to make it last longer.","ex":{"en":"Mr Chesler said foreign military aid was prolonging the war","cn":"切斯勒先生说国外的军事援助拉长了战事。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something last longer","cn":""},{"en":"to make something last longer than the usual time","cn":""},{"en":"to make something that is coming to an end continue for a longer period of time – used especially about official arrangements such as contract s and visa s","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"I don't want to prolong this definition, so I'll keep it short. To prolong is to make something last longer or to stretch it out in time."}]},"collocations":{"phrases":["ADV. indefinitely Might it be possible to prolong life indefinitely? | artificially | deliberately Doctors commented that some patients deli"]},"media":{"uk":"media/ldoce/hwd/bre/d/prolong0205.mp3","us":"media/ldoce/hwd/ame/e/prolong.mp3"},"examples":[{"en":"The operation could prolong his life by two or three years.","cn":"这次手术可使他多活两三年。"},{"en":"Don't prolong the agony (of not knowing sth) — just tell us who won!","cn":"别卖关子了，快说谁赢了！"}],"oxford":{"phon":"prəˈlɒŋ","pos":"verb","senses":[{"en":"to make something last longer","cn":"延长","ex":{"en":"The operation could prolong his life by two or three years.","cn":"这次手术可使他多活两三年。"}}]}},"prospect":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"可能性；希望","en":"If there is some prospect of something happening, there is a possibility that it will happen.","ex":{"en":"Unfortunately, there is little prospect of seeing these big questions answered","cn":"不幸的是，几乎不可能看到这些重大问题得到回复。"}},{"pos":"N-SING 单数名词","cn":"期望中的事；将要发生的事；预期；展望","en":"A particular prospect is something that you expect or know is going to happen.","ex":{"en":"They now face the prospect of having to wear a cycling helmet by law","cn":"他们现在面临的情形是：不久将需要依法佩戴摩托车头盔。"}},{"pos":"N-PLURAL 复数名词","cn":"（尤指事业的）成功机会，前景，前途","en":"Someone's prospects are their chances of being successful, especially in their career.","ex":{"en":"I chose to work abroad to improve my career prospects.","cn":"我选择出国工作以求在事业上有更好的发展。"}},{"pos":"VERB 动词","cn":"勘探；勘察","en":"When people prospect for oil, gold, or some other valuable substance, they look for it in the ground or under the sea.","ex":{"en":"He had prospected for minerals everywhere from the Gobi Desert to the Transvaal","cn":"他已在从戈壁沙漠到德兰士瓦的无数地方勘探过矿藏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what will happen to someone or something","cn":""},{"en":"someone or something’s future – used especially when you are worried that something bad could happen","cn":""},{"en":"what will happen to someone in their life, especially something important","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A prospect is the possibility that something fabulous will happen. After you graduate top of your class at Harvard, for example, your job prospects look great."}]},"collocations":{"phrases":["ADJ. reasonable | immediate","VERB + PROSPECT have | offer","PREP. in ~ Major developments are in prospect for the company. | ~ of sth There is little prospect of any improvement in the weather. 2 idea","ADJ. attractive, exciting, inviting | bleak, daunting","VERB + PROSPECT be excited at, relish, welcome I don't relish the prospect of having to share an office. | be faced with, face 3 prospects c","ADJ. bright, excellent, exciting, good | limited, poor | future, long-term | development, economic, growth | career, employment, job, promot","VERB + PROSPECT have | offer (sb) This position offers a good starting salary and excellent promotion prospects. | boost, enhance, improve G","PROSPECT + VERB improve"]},"media":{"uk":"media/ldoce/hwd/bre/a/prospect_n0205.mp3","us":"media/ldoce/hwd/ame/1/l3prospect.mp3"},"examples":[{"en":"At 25 he was an unemployed musician with no prospects. * 25","cn":"岁的他是个没有工作、前途渺茫的乐师。"},{"en":"She is one of Canada's best prospects for a gold medal.","cn":"她是加拿大最有希望夺金的选手之一。"}],"oxford":{"phon":"ˈprɒspekt","pos":"noun","senses":[{"en":"the possibility that something will happen","cn":"可能性；希望","g":"[uncountable, singular]","ex":{"en":"There is no immediate prospect of peace.","cn":"短期内没有和平的可能。"}},{"en":"an idea of what might or will happen in the future","cn":"前景；展望；设想","g":"[singular]","ex":{"en":"an exciting prospect","cn":"令人兴奋的前景"}},{"en":"the chances of being successful","cn":"成功的机会；前景；前途","g":"[plural]","ex":{"en":"good job/employment/career prospects","cn":"美好的工作／就业／事业前途"}},{"en":"a person who is likely to be successful in a competition or in a particular career","cn":"（比赛或职业的）有望获胜者，成功机会大的人","g":"[countable]","ex":{"en":"She is one of Canada's best prospects for a gold medal.","cn":"她是加拿大最有希望夺金的选手之一。"}},{"en":"a wide view of an area of land, etc.","cn":"风景；景色","g":"[countable]","lab":"formal","ex":{"en":"a delightful prospect of the lake","cn":"令人心旷神怡的湖上风光"}},{"en":"to search an area for gold, minerals, oil, etc.","cn":"探矿；勘探","lab":"figurative","ex":{"en":"Thousands moved to the area to prospect for gold.","cn":"数以千计的人涌入那个地区淘金。"},"pos":"verb"}]}},"proprietor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"所有人；业主","en":"The proprietor of a hotel, shop, newspaper, or other business is the person who owns it.","ex":{"en":"...the proprietor of a local restaurant","cn":"一家当地餐馆的业主"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who owns something","cn":""},{"en":"someone who owns a building and is paid money by the people who live in it or use it","cn":""},{"en":"someone who owns and runs a business, especially a small business such as a shop or a restaurant","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Someone who owns a business or a property is a proprietor. A bookstore proprietor might wish she became a librarian instead so the books would come back."}]},"collocations":{"phrases":["ADJ. hotel, newspaper, restaurant | landed | sole He is now sole proprietor of the business."]},"media":{"uk":"media/ldoce/hwd/bre/3/proprietor0205.mp3","us":"media/ldoce/hwd/ame/d/proprietor.mp3"},"examples":[{"en":"newspaper proprietors","cn":"报业老板"},{"en":"the proprietor of a small hotel and restaurant","cn":"一家小旅馆兼餐馆的老板"}],"oxford":{"phon":"prəˈpraɪətə(r)","pos":"noun","senses":[{"en":"the owner of a business, a hotel, etc.","cn":"业主；所有人","ex":{"en":"newspaper proprietors","cn":"报业老板"}}]}},"preacher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牧师；传道士","en":"A preacher is a person, usually a member of the clergy, who preaches sermons as part of a church service."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is specially trained to perform religious duties and ceremonies in the Christian church","cn":""},{"en":"a priest of high rank in some branches of the Christian church, who is the head of all the churches and priests in a large area","cn":""},{"en":"a priest in the Church of England who is in charge of a church in a particular area","cn":""}]},"collocations":{"phrases":["ADJ. celebrated, eminent, famous, good, great, leading | Baptist, Methodist, etc. | evangelical | lay | local | itinerant","VERB + PREACHER hear, listen to"]},"media":{"uk":"media/ldoce/hwd/bre/e/preacher0205.mp3","us":"media/ldoce/hwd/ame/b/laadpreacher.mp3"},"examples":[{"en":"a preacher famous for her inspiring sermons","cn":"以发人深省的讲道出名的传道者"},{"en":"a lay preacher (= who is not a priest, etc. but who has been trained to give religious talks)","cn":"传道员"}],"oxford":{"phon":"ˈpriːtʃə(r)","pos":"noun","senses":[{"en":"a person, often a member of the clergy, who gives religious talks and often performs religious ceremonies, for example in a church","cn":"传道者；牧师","ex":{"en":"a preacher famous for her inspiring sermons","cn":"以发人深省的讲道出名的传道者"}}]}},"predict":{"collins":{"senses":[{"pos":"VERB 动词","cn":"预言；预测；预告","en":"If you predict an event, you say that it will happen.","ex":{"en":"The latest opinion polls are predicting a very close contest","cn":"最近的民意测验预测竞争将会非常激烈。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that something will happen, before it happens","cn":"预言﹐预料﹐预测"},{"en":"to say what is likely to happen in the future, especially in relation to the weather or the economic or political situation","cn":"预报，预测〔尤用于天气﹑经济情况或政治局势〕"},{"en":"to say what the amount, size, cost etc of something is likely to be in the future, using the information you have now 〔","cn":"利用已知信息〕推断，预计"}]},"vocab":{"pos":"v","senses":[{"en":"To predict is to say what you think is going to happen in the future. If you predict that you'll win the poker championship, you're either really confident in your poker skills or you're cheating."}]},"collocations":{"phrases":["ADV. accurately, correctly, reliably, successfully, with accuracy/certainty It is not possible to predict with any certainty what effect thi","VERB + PREDICT be able/unable to, can/could | try to | dare (to) Few would have dared to predict such a landslide victory. | fail to | be di","PREP. from We can predict from this information what is likely to happen next.","PHRASES be widely predicted This result had been widely predicted by the opinion polls."]},"media":{"uk":"media/ldoce/hwd/bre/7/predict0205.mp3","us":"media/ldoce/hwd/ame/d/predict.mp3"},"examples":[{"en":"It was predicted that inflation would continue to fall.","cn":"据预报，通货膨胀率将继续下降。"},{"en":"It is impossible to predict what will happen.","cn":"预知未来的事是不可能的。"}],"oxford":{"phon":"prɪˈdɪkt","pos":"verb","senses":[{"en":"to say that something will happen in the future","cn":"预言；预告；预报","ex":{"en":"a reliable method of predicting earthquakes","cn":"预报地震的可靠方法"}}]}},"prune":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"李子干；梅干","en":"A prune is a dried plum."},{"pos":"VERB 动词","cn":"修剪；修整","en":"When you prune a tree or bush, you cut off some of the branches so that it will grow better the next year.","ex":{"en":"You have to prune a bush if you want fruit","cn":"如果想让灌木结果，就必须进行修剪。"}},{"pos":"VERB 动词","cn":"删去；除去；削减","en":"If you prune something, you cut out all the parts that you do not need.","ex":{"en":"Firms are cutting investment and pruning their product ranges.","cn":"公司正在减少投资，缩减产品系列。"}},{"pos":"","cn":"","en":"相关词组：prune back"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make trees or bushes fall down by cutting them","cn":""},{"en":"to cut down trees, especially a large number of them, using special equipment","cn":""},{"en":"to cut wood into pieces using an axe (=a tool with a long handle and a sharp blade)","cn":""}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"To prune means to clip, crop, cut back, and weed out. Pruning usually happens to overgrown trees and bushes, but can also be helpful for wild eyebrows and guest lists that are too long."}]},"collocations":{"phrases":["ADV. hard, heavily, savagely, severely Prune the trees hard in the winter. (figurative) Local councils could find their housing budgets seve"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeprune.mp3","us":"media/ldoce/hwd/ame/6/prune1.mp3"},"examples":[{"en":"Staff numbers have been pruned back to 175.","cn":"员工的数量已精简到 175 人。"},{"en":"The company would benefit from a little pruning here and there.","cn":"公司如能处处精简一点，必将获益。"}],"oxford":{"phon":"pruːn","pos":"noun","senses":[{"en":"a dried plum that is often eaten cooked","cn":"干梅子；西梅干；李子干","ex":{"en":"stewed prunes","cn":"炖梅脯"}},{"en":"to cut off some of the branches from a tree, bush, etc. so that it will grow better and stronger","cn":"修剪树枝；打杈","ex":{"en":"When should you prune apple trees?","cn":"苹果树应该什么时候剪枝？"},"pos":"verb"},{"en":"to make something smaller by removing parts; to cut out parts of something","cn":"裁减；削减；精简","ex":{"en":"Staff numbers have been pruned back to 175.","cn":"员工的数量已精减到 175 人。"},"pos":"verb"}]}},"prey":{"collins":{"senses":[{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"猎物；捕食对象","en":"A creature's prey are the creatures that it hunts and eats in order to live.","ex":{"en":"Electric rays stun their prey with huge electrical discharges","cn":"电鳐能放出强大的电流把猎物击晕。"}},{"pos":"VERB 动词","cn":"捕食；以捕猎…为生","en":"A creature that preys on other creatures lives by catching and eating them.","ex":{"en":"The effect was to disrupt the food chain, starving many animals and those that preyed on them","cn":"其结果就是破坏食物链，使很多动物和那些以捕食它们为生的动物饿死。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"伤害的对象；愚弄的对象；欺骗的对象","en":"You can refer to the people who someone tries to harm or trick as their prey .","ex":{"en":"Police officers lie in wait for the gangs who stalk their prey at night","cn":"警察设伏等待那些在晚上跟踪目标伺机作案的歹徒。"}},{"pos":"VERB 动词","cn":"欺凌，坑害（尤指弱者）","en":"If someone preys on other people, especially people who are unable to protect themselves, they take advantage of them or harm them in some way.","ex":{"en":"Pam had never learned that there were men who preyed on young runaways","cn":"帕姆从来不知道有人专门坑骗离家出走的年轻人。"}},{"pos":"VERB 动词","cn":"不断困扰；折磨；使耿耿于怀","en":"If something preys on your mind, you cannot stop thinking and worrying about it.","ex":{"en":"The absence of children at Christmas preyed on Liz's mind","cn":"利兹因为圣诞节时孩子们不在而一直心神不宁。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"受影响；受折磨；受害","en":"If someone is prey to something bad, they have a tendency to let themselves be affected by it.","ex":{"en":"He was prey to a growing despair","cn":"他被与日俱增的绝望折磨着。"}},{"pos":"PHRASE 短语","cn":"受…控制；成为…的牺牲品；受…的影响","en":"To fall prey to something bad means to be taken over or affected by it.","ex":{"en":"On the flight from Paris to Toulon, Mechiche fell prey to panic","cn":"在从巴黎飞往土伦的航班上，梅希什惊慌失措。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an animal, bird etc that is hunted and eaten by another animal","cn":"被〔其他动物〕捕食的动物﹐猎物"},{"en":"a bird or animal which lives by killing and eating other animals","cn":"食肉猛禽/猛兽"},{"en":"if someone falls prey to someone or something bad, they are harmed or affected by them","cn":"受某人/某事物所伤害［影响］"}]},"vocab":{"pos":"n v","senses":[{"en":"Prey is an animal hunted for food. If you're a delicious-looking deer during hunting season, watch your back! You're the prey for all those guys in orange jackets carrying rifles."}]},"collocations":{"phrases":["ADJ. easy Teenagers are easy prey for unscrupulous drug dealers. | ideal","VERB + PREY chase, hunt for, look for, pursue, stalk | capture, pounce on a cat pouncing on its prey | kill","PREP. ~ for The young deer are ideal prey for the leopard. | ~ to (figurative) She was prey to all kinds of conflicting emotions.","PHRASES a beast/bird of prey, be/fall prey to sth (figurative) The new government has fallen prey to corruption and fraud."]},"media":{"uk":"media/ldoce/hwd/bre/e/prey_n0205.mp3","us":"media/ldoce/hwd/ame/0/pray1.mp3"},"examples":[{"en":"Bogus social workers have been preying on old people living alone.","cn":"冒牌社会福利工作员不断坑害独居老人。"},{"en":"The lion will often stalk its prey for hours.","cn":"狮子经常悄然跟踪猎物达几个小时。"}],"oxford":{"phon":"preɪ","pos":"noun","senses":[{"en":"an animal, a bird, etc. that is hunted, killed and eaten by another","cn":"猎物","ex":{"en":"The lion will often stalk its prey for hours.","cn":"狮子经常悄然跟踪猎物达几个小时。"}},{"en":"a person who is harmed or tricked by somebody, especially for dishonest purposes","cn":"受害者；受骗者","ex":{"en":"Elderly people are easy prey for dishonest salesmen.","cn":"老年人容易上狡诈推销员的当。"}}]}},"prague":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of the czech republic , which is an important industrial centre. It is known for its many beautiful buildings and is visited by many tourists.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/p028-000009943.mp3","us":"media/ldoce/hwd/ame/e/p028-000009943.mp3"}},"probability":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"可能性；几率；概率","en":"The probability of something happening is how likely it is to happen, sometimes expressed as a fraction or a percentage.","ex":{"en":"Without a transfusion, the victim's probability of dying was 100%","cn":"如果不输血，患者必死无疑。"}},{"pos":"N-VAR 可变名词","cn":"可能性；或然性","en":"You say that there is a probability that something will happen when it is likely to happen.","ex":{"en":"There's an excellent probability that unless action is quickly taken, pipes will freeze","cn":"除非立即采取行动，否则管道很有可能冻住。"}},{"pos":"PHRASE 短语","cn":"很可能","en":"If you say that something will happen in all probability, you mean that you think it is very likely to happen.","ex":{"en":"The Republicans had better get used to the fact that in all probability, they are going to lose","cn":"共和党人最好习惯他们很有可能失败的事实。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how likely it is that something will happen - use this especially about situations where you can calculate fairly exactly how likely something is","cn":""},{"en":"the chance that something you hope for will happen soon","cn":""},{"en":"how likely it is that something you hope for will actually happen","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Probability has to do with how likely something is to happen. If there's a 50/50 chance, then the probability is 50%."}]},"collocations":{"phrases":["ADJ. high, real, strong There is a high probability that it will snow tonight. | greater, increased | low","QUANT. degree We can say with a high degree of probability that the poem was written by Shakespeare.","VERB + PROBABILITY have | increase | reduce | assess, calculate, judge","PREP. ~ of This surgical procedure has a high probability of success.","PHRASES in all probability In all probability she wouldn't come even if we invited her. | on a balance of probabilities The coroner thought "]},"media":{"uk":"media/ldoce/hwd/bre/e/probability0205.mp3","us":"media/ldoce/hwd/ame/b/probability.mp3"},"examples":[{"en":"A fall in interest rates is a strong probability in the present economic climate.","cn":"在目前的经济形势下，降低利率大有可能。"},{"en":"It now seems a probability rather than just a possibility.","cn":"这件事似乎十拿九稳，而不是仅有可能。"}],"oxford":{"phon":"ˌprɒbəˈbɪləti","pos":"noun","senses":[{"en":"how likely something is to happen","cn":"可能性；或然性","g":"[uncountable, countable]","ex":{"en":"The probability is that prices will rise rapidly.","cn":"物价有可能会迅速上升。"}},{"en":"a thing that is likely to happen","cn":"很可能发生的事","g":"[countable]","ex":{"en":"A fall in interest rates is a strong probability in the present economic climate.","cn":"在目前的经济形势下，降低利率大有可能。"}},{"en":"a ratio showing the chances that a particular thing will happen","cn":"概率；几率；或然率","g":"[countable, uncountable]","lab":"mathematics","ex":{"en":"There is a 60 per cent probability that the population will be infected with the disease.","cn":"民众感染这种疾病的概率为 60%。"}}]}},"probe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"调查；打探；探究；探听","en":"If you probe into something, you ask questions or try to discover facts about it.","ex":{"en":"The more they probed into his background, the more inflamed their suspicions would become","cn":"他们越调查他的背景，疑团就越多。"}},{"pos":"VERB 动词","cn":"（医生或牙医用细长的工具）探查，检查，探测","en":"If a doctor or dentist probes, he or she uses a long instrument to examine part of a patient's body.","ex":{"en":"The surgeon would pick up his instruments, probe, repair and stitch up again","cn":"外科医生会拿起他的工具，探查、修复然后再重新缝合。"}},{"pos":"N-COUNT 可数名词","cn":"（医生和牙医用的）探针","en":"A probe is a long thin instrument that doctors and dentists use to examine parts of the body.","ex":{"en":"...a fibre-optic probe.","cn":"光纤探针"}},{"pos":"VERB 动词","cn":"搜寻；搜查","en":"If you probe a place, you search it in order to find someone or something that you are looking for.","ex":{"en":"A flashlight beam probed the underbrush only yards away from their hiding place","cn":"一束手电筒的光束在离他们的藏身之地只有几码远的灌木丛里搜寻着。"}},{"pos":"VERB 动词","cn":"侦察，侦探（敌情）","en":"In a conflict such as a war, if one side probes another side's defences, they try to find their weaknesses, for example by attacking them in specific areas using a small number of troops.","ex":{"en":"He probes the enemy's weak positions, ignoring his strongholds","cn":"他侦察敌人兵力薄弱的位置，对其要塞不予理睬。"}},{"pos":"N-COUNT 可数名词","cn":"航天探测器；太空探测器","en":"A space probe is a spacecraft which travels into space with no people in it, usually in order to study the planets and send information about them back to earth.","ex":{"en":"Its rings were discovered by telescope from Earth, but space probes later found that spectacular rings surround some other planets","cn":"它的圆环是从地球上用望远镜发现的，但是太空探测器后来又发现了围绕其他一些星球的壮观的圆环。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to find out the truth about something such as a crime, accident, or scientific problem","cn":""},{"en":"to find out more about a problem, especially after someone has asked you to do this","cn":""},{"en":"to consider or discuss something, in order to help you decide what you should do","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you probe something, you investigate it thoroughly. If you go into business with someone, you might probe her finances to make sure that she has a good track record."}]},"collocations":{"phrases":["ADV. deep/deeply (figurative) probing deeper and deeper into the secrets of the universe | further | gently","PREP. for using its long beak to probe for worms | into (figurative) The police were probing into her personal life. | with He probed the mu"]},"media":{"uk":"media/ldoce/hwd/bre/9/probe_n0205.mp3","us":"media/ldoce/hwd/ame/a/probe1.mp3"},"examples":[{"en":"a TV programme that probed government scandals in the 1990s","cn":"追查 20 世纪 90 年代政府丑闻的电视节目"},{"en":"a police probe into the financial affairs of the company","cn":"警方对这家公司的财务进行的详细调查"}],"oxford":{"phon":"prəʊb","pos":"noun","senses":[{"en":"a complete and careful investigation of something","cn":"探究；详尽调查","ex":{"en":"a police probe into the financial affairs of the company","cn":"警方对这家公司的财务的详细调查"}},{"en":"a spacecraft without people on board that obtains information and sends it back to earth","cn":"（不载人）空间探测器"},{"en":"a long, thin metal tool used by doctors for examining inside the body","cn":"（医生用的）探针","lab":"specialist"},{"en":"a small device put inside something and used by scientists to test something or record information","cn":"探测仪；传感器；取样器","lab":"specialist"},{"en":"to ask questions in order to find out secret or hidden information about somebody/something","cn":"盘问；追问；探究","g":"[intransitive, transitive]","ex":{"en":"He didn't like the media probing into his past.","cn":"他不喜欢媒体追问他的过去。"},"pos":"verb"},{"en":"to touch, examine or look for something, especially with a long, thin instrument","cn":"（用细长工具）探查，查看","g":"[transitive]","ex":{"en":"The doctor probed the wound for signs of infection.","cn":"医生检查伤口是否有感染的迹象。"},"pos":"verb"}]}},"presumptively":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"based on a reasonable belief about what is likely to be true","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41presumptive.mp3","us":"media/ldoce/hwd/ame/6/presumptive.mp3"}},"prism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"棱镜","en":"A prism is a block of clear glass or plastic which separates the light passing through it into different colours."},{"pos":"N-COUNT 可数名词","cn":"曲解；扭曲","en":"If you see something through a prism of something such as time or memory, your idea of it is affected by that thing.","ex":{"en":"Through the smoky prism of time, I could just barely make out my father as a young man.","cn":"时间模糊了记忆，我几乎想不起父亲年轻时的样子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a transparent block of glass that breaks up white light into different colours","cn":"棱镜"},{"en":"a solid object with matching ends and several sides which are the same width all the way up","cn":"棱柱（体）"}]},"vocab":{"pos":"n","senses":[{"en":"In geometry, a prism is a three-dimensional shape that has two bases that are parallel and the same size and shape. The prism 's sides are all parallelograms. A classic pup tent is a triangular prism ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/prism0205.mp3","us":"media/ldoce/hwd/ame/f/prism.mp3","img":["media/thumb/prism.jpg"]},"oxford":{"phon":"ˈprɪzəm","pos":"noun","senses":[{"en":"a solid figure with ends that are parallel (= the same distance apart at every point) and of the same size and shape, and with sides whose opposite edges are equal and parallel","cn":"棱柱体；棱柱","lab":"geometry"},{"en":"a clear glass or plastic object, often with ends in the shape of a triangle, which separates light that passes through it into the colours of the rainbow","cn":"棱镜；三棱镜"}]}}});
